import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'xs' | 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-indigo-500 to-indigo-800 border-indigo-400 shadow-[0_0.2rem_0_rgba(0,0,0,0.8)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgba(0,0,0,0.8)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgba(0,0,0,0.8)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgba(0,0,0,0.8)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgba(0,0,0,0.8)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgba(0,0,0,0.8)]",
    };

    const sizeConfigs = {
        xs: { height: "h-[1.65rem]", fontSize: 1.1, padding: "px-1" },
        sm: { height: "h-8", fontSize: 1.35, padding: "px-0.5" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-1.5" },
        lg: { height: "h-16", fontSize: 1.45, padding: "px-1" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const hasExplicitWidth = className.includes('w-') || className.includes('max-w-');
    const widthClass = fullWidth ? 'w-full' : (hasExplicitWidth ? '' : 'w-max');

    const containerJustify = 'justify-center';
    const textJustify = icon ? 'justify-start' : 'justify-center';

    return (
        <div className={`relative group ${widthClass} ${config.height} min-w-0 ${props.disabled ? 'opacity-50 pointer-events-none' : ''} ${className}`}>
            <button 
                className={`w-full h-full relative z-10 transition-all outline-none active:translate-y-0.5`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                {/* SLANTED BACKGROUND */}
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-9deg] overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* SLANTED CONTENT WRAPPER */}
                <div className={`relative z-20 h-full w-full pointer-events-none flex items-center ${containerJustify} skew-x-[-9deg] min-w-0 ${children ? config.padding : 'px-1.5'}`}>
                    <div className={`flex items-center ${containerJustify} gap-0.5 w-full h-full min-w-0 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                                {icon}
                            </div>
                        )}

                        {children && (
                            <div className={`flex-1 h-full min-w-0 flex items-center ${textJustify}`}>
                                {typeof children === 'string' || typeof children === 'number' ? (
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        skewFactor={0.9} 
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                    />
                                ) : (
                                    <div className={`flex items-center ${textJustify} drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] w-full h-full min-w-0`}>
                                        {children}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { ActivityLogEntry, ProgressionRewardType } from '../../types';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { SlantedButton } from '../ui/SlantedButton';
import { BoosterIcon, CreditIcon, GoldIcon, TokenIcon, OmegaBoxIcon } from '../ui/CurrencyIcons';

type FilterType = 'all' | ProgressionRewardType;

const ActivityLogItem = React.memo(({ item }: { item: ActivityLogEntry }) => {
    let iconScale = 'scale-[1.45]'; 
    if (item.type === 'card') iconScale = 'scale-[0.6]'; 
    else if (item.type === 'credits' || item.type === 'gold' || item.type === 'tokens') iconScale = 'scale-[1.55]';

    return (
        <div className="flex items-center justify-between py-2 px-3 bg-slate-800 border border-slate-700/50 rounded-lg shadow-sm cursor-default">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 flex items-center justify-center overflow-visible">
                    <div className={iconScale}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>
                <div>
                    <div className="font-black text-[0.75rem] tracking-tight text-white uppercase italic leading-tight">{item.title}</div>
                    <div className="text-[0.5rem] text-white/70 font-bold uppercase tracking-[0.2em] mt-0.5">Manifest Claim</div>
                </div>
            </div>
            <div className="text-right flex flex-col items-end shrink-0">
                 <div className="text-[0.7rem] font-black text-white uppercase tracking-tighter tabular-nums leading-none mb-1">{item.date}</div>
                 <div className="text-[0.55rem] font-bold text-white/50 uppercase tracking-widest tabular-nums leading-none">{item.time}</div>
            </div>
        </div>
    );
});

export const ActivityLogSection: React.FC<{ logs: ActivityLogEntry[] }> = ({ logs }) => {
    const [activeFilter, setActiveFilter] = useState<FilterType>('all');

    const filteredLogs = useMemo(() => {
        if (activeFilter === 'all') return logs;
        return logs.filter(log => log.type === activeFilter);
    }, [logs, activeFilter]);

    const filters: { id: FilterType; icon: React.ReactNode; variant: any }[] = [
        { id: 'all', icon: <span className="text-[0.6rem] font-black italic">ALL</span>, variant: 'primary' },
        { id: 'booster', icon: <BoosterIcon size="xs" />, variant: 'success' },
        { id: 'credits', icon: <CreditIcon size="xs" />, variant: 'blue' },
        { id: 'gold', icon: <GoldIcon size="xs" />, variant: 'warning' },
        { id: 'tokens', icon: <TokenIcon size="xs" />, variant: 'danger' },
        { id: 'box', icon: <OmegaBoxIcon size="xs" />, variant: 'primary' },
    ];

    return (
        <div className="flex flex-col h-full overflow-hidden">
            {/* FIXED HEADER SECTION */}
            <div className="shrink-0 pt-4">
                <div className="flex flex-col gap-4 mb-4 px-4">
                    <div className="flex items-center gap-3">
                        <h3 className="text-[0.6rem] font-black text-white uppercase tracking-[0.4em] whitespace-nowrap">Activity Archive</h3>
                        <div className="flex-1 h-px bg-white/5" />
                    </div>
                </div>

                {/* Flat Filter Bar */}
                <div className="flex items-center gap-1.5 mb-4 overflow-x-auto pb-1 scrollbar-hide px-4">
                    {filters.map((f) => (
                        <SlantedButton
                            key={f.id}
                            variant={activeFilter === f.id ? f.variant : 'secondary'}
                            size="xs"
                            className={`!w-[13vw] max-w-[3rem] shrink-0 !transition-none shadow-lg ${activeFilter === f.id ? 'opacity-100' : 'opacity-40'}`}
                            onClick={() => setActiveFilter(f.id)}
                        >
                            {f.icon}
                        </SlantedButton>
                    ))}
                </div>
            </div>

            {/* SCROLLABLE LIST AREA */}
            <div className="flex-1 overflow-y-auto px-4 pb-24 custom-scrollbar scrolling-touch">
                <div className="mb-4 text-center">
                    <span className="text-[0.5rem] font-black text-white/20 uppercase tracking-[0.3em] italic">Only the last 200 entries shown</span>
                </div>

                <div className="space-y-2">
                    {filteredLogs.length > 0 ? (
                        filteredLogs.map((item) => (
                            <ActivityLogItem key={item.id} item={item} />
                        ))
                    ) : (
                        <div className="h-32 flex flex-col items-center justify-center border-2 border-dashed border-white/5 rounded-xl bg-white/5">
                            <div className="opacity-10 mb-2">
                                 {filters.find(f => f.id === activeFilter)?.icon}
                            </div>
                            <span className="text-[0.55rem] font-black text-white/20 uppercase tracking-[0.4em]">No {activeFilter} entries</span>
                        </div>
                    )}
                </div>

                <div className="h-10 w-full" />
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';
import { SlantedButton } from '../ui/SlantedButton';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction, inspect } = useUser();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');
    const [claimingIdx, setClaimingIdx] = useState<number | null>(null);
    const [successIdx, setSuccessIdx] = useState<number | null>(null);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType, idx: number) => {
        if (claimingIdx !== null || successIdx !== null) return;
        setClaimingIdx(idx);
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 600 });
        setClaimingIdx(null);
        if (success) {
            setSuccessIdx(idx);
            setTimeout(() => setSuccessIdx(null), 2500);
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            {/* OPAQUE PERFORMANCE LAYER - Entrance Animation Removed */}
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">

                {/* Hardware-accelerated animated gradient layer */}
                <div className="absolute inset-0 animated-bg z-0" />

                {/* SOLID OPAQUE TABBED HEADER */}
                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 px-3 z-40 flex items-center justify-between">
                    <div className="w-32 h-6">
                        <GameText 
                            text="COLLECTION LEVEL" 
                            baseFontSize={1.1} 
                            className="text-white font-black italic tracking-tighter uppercase drop-shadow-lg" 
                        />
                    </div>

                    <div className="flex items-center gap-1.5">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem] shadow-xl"
                            onClick={() => setActiveTab('REWARDS')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12z" />
                                <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 18.75h-9m9 0a2.25 2.25 0 002.25-2.25V5.25A2.25 2.25 0 0016.5 3h-9A2.25 2.25 0 005.25 5.25v11.25a2.25 2.25 0 002.25 2.25m9 0V21a.75.75 0 01-.75.75h-7.5a.75.75 0 01-.75-.75v-2.25" />
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 14.25v6m0 0H8.25m3.75 0h3.75M7.5 4.875C7.5 3.125 9.125 1.5 12 1.5s4.5 1.625 4.5 3.375V7.5h-9V4.875zM4.5 10.5c0-1.5 1-3 3-3v3c0 1.5-1 3-3 3s-3-1.5-3-3zm15 0c0-1.5-1-3-3-3v3c0 1.5 1 3 3 3s3-1.5 3-3z" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton 
                            variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem] shadow-xl"
                            onClick={() => setActiveTab('ACTIVITY')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        /* STATIC REWARD MANIFEST VIEW */
                        <div className="flex-1 flex flex-col min-h-0">
                            {/* Hero Display */}
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />
                                <div className="h-10 w-full px-4 relative z-10">
                                    <GameText 
                                        text={progressionData.collectionLevel.toLocaleString()} 
                                        baseFontSize={3.2} 
                                        className="text-white font-black italic tracking-tighter drop-shadow-[0_0_20px_rgba(99,102,241,0.6)]" 
                                    />
                                </div>
                            </div>

                            {/* Tracks Area */}
                            <div className="flex-1 flex flex-col px-4 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2">
                                    <div className="h-4 w-full">
                                        <GameText 
                                            text="Reward Manifest" 
                                            baseFontSize={0.65} 
                                            className="text-indigo-300 font-black uppercase tracking-[0.4em]" 
                                        />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {progressionData.tracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIdx === idx}
                                            isSuccess={successIdx === idx}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        /* ACTIVITY LOG VIEW - Non-scrolling container, internal scrolling */
                        <div className="flex-1 flex flex-col bg-slate-950/40 overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                {/* COMPACT FOOTER - No Background, Slanted Button */}
                <div className="shrink-0 h-16 flex items-center justify-center z-50 mb-2">
                    <SlantedButton 
                        variant="secondary" 
                        size="md" 
                        onClick={onClose}
                        className="shadow-2xl !w-[45vw] max-w-[12rem] !h-10"
                    >
                        CLOSE
                    </SlantedButton>
                </div>
            </div>
        </Portal>
    );
};

