                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 px-3 z-40 flex items-center justify-between">
                    <div className="w-32 h-6">
                        <GameText 
                            text="COLLECTION LEVEL" 
                            baseFontSize={1.1} 
                            className="text-white font-black italic tracking-tighter uppercase drop-shadow-lg" 
