                                <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 18.75h-9m9 0a2.25 2.25 0 002.25-2.25V5.25A2.25 2.25 0 0016.5 3h-9A2.25 2.25 0 005.25 5.25v11.25a2.25 2.25 0 002.25 2.25m9 0V21a.75.75 0 01-.75.75h-7.5a.75.75 0 01-.75-.75v-2.25" />
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 14.25v6m0 0H8.25m3.75 0h3.75M7.5 4.875C7.5 3.125 9.125 1.5 12 1.5s4.5 1.625 4.5 3.375V7.5h-9V4.875zM4.5 10.5c0-1.5 1-3 3-3v3c0 1.5-1 3-3 3s-3-1.5-3-3zm15 0c0-1.5-1-3-3-3v3c0 1.5 1 3 3 3s3-1.5 3-3z" />
