import { UserProfile, ProgressionData, ProgressionTrack } from '../../types';
import { REWARD_SEQUENCE } from './mockData';
import { progressionStore } from './mockDb';

/**
 * Calculates current progression for all tracks based on a Rolling Reward Waterfall.
 * Each track has a capacity and an offset.
 */
export const getProgressionDataInternal = (user: UserProfile): ProgressionData => {
    const GCL = user.level;

    const tracks: ProgressionTrack[] = REWARD_SEQUENCE.map((config, i) => {
        const totalPoints = GCL + config.offset;
        const currentProgress = totalPoints % config.capacity;
        const totalEarnedCount = Math.floor(totalPoints / config.capacity);

        // Unclaimed logic: Total rewards generated by level - rewards already taken
        const claimedCount = progressionStore.claimedCounts[i] || 0;
        const unclaimedCount = Math.max(0, totalEarnedCount - claimedCount);

        return {
            type: config.type,
            label: config.label,
            currentXP: currentProgress,
            targetXP: config.capacity,
            unclaimedCount,
            nextRewardAmount: config.amount,
        };
    });

    return { 
        collectionLevel: GCL, 
        tracks 
    };
};

import { UserProfile, ProgressionData, ActivityLogEntry, ProgressionRewardType } from '../../types';
import { REWARD_SEQUENCE } from './mockData';
import { progressionStore } from './mockDb';
import { getProgressionDataInternal } from './progressionLogic';
import { generateInstanceId } from '../../utils/id';

/**
 * PROGRESSION SERVICE
 * Orchestrates CL rewards, claiming, and the global activity archive.
 */
export const progressionService = {
    async getProgression(user: UserProfile): Promise<ProgressionData> {
        await new Promise(resolve => setTimeout(resolve, 400));
        return getProgressionDataInternal(user);
    },

    async getActivityLog(): Promise<ActivityLogEntry[]> {
        await new Promise(resolve => setTimeout(resolve, 200));
        return progressionStore.activityLog;
    },

    async claimReward(user: UserProfile, type: ProgressionRewardType) {
        await new Promise(resolve => setTimeout(resolve, 500));

        const currentData = getProgressionDataInternal(user);
        const trackIdx = currentData.tracks.findIndex(t => t.type === type && t.unclaimedCount > 0);

        if (trackIdx === -1) return { success: false };

        const rewardConfig = REWARD_SEQUENCE[trackIdx];
        const updatedProfile = { ...user };

        // 1. Increment persistent claim counter
        const newClaimed = [...progressionStore.claimedCounts];
        newClaimed[trackIdx]++;
        progressionStore.claimedCounts = newClaimed;

        // 2. Grant rewards to user profile
        if (type === 'credits') updatedProfile.credits += rewardConfig.amount as number;
        else if (type === 'gold') updatedProfile.gold += rewardConfig.amount as number;
        else if (type === 'tokens') updatedProfile.tokens += rewardConfig.amount as number;

        // 3. Log to activity archive
        const now = new Date();
        const newLog: ActivityLogEntry = {
            id: generateInstanceId(),
            title: `${rewardConfig.amount} ${rewardConfig.label}`,
            type,
            date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
            time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
            amount: rewardConfig.amount
        };

        progressionStore.activityLog = [newLog, ...progressionStore.activityLog];

        return { 
            success: true, 
            updatedProfile, 
            progressionData: getProgressionDataInternal(updatedProfile),
            activityLog: [...progressionStore.activityLog]
        };
    }
};

