import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';
import { useUI } from '../contexts/UIContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  scrollRef: React.RefObject<HTMLElement>;
  vaultRef: React.RefObject<HTMLElement>;
  archiveRef: React.RefObject<HTMLElement>;
}

// Gesture Constants
const DRAG_MOVE_THRESHOLD = 12; // Pixels moved before we definitely lock into 'Drag' mode
const SCROLL_MIN_THRESHOLD = 6;  // Pixels moved before we definitely lock into 'Scroll' mode
const PICKUP_DELAY = 220;       
const FRICTION = 0.95; 
const MIN_VELOCITY = 0.1;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef, vaultRef, archiveRef }: UseCollectionDragProps) => {
    const { user } = useUser();
    const { inspect } = useUI();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    const stateRef = useRef({
        isScrolling: false,
        isDragging: false,
        isIntentLocked: false, 
        startPos: { x: 0, y: 0 },
        lastValidPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        samples: [] as { dy: number, dt: number }[]
    });

    const inertiaFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runInertia = useCallback(() => {
        const el = scrollRef.current;
        if (!el) return;
        const g = stateRef.current;
        el.scrollTop -= g.velocity;
        g.velocity *= FRICTION;
        if (el.scrollTop <= 0 || el.scrollTop >= el.scrollHeight - el.clientHeight) g.velocity = 0;
        if (Math.abs(g.velocity) > MIN_VELOCITY) {
            inertiaFrameRef.current = requestAnimationFrame(runInertia);
        } else {
            g.velocity = 0;
            inertiaFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopInertia = useCallback(() => {
        if (inertiaFrameRef.current !== null) {
            cancelAnimationFrame(inertiaFrameRef.current);
            inertiaFrameRef.current = null;
        }
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;
        stopInertia();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { 
            // Lock all pointer events to this element until release
            target.setPointerCapture(e.pointerId); 
        } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        const isOwned = user.collection.includes(card?.id || '');
        const inDeck = user.decks[user.activeDeckId]?.includes(card?.id || '');
        const canDrag = card && (origin === 'vault' || (isOwned && !inDeck));

        stateRef.current = {
            isScrolling: false,
            isDragging: false,
            isIntentLocked: false,
            startPos,
            lastValidPos: startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (canDrag) {
            pickupTimerRef.current = window.setTimeout(() => {
                stateRef.current.isIntentLocked = true;
                // If we aren't scrolling, and enough time passed, we are likely dragging
                if (!stateRef.current.isScrolling) {
                    stateRef.current.isDragging = true;
                }
            }, PICKUP_DELAY);
        }
    }, [scrollRef, stopInertia, user]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const g = stateRef.current;
            const now = performance.now();
            const dt = now - g.lastTime;
            const deltaX = e.clientX - g.startPos.x;
            const deltaY = e.clientY - g.startPos.y;
            const moveDist = Math.hypot(deltaX, deltaY);

            g.lastValidPos = { x: e.clientX, y: e.clientY };

            if (dt > 0) {
                const dy = e.clientY - g.lastY;
                g.samples.push({ dy, dt });
                if (g.samples.length > 3) g.samples.shift();
                const totalDy = g.samples.reduce((sum, s) => sum + s.dy, 0);
                const totalDt = g.samples.reduce((sum, s) => sum + s.dt, 0);
                g.velocity = totalDy / (totalDt / 16.67);
                g.lastY = e.clientY;
                g.lastTime = now;
            }

            // GESTURE ARBITRATION
            if (!g.isScrolling && !g.isDragging) {
                // If they move primarily horizontal OR the pickup timer finished, it's a DRAG
                if (Math.abs(deltaX) > DRAG_MOVE_THRESHOLD || (g.isIntentLocked && moveDist > DRAG_MOVE_THRESHOLD)) {
                    g.isDragging = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                } 
                // If they move primarily vertical and intent isn't locked, it's a SCROLL
                else if (Math.abs(deltaY) > SCROLL_MIN_THRESHOLD && !g.isIntentLocked) {
                    g.isScrolling = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                }
            }

            if (g.isScrolling && scrollRef.current) {
                scrollRef.current.scrollTop = g.startScrollTop - deltaY;
                return;
            }

            if (g.isDragging) {
                if (e.cancelable) e.preventDefault();
                if (!dragState.active && moveDist > DRAG_MOVE_THRESHOLD) {
                    setDragState(prev => prev ? { ...prev, active: true } : null);
                }
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const g = stateRef.current;
            const endX = e.type === 'pointercancel' ? g.lastValidPos.x : e.clientX;
            const endY = e.type === 'pointercancel' ? g.lastValidPos.y : e.clientY;
            const moveDist = Math.hypot(endX - g.startPos.x, endY - g.startPos.y);

            const isInside = (ref: React.RefObject<HTMLElement>, x: number, y: number) => {
                if (!ref.current) return false;
                const rect = ref.current.getBoundingClientRect();
                return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
            };

            // RESOLVE INTERACTION
            if (g.isDragging && dragState.active && g.hasCard) {
                // Was definitely a drag
                if (dragState.origin === 'archive' && isInside(vaultRef, endX, endY)) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && isInside(archiveRef, endX, endY)) {
                    onRemove(dragState.card.id);
                }
            } 
            else if (!g.isScrolling && !g.isDragging && g.hasCard) {
                // If the finger release happened within a small radius of the start,
                // and we didn't scroll or drag, it's a Tap.
                if (moveDist < DRAG_MOVE_THRESHOLD) {
                    inspect(dragState.card);
                }
            }

            // Final inertia scroll
            if (g.isScrolling && Math.abs(g.velocity) > MIN_VELOCITY) {
                inertiaFrameRef.current = requestAnimationFrame(runInertia);
            }

            setDragState(null);
            g.isScrolling = false;
            g.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, vaultRef, archiveRef, runInertia]);

    return { dragState, handlePointerDown };
};

import React, { createContext, useContext, useState, ReactNode, useCallback } from 'react';
import { CardInstance, CardDefinition, LocationDefinition, SeasonRewardType, ProgressionRewardType } from '../types';
import { audio } from '../services/audio';

interface BoxReward {
    type: 'box';
    boxType: 'MYSTERY' | 'MEGA';
    title: string;
    description: string;
}

export interface SeasonRewardInfo {
    type: 'level_info';
    level: number;
    rewardType: SeasonRewardType | ProgressionRewardType;
    rewardAmount: string | number;
    isClaimed?: boolean;
    cardDef?: CardDefinition;
}

interface InspectingCard {
    data: CardInstance | CardDefinition;
    borderOverride?: string;
}

interface UIContextType {
    inspectingCard: InspectingCard | null;
    inspectingLocation: LocationDefinition | null;
    inspectingCurrency: { type: 'gold' | 'credits', amount: number } | null;
    inspectingBox: BoxReward | null;
    inspectingReward: SeasonRewardInfo | null;
    inspect: (item: any, options?: { borderOverride?: string }) => void;
    closeInspector: () => void;
    storeScrollTarget: string | null;
    setStoreScrollTarget: (id: string | null) => void;
    // Level Up Flow
    pendingLevelIncrement: number;
    signalLevelUp: (increment: number) => void;
    clearLevelUpSignal: () => void;
}

const UIContext = createContext<UIContextType | null>(null);

export const UIProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [inspectingCard, setInspectingCard] = useState<InspectingCard | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);
    const [inspectingBox, setInspectingBox] = useState<BoxReward | null>(null);
    const [inspectingReward, setInspectingReward] = useState<SeasonRewardInfo | null>(null);
    const [storeScrollTarget, setStoreScrollTarget] = useState<string | null>(null);
    const [pendingLevelIncrement, setPendingLevelIncrement] = useState(0);

    const inspect = useCallback((item: any, options?: { borderOverride?: string }) => {
        if (!item) return; 
        audio.playUiClick();

        setInspectingCurrency(null); 
        setInspectingCard(null); 
        setInspectingLocation(null); 
        setInspectingBox(null); 
        setInspectingReward(null);

        if ('type' in item) {
            if (item.type === 'gold' || item.type === 'credits') setInspectingCurrency(item);
            else if (item.type === 'box') setInspectingBox(item);
            else if (item.type === 'level_info') setInspectingReward(item);
        } 
        else if (('instanceId' in item) || ('basePower' in item) || ('definitionId' in item)) {
            setInspectingCard({ data: item, borderOverride: options?.borderOverride });
        }
        else if ('description' in item) {
            setInspectingLocation(item);
        }
    }, []);

    const closeInspector = useCallback(() => { 
        setInspectingCard(null); 
        setInspectingLocation(null); 
        setInspectingCurrency(null); 
        setInspectingBox(null); 
        setInspectingReward(null); 
    }, []);

    const signalLevelUp = useCallback((increment: number) => {
        setPendingLevelIncrement(increment);
    }, []);

    const clearLevelUpSignal = useCallback(() => {
        setPendingLevelIncrement(0);
    }, []);

    return (
        <UIContext.Provider value={{ 
            inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward,
            inspect, closeInspector, storeScrollTarget, setStoreScrollTarget,
            pendingLevelIncrement, signalLevelUp, clearLevelUpSignal
        }}>
            {children}
        </UIContext.Provider>
    );
};

export const useUI = () => {
    const context = useContext(UIContext);
    if (!context) throw new Error('useUI must be used within a UIProvider');
    return context;
};

import React, { createContext, useContext, useState, ReactNode, useEffect, useCallback, useMemo } from 'react';
import { UserProfile, StoreData, CardDefinition, CardRarity, SeasonPassData, ProgressionData, ActivityLogEntry, PurchaseResponse } from '../types';
import { audio } from '../services/audio';
import { api } from '../services/api';
import { CARDS } from '../constants';
import { useUI } from './UIContext';

export type CollectionSortOption = 'Cost' | 'Power' | 'Name' | 'Newest';

interface UserContextType {
    user: UserProfile;
    storeData: StoreData | null;
    isStoreLoading: boolean;
    seasonPassData: SeasonPassData | null;
    isSeasonLoading: boolean;
    syncSeasonPass: () => Promise<void>;
    debugSwitchSeason: () => Promise<void>; 
    progressionData: ProgressionData | null;
    activityLog: ActivityLogEntry[];
    isProgressionLoading: boolean;
    syncProgression: (showLoading?: boolean) => Promise<void>;

    collectionSort: CollectionSortOption;
    setCollectionSort: (s: CollectionSortOption) => void;
    collectionFilterSearch: string;
    setCollectionFilterSearch: (s: string) => void;
    collectionFilterTags: string[];
    toggleCollectionFilterTag: (tag: string) => void;

    performSynchronizedAction: (apiCall: () => Promise<PurchaseResponse>, options?: { visualDelay?: number, sfx?: string }) => Promise<boolean>;
    syncStore: () => Promise<void>;
    upgradeCard: (id: string) => void;
    setActiveDeck: (id: number) => void;
    updateDeck: (id: number, cardIds: string[]) => void;
    activeDeck: string[];
}

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode; initialUser: UserProfile }> = ({ children, initialUser }) => {
    const [user, setUser] = useState<UserProfile>(initialUser);
    const [storeData, setStoreData] = useState<StoreData | null>(null);
    const [isStoreLoading, setIsStoreLoading] = useState(false);
    const [seasonPassData, setSeasonPassData] = useState<SeasonPassData | null>(null);
    const [isSeasonLoading, setIsSeasonLoading] = useState(false);
    const [progressionData, setProgressionData] = useState<ProgressionData | null>(null);
    const [activityLog, setActivityLog] = useState<ActivityLogEntry[]>([]);
    const [isProgressionLoading, setIsProgressionLoading] = useState(false);

    const [collectionSort, setCollectionSort] = useState<CollectionSortOption>('Cost');
    const [collectionFilterSearch, setCollectionFilterSearch] = useState('');
    const [collectionFilterTags, setCollectionFilterTags] = useState<string[]>([]);

    const ui = useUI();

    const toggleCollectionFilterTag = useCallback((tag: string) => {
        setCollectionFilterTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    }, []);

    const syncSeasonPass = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            const data = await api.getSeasonPass(user);
            setSeasonPassData(data);
        } catch (e) {
            console.error("Season Sync Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [user]);

    const debugSwitchSeason = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            await api.debugNextSeason();
            await syncSeasonPass();
        } catch (e) {
            console.error("Debug Switch Season Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [syncSeasonPass]);

    const syncProgression = useCallback(async (showLoading = false) => {
        if (showLoading) setIsProgressionLoading(true);
        try {
            const data = await api.getProgression(user);
            const logs = await api.getActivityLog();
            setProgressionData(data);
            setActivityLog(logs);
        } catch (e) {
            console.error("Progression Sync Failed", e);
        } finally {
            setIsProgressionLoading(false);
        }
    }, [user]);

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    const performSynchronizedAction = async (
        apiCall: () => Promise<PurchaseResponse | any>, 
        options?: { visualDelay?: number, sfx?: string }
    ): Promise<boolean> => {
        try {
            const result = await apiCall();
            if (result.success && result.updatedProfile) {
                if (options?.visualDelay) {
                    await new Promise(resolve => setTimeout(resolve, options.visualDelay));
                }
                setUser(result.updatedProfile);
                if ('progressionData' in result && result.progressionData) setProgressionData(result.progressionData);
                if ('activityLog' in result && result.activityLog) setActivityLog(result.activityLog);
                audio.play((options?.sfx || 'sfx_victory') as any, 0.5);
                return true;
            }
        } catch (err) {
            console.error("Synchronized Action Failed:", err);
        }
        return false;
    };

    const upgradeCard = useCallback((cardId: string) => {
        setUser(prev => {
            const def = CARDS.find(c => c.id === cardId);
            if (!def) return prev;
            const currentRarity = prev.cardRarities[cardId] || def.rarity;
            const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
            const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
            if (!nextRarity) return prev;
            const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
            const levelIncrementMap: Record<string, number> = { "Rare": 1, "Epic": 4, "Legendary": 10 };
            const cost = costMap[nextRarity];
            const increment = levelIncrementMap[nextRarity];

            if (prev.credits >= cost) {
                audio.play('sfx_victory', 0.6);
                // Signal UI to trigger progression animation flow
                ui.signalLevelUp(increment);

                return {
                    ...prev,
                    credits: prev.credits - cost,
                    level: prev.level + increment,
                    cardRarities: { ...prev.cardRarities, [cardId]: nextRarity }
                };
            }
            return prev;
        });
    }, [ui]);

    const setActiveDeck = useCallback(async (deckId: number) => {
        try {
            const updated = await api.updateActiveDeck(user, deckId);
            setUser(updated);
        } catch (e) {
            console.error("Update active deck failed", e);
        }
    }, [user]);

    const updateDeck = useCallback((deckId: number, cardIds: string[]) => {
        setUser(prev => ({
            ...prev,
            decks: { ...prev.decks, [deckId]: cardIds }
        }));
    }, []);

    useEffect(() => {
        syncStore(true);
        syncSeasonPass();
        syncProgression(true);
    }, [user.id, syncStore, syncSeasonPass, syncProgression]);

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, storeData, isStoreLoading,
            seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason,
            progressionData, activityLog, isProgressionLoading, syncProgression,
            collectionSort, setCollectionSort, collectionFilterSearch, setCollectionFilterSearch,
            collectionFilterTags, toggleCollectionFilterTag,
            performSynchronizedAction, syncStore, 
            upgradeCard, setActiveDeck, updateDeck, activeDeck
        }}>{children}</UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) throw new Error('useUser must be used within a UserProvider');
    return context;
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { InspectorOverlay } from './components/InspectorOverlay';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { api } from './services/api';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey, UserProfile } from './types';
import { UserProvider } from './contexts/UserContext';
import { UIProvider, useUI } from './contexts/UIContext';

function AppContent({ userProfile }: { userProfile: UserProfile }) {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isAppReady, setIsAppReady] = useState(false); 
  const { pendingLevelIncrement } = useUI();

  const gridRef = useRef<HTMLDivElement>(null);

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  useEffect(() => {
    const initApp = async () => {
      try {
          await preloadAssets((progress) => setLoadingProgress(progress));
          requestAnimationFrame(() => {
              requestAnimationFrame(() => {
                  setIsAppReady(true);
              });
          });
      } catch (err) {
          console.error("Critical System Failure:", err);
          setIsAppReady(true);
      }
    };
    initApp();
  }, []);

  // Listen for level up increments to trigger auto-navigation
  useEffect(() => {
    if (pendingLevelIncrement > 0 && activeScreen !== 'DECK') {
        navigateTo('DECK');
    }
  }, [pendingLevelIncrement, activeScreen, navigateTo]);

  useEffect(() => {
      if (!isLoggedIn || !isAppReady) return;
      const targetBgm = activeScreen === 'GAME' ? 'bgm_game' : 'bgm_menu';
      audio.playBgm(targetBgm);
  }, [activeScreen, isLoggedIn, isAppReady]);

  const activeConfig = WORLDS[activeScreen];
  const prevConfig = prevScreen ? WORLDS[prevScreen] : null;

  const renderedScreens = useMemo(() => {
      const keys = Object.keys(WORLDS) as ScreenKey[];
      return keys.filter(key => {
          if (!isAppReady) return true;
          const config = WORLDS[key];
          if (config.isPersistent) return true;
          const dx = Math.abs(config.x - activeConfig.x);
          const dy = Math.abs(config.y - activeConfig.y);
          if (dx <= 1 && dy <= 1) return true;
          if (isTransitioning && prevConfig) {
              const pdx = Math.abs(config.x - prevConfig.x);
              const pdy = Math.abs(config.y - prevConfig.y);
              return pdx <= 1 && pdy <= 1;
          }
          return false;
      });
  }, [activeScreen, prevScreen, isTransitioning, isAppReady, WORLDS, activeConfig, prevConfig]);

  const handleLogin = async () => {
      await audio.init(); 
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      audio.stopBgm();
      setIsLoggedIn(false);
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  return (
    <AppShell>
        <LoadingScreen progress={loadingProgress} isVisible={!isAppReady} />
        <div className={`w-full h-full relative transition-opacity duration-700 ${isAppReady ? 'opacity-100' : 'opacity-0'}`} aria-hidden={!isAppReady}>
            {!isLoggedIn && (
                <div className="absolute inset-0 z-[100] bg-slate-950">
                    <LoginScreen onLogin={handleLogin} />
                </div>
            )}
            <InspectorOverlay />
            <div ref={gridRef} className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform" style={containerStyle}>
                {renderedScreens.map((key) => {
                    const config = WORLDS[key];
                    const ScreenComponent = config.component;
                    const isActive = key === activeScreen;
                    const isVisible = isActive || (isTransitioning && (Math.abs(config.x - activeConfig.x) <= 1 && Math.abs(config.y - activeConfig.y) <= 1));
                    return (
                        <div key={key} className={`absolute w-full h-full top-0 left-0 overflow-hidden transition-opacity duration-300 ${!isVisible ? 'pointer-events-none invisible opacity-0' : 'pointer-events-auto visible opacity-100'}`} style={{ transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)`}}>
                            <ScreenComponent onNavigate={navigateTo} onExit={() => navigateTo('MENU')} onBack={() => navigateTo('MENU')} onStartGame={handleStartGame} onLogout={handleLogout} activeScreen={activeScreen} />
                        </div>
                    );
                })}
            </div>
            {isLoggedIn && activeScreen !== 'GAME' && ( <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} /> )}
        </div>
    </AppShell>
  );
}

export default function App() {
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);

  useEffect(() => {
    const loadProfile = async () => {
        try {
            const profile = await api.getProfile('u1');
            setUserProfile(profile);
        } catch (err) {
            console.error("Profile load failed", err);
        }
    };
    loadProfile();
  }, []);

  if (!userProfile) return null;

  return (
    <UIProvider>
        <UserProvider initialUser={userProfile}>
            <AppContent userProfile={userProfile} />
        </UserProvider>
    </UIProvider>
  );
}

