import React, { useState, useEffect, useRef, useMemo } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { inspect, pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');
    const [claimingIdx, setClaimingIdx] = useState<number | null>(null);
    const [successIdx, setSuccessIdx] = useState<number | null>(null);

    // Visual Chasing Engine State
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const isChasingRef = useRef(pendingLevelIncrement > 0);

    useEffect(() => {
        if (isChasingRef.current && visualLevel < user.level) {
            const timer = setTimeout(() => {
                const nextLevel = visualLevel + 1;

                // Lap Detection Logic
                const newLaps = new Set<number>();
                REWARD_SEQUENCE.forEach((conf, i) => {
                    // A lap occurs if we land exactly on zero modulo capacity
                    // or if the integer division changed. Simple modulo check:
                    if ((nextLevel + conf.offset) % conf.capacity === 0) {
                        newLaps.add(i);
                        audio.play('sfx_ui_click', 1.2); // Satisfaction ping
                    }
                });

                if (newLaps.size > 0) {
                    setLappingIndices(newLaps);
                    // Clear lap glow after a duration
                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), 1000);
                }

                setVisualLevel(nextLevel);
                audio.play('sfx_ui_hover', 0.4);
            }, 500);
            return () => clearTimeout(timer);
        } else if (visualLevel >= user.level && isChasingRef.current) {
            isChasingRef.current = false;
            clearLevelUpSignal();
        }
    }, [visualLevel, user.level, clearLevelUpSignal]);

    // Compute derived visual track data based on visualLevel
    const visualTracks: ProgressionTrack[] = useMemo(() => {
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPoints = visualLevel + config.offset;
            const currentXP = totalPoints % config.capacity;

            // Map authoritative unclaimed count but override with visual XP state if needed
            // For simplicity, we trust the DB's unclaimed count but drive bar with visualLevel
            const realTrack = progressionData?.tracks[i];

            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: realTrack?.unclaimedCount || 0,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType, idx: number) => {
        if (claimingIdx !== null || successIdx !== null || isChasingRef.current) return;
        setClaimingIdx(idx);
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 600 });
        setClaimingIdx(null);
        if (success) {
            setSuccessIdx(idx);
            setTimeout(() => setSuccessIdx(null), 2500);
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />

                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0">
                        <h1 className="text-[1.35rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none">
                            COLLECTION LEVEL
                        </h1>
                    </div>

                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('REWARDS')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton 
                            variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('ACTIVITY')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />
                                <div className="h-10 w-full px-4 relative z-10">
                                    <GameText 
                                        text={visualLevel.toLocaleString()} 
                                        baseFontSize={3.2} 
                                        className="text-white font-black italic tracking-tighter drop-shadow-[0_0_20px_rgba(99,102,241,0.6)]" 
                                    />
                                </div>
                            </div>

                            <div className="flex-1 flex flex-col px-4 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2">
                                    <div className="h-4 w-full">
                                        <GameText 
                                            text="Progression Details" 
                                            baseFontSize={0.65} 
                                            className="text-indigo-300 font-black uppercase tracking-[0.4em]" 
                                        />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIdx === idx}
                                            isSuccess={successIdx === idx}
                                            isLapping={lappingIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton 
                        variant="danger" 
                        size="md" 
                        onClick={onClose}
                        className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8"
                    >
                        CLOSE
                    </SlantedButton>
                </div>
            </div>
        </Portal>
    );
};

import React from 'react';
import { ProgressionTrack } from '../../types';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { getVariant, getScale, getColors } from './progressionUtils';
import { GameText } from '../ui/GameText';

interface ProgressionTrackRowProps {
    track: ProgressionTrack;
    isClaiming: boolean;
    isSuccess: boolean;
    isLapping?: boolean;
    onClaim: () => void;
    onInspect: () => void;
}

const ProgressionTrackRowComponent: React.FC<ProgressionTrackRowProps> = ({
    track,
    isClaiming,
    isSuccess,
    isLapping = false,
    onClaim,
    onInspect
}) => {
    const styles = getColors(track.type);
    const variant = getVariant(track.type);
    const percent = (track.currentXP / track.targetXP) * 100;
    const canClaim = track.unclaimedCount > 0;

    const renderClaimLabel = () => {
        if (isClaiming) {
            return (
                <div className="h-4 w-full animate-pulse">
                    <GameText text="CLAIMING..." baseFontSize={0.65} className="text-white/60 font-black italic uppercase tracking-widest" />
                </div>
            );
        }

        if (isSuccess) {
            return (
                <div className="h-5 w-full">
                    <GameText text="SUCCESS!" baseFontSize={0.75} className="text-white font-black italic uppercase tracking-tighter" />
                </div>
            );
        }

        const rewardLabel = track.type === 'box' ? track.label : track.label.toUpperCase();

        return (
            <div className="flex flex-col items-center justify-center w-full h-full py-0.5 pointer-events-none">
                <div className="h-2 w-full mb-0.5 opacity-70">
                    <GameText text="CLAIM" baseFontSize={0.45} className="text-white font-black uppercase tracking-widest" />
                </div>
                <div className="h-4 w-full">
                    <GameText 
                        text={track.type === 'box' ? rewardLabel : `${track.nextRewardAmount} ${rewardLabel}`} 
                        baseFontSize={0.7} 
                        className="text-white font-black italic uppercase tracking-tighter drop-shadow-md" 
                    />
                </div>
            </div>
        );
    };

    return (
        <div 
            className="grid grid-cols-[1fr_30vw] gap-3 items-center h-16 will-change-transform"
            style={{ contain: 'content' }} 
        >
            {/* XP Track Area */}
            <div className="relative h-full flex items-center cursor-pointer group" onClick={onInspect}>
                {/* Reward Label Header */}
                <div className="absolute top-[0.35rem] left-[2.8rem] right-0 z-50 pointer-events-none h-4 flex items-center">
                    <GameText 
                        text={`${track.nextRewardAmount} ${track.label}`} 
                        baseFontSize={0.6} 
                        className="text-white/90 font-black italic uppercase tracking-wider drop-shadow-[0_1.5px_2px_rgba(0,0,0,1)]" 
                    />
                </div>

                {/* Visual Icon Badge */}
                <div className={`absolute left-0 z-40 transition-all duration-300 origin-center drop-shadow-xl ${isLapping ? 'scale-125' : ''}`}>
                    <HexBadge variant={variant} size="lg">
                        <div className="relative w-full h-full overflow-visible">
                            <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                <RewardIconGraphic type={track.type as any} size="lg" />
                            </div>
                        </div>
                    </HexBadge>
                </div>

                {/* Progress Bar Container */}
                <div className={`absolute left-8 right-0 h-8 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)]`}>
                    <div 
                        className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-500 ease-out`} 
                        style={{ width: `${isLapping ? 100 : percent}%` }} 
                    />
                    <div className="absolute inset-0 flex items-center justify-center pl-10 pr-2 py-0 pointer-events-none">
                        <div className="h-4 w-full">
                            <GameText 
                                text={`${isLapping ? track.targetXP : track.currentXP} / ${track.targetXP} CL`} 
                                baseFontSize={0.75} 
                                className="text-white font-black italic tracking-[0.15em] drop-shadow-[0_2px_3px_rgba(0,0,0,1)]" 
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* Button Column */}
            <div className="flex flex-col items-center gap-1 h-full justify-center">
                <button 
                    disabled={(isClaiming || !canClaim) && !isSuccess}
                    onClick={(e) => { e.stopPropagation(); onClaim(); }}
                    className={`
                        w-[30vw] h-10 relative group outline-none transition-all
                        ${(!canClaim || isClaiming) && !isSuccess ? 'opacity-40 grayscale pointer-events-none' : ''}
                        ${isLapping ? 'scale-105 ring-2 ring-white animate-pulse' : ''}
                    `}
                >
                    <div className={`
                        absolute inset-0 rounded skew-x-[-9deg] border transition-all duration-300 bg-gradient-to-b
                        ${isSuccess ? 'from-emerald-500 to-emerald-800 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]' : 
                          (canClaim ? (variant === 'blue' ? 'from-blue-500 to-blue-800 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]' : 
                                       variant === 'warning' ? 'from-amber-500 to-amber-800 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]' :
                                       variant === 'danger' ? 'from-red-500 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]' :
                                       variant === 'success' ? 'from-emerald-500 to-emerald-800 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]' :
                                       'from-indigo-500 to-indigo-800 border-indigo-400 shadow-[0_0.2rem_0_rgb(30,27,75)]') 
                                    : 'from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]')}
                    `} />

                    {/* Lap Glow Overlay */}
                    {isLapping && (
                        <div className="absolute inset-0 bg-white/40 skew-x-[-9deg] blur-md animate-pulse" />
                    )}

                    <div className="relative h-full flex items-center justify-center skew-x-[-9deg] px-1 pointer-events-none">
                        {renderClaimLabel()}
                    </div>
                </button>
                <div className="h-2 w-full">
                    <GameText 
                        text={`${track.unclaimedCount} UNCLAIMED`} 
                        baseFontSize={0.45} 
                        className={`font-black uppercase tracking-[0.2em] drop-shadow-sm ${canClaim ? 'text-indigo-300' : 'text-slate-600'}`} 
                    />
                </div>
            </div>
        </div>
    );
};

