import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { getVariant, getScale, getColors } from './progressionUtils';
import { GameText } from '../ui/GameText';

interface ProgressionTrackRowProps {
    track: ProgressionTrack;
    isClaiming: boolean;
    isSuccess: boolean;
    isLapping?: boolean;
    onClaim: () => void;
    onInspect: () => void;
}

const ProgressionTrackRowComponent: React.FC<ProgressionTrackRowProps> = ({
    track,
    isClaiming,
    isSuccess,
    isLapping = false,
    onClaim,
    onInspect
}) => {
    const styles = getColors(track.type);
    const variant = getVariant(track.type);
    const percent = (track.currentXP / track.targetXP) * 100;
    const canClaim = track.unclaimedCount > 0;

    const renderClaimLabel = () => {
        if (isClaiming) {
            return (
                <div className="h-4 w-full animate-pulse">
                    <GameText text="CLAIMING..." baseFontSize={0.65} className="text-white/60 font-black italic uppercase tracking-widest" />
                </div>
            );
