                    {isLapping && (
                        <div className="absolute inset-0 bg-white/30 animate-pulse pointer-events-none" />
                    )}
                </div>
            </div>

            {/* Button Column - Decoupled from isLapping, pulses only when canClaim is true */}
            <div className="flex flex-col items-center gap-1 h-full justify-center">
                <button 
                    disabled={(isClaiming || !canClaim) && !isSuccess}
                    onClick={(e) => { e.stopPropagation(); onClaim(); }}
                    className={`
