import React, { useState, useEffect, useRef, useMemo } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS (2x Speed)
const BASE_TICK_MS = 250;
const LAP_MECHANICAL_PAUSE_MS = 200;
const LAP_OVERRIDE_DURATION_MS = 150;
const BUTTON_FLASH_DURATION_MS = 1000;

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { inspect, pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');
    const [claimingIdx, setClaimingIdx] = useState<number | null>(null);
    const [successIdx, setSuccessIdx] = useState<number | null>(null);

    // Visual Chasing Engine State
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());
    const isChasingRef = useRef(pendingLevelIncrement > 0);

    useEffect(() => {
        if (isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;

            // 1. Lap Detection Logic
            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) {
                    newLaps.add(i);
                }
            });

            // 2. Dynamic Delay
            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    // Set both lapping (for the bar) and newlyGained (for the button flash)
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    // Lap "Ding" SFX
                    audio.play('sfx_ui_click', 1.6); 

                    // Clear lap override quickly so the "Zero" state is rendered
                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVERRIDE_DURATION_MS);

                    // Clear button flash after requested duration
                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);

            return () => clearTimeout(timer);
        } else if (visualLevel >= user.level && isChasingRef.current) {
            isChasingRef.current = false;
            // Clear the signal so parents know we are done, 
            // but the modal stays open due to local state in DeckScreen.
            clearLevelUpSignal();
        }
    }, [visualLevel, user.level, clearLevelUpSignal]);

    // Compute derived visual track data based on visualLevel
    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];

        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;

            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;

            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);

            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType, idx: number) => {
        if (claimingIdx !== null || successIdx !== null || isChasingRef.current) return;
        setClaimingIdx(idx);
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 600 });
        setClaimingIdx(null);
        if (success) {
            setSuccessIdx(idx);
            setTimeout(() => setSuccessIdx(null), 2500);
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />

                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0">
                        <h1 className="text-[1.35rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none">
                            COLLECTION LEVEL
                        </h1>
                    </div>

                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('REWARDS')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton 
                            variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('ACTIVITY')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />
                                <div className="h-10 w-full px-4 relative z-10">
                                    <GameText 
                                        text={visualLevel.toLocaleString()} 
                                        baseFontSize={3.2} 
                                        className="text-white font-black italic tracking-tighter drop-shadow-[0_0_20px_rgba(99,102,241,0.6)]" 
                                    />
                                </div>
                            </div>

                            <div className="flex-1 flex flex-col px-4 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2">
                                    <div className="h-4 w-full">
                                        <GameText 
                                            text="Progression Details" 
                                            baseFontSize={0.65} 
                                            className="text-indigo-300 font-black uppercase tracking-[0.4em]" 
                                        />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIdx === idx}
                                            isSuccess={successIdx === idx}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton 
                        variant="danger" 
                        size="md" 
                        onClick={onClose}
                        className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8"
                    >
                        CLOSE
                    </SlantedButton>
                </div>
            </div>
        </Portal>
    );
};

