/**
 * PROGRESSION SERVICE
 * Orchestrates CL rewards, claiming, and the global activity archive.
 */
export const progressionService = {
    async getProgression(user: UserProfile): Promise<ProgressionData> {
        await new Promise(resolve => setTimeout(resolve, 400));
        return getProgressionDataInternal(user);
    },

    async getActivityLog(): Promise<ActivityLogEntry[]> {
        await new Promise(resolve => setTimeout(resolve, 200));
        return progressionStore.activityLog;
    },

    async claimReward(user: UserProfile, type: ProgressionRewardType) {
        await new Promise(resolve => setTimeout(resolve, 400));

        const currentData = getProgressionDataInternal(user);
        const trackIdx = currentData.tracks.findIndex(t => t.type === type && t.unclaimedCount > 0);

        if (trackIdx === -1) return { success: false };

        const rewardConfig = REWARD_SEQUENCE[trackIdx];
        const updatedProfile = { ...user };

        // 1. Increment persistent claim counter
        const newClaimed = [...progressionStore.claimedCounts];
        newClaimed[trackIdx]++;
        progressionStore.claimedCounts = newClaimed;

        // 2. Grant rewards to user profile
        if (type === 'credits') updatedProfile.credits += rewardConfig.amount as number;
        else if (type === 'gold') updatedProfile.gold += rewardConfig.amount as number;
        else if (type === 'tokens') updatedProfile.tokens += rewardConfig.amount as number;

        // 3. Log to activity archive
        const now = new Date();
        const newLog: ActivityLogEntry = {
            id: generateInstanceId(),
            title: `${rewardConfig.amount} ${rewardConfig.label}`,
            type,
            date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
            time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
            amount: rewardConfig.amount
        };

        progressionStore.activityLog = [newLog, ...progressionStore.activityLog];

        return { 
            success: true, 
            updatedProfile, 
            progressionData: getProgressionDataInternal(updatedProfile),
            activityLog: [...progressionStore.activityLog]
        };
    },

    async claimAllRewards(user: UserProfile, type: ProgressionRewardType) {
        await new Promise(resolve => setTimeout(resolve, 700));

        const currentData = getProgressionDataInternal(user);
        const trackIdx = currentData.tracks.findIndex(t => t.type === type);

        if (trackIdx === -1 || currentData.tracks[trackIdx].unclaimedCount <= 0) {
            return { success: false };
        }

        const count = currentData.tracks[trackIdx].unclaimedCount;
        const rewardConfig = REWARD_SEQUENCE[trackIdx];
        const updatedProfile = { ...user };

        // 1. Clear all for this track
        const newClaimed = [...progressionStore.claimedCounts];
        newClaimed[trackIdx] += count;
        progressionStore.claimedCounts = newClaimed;

        // 2. Grant bulk rewards
        const totalAmount = (rewardConfig.amount as number) * count;
        if (type === 'credits') updatedProfile.credits += totalAmount;
        else if (type === 'gold') updatedProfile.gold += totalAmount;
        else if (type === 'tokens') updatedProfile.tokens += totalAmount;

        // 3. Log a single bulk entry
        const now = new Date();
        const newLog: ActivityLogEntry = {
            id: generateInstanceId(),
            title: `BULK: ${totalAmount} ${rewardConfig.label}`,
            type,
            date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
            time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
            amount: totalAmount
        };

        progressionStore.activityLog = [newLog, ...progressionStore.activityLog];

        return { 
            success: true, 
            updatedProfile, 
            progressionData: getProgressionDataInternal(updatedProfile),
            activityLog: [...progressionStore.activityLog]
        };
    }
};

import { GameState, UserProfile, PurchaseResponse, StoreData, SeasonPassData, ProgressionData, ActivityLogEntry, ProgressionRewardType } from '../types';
import { PendingMove } from './planning';
import { generateAiMoves } from './ai';

// Domain Services
import { profileService } from './api/profileService';
import { storeService } from './api/storeService';
import { seasonService } from './api/seasonService';
import { progressionService } from './api/progressionService';

/**
 * UNIFIED API GATEWAY
 * This is the public interface for the application. It delegates all
 * logic to domain-specific services for better maintainability.
 */
export const api = {
    // 1. Profile & Decks
    getProfile: (userId: string) => profileService.getProfile(userId),
    updateActiveDeck: (user: UserProfile, deckId: number) => profileService.updateActiveDeck(user, deckId),
    addCollectionLevels: (user: UserProfile, increment: number) => profileService.addCollectionLevels(user, increment),

    // 2. Battle Engine (Server-Side Moves)
    async submitTurn(gameState: GameState, playerMoves: PendingMove[]): Promise<{ opponentMoves: PendingMove[] }> {
        await new Promise(resolve => setTimeout(resolve, 600));
        return { opponentMoves: generateAiMoves(gameState) };
    },

    // 3. Economy & Store
    getStoreOffers: (user: UserProfile) => storeService.getOffers(user),
    purchaseOffer: (user: UserProfile, offerId: string, txnId: string) => storeService.purchaseOffer(user, offerId, txnId),

    // 4. Seasons
    getSeasonPass: (user: UserProfile) => seasonService.getSeasonPass(user),
    debugNextSeason: () => seasonService.debugNextSeason(),

    // 5. Progression & Archive
    getProgression: (user: UserProfile) => progressionService.getProgression(user),
    getActivityLog: () => progressionService.getActivityLog(),
    claimProgressionReward: (user: UserProfile, type: ProgressionRewardType) => progressionService.claimReward(user, type),
    claimAllProgressionRewards: (user: UserProfile, type: ProgressionRewardType) => progressionService.claimAllRewards(user, type),
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue' | 'black';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'xs' | 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onHoldComplete?: (e: React.PointerEvent) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onHoldComplete,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);
    const hasTriggeredHold = useRef(false);

    const variants = {
        primary: "from-indigo-500 to-indigo-800 border-indigo-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
        black: "from-slate-900 to-black border-slate-800 shadow-[0_0.2rem_0_rgb(0,0,0)]",
    };

    const sizeConfigs = {
        xs: { height: "h-[1.65rem]", fontSize: 1.2, padding: "px-1" },
        sm: { height: "h-8", fontSize: 1.35, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-3" },
        lg: { height: "h-16", fontSize: 1.45, padding: "px-4" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        hasTriggeredHold.current = false;
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100 && !hasTriggeredHold.current) {
                hasTriggeredHold.current = true;
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                if (onHoldComplete) {
                    onHoldComplete(e);
                } else if (onClick) {
                    const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                    onClick(sEvent);
                }

                setIsHolding(false);
                onHoldChange?.(false);
                setProgress(0);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    const handleButtonClick = (e: React.MouseEvent<HTMLButtonElement>) => {
        // If a hold duration is set, we only trigger onClick if the hold DID NOT complete
        if (holdDuration > 0 && hasTriggeredHold.current) {
            return;
        }
        onClick?.(e);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const hasExplicitWidth = className.includes('w-') || className.includes('max-w-');
    const widthClass = fullWidth ? 'w-full' : (hasExplicitWidth ? '' : 'w-max');

    const containerJustify = (icon && children !== undefined) ? 'justify-start' : 'justify-center';
    const textJustify = 'justify-center';

    return (
        <div className={`relative group ${widthClass} ${config.height} min-w-0 ${props.disabled ? 'opacity-50 pointer-events-none' : ''} ${className}`}>
            <button 
                className={`w-full h-full relative z-10 outline-none`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={handleButtonClick}
                role="button"
                {...props}
            >
                {/* SLANTED BACKGROUND */}
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-9deg] overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className={`absolute inset-y-0 left-0 bg-white/30 transition-all duration-75 ease-linear pointer-events-none`} style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* SLANTED CONTENT WRAPPER */}
                <div className={`relative z-20 h-full w-full pointer-events-none flex items-center ${containerJustify} skew-x-[-9deg] min-w-0 ${config.padding}`}>
                    <div className={`flex items-center ${containerJustify} gap-0 w-full h-full min-w-0 ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] pr-0.5">
                                {icon}
                            </div>
                        )}

                        {children !== undefined && (
                            <div className={`flex-1 h-full min-w-0 flex items-center ${textJustify}`}>
                                {typeof children === 'string' || typeof children === 'number' ? (
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        skewFactor={0.9} 
                                        maxScale={1.8}
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                    />
                                ) : (
                                    <div className={`flex items-center ${textJustify} drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] w-full h-full min-w-0`}>
                                        {children}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS (4x Speed vs original, 2x speed vs previous)
const BASE_TICK_MS = 125;
const LAP_MECHANICAL_PAUSE_MS = 100;
const LAP_OVERRIDE_DURATION_MS = 75;
const BUTTON_FLASH_DURATION_MS = 500;

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { inspect, pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    // Using a Set to allow parallel claiming animations
    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());

    // Visual Chasing Engine State
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());
    const isChasingRef = useRef(pendingLevelIncrement > 0);

    useEffect(() => {
        if (isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;

            // 1. Lap Detection Logic
            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) {
                    newLaps.add(i);
                }
            });

            // 2. Dynamic Delay
            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    // Set both lapping (for the bar) and newlyGained (for the button flash)
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    // Lap "Ding" SFX
                    audio.play('sfx_ui_click', 1.6); 

                    // Clear lap override quickly so the "Zero" state is rendered
                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVERRIDE_DURATION_MS);

                    // Clear button flash after requested duration
                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);

            return () => clearTimeout(timer);
        } else if (visualLevel >= user.level && isChasingRef.current) {
            isChasingRef.current = false;
            clearLevelUpSignal();
        }
    }, [visualLevel, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];

        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;

            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;

            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);

            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || isChasingRef.current) return;

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.add(idx);
            return next;
        });

        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 400 });

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.delete(idx);
            return next;
        });

        if (success) {
            setSuccessIndices(prev => {
                const next = new Set(prev);
                next.add(idx);
                return next;
            });
            setTimeout(() => setSuccessIndices(prev => {
                const next = new Set(prev);
                next.delete(idx);
                return next;
            }), 1500);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || isChasingRef.current) return;

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.add(idx);
            return next;
        });

        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user, type), { visualDelay: 600 });

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.delete(idx);
            return next;
        });

        if (success) {
            setSuccessIndices(prev => {
                const next = new Set(prev);
                next.add(idx);
                return next;
            });
            setTimeout(() => setSuccessIndices(prev => {
                const next = new Set(prev);
                next.delete(idx);
                return next;
            }), 2000);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />

                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0">
                        <h1 className="text-[1.35rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none">
                            COLLECTION LEVEL
                        </h1>
                    </div>

                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('REWARDS')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton 
                            variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('ACTIVITY')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />
                                <div className="h-10 w-full px-4 relative z-10">
                                    <GameText 
                                        text={visualLevel.toLocaleString()} 
                                        baseFontSize={3.2} 
                                        className="text-white font-black italic tracking-tighter drop-shadow-[0_0_20px_rgba(99,102,241,0.6)]" 
                                    />
                                </div>
                            </div>

                            <div className="flex-1 flex flex-col px-4 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2">
                                    <div className="h-4 w-full">
                                        <GameText 
                                            text="Progression Details" 
                                            baseFontSize={0.65} 
                                            className="text-white font-black uppercase tracking-[0.4em]" 
                                        />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton 
                        variant="danger" 
                        size="md" 
                        onClick={onClose}
                        className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8"
                    >
                        CLOSE
                    </SlantedButton>
                </div>
            </div>
        </Portal>
    );
};

import React from 'react';
import { ProgressionTrack } from '../../types';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { getVariant, getScale, getColors } from './progressionUtils';
import { GameText } from '../ui/GameText';
import { SlantedButton } from '../ui/SlantedButton';

interface ProgressionTrackRowProps {
    track: ProgressionTrack;
    isClaiming: boolean;
    isSuccess: boolean;
    isLapping?: boolean;
    isNewlyGained?: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
    onInspect: () => void;
}

const ProgressionTrackRowComponent: React.FC<ProgressionTrackRowProps> = ({
    track,
    isClaiming,
    isSuccess,
    isLapping = false,
    isNewlyGained = false,
    onClaim,
    onClaimAll,
    onInspect
}) => {
    const styles = getColors(track.type);
    const variant = getVariant(track.type);
    const percent = (track.currentXP / track.targetXP) * 100;
    const canClaim = track.unclaimedCount > 0;

    // Determine the button variant based on the track reward type and current status
    const getButtonVariant = () => {
        if (isSuccess) return 'success';
        if (!canClaim) return 'secondary';

        switch(track.type) {
            case 'booster': return 'success'; 
            case 'credits': return 'blue';
            case 'gold': return 'warning';
            case 'tokens': return 'danger';
            case 'box': return 'primary';
            default: return 'primary';
        }
    };

    const getButtonLabel = () => {
        if (isClaiming) return track.unclaimedCount > 1 ? "CLAIMING ALL..." : "CLAIMING...";
        if (isSuccess) return "SUCCESS!";

        const rewardLabel = track.type === 'box' ? track.label : track.label.toUpperCase();
        return `CLAIM\n${track.type === 'box' ? rewardLabel : `${track.nextRewardAmount} ${rewardLabel}`}`;
    };

    return (
        <div 
            className="grid grid-cols-[1fr_36vw] gap-3 items-center h-16 px-1.5 will-change-transform overflow-visible"
            style={{ contain: 'layout' }} 
        >
            {/* XP Track Area */}
            <div className="relative h-full flex items-center cursor-pointer group" onClick={onInspect}>
                {/* Floating Reward Label */}
                <div className="absolute top-[0.1rem] left-[2.8rem] right-0 z-50 pointer-events-none h-4 flex items-center">
                    <GameText 
                        text={`${track.nextRewardAmount} ${track.label}`} 
                        baseFontSize={0.6} 
                        className="text-white font-black italic uppercase tracking-wider drop-shadow-[0_1.5px_2px_rgba(0,0,0,1)]" 
                    />
                </div>

                <div className={`absolute left-0 z-40 transition-all duration-300 origin-center drop-shadow-xl`}>
                    <HexBadge variant={variant} size="lg">
                        <div className="relative w-full h-full overflow-visible">
                            <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                <RewardIconGraphic type={track.type as any} size="lg" />
                            </div>
                        </div>
                    </HexBadge>
                </div>

                <div className={`
                    absolute left-8 right-0 h-8 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] transition-all duration-300
                    ${isLapping ? 'ring-2 ring-white shadow-[0_0_20px_rgba(255,255,255,0.6)] scale-[1.01]' : ''}
                `}>
                    <div 
                        className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-500 ease-out`} 
                        style={{ width: `${isLapping ? 100 : percent}%` }} 
                    />
                    {/* Progress Text */}
                    <div className="absolute inset-0 flex items-center justify-start pl-6 pr-2 py-0 pointer-events-none">
                        <div className="h-4 w-full">
                            <GameText 
                                text={`${isLapping ? track.targetXP : track.currentXP} / ${track.targetXP} CL`} 
                                baseFontSize={0.75} 
                                className="text-white font-black italic tracking-wider drop-shadow-[0_2px_3px_rgba(0,0,0,1)]" 
                            />
                        </div>
                    </div>
                    {isLapping && (
                        <div className="absolute inset-0 bg-white/30 animate-pulse pointer-events-none" />
                    )}
                </div>
            </div>

            {/* Button Column */}
            <div className="flex flex-col items-center gap-0.5 h-full justify-center overflow-visible pr-1">
                <SlantedButton
                    variant={getButtonVariant()}
                    size="md"
                    fullWidth
                    disabled={(isClaiming || !canClaim) && !isSuccess}
                    onClick={(e) => { e.stopPropagation(); onClaim(); }}
                    onHoldComplete={(e) => { e.stopPropagation(); onClaimAll(); }}
                    holdDuration={track.unclaimedCount > 1 ? 1000 : 0}
                    className={`
                        !h-11 shadow-lg transition-all
                        ${isNewlyGained ? 'animate-gain-flash' : ''}
                        ${isClaiming ? 'animate-pulse' : ''}
                    `}
                >
                    {getButtonLabel()}
                </SlantedButton>

                <div className="h-2 w-full">
                    <GameText 
                        text={`${track.unclaimedCount} UNCLAIMED`} 
                        baseFontSize={0.4} 
                        className={`font-black uppercase tracking-[0.1em] drop-shadow-sm text-white`} 
                    />
                </div>
            </div>

            <style>{`
                @keyframes gain-flash {
                    0% { filter: brightness(1); }
                    20% { filter: brightness(2.5); box-shadow: 0 0 20px rgba(255,255,255,0.6); }
                    100% { filter: brightness(1); box-shadow: none; }
                }
                .animate-gain-flash {
                    animation: gain-flash 0.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
                }
            `}</style>
        </div>
    );
};

