                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40 min-h-[5.5rem] justify-center overflow-visible">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />

                                <div className="relative z-10 w-full flex justify-center items-center h-14 overflow-visible px-1">
                                    {/* ANIMATION STRING CONTAINER */}
                                    <div 
                                        className={`absolute flex items-center justify-center transition-all duration-500 ease-in-out gap-0 overflow-visible w-full px-2
                                            ${isAnimatingLevels ? 'opacity-100 scale-100' : 'opacity-0 scale-95 pointer-events-none'}`}
                                    >
                                        <div className="h-10 shrink-0">
                                            <GameText 
                                                text="CL" 
                                                baseFontSize={headerFontSize} 
                                                className="text-white/40 font-black italic tracking-tighter mr-2" 
                                            />
                                        </div>
                                        <div className="h-10 opacity-70 shrink-0">
                                            <GameText 
                                                text={startLevel.toLocaleString()} 
                                                baseFontSize={headerFontSize} 
                                                className="text-white font-black italic tracking-tighter drop-shadow-md" 
                                            />
                                        </div>
                                        <div className="h-10 shrink-0 ml-1.5">
                                            <GameText 
                                                text={`+${totalGain}`} 
                                                baseFontSize={headerFontSize} 
                                                className="text-emerald-400 font-black italic tracking-tighter drop-shadow-[0_0_10px_rgba(52,211,153,0.4)]" 
                                            />
                                        </div>
                                        <div className="h-10 opacity-40 px-1 shrink-0">
                                            <GameText text="->" baseFontSize={headerFontSize * 0.7} className="text-white font-black italic" />
                                        </div>
                                        {/* INCREMENTING LEVEL NUMBER */}
                                        <div className="relative h-12 flex items-center justify-center shrink-0 min-w-0">
                                            <GameText 
                                                text={visualLevel.toLocaleString()} 
                                                baseFontSize={headerFontSize} 
                                                className={`
                                                    text-white font-black italic tracking-tighter transition-all duration-200
                                                    animate-pulse-glow drop-shadow-[0_0_15px_rgba(255,255,255,0.8)]
                                                `}
