                                    {/* FINAL CENTERED DISPLAY: Using w-screen and huge horizontal padding to escape any possible clipping wall */}
                                    <div 
                                        className={`absolute w-screen flex items-center justify-center transition-all duration-700 ease-out overflow-visible
                                            ${showFinalCentred ? 'opacity-100 scale-125 translate-y-0' : 'opacity-0 scale-50 translate-y-4 pointer-events-none'}`}
                                    >
                                        <div className="h-16 w-max px-20 overflow-visible">
                                            <GameText 
                                                text={visualLevel.toLocaleString()} 
                                                baseFontSize={headerFontSize} 
                                                className={`
                                                    text-white font-black italic tracking-tighter drop-shadow-[0_0_25px_rgba(99,102,241,0.8)]
                                                    ${isCompletionFlare ? 'animate-completion-flare' : ''}
                                                `} 
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex-1 flex flex-col px-2 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2 px-2">
                                    <div className="h-4 w-full">
                                        <GameText 
                                            text="Progression Details" 
                                            baseFontSize={0.65} 
                                            className="text-white font-black uppercase tracking-[0.4em]" 
                                        />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton 
                        variant="danger" 
                        size="md" 
                        onClick={onClose}
                        className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8"
                    >
                        CLOSE
                    </SlantedButton>
                </div>
            </div>

            <style>{`
                @keyframes detailed-entry {
                    from { opacity: 0; transform: translateY(10px) scale(0.9); }
                    to { opacity: 1; transform: translateY(0) scale(1); }
                }
                .animate-detailed-entry {
                    animation: detailed-entry 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }

                @keyframes pulse-glow {
                    0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.4)); }
                    50% { filter: brightness(1.6) drop-shadow(0 0 25px rgba(255,255,255,1)); }
                }
                .animate-pulse-glow {
                    animation: pulse-glow 1.2s ease-in-out infinite;
                }

                @keyframes completion-flare {
                    0% { filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); }
                    20% { filter: brightness(3.5); text-shadow: 0 0 60px rgba(99,102,241,1); }
                    100% { filter: brightness(1); text-shadow: 0 0 20px rgba(99,102,241,0.6); }
                }
                .animate-completion-flare {
                    animation: completion-flare 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </Portal>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 125;
const LAP_MECHANICAL_PAUSE_MS = 100;
const LAP_OVERRIDE_DURATION_MS = 75;
const BUTTON_FLASH_DURATION_MS = 500;

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { inspect, pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());

    // Visual Chasing Engine State
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [isAnimatingLevels, setIsAnimatingLevels] = useState(pendingLevelIncrement > 0);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);
    const [showFinalCentred, setShowFinalCentred] = useState(pendingLevelIncrement === 0);

    // Lock in the starting point for the header string
    const startLevel = useMemo(() => user.level - pendingLevelIncrement, [pendingLevelIncrement === 0]);
    const totalGain = pendingLevelIncrement;

    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());
    const isChasingRef = useRef(pendingLevelIncrement > 0);

    useEffect(() => {
        if (isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) {
                    newLaps.add(i);
                }
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    audio.play('sfx_ui_click', 1.6); 

                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVERRIDE_DURATION_MS);

                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);

            return () => clearTimeout(timer);
        } else if (visualLevel >= user.level && isChasingRef.current) {
            isChasingRef.current = false;

            // Initiation of Completion Sequence
            setTimeout(() => {
                setIsAnimatingLevels(false);

                setTimeout(() => {
                    setShowFinalCentred(true);
                    setIsCompletionFlare(true);
                    audio.play('sfx_victory', 0.6);
                    clearLevelUpSignal();

                    setTimeout(() => setIsCompletionFlare(false), 1000);
                }, 400); 
            }, 300);
        }
    }, [visualLevel, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];

        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;

            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;

            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);

            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || isChasingRef.current) return;

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.add(idx);
            return next;
        });

        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 400 });

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.delete(idx);
            return next;
        });

        if (success) {
            setSuccessIndices(prev => {
                const next = new Set(prev);
                next.add(idx);
                return next;
            });
            setTimeout(() => setSuccessIndices(prev => {
                const next = new Set(prev);
                next.delete(idx);
                return next;
            }), 1500);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || isChasingRef.current) return;

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.add(idx);
            return next;
        });

        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user, type), { visualDelay: 600 });

        setClaimingIndices(prev => {
            const next = new Set(prev);
            next.delete(idx);
            return next;
        });

        if (success) {
            setSuccessIndices(prev => {
                const next = new Set(prev);
                next.add(idx);
                return next;
            });
            setTimeout(() => setSuccessIndices(prev => {
                const next = new Set(prev);
                next.delete(idx);
                return next;
            }), 2000);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />

                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg overflow-visible">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">
                            COLLECTION LEVEL
                        </h1>
                    </div>

                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('REWARDS')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton 
                            variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                            size="xs"
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]"
                            onClick={() => setActiveTab('ACTIVITY')}
                        >
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40 min-h-[5.5rem] justify-center overflow-visible">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />

                                <div className="relative z-10 w-full flex justify-center items-center h-14 overflow-visible px-4">
                                    {/* 
                                        SIMPLIFIED ANIMATION HEADER: 
                                        Using standard HTML with large right-padding to solve italic clipping once and for all.
                                        Avoiding complex auto-scaling measurement logic for this sequence.
                                    */}
                                    <div 
                                        className={`absolute flex items-center justify-center transition-all duration-500 ease-in-out gap-2 overflow-visible w-full
                                            ${isAnimatingLevels ? 'opacity-100 scale-100' : 'opacity-0 scale-95 pointer-events-none'}`}
                                    >
                                        <div className="flex items-center gap-1.5 whitespace-nowrap font-black italic tracking-tighter pr-10">
                                            <span className="text-white/40 text-xl">CL</span>
                                            <span className="text-white/70 text-2xl">{startLevel.toLocaleString()}</span>
                                            <span className="text-emerald-400 text-2xl drop-shadow-[0_0_10px_rgba(52,211,153,0.4)]">+{totalGain}</span>
                                            <span className="text-white/30 text-lg">-></span>
                                            <span className="text-white text-3xl animate-pulse-glow drop-shadow-[0_0_15px_rgba(255,255,255,0.8)]">
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>

                                    {/* 
                                        FINAL CENTERED DISPLAY: 
                                        Centered standard element with massive right-padding buffer.
                                    */}
                                    <div 
                                        className={`absolute w-screen flex items-center justify-center transition-all duration-700 ease-out overflow-visible
                                            ${showFinalCentred ? 'opacity-100 scale-125 translate-y-0' : 'opacity-0 scale-50 translate-y-4 pointer-events-none'}`}
                                    >
                                        <div className="font-black italic tracking-tighter text-white text-5xl drop-shadow-[0_0_25px_rgba(99,102,241,0.8)] pr-12 text-center whitespace-nowrap">
                                            <span className={isCompletionFlare ? 'animate-completion-flare block' : 'block'}>
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex-1 flex flex-col px-2 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2 px-2">
                                    <div className="h-4 w-full">
                                        <GameText 
                                            text="Progression Details" 
                                            baseFontSize={0.65} 
                                            className="text-white font-black uppercase tracking-[0.4em]" 
                                        />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton 
                        variant="danger" 
                        size="md" 
                        onClick={onClose}
                        className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8"
                    >
                        CLOSE
                    </SlantedButton>
                </div>
            </div>

            <style>{`
                @keyframes pulse-glow {
                    0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.4)); }
                    50% { filter: brightness(1.6) drop-shadow(0 0 25px rgba(255,255,255,1)); }
                }
                .animate-pulse-glow {
                    animation: pulse-glow 1.2s ease-in-out infinite;
                }

                @keyframes completion-flare {
                    0% { filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); }
                    20% { filter: brightness(3.5); text-shadow: 0 0 60px rgba(99,102,241,1); }
                    100% { filter: brightness(1); text-shadow: 0 0 20px rgba(99,102,241,0.6); }
                }
                .animate-completion-flare {
                    animation: completion-flare 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </Portal>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 125;
const LAP_MECHANICAL_PAUSE_MS = 100;
const LAP_OVERRIDE_DURATION_MS = 75;
const BUTTON_FLASH_DURATION_MS = 500;

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';
type HeaderStage = 'INITIAL' | 'FORMULA' | 'FINAL';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { inspect, pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    // --- Header Animation Flow State ---
    const [headerStage, setHeaderStage] = useState<HeaderStage>(pendingLevelIncrement > 0 ? 'INITIAL' : 'FINAL');
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());

    const startLevel = useMemo(() => user.level - pendingLevelIncrement, [pendingLevelIncrement === 0]);
    const totalGain = pendingLevelIncrement;
    const isChasingRef = useRef(false);

    // Flow Controller
    useEffect(() => {
        if (pendingLevelIncrement > 0 && headerStage === 'INITIAL') {
            const timer = setTimeout(() => {
                setHeaderStage('FORMULA');
                isChasingRef.current = true;
            }, 1000); // 1 Second Pause as requested
            return () => clearTimeout(timer);
        }
    }, [pendingLevelIncrement, headerStage]);

    // Numerical Chasing Logic
    useEffect(() => {
        if (isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) {
                    newLaps.add(i);
                }
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });
                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    audio.play('sfx_ui_click', 1.6); 

                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVERRIDE_DURATION_MS);

                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);

            return () => clearTimeout(timer);
        } else if (visualLevel >= user.level && isChasingRef.current) {
            isChasingRef.current = false;

            // Wait slightly before collapsing formula back to center
            setTimeout(() => {
                setHeaderStage('FINAL');
                setIsCompletionFlare(true);
                audio.play('sfx_victory', 0.6);
                clearLevelUpSignal();
                setTimeout(() => setIsCompletionFlare(false), 1000);
            }, 600);
        }
    }, [visualLevel, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || isChasingRef.current) return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 400 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 1500);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || isChasingRef.current) return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user, type), { visualDelay: 600 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 2000);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />

                {/* --- NAVIGATION HEADER --- */}
                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg overflow-visible">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">
                            COLLECTION LEVEL
                        </h1>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('REWARDS')}>
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('ACTIVITY')}>
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            {/* --- ANIMATED PROGRESSION HEADER --- */}
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40 min-h-[6rem] justify-center overflow-visible">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />

                                <div className="relative z-10 w-full flex justify-center items-center h-14 overflow-visible px-4">

                                    {/* STAGE 1: INITIAL CENTERED (Paused for 1s) */}
                                    <div className={`absolute w-screen flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'INITIAL' ? 'opacity-100 scale-100' : 'opacity-0 scale-75 pointer-events-none'}`}>
                                        <div className="font-black italic tracking-tighter text-white/90 text-4xl pr-12 drop-shadow-lg">
                                            {startLevel.toLocaleString()}
                                        </div>
                                    </div>

                                    {/* STAGE 2: FORMULA (Old + Gain -> New) */}
                                    <div className={`absolute flex items-center justify-center transition-all duration-500 overflow-visible w-full
                                        ${headerStage === 'FORMULA' ? 'opacity-100 scale-100' : 'opacity-0 scale-110 pointer-events-none'}`}>
                                        <div className="flex items-center gap-2 whitespace-nowrap font-black italic tracking-tighter pr-12">
                                            <span className="text-white/30 text-xl">CL</span>
                                            <span className="text-white/60 text-2xl">{startLevel.toLocaleString()}</span>
                                            <span className="text-emerald-400 text-2xl drop-shadow-[0_0_10px_rgba(52,211,153,0.4)]">+{totalGain}</span>
                                            <span className="text-white/20 text-lg">-></span>
                                            <span className="text-white text-3xl animate-pulse-glow drop-shadow-[0_0_15px_rgba(255,255,255,0.8)]">
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>

                                    {/* STAGE 3: FINAL CENTERED (Completion) */}
                                    <div className={`absolute w-screen flex items-center justify-center transition-all duration-700 ease-out overflow-visible
                                        ${headerStage === 'FINAL' ? 'opacity-100 scale-125 translate-y-0' : 'opacity-0 scale-50 translate-y-4 pointer-events-none'}`}>
                                        <div className="font-black italic tracking-tighter text-white text-5xl drop-shadow-[0_0_30px_rgba(99,102,241,0.8)] pr-12 text-center whitespace-nowrap">
                                            <span className={isCompletionFlare ? 'animate-completion-flare block' : 'block'}>
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* --- CONTENT AREA --- */}
                            <div className="flex-1 flex flex-col px-2 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2 px-2">
                                    <div className="h-4 w-full">
                                        <GameText text="Progression Details" baseFontSize={0.65} className="text-white font-black uppercase tracking-[0.4em]" />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>
                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton variant="danger" size="md" onClick={onClose} className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8">
                        CLOSE
                    </SlantedButton>
                </div>
            </div>

            <style>{`
                @keyframes pulse-glow {
                    0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.4)); }
                    50% { filter: brightness(1.6) drop-shadow(0 0 25px rgba(255,255,255,1)); }
                }
                .animate-pulse-glow {
                    animation: pulse-glow 1.2s ease-in-out infinite;
                }
                @keyframes completion-flare {
                    0% { filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); }
                    20% { filter: brightness(3.5); text-shadow: 0 0 60px rgba(99,102,241,1); }
                    100% { filter: brightness(1); text-shadow: 0 0 20px rgba(99,102,241,0.6); }
                }
                .animate-completion-flare {
                    animation: completion-flare 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </Portal>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 125;
const LAP_MECHANICAL_PAUSE_MS = 100;
const LAP_OVERRIDE_DURATION_MS = 75;
const BUTTON_FLASH_DURATION_MS = 500;

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';
type HeaderStage = 'INITIAL' | 'FORMULA' | 'FINAL';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { inspect, pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    // --- Header Animation Flow State ---
    const [headerStage, setHeaderStage] = useState<HeaderStage>(pendingLevelIncrement > 0 ? 'INITIAL' : 'FINAL');

    // Lock initial values to prevent jitter if global state updates during 1s pause
    const statsRef = useRef({
        startLevel: user.level - pendingLevelIncrement,
        totalGain: pendingLevelIncrement
    });

    const [visualLevel, setVisualLevel] = useState<number>(statsRef.current.startLevel);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());

    // Sequence Controller: Handles the 1s initial pause
    useEffect(() => {
        if (headerStage === 'INITIAL') {
            const timer = setTimeout(() => {
                setHeaderStage('FORMULA');
            }, 1000);
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    // Numerical Chasing Logic: Driven by headerStage
    useEffect(() => {
        if (headerStage === 'FORMULA' && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;

            // Calculate if any reward tracks "lap" (completed a cycle)
            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) {
                    newLaps.add(i);
                }
            });

            // If lapping, add a small mechanical pause for punchiness
            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });
                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    audio.play('sfx_ui_click', 1.6); 

                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVERRIDE_DURATION_MS);

                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);

            return () => clearTimeout(timer);
        } 
        else if (headerStage === 'FORMULA' && visualLevel >= user.level) {
            // Target reached: Transition to final centered display
            const timer = setTimeout(() => {
                setHeaderStage('FINAL');
                setIsCompletionFlare(true);
                audio.play('sfx_victory', 0.6);

                // Clear the UI signal now that visual catching is complete
                clearLevelUpSignal();

                setTimeout(() => setIsCompletionFlare(false), 1000);
            }, 600);
            return () => clearTimeout(timer);
        }
    }, [headerStage, visualLevel, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || headerStage === 'FORMULA') return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 400 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 1500);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction, headerStage]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || headerStage === 'FORMULA') return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user, type), { visualDelay: 600 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 2000);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction, headerStage]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />

                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg overflow-visible">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">
                            COLLECTION LEVEL
                        </h1>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('REWARDS')}>
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('ACTIVITY')}>
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40 min-h-[6rem] justify-center overflow-visible">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />

                                <div className="relative z-10 w-full flex justify-center items-center h-14 overflow-visible px-4">
                                    <div className={`absolute w-screen flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'INITIAL' ? 'opacity-100 scale-100' : 'opacity-0 scale-75 pointer-events-none'}`}>
                                        <div className="font-black italic tracking-tighter text-white/90 text-4xl pr-12 drop-shadow-lg">
                                            {statsRef.current.startLevel.toLocaleString()}
                                        </div>
                                    </div>

                                    <div className={`absolute flex items-center justify-center transition-all duration-500 overflow-visible w-full
                                        ${headerStage === 'FORMULA' ? 'opacity-100 scale-100' : 'opacity-0 scale-110 pointer-events-none'}`}>
                                        <div className="flex items-center gap-2 whitespace-nowrap font-black italic tracking-tighter pr-12">
                                            <span className="text-white/30 text-xl">CL</span>
                                            <span className="text-white/60 text-2xl">{statsRef.current.startLevel.toLocaleString()}</span>
                                            <span className="text-emerald-400 text-2xl drop-shadow-[0_0_10px_rgba(52,211,153,0.4)]">+{statsRef.current.totalGain}</span>
                                            <span className="text-white/20 text-lg">-></span>
                                            <span className="text-white text-3xl animate-pulse-glow drop-shadow-[0_0_15px_rgba(255,255,255,0.8)]">
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>

                                    <div className={`absolute w-screen flex items-center justify-center transition-all duration-700 ease-out overflow-visible
                                        ${headerStage === 'FINAL' ? 'opacity-100 scale-125 translate-y-0' : 'opacity-0 scale-50 translate-y-4 pointer-events-none'}`}>
                                        <div className="font-black italic tracking-tighter text-white text-5xl drop-shadow-[0_0_30px_rgba(99,102,241,0.8)] pr-12 text-center whitespace-nowrap">
                                            <span className={isCompletionFlare ? 'animate-completion-flare block' : 'block'}>
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex-1 flex flex-col px-2 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2 px-2">
                                    <div className="h-4 w-full">
                                        <GameText text="Progression Details" baseFontSize={0.65} className="text-white font-black uppercase tracking-[0.4em]" />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>
                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
