                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            {/* --- ANIMATED PROGRESSION HEADER --- */}
                            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center relative z-10 bg-black/40 min-h-[7rem] justify-center overflow-visible">
                                <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />

                                <div className="relative z-10 w-full flex justify-center items-center h-14 overflow-visible">

                                    {/* STAGE 1: INITIAL CENTERED (Paused for 1s) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'INITIAL' ? 'opacity-100 scale-100' : 'opacity-0 scale-75 pointer-events-none'}`}>
                                        <div className="font-black italic tracking-tighter text-white text-5xl text-center whitespace-nowrap overflow-visible drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]">
                                            {initialStats.startLevel.toLocaleString()}
                                        </div>
                                    </div>

                                    {/* STAGE 2: FORMULA (Old + Gain -> New) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'FORMULA' ? 'opacity-100 scale-100' : 'opacity-0 scale-110 pointer-events-none'}`}>
                                        <div className="flex items-center gap-2 whitespace-nowrap font-black italic tracking-tighter overflow-visible justify-center text-center">
                                            <span className="text-white/30 text-xl">CL</span>
                                            <span className="text-white/60 text-2xl">{initialStats.startLevel.toLocaleString()}</span>
