                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-700 ease-out overflow-visible
                                        ${headerStage === 'FINAL' ? 'opacity-100 scale-125 translate-y-0' : 'opacity-0 scale-50 translate-y-4 pointer-events-none'}`}>
                                        <div className="font-black italic tracking-tighter text-white text-5xl text-center whitespace-nowrap overflow-visible drop-shadow-[0_0_30px_rgba(99,102,241,0.8)]">
                                            <span className={isCompletionFlare ? 'animate-completion-flare block' : 'block'}>
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* --- CONTENT AREA --- */}
                            <div className="flex-1 flex flex-col px-2 py-4 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-2 px-2">
                                    <div className="h-4 w-full">
                                        <GameText text="Progression Details" baseFontSize={0.65} className="text-white font-black uppercase tracking-[0.4em]" />
                                    </div>
                                    <div className="h-px w-full bg-indigo-500/20 relative">
                                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                                    </div>
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.length > 0 ? visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    )) : (
                                        <div className="flex-1 flex items-center justify-center opacity-20">
                                            <span className="text-[0.6rem] font-black uppercase tracking-[0.3em]">No Track Data</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton variant="danger" size="md" onClick={onClose} className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8">
                        CLOSE
                    </SlantedButton>
                </div>
            </div>

            <style>{`
                @keyframes pulse-glow {
                    0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.4)); }
                    50% { filter: brightness(1.6) drop-shadow(0 0 25px rgba(255,255,255,1)); }
                }
                .animate-pulse-glow {
                    animation: pulse-glow 1.2s ease-in-out infinite;
                }
                @keyframes completion-flare {
                    0% { filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); }
                    20% { filter: brightness(3.5); text-shadow: 0 0 60px rgba(99,102,241,1); }
                    100% { filter: brightness(1); text-shadow: 0 0 20px rgba(99,102,241,0.6); }
                }
                .animate-completion-flare {
                    animation: completion-flare 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </Portal>
    );
};

