                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('ACTIVITY')}>
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            {/* --- COMPACT ANIMATED PROGRESSION HEADER --- */}
                            <div className="shrink-0 pt-[1rem] pb-[1rem] flex flex-col items-center relative z-10 overflow-visible">
                                <div className="relative w-full flex justify-center items-center h-12 overflow-visible">

                                    {/* STAGE 1: INITIAL CENTERED (Paused for 1s) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'INITIAL' ? 'opacity-100 scale-100' : 'opacity-0 scale-75 pointer-events-none'}`}>
                                        <div className="flex items-center gap-2 overflow-visible">
                                            <div className="flex flex-col items-end text-right leading-[0.8] pr-2 border-r border-white/20">
                                                <span className="text-[0.65rem] font-bold tracking-widest text-indigo-300">COLLECTION</span>
                                                <span className="text-[0.65rem] font-bold tracking-widest text-indigo-300">LEVEL</span>
                                            </div>
                                            <div className="text-[2rem] font-black italic tracking-tighter text-white drop-shadow-md leading-none">
                                                {initialStats.startLevel.toLocaleString()}
                                            </div>
                                        </div>
                                    </div>

                                    {/* STAGE 2: FORMULA (Old + Gain -> New) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'FORMULA' ? 'opacity-100 scale-100' : 'opacity-0 scale-110 pointer-events-none'}`}>
                                        <div className="flex items-center gap-1.5 whitespace-nowrap font-black italic tracking-tighter overflow-visible justify-center text-center">
                                            <span className="text-white/40 text-[1.2rem]">CL</span>
                                            <span className="text-white/60 text-[1.4rem]">{initialStats.startLevel.toLocaleString()}</span>
                                            <span className="text-emerald-400 text-[1.4rem] drop-shadow-[0_0_10px_rgba(52,211,153,0.4)]">+{initialStats.totalGain}</span>
                                            <span className="text-white/20 text-[1rem]">-></span>
                                            <span className="text-white text-[1.8rem] animate-pulse-glow drop-shadow-[0_0_15px_rgba(255,255,255,0.8)]">
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>

                                    {/* STAGE 3: FINAL CENTERED (Completion) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-700 ease-out overflow-visible
                                        ${headerStage === 'FINAL' ? 'opacity-100 scale-100' : 'opacity-0 scale-50 translate-y-4 pointer-events-none'}`}>
                                        <div className="flex items-center gap-2 overflow-visible">
                                            <div className="flex flex-col items-end text-right leading-[0.8] pr-2 border-r border-white/20">
                                                <span className="text-[0.65rem] font-bold tracking-widest text-indigo-300">COLLECTION</span>
                                                <span className="text-[0.65rem] font-bold tracking-widest text-indigo-300">LEVEL</span>
                                            </div>
                                            <div className="text-[2rem] font-black italic tracking-tighter text-white drop-shadow-[0_0_30px_rgba(99,102,241,0.8)] leading-none">
                                                <span className={isCompletionFlare ? 'animate-completion-flare block' : 'block'}>
                                                    {visualLevel.toLocaleString()}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* --- CONTENT AREA --- */}
                            <div className="flex-1 flex flex-col px-2 py-2 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-1 mb-2 px-2">
                                    <div className="h-4 w-full">
                                        <GameText text="Progression Details" baseFontSize={0.6} className="text-white/60 font-black uppercase tracking-[0.4em]" />
                                    </div>
                                    <div className="h-px w-full bg-white/5" />
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.length > 0 ? visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    )) : (
                                        <div className="flex-1 flex items-center justify-center opacity-20">
                                            <span className="text-[0.6rem] font-black uppercase tracking-[0.3em]">No Track Data</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton variant="danger" size="md" onClick={onClose} className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8">
                        CLOSE
                    </SlantedButton>
                </div>
            </div>

            <style>{`
                @keyframes pulse-glow {
                    0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.4)); }
                    50% { filter: brightness(1.6) drop-shadow(0 0 25px rgba(255,255,255,1)); }
                }
                .animate-pulse-glow {
                    animation: pulse-glow 1.2s ease-in-out infinite;
                }
                @keyframes completion-flare {
                    0% { filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); }
                    20% { filter: brightness(3.5); text-shadow: 0 0 60px rgba(99,102,241,1); }
                    100% { filter: brightness(1); text-shadow: 0 0 20px rgba(99,102,241,0.6); }
                }
                .animate-completion-flare {
                    animation: completion-flare 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </Portal>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 100;
const LAP_MECHANICAL_PAUSE_MS = 100;
const LAP_OVERRIDE_DURATION_MS = 75;
const BUTTON_FLASH_DURATION_MS = 500;

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';
type HeaderStage = 'INITIAL' | 'FORMULA' | 'FINAL';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { inspect, pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    // --- Header Animation Flow State ---
    const [headerStage, setHeaderStage] = useState<HeaderStage>(pendingLevelIncrement > 0 ? 'INITIAL' : 'FINAL');

    // Lock initial values to prevent jitter
    const initialStats = useMemo(() => ({
        startLevel: user.level - pendingLevelIncrement,
        totalGain: pendingLevelIncrement
    }), []);

    const [visualLevel, setVisualLevel] = useState<number>(initialStats.startLevel);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());

    const isChasingRef = useRef(false);

    // Sequence Controller
    useEffect(() => {
        if (headerStage === 'INITIAL') {
            const timer = setTimeout(() => {
                setHeaderStage('FORMULA');
                isChasingRef.current = true;
            }, 1000);
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    // Numerical Chasing Logic
    useEffect(() => {
        if (headerStage === 'FORMULA' && isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;
            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) {
                    newLaps.add(i);
                }
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });
                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });
                    audio.play('sfx_ui_click', 1.6); 
                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVERRIDE_DURATION_MS);
                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }
                setVisualLevel(nextLevel);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);
            return () => clearTimeout(timer);
        } 
        else if (headerStage === 'FORMULA' && visualLevel >= user.level) {
            isChasingRef.current = false;
            const timer = setTimeout(() => {
                setHeaderStage('FINAL');
                setIsCompletionFlare(true);
                audio.play('sfx_victory', 0.6);
                clearLevelUpSignal();
                setTimeout(() => setIsCompletionFlare(false), 1000);
            }, 600);
            return () => clearTimeout(timer);
        }
    }, [headerStage, visualLevel, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || headerStage === 'FORMULA') return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 400 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 1500);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction, headerStage]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || successIndices.has(idx) || headerStage === 'FORMULA') return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user, type), { visualDelay: 600 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 2000);
        }
    }, [claimingIndices, successIndices, user, performSynchronizedAction, headerStage]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />

                {/* --- NAVIGATION HEADER --- */}
                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg overflow-visible">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">
                            COLLECTION LEVEL
                        </h1>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('REWARDS')}>
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" />
                            </svg>
                        </SlantedButton>
                        <SlantedButton variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('ACTIVITY')}>
                            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </SlantedButton>
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            {/* --- COMPACT ANIMATED PROGRESSION HEADER --- */}
                            <div className="shrink-0 pt-[1rem] pb-[1rem] flex flex-col items-center relative z-10 overflow-visible">
                                <div className="relative w-full flex justify-center items-center h-12 overflow-visible">

                                    {/* STAGE 1: INITIAL CENTERED (Paused for 1s) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'INITIAL' ? 'opacity-100 scale-100' : 'opacity-0 scale-75 pointer-events-none'}`}>
                                        <div className="flex items-center gap-2 overflow-visible">
                                            <div className="flex flex-col items-end text-right pr-2 border-r border-white/20 gap-1">
                                                <span className="text-[0.65rem] font-bold tracking-widest text-slate-200 leading-none">COLLECTION</span>
                                                <span className="text-[0.65rem] font-bold tracking-widest text-slate-200 leading-none">LEVEL</span>
                                            </div>
                                            <div className="text-[2rem] font-black italic tracking-tighter text-white drop-shadow-md leading-none">
                                                {initialStats.startLevel.toLocaleString()}
                                            </div>
                                        </div>
                                    </div>

                                    {/* STAGE 2: FORMULA (Old + Gain -> New) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-500 overflow-visible
                                        ${headerStage === 'FORMULA' ? 'opacity-100 scale-100' : 'opacity-0 scale-110 pointer-events-none'}`}>
                                        <div className="flex items-center gap-1.5 whitespace-nowrap font-black italic tracking-tighter overflow-visible justify-center text-center">
                                            <span className="text-white/40 text-[1.2rem]">CL</span>
                                            <span className="text-white/60 text-[1.4rem]">{initialStats.startLevel.toLocaleString()}</span>
                                            <span className="text-emerald-400 text-[1.4rem] drop-shadow-[0_0_10px_rgba(52,211,153,0.4)]">+{initialStats.totalGain}</span>
                                            <span className="text-white/20 text-[1rem]">-></span>
                                            <span className="text-white text-[1.8rem] animate-pulse-glow drop-shadow-[0_0_15px_rgba(255,255,255,0.8)]">
                                                {visualLevel.toLocaleString()}
                                            </span>
                                        </div>
                                    </div>

                                    {/* STAGE 3: FINAL CENTERED (Completion) */}
                                    <div className={`absolute inset-0 flex items-center justify-center transition-all duration-700 ease-out overflow-visible
                                        ${headerStage === 'FINAL' ? 'opacity-100 scale-100' : 'opacity-0 scale-50 translate-y-4 pointer-events-none'}`}>
                                        <div className="flex items-center gap-2 overflow-visible">
                                            <div className="flex flex-col items-end text-right pr-2 border-r border-white/20 gap-1">
                                                <span className="text-[0.65rem] font-bold tracking-widest text-slate-200 leading-none">COLLECTION</span>
                                                <span className="text-[0.65rem] font-bold tracking-widest text-slate-200 leading-none">LEVEL</span>
                                            </div>
                                            <div className="text-[2rem] font-black italic tracking-tighter text-white drop-shadow-[0_0_30px_rgba(99,102,241,0.8)] leading-none">
                                                <span className={isCompletionFlare ? 'animate-completion-flare block' : 'block'}>
                                                    {visualLevel.toLocaleString()}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* --- CONTENT AREA --- */}
                            <div className="flex-1 flex flex-col px-2 py-2 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-1 mb-2 px-2">
                                    <div className="h-4 w-full">
                                        <GameText text="Progression Details" baseFontSize={0.6} className="text-white/60 font-black uppercase tracking-[0.4em]" />
                                    </div>
                                    <div className="h-px w-full bg-white/5" />
                                </div>

                                <div className="flex-1 flex flex-col justify-around">
                                    {visualTracks.length > 0 ? visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={`${track.type}-${idx}`}
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                            onInspect={() => handleInspect(track)}
                                        />
                                    )) : (
                                        <div className="flex-1 flex items-center justify-center opacity-20">
                                            <span className="text-[0.6rem] font-black uppercase tracking-[0.3em]">No Track Data</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                            <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3">
                    <SlantedButton variant="danger" size="md" onClick={onClose} className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8">
                        CLOSE
                    </SlantedButton>
                </div>
            </div>

            <style>{`
                @keyframes pulse-glow {
                    0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.4)); }
                    50% { filter: brightness(1.6) drop-shadow(0 0 25px rgba(255,255,255,1)); }
                }
                .animate-pulse-glow {
                    animation: pulse-glow 1.2s ease-in-out infinite;
                }
                @keyframes completion-flare {
                    0% { filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); }
                    20% { filter: brightness(3.5); text-shadow: 0 0 60px rgba(99,102,241,1); }
                    100% { filter: brightness(1); text-shadow: 0 0 20px rgba(99,102,241,0.6); }
                }
                .animate-completion-flare {
