import React from 'react';
import { ProgressionTrack } from '../../types';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { getVariant, getScale, getColors } from './progressionUtils';
import { GameText } from '../ui/GameText';
import { SlantedButton } from '../ui/SlantedButton';

interface ProgressionTrackRowProps {
    track: ProgressionTrack;
    isClaiming: boolean;
    isSuccess: boolean;
    isLapping?: boolean;
    isNewlyGained?: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
    onInspect: () => void;
}

const ProgressionTrackRowComponent: React.FC<ProgressionTrackRowProps> = ({
    track,
    isClaiming,
    isSuccess,
    isLapping = false,
    isNewlyGained = false,
    onClaim,
    onClaimAll,
    onInspect
}) => {
    const styles = getColors(track.type);
    const variant = getVariant(track.type);
    const percent = (track.currentXP / track.targetXP) * 100;
    const canClaim = track.unclaimedCount > 0;

    // Determine the button variant based on the track reward type and current status
    const getButtonVariant = () => {
        if (isSuccess) return 'success';
        if (!canClaim) return 'secondary';

        switch(track.type) {
            case 'booster': return 'success'; 
            case 'credits': return 'blue';
            case 'gold': return 'warning';
            case 'tokens': return 'danger';
            case 'box': return 'primary';
            default: return 'primary';
        }
    };

    const getButtonLabel = () => {
        if (isClaiming) return track.unclaimedCount > 1 ? "CLAIMING ALL..." : "CLAIMING...";
        if (isSuccess) return "SUCCESS!";

        const rewardLabel = track.type === 'box' ? track.label : track.label.toUpperCase();
        return `CLAIM\n${track.type === 'box' ? rewardLabel : `${track.nextRewardAmount} ${rewardLabel}`}`;
    };

    return (
        <div 
            className="grid grid-cols-[1fr_34vw] gap-4 items-center h-16 px-1.5 will-change-transform overflow-visible"
            style={{ contain: 'layout' }} 
        >
            {/* XP Track Area */}
            <div className="relative h-full flex items-center cursor-pointer group" onClick={onInspect}>

                {/* 
                    REWARD LABEL - MOVED BELOW BAR 
                    Container is h-16 (4rem). Bar is h-8 (2rem) and centered (starts at 1rem, ends at 3rem).
                    3rem + 0.25rem = top-[3.25rem]
                */}
                <div className="absolute top-[3.25rem] left-[2.8rem] right-0 z-50 pointer-events-none h-4 flex items-center">
                    <GameText 
                        text={`${track.nextRewardAmount} ${track.label}`} 
                        baseFontSize={0.6} 
                        className="text-white font-black italic uppercase tracking-wider drop-shadow-[0_1.5px_2px_rgba(0,0,0,1)]" 
                    />
                </div>

                <div className={`absolute left-0 z-40 transition-all duration-300 origin-center drop-shadow-xl`}>
                    <HexBadge variant={variant} size="lg">
                        <div className="relative w-full h-full overflow-visible">
                            <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                <RewardIconGraphic type={track.type as any} size="lg" />
                            </div>
                        </div>
                    </HexBadge>
                </div>

                <div className={`
                    absolute left-8 right-0 h-8 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] transition-all duration-300
                    ${isLapping ? 'ring-2 ring-white shadow-[0_0_20px_rgba(255,255,255,0.6)] scale-[1.01]' : ''}
                `}>
                    <div 
                        className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-500 ease-out`} 
                        style={{ width: `${isLapping ? 100 : percent}%` }} 
                    />
                    {/* Progress Text */}
                    <div className="absolute inset-0 flex items-center justify-start pl-6 pr-2 py-0 pointer-events-none">
                        <div className="h-4 w-full">
                            <GameText 
                                text={`${isLapping ? track.targetXP : track.currentXP} / ${track.targetXP} CL`} 
                                baseFontSize={0.75} 
                                className="text-white font-black italic tracking-wider drop-shadow-[0_2px_3px_rgba(0,0,0,1)]" 
                            />
                        </div>
                    </div>
                    {isLapping && (
                        <div className="absolute inset-0 bg-white/30 animate-pulse pointer-events-none" />
                    )}
                </div>
            </div>

            {/* Button Column */}
            <div className="flex flex-col items-center h-full justify-center overflow-visible pr-1">
                <SlantedButton
                    variant={getButtonVariant()}
                    size="md"
                    fullWidth
                    disabled={(isClaiming || !canClaim) && !isSuccess}
                    onClick={(e) => { e.stopPropagation(); onClaim(); }}
                    onHoldComplete={(e) => { e.stopPropagation(); onClaimAll(); }}
                    holdDuration={track.unclaimedCount > 1 ? 1000 : 0}
                    className={`
                        !h-11 shadow-lg transition-all
                        ${isNewlyGained ? 'animate-gain-flash' : ''}
                        ${isClaiming ? 'animate-pulse' : ''}
                    `}
                >
                    {getButtonLabel()}
                </SlantedButton>

                <div className="h-3 w-full mt-1">
                    <GameText 
                        text={`${track.unclaimedCount} UNCLAIMED`} 
                        baseFontSize={0.6} 
                        className={`font-black uppercase tracking-[0.1em] drop-shadow-sm text-white`} 
                    />
                </div>
            </div>

            <style>{`
                @keyframes gain-flash {
                    0% { filter: brightness(1); }
                    20% { filter: brightness(2.5); box-shadow: 0 0 20px rgba(255,255,255,0.6); }
                    100% { filter: brightness(1); box-shadow: none; }
                }
                .animate-gain-flash {
                    animation: gain-flash 0.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
                }
            `}</style>
        </div>
    );
};

