    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());

    const isChasingRef = useRef(false);

    // 1. Initial State Delay (1s)
    useEffect(() => {
        if (headerStage === 'INITIAL') {
            const timer = setTimeout(() => {
                setHeaderStage('SLIDING');
            }, 1000);
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    // 2. Slide Sequence (Moves number to the left to make room for green gain)
    useEffect(() => {
        if (headerStage === 'SLIDING') {
            const timer = setTimeout(() => {
                setHeaderStage('TICKING');
                isChasingRef.current = true;
            }, 500); 
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    // 3. Numerical Chasing Logic (The Extraction)
    useEffect(() => {
        if (headerStage === 'TICKING' && isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;
            const nextGain = Math.max(0, visualGain - 1);

            const newLaps = new Set<number>();
