            const nextGain = Math.max(0, visualGain - 1);

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) {
                    newLaps.add(i);
                }
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });
                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    // SPECIALIZED LAP SFX
                    if (newLaps.has(4)) { // TOKENS (Index 4)
                        audio.play('sfx_teleport_short', 0.8);
                    } else if (newLaps.has(3)) { // OMEGA BOX (Index 3)
                        audio.play('sfx_equip_tech', 1.2);
                    } else {
                        audio.play('sfx_ui_click', 1.6); 
                    }

                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVERRIDE_DURATION_MS);
                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                setVisualGain(nextGain);

                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);
            return () => clearTimeout(timer);
        } 
        else if (headerStage === 'TICKING' && visualLevel >= user.level) {
            isChasingRef.current = false;
            // Counts are done. Initiate slide-back to center.
            const settleTimer = setTimeout(() => {
                setHeaderStage('FINAL'); // CSS will start centering via translateX(0)

                // Wait for the slide transition (centering) to finish before the climax
                setTimeout(() => {
                    setIsCompletionFlare(true);
                    audio.play('sfx_victory', 0.6);
                    clearLevelUpSignal();

                    // CLIMAX DURATION EXTENDED 3X (from 1500 to 4500)
                    setTimeout(() => setIsCompletionFlare(false), 4500);
                }, CENTERING_DURATION_MS);

            }, 400); 
            return () => clearTimeout(settleTimer);
        }
