                    0% { 
                        transform: scale(1); 
                        filter: brightness(1); 
                        text-shadow: 0 0 0px rgba(255,255,255,0); 
                    }
                    /* Slow grow to peak at 35% mark */
                    35% { 
                        transform: scale(1.3); 
                        filter: brightness(14); 
                        text-shadow: 0 0 40px rgba(99,102,241,1), 0 0 100px rgba(255,255,255,1); 
                    }
                    /* Very gradual settle back down */
                    70% {
                        transform: scale(1.1);
                        filter: brightness(3);
                        text-shadow: 0 0 20px rgba(99,102,241,0.8);
                    }
                    100% { 
                        transform: scale(1); 
                        filter: brightness(1); 
                        text-shadow: 0 0 25px rgba(99,102,241,0.7); 
                    }
                }
                .animate-completion-flare {
                    animation: completion-flare 4.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                    z-index: 100;
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
