                                        className={`flex items-center gap-1.5 transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)]
                                            ${isShifted ? '-translate-x-6' : 'translate-x-0'}`}
                                    >
                                        {/* COLLECTION LEVEL LABELS: Brightened to opacity-90 and pure white */}
                                        <div className="flex flex-col items-end text-right gap-0.5 opacity-90">
