import { UserProfile, StoreData, PurchaseResponse } from '../../types';
import { MOCK_STORE_OFFERS } from './mockData';
import { simulateNetwork } from './apiUtils';
import { getPersistedProfile, persistUserProfile } from './mockDb';

// Atomic transaction lock to prevent concurrent modifications to the mock DB
let transactionTail = Promise.resolve();

/**
 * STORE SERVICE
 * Handles offer filtering and authoritative transaction processing.
 */
export const storeService = {
    async getOffers(user: UserProfile): Promise<StoreData> {
        await simulateNetwork(300, 500); 
        const filteredOffers = MOCK_STORE_OFFERS.filter(offer => {
            if (offer.isOneTime && user.purchasedOfferIds.includes(offer.id)) return false;
            return true;
        });
        return { offers: [...filteredOffers], lastUpdated: Date.now(), refreshHintSeconds: 60 };
    },

    async purchaseOffer(clientUser: UserProfile, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        // We wrap the logic in a promise chain to ensure sequential execution (Queueing)
        const result = await (transactionTail = transactionTail.then(async () => {
            await simulateNetwork(800, 1200);

            // 1. Load authoritative profile from "DB", ignore client-side snapshot
            const user = getPersistedProfile() || clientUser;
            const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);

            if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId } as PurchaseResponse;

            // 2. Authoritative Balance Check
            if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) {
                return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId } as PurchaseResponse;
            }
            if (offer.priceType === 'tokens' && user.tokens < (offer.priceAmount || 0)) {
                return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId } as PurchaseResponse;
            }

            // 3. Clone for mutation
            const updatedProfile: UserProfile = { ...user };

            // 4. Deduct Price
            if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
            if (offer.priceType === 'tokens') updatedProfile.tokens -= (offer.priceAmount || 0);

            // 5. Grant Rewards (Delta Update)
            offer.contents.forEach(item => {
                if (item.type === 'currency') {
                    if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                    if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
                    if (item.currencyType === 'tokens') updatedProfile.tokens += item.amount;
                } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                    updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
                }
            });

            // 6. Record purchase
            updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];

            // 7. Persist to Mock DB
            persistUserProfile(updatedProfile);

            return { success: true, transactionId, updatedProfile } as PurchaseResponse;
        }));

        return result;
    }
};

import { UserProfile, ProgressionData, ActivityLogEntry, ProgressionRewardType } from '../../types';
import { REWARD_SEQUENCE } from './mockData';
import { progressionStore, getPersistedProfile, persistUserProfile } from './mockDb';
import { getProgressionDataInternal } from './progressionLogic';
import { generateInstanceId } from '../../utils/id';
import { simulateNetwork } from './apiUtils';

// Atomic lock for progression updates
let progressionTail = Promise.resolve();

/**
 * PROGRESSION SERVICE
 * Orchestrates CL rewards, claiming, and the global activity archive.
 */
export const progressionService = {
    async getProgression(user: UserProfile): Promise<ProgressionData> {
        await simulateNetwork(200, 400);
        return getProgressionDataInternal(user);
    },

    async getActivityLog(): Promise<ActivityLogEntry[]> {
        await simulateNetwork(100, 200);
        return progressionStore.activityLog;
    },

    async claimReward(clientUser: UserProfile, type: ProgressionRewardType) {
        return progressionTail = progressionTail.then(async () => {
            await simulateNetwork(400, 600);

            // Load authoritative data
            const user = getPersistedProfile() || clientUser;
            const currentData = getProgressionDataInternal(user);
            const trackIdx = currentData.tracks.findIndex(t => t.type === type && t.unclaimedCount > 0);

            if (trackIdx === -1) return { success: false };

            const rewardConfig = REWARD_SEQUENCE[trackIdx];
            const updatedProfile = { ...user };

            // 1. Increment persistent claim counter
            const newClaimed = [...progressionStore.claimedCounts];
            newClaimed[trackIdx]++;
            progressionStore.claimedCounts = newClaimed;

            // 2. Grant rewards to user profile
            if (type === 'credits') updatedProfile.credits += rewardConfig.amount as number;
            else if (type === 'gold') updatedProfile.gold += rewardConfig.amount as number;
            else if (type === 'tokens') updatedProfile.tokens += rewardConfig.amount as number;

            // 3. Log to activity archive
            const now = new Date();
            const newLog: ActivityLogEntry = {
                id: generateInstanceId(),
                title: `${rewardConfig.amount} ${rewardConfig.label}`,
                type,
                date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
                time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
                amount: rewardConfig.amount
            };

            progressionStore.activityLog = [newLog, ...progressionStore.activityLog];

            // 4. Save to DB
            persistUserProfile(updatedProfile);

            return { 
                success: true, 
                updatedProfile, 
                progressionData: getProgressionDataInternal(updatedProfile),
                activityLog: [...progressionStore.activityLog]
            };
        });
    },

    async claimAllRewards(clientUser: UserProfile, type: ProgressionRewardType) {
        return progressionTail = progressionTail.then(async () => {
            await simulateNetwork(600, 900);

            const user = getPersistedProfile() || clientUser;
            const currentData = getProgressionDataInternal(user);
            const trackIdx = currentData.tracks.findIndex(t => t.type === type);

            if (trackIdx === -1 || currentData.tracks[trackIdx].unclaimedCount <= 0) {
                return { success: false };
            }

            const count = currentData.tracks[trackIdx].unclaimedCount;
            const rewardConfig = REWARD_SEQUENCE[trackIdx];
            const updatedProfile = { ...user };

            // 1. Clear all for this track
            const newClaimed = [...progressionStore.claimedCounts];
            newClaimed[trackIdx] += count;
            progressionStore.claimedCounts = newClaimed;

            // 2. Grant bulk rewards
            const totalAmount = (rewardConfig.amount as number) * count;
            if (type === 'credits') updatedProfile.credits += totalAmount;
            else if (type === 'gold') updatedProfile.gold += totalAmount;
            else if (type === 'tokens') updatedProfile.tokens += totalAmount;

            // 3. Log a single bulk entry
            const now = new Date();
            const newLog: ActivityLogEntry = {
                id: generateInstanceId(),
                title: `BULK: ${totalAmount} ${rewardConfig.label}`,
                type,
                date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
                time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
                amount: totalAmount
            };

            progressionStore.activityLog = [newLog, ...progressionStore.activityLog];

            // 4. Save to DB
            persistUserProfile(updatedProfile);

            return { 
                success: true, 
                updatedProfile, 
                progressionData: getProgressionDataInternal(updatedProfile),
                activityLog: [...progressionStore.activityLog]
            };
        });
    }
};

