import { generateAiMoves } from './ai';

// Domain Services
import { profileService } from './api/profileService';
import { storeService } from './api/storeService';
import { seasonService } from './api/seasonService';
import { progressionService } from './api/progressionService';

/**
 * UNIFIED API GATEWAY
 * This is the public interface for the application. 
 * Authoritative Pattern: Mutations accept IDs/Tokens, not client-side state objects.
 */
export const api = {
    // 1. Profile & Decks
    getProfile: (userId: string) => profileService.getProfile(userId),
    updateActiveDeck: (userId: string, deckId: number) => profileService.updateActiveDeck(userId, deckId),
    addCollectionLevels: (userId: string, increment: number) => profileService.addCollectionLevels(userId, increment),

    // 2. Battle Engine (Server-Side Moves)
    async submitTurn(gameState: GameState, playerMoves: PendingMove[]): Promise<{ opponentMoves: PendingMove[] }> {
        await new Promise(resolve => setTimeout(resolve, 600));
        return { opponentMoves: generateAiMoves(gameState) };
    },

    // 3. Economy & Store
    getStoreOffers: (userId: string) => storeService.getOffers(userId),
    purchaseOffer: (userId: string, offerId: string, txnId: string) => storeService.purchaseOffer(userId, offerId, txnId),

    // 4. Seasons
    getSeasonPass: (userId: string) => seasonService.getSeasonPass(userId),
    debugNextSeason: () => seasonService.debugNextSeason(),

    // 5. Progression & Archive
    getProgression: (userId: string) => progressionService.getProgression(userId),
    getActivityLog: () => progressionService.getActivityLog(),
    claimProgressionReward: (userId: string, type: ProgressionRewardType) => progressionService.claimReward(userId, type),
    claimAllProgressionRewards: (userId: string, type: ProgressionRewardType) => progressionService.claimAllRewards(userId, type),
};

