            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const { status, holdProgress, isHolding, execute, bind } = useSynchronizedAction({
        holdDuration: isFree ? 0 : 800,
        onAction: async () => {
            if (!hasFunds) {
                syncStore();
                return false;
            }
            if (!offerId) return false;

            return await performSynchronizedAction(
                () => api.purchaseOffer(user.id, offerId, `txn_${Math.random()}`),
                { visualDelay: SUCCESS_WINDOW }
            );
        }
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    const isPermanentlyClaimed = useMemo(() => {
        const offer = storeData?.offers.find(o => o.id === offerId);
        return offer?.isOneTime && user.purchasedOfferIds.includes(offerId || '');
    }, [user.purchasedOfferIds, offerId, storeData]);

    const showSuccess = isSuccess || isPermanentlyClaimed;
    const colors = type === 'gold' ? { text: 'text-amber-500', bg: 'bg-amber-400/30' } : (type === 'tokens' ? { text: 'text-red-500', bg: 'bg-red-400/30' } : { text: 'text-blue-400', bg: 'bg-blue-400/30' });

    return (
        <div 
            className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}
            {...(isFree || isLocked || isPermanentlyClaimed ? {} : bind)}
        >
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`} style={{ width: `${holdProgress}%` }} />
            )}

            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText text={amount.toLocaleString()} baseFontSize={1.1} className="text-white drop-shadow-md" />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>{type}</div>
            </div>

            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}`}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-black">Hold to Buy</span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-cyan">Syncing...</span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-emerald">Deposited</span>
                    ) : null}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        onClick={execute}
                        disabled={isProcessing || showSuccess}
                    >
                        {isProcessing ? 'AUTHORIZING' : (showSuccess ? 'SYNCED' : costLabel)}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import { UserProfile, StoreData, PurchaseResponse, StoreOffer } from '../../types';
import { MOCK_STORE_OFFERS } from './mockData';
import { simulateNetwork } from './apiUtils';
import { getPersistedProfile, persistUserProfile } from './mockDb';

// Atomic transaction lock to prevent concurrent modifications to the mock DB
let transactionTail: Promise<any> = Promise.resolve();

const COOLDOWN_DURATION_MS = 60000; // 1 minute as requested

/**
 * STORE SERVICE
 * Handles offer filtering and authoritative transaction processing.
 */
export const storeService = {
    async getOffers(userId: string): Promise<StoreData> {
        await simulateNetwork(300, 500); 
        const user = getPersistedProfile();

        const offersWithCooldowns = MOCK_STORE_OFFERS.map(offer => {
            const lastClaimed = user?.lastClaimedDates[offer.id];
            if (lastClaimed) {
                const availableAt = new Date(lastClaimed).getTime();
                const now = Date.now();
                if (availableAt > now) {
                    return { ...offer, availableAt: new Date(availableAt).toISOString() };
                }
            }
            return { ...offer };
        }).filter(offer => {
            if (offer.isOneTime && user?.purchasedOfferIds.includes(offer.id)) return false;
            return true;
        });

        return { offers: [...offersWithCooldowns], lastUpdated: Date.now(), refreshHintSeconds: 60 };
    },

    async purchaseOffer(userId: string, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        const result = await (transactionTail = transactionTail.then(async () => {
            await simulateNetwork(800, 1200);

            // 1. Authoritative Lookup
            const user = getPersistedProfile();
            if (!user || user.id !== userId) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId } as PurchaseResponse;

            const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
            if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId } as PurchaseResponse;

            // 2. Authoritative Cooldown Validation
            if (offer.priceType === 'free') {
                const nextAvailableAt = user.lastClaimedDates[offerId];
                if (nextAvailableAt && new Date(nextAvailableAt).getTime() > Date.now()) {
                    return { success: false, errorCode: 'ERR_COOLDOWN_ACTIVE', transactionId } as PurchaseResponse;
                }
            }

            // 3. Authoritative Balance Validation
            if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) {
                return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId } as PurchaseResponse;
            }
            if (offer.priceType === 'tokens' && user.tokens < (offer.priceAmount || 0)) {
                return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId } as PurchaseResponse;
            }

            // 4. Execution
            const updatedProfile: UserProfile = { ...user };

            // Apply price
            if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
            if (offer.priceType === 'tokens') updatedProfile.tokens -= (offer.priceAmount || 0);

            // Handle Cooldown for Free items
            if (offer.priceType === 'free') {
                updatedProfile.lastClaimedDates = {
                    ...updatedProfile.lastClaimedDates,
                    [offerId]: new Date(Date.now() + COOLDOWN_DURATION_MS).toISOString()
                };
            }

            // Grant rewards
            offer.contents.forEach(item => {
                if (item.type === 'currency') {
                    if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                    if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
                    if (item.currencyType === 'tokens') updatedProfile.tokens += item.amount;
                } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                    updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
                }
            });

            // Record purchase history for one-time offers
            if (offer.isOneTime) {
                updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
            }

            // 5. Persistence
            persistUserProfile(updatedProfile);

            return { success: true, transactionId, updatedProfile } as PurchaseResponse;
        }));

        return result;
    }
};

import React, { useEffect, useState, useMemo } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { useSynchronizedAction } from '../../hooks/useSynchronizedAction';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';
import { api } from '../../services/api';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

const SUCCESS_WINDOW = 800; // API Simulation delay
const THEATRICAL_RESET_DELAY = 4000; // How long to stay in "Success" state

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, storeData, performSynchronizedAction, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasFunds = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    /**
     * AUTHORITATIVE COOLDOWN CALCULATION
     * We check both the initial 'availableAt' from the offer manifest 
     * AND the live user profile's 'lastClaimedDates' to ensure zero-lag cooldown detection.
     */
    const effectiveAvailableAt = useMemo(() => {
        const userClaimedAt = offerId ? user.lastClaimedDates[offerId] : null;
        if (userClaimedAt) {
            const userTime = new Date(userClaimedAt).getTime();
            const manifestTime = availableAt ? new Date(availableAt).getTime() : 0;
            // Return the furthest future date
            return userTime > manifestTime ? userClaimedAt : availableAt;
        }
        return availableAt;
    }, [availableAt, user.lastClaimedDates, offerId]);

    useEffect(() => {
        if (!effectiveAvailableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(effectiveAvailableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [effectiveAvailableAt]);

    const { status, holdProgress, isHolding, execute, bind } = useSynchronizedAction({
        holdDuration: isFree ? 0 : 800,
        resetDelay: THEATRICAL_RESET_DELAY,
        onAction: async () => {
            if (!hasFunds) {
                syncStore();
                return false;
            }
            if (!offerId) return false;

            return await performSynchronizedAction(
                () => api.purchaseOffer(user.id, offerId, `txn_${Math.random()}`),
                { visualDelay: SUCCESS_WINDOW }
            );
        }
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    // One-time bundles stay "claimed" forever
    const isPermanentlyClaimed = useMemo(() => {
        const offer = storeData?.offers.find(o => o.id === offerId);
        return offer?.isOneTime && user.purchasedOfferIds.includes(offerId || '');
    }, [user.purchasedOfferIds, offerId, storeData]);

    /**
     * SUCCESS vs COOLDOWN PRIORITY
     * While 'isSuccess' is true (the 4s theatrical window), we show the green "SYNCED" state.
     * Once that expires, if there's still a cooldown (isLocked), we switch to the timer.
     */
    const showSuccess = isSuccess || isPermanentlyClaimed;

    const colors = type === 'gold' 
        ? { text: 'text-amber-500', bg: 'bg-amber-400/30' } 
        : (type === 'tokens' ? { text: 'text-red-500', bg: 'bg-red-400/30' } : { text: 'text-blue-400', bg: 'bg-blue-400/30' });

    return (
        <div 
            className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : (isLocked ? 'border-slate-800 grayscale-[0.3]' : 'border-slate-700')}`}
            {...(isFree || isLocked || isPermanentlyClaimed ? {} : bind)}
        >
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`} style={{ width: `${holdProgress}%` }} />
            )}

            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText text={amount.toLocaleString()} baseFontSize={1.1} className="text-white drop-shadow-md" />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>{type}</div>
            </div>

            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : (isLocked ? 'bg-slate-950 border-slate-800 opacity-40' : 'bg-slate-900 border-slate-700')}`}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-black">Hold to Buy</span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-cyan">Syncing...</span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-emerald">Deposited</span>
                    ) : isLocked ? (
                         <span className="text-[0.45rem] font-black text-slate-500 uppercase tracking-[0.3em] leading-none">Cooldown</span>
                    ) : null}
                </div>

                {isLocked && !showSuccess ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        onClick={execute}
                        disabled={isProcessing || showSuccess || isLocked}
                    >
                        {isProcessing ? 'AUTHORIZING' : (showSuccess ? 'SYNCED' : costLabel)}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

/**
 * SIMULATED NETWORK LATENCY (BACKUP COPY)
 * Standardizes fake API delays to make UI testing consistent.
 */
export const simulateNetwork = async (minMs = 200, maxMs = 600) => {
    const delay = Math.floor(Math.random() * (maxMs - minMs + 1) + minMs);
    await new Promise(resolve => setTimeout(resolve, delay));
};

export class ApiError extends Error {
    constructor(public code: string, message: string) {
        super(message);
        this.name = 'ApiError';
    }
}

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 80;
const LAP_MECHANICAL_PAUSE_MS = 100;
const LAP_OVER_RIDE_DURATION_MS = 75;
const BUTTON_FLASH_DURATION_MS = 500;
const CENTERING_DURATION_MS = 500; 
const VICTORY_CLIMAX_DURATION_MS = 4500; 

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';
type HeaderStage = 'INITIAL' | 'SLIDING' | 'TICKING' | 'FINAL';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');
    const [headerStage, setHeaderStage] = useState<HeaderStage>(pendingLevelIncrement > 0 ? 'INITIAL' : 'FINAL');

    const initialStats = useMemo(() => ({
        startLevel: user.level - pendingLevelIncrement,
        totalGain: pendingLevelIncrement
    }), []);

    const [visualLevel, setVisualLevel] = useState<number>(initialStats.startLevel);
    const [visualGain, setVisualGain] = useState<number>(initialStats.totalGain);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [claimingAllIndices, setClaimingAllIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());

    const isChasingRef = useRef(false);

    const handleManualClose = useCallback(() => {
        clearLevelUpSignal();
        onClose();
    }, [clearLevelUpSignal, onClose]);

    useEffect(() => {
        if (headerStage === 'INITIAL') {
            const timer = setTimeout(() => setHeaderStage('SLIDING'), 1000);
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    useEffect(() => {
        if (headerStage === 'SLIDING') {
            const timer = setTimeout(() => {
                setHeaderStage('TICKING');
                isChasingRef.current = true;
            }, 500); 
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    useEffect(() => {
        if (headerStage === 'TICKING' && isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;
            const nextGain = Math.max(0, visualGain - 1);

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) newLaps.add(i);
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });
                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    if (newLaps.has(4)) audio.play('sfx_teleport_short', 0.8);
                    else if (newLaps.has(3)) audio.play('sfx_equip_tech', 1.2);
                    else audio.play('sfx_ui_click', 1.6); 

                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVER_RIDE_DURATION_MS);
                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                setVisualGain(nextGain);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);
            return () => clearTimeout(timer);
        } 
        else if (headerStage === 'TICKING' && visualLevel >= user.level) {
            isChasingRef.current = false;
            const settleTimer = setTimeout(() => {
                setHeaderStage('FINAL'); 
                setTimeout(() => {
                    setIsCompletionFlare(true);
                    audio.play('sfx_victory', 0.6);
                    clearLevelUpSignal();
                    setTimeout(() => setIsCompletionFlare(false), VICTORY_CLIMAX_DURATION_MS);
                }, CENTERING_DURATION_MS);
            }, 400); 
            return () => clearTimeout(settleTimer);
        }
    }, [headerStage, visualLevel, visualGain, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || successIndices.has(idx) || headerStage === 'TICKING') return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 400 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 1500);
        }
    }, [claimingIndices, claimingAllIndices, successIndices, user, performSynchronizedAction, headerStage]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || successIndices.has(idx) || headerStage === 'TICKING') return;
        setClaimingAllIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user, type), { visualDelay: 600 });
        setClaimingAllIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
