import React, { useState, useRef, useEffect } from 'react';
import { HexBadge } from '../ui/HexBadge';
import { GameText } from '../ui/GameText';
import { ProgressionRewardType } from '../../types';
import { getVariant } from './progressionUtils';

interface ProgressionHexButtonProps {
    type: ProgressionRewardType;
    unclaimedCount: number;
    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

export const ProgressionHexButton: React.FC<ProgressionHexButtonProps> = ({
    type,
    unclaimedCount,
    isClaiming,
    isClaimingAll,
    isSuccess,
    onClaim,
    onClaimAll
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const canClaim = unclaimedCount > 0;
    const variant = getVariant(type);

    const startHold = (e: React.PointerEvent) => {
        if (!canClaim || unclaimedCount <= 1 || isClaiming || isClaimingAll || isSuccess) return;
        setIsHolding(true);
        const startTime = Date.now();
        timerRef.current = window.setInterval(() => {
            const p = Math.min(((Date.now() - startTime) / 1000) * 100, 100);
            setProgress(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                onClaimAll();
                setIsHolding(false);
                setProgress(0);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) clearInterval(timerRef.current);
        setIsHolding(false);
        setProgress(0);
    };

    const handleClick = (e: React.MouseEvent) => {
        if (progress < 100 && canClaim && !isClaiming && !isClaimingAll && !isSuccess) {
            onClaim();
        }
    };

    // Pulse animation for available rewards
    const pulseClass = canClaim && !isSuccess && !isClaiming && !isClaimingAll ? 'animate-hex-pulse' : '';

    return (
        <div 
            className={`relative group cursor-pointer select-none touch-none transition-transform active:scale-90 ${!canClaim && !isSuccess ? 'opacity-40 grayscale pointer-events-none' : ''}`}
            onPointerDown={startHold}
            onPointerUp={cancelHold}
            onPointerLeave={cancelHold}
            onClick={handleClick}
        >
            {/* Hold Progress Radial (Simulated with a clip-path or simple overlay) */}
            {isHolding && (
                <div className="absolute inset-0 z-50 pointer-events-none flex items-center justify-center">
                    <div className="w-full h-full bg-white/20 rounded-full animate-ping" />
                </div>
            )}

            <HexBadge 
                variant={isSuccess ? 'success' : variant} 
                size="lg" 
                glow={canClaim}
                className={`${pulseClass} transition-all duration-500`}
            >
                <div className="flex flex-col items-center justify-center w-full h-full relative">
                    {isSuccess ? (
                        <svg className="w-8 h-8 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={4}>
                            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                        </svg>
                    ) : isClaiming || isClaimingAll ? (
                        <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin" />
                    ) : (
                        <>
                            <div className="h-6 w-full mb-0.5">
                                <GameText text="CLAIM" baseFontSize={0.7} className="text-white font-black italic tracking-tighter" />
                            </div>
                            {unclaimedCount > 1 && (
                                <div className="absolute -bottom-1 -right-1 bg-red-600 border border-white text-[0.5rem] font-black px-1 rounded-full shadow-lg z-50">
                                    {unclaimedCount}
                                </div>
                            )}
                        </>
                    )}
                </div>
            </HexBadge>

            <style>{`
                @keyframes hex-pulse {
                    0% { transform: scale(1); filter: brightness(1); }
                    50% { transform: scale(1.08); filter: brightness(1.3); drop-shadow: 0 0 15px currentColor; }
                    100% { transform: scale(1); filter: brightness(1); }
                }
                .animate-hex-pulse {
                    animation: hex-pulse 2s infinite ease-in-out;
                }
            `}</style>
        </div>
    );
};

