    isNewlyGained?: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const ProgressionTrackRowComponent: React.FC<ProgressionTrackRowProps> = ({
    track,
    isClaiming,
    isClaimingAll,
    isSuccess,
    isLapping = false,
    isNewlyGained = false,
    onClaim,
    onClaimAll
}) => {
    const styles = getColors(track.type);
    const percent = (track.currentXP / track.targetXP) * 100;

    const isResetting = !isLapping && percent < 15;
    const transitionDuration = isResetting ? 'duration-[150ms]' : 'duration-[250ms]';

    return (
        <div 
            className="flex flex-col h-14 px-4 will-change-transform overflow-visible justify-center"
            style={{ contain: 'layout' }} 
        >
            {/* TOP ROW: LABEL */}
            <div className="h-3 w-full mb-1 px-1">
                <GameText 
                    text={`${track.nextRewardAmount} ${track.label}`} 
                    baseFontSize={0.65} 
                    className="text-white font-black uppercase tracking-[0.15em] text-left opacity-80 drop-shadow-md" 
                />
            </div>

            {/* BOTTOM ROW: CONNECTED BAR AND HEX */}
            <div className="flex items-center overflow-visible">
                {/* TRACK CONTAINER: Flat right edge, no gap */}
                <div className={`
                    flex-1 h-[1.7rem] ${styles.bgTrack} border-2 border-white/20 border-r-0 rounded-l-full overflow-hidden shadow-inner relative
                    ${isLapping ? 'ring-1 ring-white shadow-[0_0_10px_rgba(255,255,255,0.4)]' : ''}
                `}>
                    <div 
                        className={`h-full bg-gradient-to-r ${styles.color} transition-all ${transitionDuration} ease-out`} 
                        style={{ width: `${isLapping ? 100 : percent}%` }} 
                    />

                    <div className="absolute inset-0 flex items-center justify-end pr-4 py-0 pointer-events-none">
                        <span className="text-[0.8rem] text-white font-black italic tracking-wider drop-shadow-md tabular-nums">
                            {isLapping ? track.targetXP : track.currentXP} / {track.targetXP} CL
                        </span>
                    </div>
                </div>

                {/* ACTION BUTTON: Negative margin pulls the hex vertical edge flush against the bar */}
                {/* TRANSFORM REMOVED for isNewlyGained per feedback */}
                <div className={`shrink-0 z-20 transition-transform duration-300 ml-[-0.18rem]`}>
                    <ProgressionHexButton 
                        type={track.type}
                        unclaimedCount={track.unclaimedCount}
                        isClaiming={isClaiming}
                        isClaimingAll={isClaimingAll}
                        isSuccess={isSuccess}
                        onClaim={onClaim}
                        onClaimAll={onClaimAll}
                    />
                </div>
            </div>
        </div>
    );
};

export const ProgressionTrackRow = React.memo(ProgressionTrackRowComponent);

import { ProgressionRewardType } from '../../types';

export const getScale = (type: string) => {
    // Scales adjusted based on user feedback
    if (type === 'tokens') return 'scale-[1.36]';   // 1.13 * 1.2
    if (type === 'gold') return 'scale-[1.16]';     // 0.58 * 2.0
    if (type === 'credits') return 'scale-[1.16]';  // 0.58 * 2.0
    if (type === 'booster') return 'scale-[1.4]';    // 0.93 * 1.5
    if (type === 'box') return 'scale-[1.4]';        // 1.17 * 1.2
    return 'scale-[1.4]';
};

export const getVariant = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return 'success';
        case 'credits': return 'blue';
        case 'gold': return 'warning';
        case 'tokens': return 'danger';
        case 'box': return 'primary';
        default: return 'secondary';
    }
};

export const getPulseColor = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return 'border-emerald-400';
        case 'credits': return 'border-blue-400';
        case 'gold': return 'border-amber-400';
        case 'tokens': return 'border-red-400';
        case 'box': return 'border-indigo-400';
        default: return 'border-white';
    }
};

export const getColors = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return { color: 'from-emerald-600 to-emerald-400', bgTrack: 'bg-[#064e3b]', borderColor: 'border-emerald-400/50' };
        case 'credits': return { color: 'from-blue-600 to-blue-400', bgTrack: 'bg-[#1e3a8a]', borderColor: 'border-blue-400/50' };
        case 'gold': return { color: 'from-amber-600 to-amber-400', bgTrack: 'bg-[#78350f]', borderColor: 'border-amber-400/50' };
        case 'tokens': return { color: 'from-red-600 to-red-400', bgTrack: 'bg-[#450a0a]', borderColor: 'border-red-400/50' };
        case 'box': return { color: 'from-indigo-600 to-indigo-400', bgTrack: 'bg-[#1e1b4b]', borderColor: 'border-indigo-400/50' };
        default: return { color: 'from-slate-600 to-white', bgTrack: 'bg-[#334155]', borderColor: 'border-white/50' };
    }
};

