        case 'credits': return { color: 'from-blue-600 to-blue-400', bgTrack: 'bg-[#1e3a8a]', borderColor: 'border-blue-400/50' };
        case 'gold': return { color: 'from-amber-600 to-amber-400', bgTrack: 'bg-[#78350f]', borderColor: 'border-amber-400/50' };
        case 'tokens': return { color: 'from-red-600 to-red-400', bgTrack: 'bg-[#450a0a]', borderColor: 'border-red-400/50' };
        case 'box': return { color: 'from-indigo-600 to-indigo-400', bgTrack: 'bg-[#1e1b4b]', borderColor: 'border-indigo-400/50' };
        default: return { color: 'from-slate-600 to-white', bgTrack: 'bg-[#334155]', borderColor: 'border-white/50' };
    }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { ProgressionRewardType } from '../../types';
import { getVariant, getScale, getPulseColor, getSpinnerColor, getCheckmarkColor, getFlareColor } from './progressionUtils';
import { GameText } from '../ui/GameText';

interface ProgressionHexButtonProps {
    type: ProgressionRewardType;
    unclaimedCount: number;
    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const CheckmarkIcon = ({ className = "", delay = 0, colorClass = "text-white" }: { className?: string, delay?: number, colorClass?: string }) => (
    <svg 
        className={`w-full h-full animate-pop ${colorClass} ${className}`} 
        fill="none" 
        viewBox="0 0 24 24" 
        stroke="currentColor" 
        strokeWidth={1.5}
        style={{ animationDelay: `${delay}ms` }}
    >
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

export const ProgressionHexButton: React.FC<ProgressionHexButtonProps> = ({
    type,
    unclaimedCount,
    isClaiming,
    isClaimingAll,
    isSuccess,
    onClaim,
    onClaimAll
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [showTapPulse, setShowTapPulse] = useState(false);
    const [capturedCount, setCapturedCount] = useState(1);

    const hasTriggeredHold = useRef(false);
    const timerRef = useRef<number | null>(null);
    const canClaim = unclaimedCount > 0;
    const variant = getVariant(type);
    const pulseBorderColor = getPulseColor(type);
    const spinnerBorderColor = getSpinnerColor(type);
    const checkmarkColor = getCheckmarkColor(type);
    const flareColor = getFlareColor(type);

    const startHold = useCallback((e: React.PointerEvent) => {
        if (!canClaim || isClaiming || isClaimingAll || isSuccess) return;

        hasTriggeredHold.current = false;

        // Only allow "Claim All" hold if there's actually more than 1 to claim
        if (unclaimedCount <= 1) return;

        setIsHolding(true);
        const startTime = Date.now();
        timerRef.current = window.setInterval(() => {
            const p = Math.min(((Date.now() - startTime) / 800) * 100, 100);
            setProgress(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                hasTriggeredHold.current = true;
                setCapturedCount(unclaimedCount);
                onClaimAll();
                setIsHolding(false);
                setProgress(0);
            }
        }, 16);
    }, [canClaim, unclaimedCount, isClaiming, isClaimingAll, isSuccess, onClaimAll]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }

        // If it wasn't a completed hold, treat as a single claim tap
        if (!hasTriggeredHold.current && !isClaiming && !isClaimingAll && !isSuccess && canClaim) {
            setShowTapPulse(true);
            setTimeout(() => setShowTapPulse(false), 600);
            setCapturedCount(1);
            onClaim();
        }

        setIsHolding(false);
        setProgress(0);
    }, [isClaiming, isClaimingAll, isSuccess, canClaim, onClaim]);

    const cancelHold = useCallback(() => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        setProgress(0);
    }, []);

    useEffect(() => {
        return () => { if (timerRef.current) clearInterval(timerRef.current); };
    }, []);

    // Idle pulse vs Success Flare vs Active Charging
    const pulseClass = canClaim && !isSuccess && !isClaiming && !isClaimingAll && !isHolding ? 'animate-hex-glow' : '';
    const successClass = isSuccess ? 'animate-success-flare' : '';
    const bulkChargeClass = isHolding ? 'brightness-125' : '';

    const renderSuccessIcons = () => {
        // Multi-checkmark staggered arrangement logic
        if (capturedCount <= 1) {
            return <div className="w-8 h-8"><CheckmarkIcon colorClass={checkmarkColor} /></div>;
        }
        if (capturedCount === 2) {
            return (
                <div className="relative w-10 h-10">
                    <div className="absolute top-1 left-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                    <div className="absolute bottom-1 right-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                </div>
            );
        }
        // 3 or more (Triangular staggered layout)
        return (
            <div className="relative w-10 h-10">
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                <div className="absolute bottom-0.5 left-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                <div className="absolute bottom-0.5 right-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={300} /></div>
            </div>
        );
    };

    return (
        <div 
            className={`relative group cursor-pointer select-none touch-none transition-all duration-300 ${!canClaim && !isSuccess ? 'opacity-40 grayscale pointer-events-none' : ''} ${bulkChargeClass}`}
            onPointerDown={startHold}
            onPointerUp={handlePointerUp}
            onPointerLeave={cancelHold}
            onContextMenu={(e) => e.preventDefault()}
            style={{ '--flare-color': flareColor } as React.CSSProperties}
        >
            {/* TAP PULSE EFFECT (Dynamic Thematic Color) */}
            {showTapPulse && (
                <div className="absolute inset-0 z-50 pointer-events-none flex items-center justify-center">
                    <div className={`w-full h-full border-4 ${pulseBorderColor} rounded-full animate-ping opacity-100`} />
                </div>
            )}

            {/* HOLD PROGRESS CIRCLE */}
            {isHolding && (
                <div className="absolute inset-[-0.2rem] z-50 pointer-events-none flex items-center justify-center">
                    <svg className="w-full h-full -rotate-90 drop-shadow-[0_0_8px_rgba(34,211,238,0.8)]" viewBox="0 0 100 100">
                        <circle
                            cx="50" cy="50" r="45"
                            fill="none"
                            stroke="white"
                            strokeWidth="6"
                            strokeDasharray={`${progress * 2.82} 282`}
                            strokeLinecap="round"
                            className="opacity-90"
                        />
                    </svg>
                    <div className="absolute inset-0 bg-cyan-500/20 rounded-full animate-pulse" />
                </div>
            )}

            <HexBadge 
                variant={variant} 
                size="lg" 
                glow={canClaim || isSuccess}
                className={`${pulseClass} ${successClass} transition-all duration-500`}
            >
                <div className="flex flex-col items-center justify-center w-full h-full relative">
                    {isSuccess ? (
                        renderSuccessIcons()
                    ) : isClaiming || isClaimingAll ? (
                        <div className={`w-6 h-6 border-4 border-white/20 ${spinnerBorderColor} rounded-full animate-spin shadow-[0_0_10px_rgba(255,255,255,0.2)]`} />
                    ) : (
                        <>
                            <div className={`flex items-center justify-center transition-transform duration-300 ${getScale(type)}`}>
                                <RewardIconGraphic type={type as any} size="sm" />
                            </div>
                            {unclaimedCount > 1 && (
                                <div className="absolute -bottom-1 -right-1 bg-red-600 border border-white h-[1.1rem] min-w-[1.1rem] px-1 flex items-center justify-center rounded-full shadow-[0_2px_5px_rgba(0,0,0,0.5)] z-50 animate-pop overflow-hidden">
                                    <div className="w-full h-[70%]">
                                        <GameText 
                                            text={unclaimedCount.toString()} 
                                            baseFontSize={0.55} 
                                            italic={false}
                                            className="text-white font-black drop-shadow-md" 
                                        />
                                    </div>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </HexBadge>

            <style>{`
                @keyframes hex-glow {
                    0% { filter: brightness(1) drop-shadow(0 0 5px rgba(255,255,255,0.1)); }
                    50% { filter: brightness(1.4) drop-shadow(0 0 20px currentColor); }
                    100% { filter: brightness(1) drop-shadow(0 0 5px rgba(255,255,255,0.1)); }
                }
                .animate-hex-glow {
                    animation: hex-glow 2.5s infinite ease-in-out;
                }

                @keyframes success-flare {
                    0% { filter: brightness(1) drop-shadow(0 0 0px var(--flare-color)); }
                    40% { filter: brightness(3.5) drop-shadow(0 0 45px var(--flare-color)); }
                    70% { filter: brightness(3) drop-shadow(0 0 40px var(--flare-color)); }
                    100% { filter: brightness(1) drop-shadow(0 0 5px rgba(255,255,255,0.1)); }
                }
                .animate-success-flare {
                    animation: success-flare 2.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </div>
    );
};

