    // Helper for the experimental overlay
    const renderOverlay = () => {
        if (!SHOW_EXPERIMENTAL_OVERLAY || size !== 'sm' || !amount || type === 'card' || type === 'box') return null;

        // Switched from dynamic GameText to a fixed 0.9rem font size for absolute consistency
        return (
            <div className="absolute left-1/2 -translate-x-1/2 bottom-[-0.45rem] z-50 flex justify-center pointer-events-none overflow-visible">
