                    {amount}
                </span>
            </div>
        );
    };

    const wrap = (icon: React.ReactNode) => (
        <div className="relative flex items-center justify-center overflow-visible">
            {/* Shift the icon UP when the overlay is active to create vertical separation */}
            <div className={`transition-transform duration-300 ${SHOW_EXPERIMENTAL_OVERLAY && size === 'sm' ? '-translate-y-1' : ''}`}>
                {icon}
            </div>
            {renderOverlay()}
        </div>
    );

    switch (type) {
        case 'gold': return wrap(<GoldIcon size={iconSize} animate={isHero} />);
        case 'credits': return wrap(<CreditIcon size={iconSize} />);
        case 'tokens': return wrap(<TokenIcon size={iconSize} animate={isHero} />);
        case 'card': 
            if (cardDef) {
                return (
                    <div className={`${isHero ? 'w-44' : (size === 'lg' ? 'w-36' : 'w-9')} aspect-[5/7] flex items-center justify-center shadow-2xl`}>
