                            {rewardAmount && (
                                <div className="absolute left-1/2 -translate-x-1/2 bottom-[-0.45rem] z-50 flex justify-center pointer-events-none overflow-visible">
                                    <span className="text-white font-black italic drop-shadow-[0_2px_4px_rgba(0,0,0,1)] text-[0.6rem] leading-none uppercase tracking-tighter tabular-nums whitespace-nowrap">
                                        {rewardAmount}
                                    </span>
                                </div>
