    isClaimingAll: boolean;
    isSuccess: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const CheckmarkIcon = ({ className = "", delay = 0, colorClass = "text-white" }: { className?: string, delay?: number, colorClass?: string }) => (
    <svg 
        className={`w-full h-full animate-pop ${colorClass} ${className}`} 
        fill="none" 
        viewBox="0 0 24 24" 
        stroke="currentColor" 
        strokeWidth={1.5}
        style={{ animationDelay: `${delay}ms` }}
    >
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

/**
 * GLOBAL FLOATING FEEDBACK ELEMENT
 * Rendered via Portal to avoid clipping and ensure smooth screen-space motion.
 */
interface FloatingClaimProps {
    amount: string | number;
    type: ProgressionRewardType;
    x: number;
    y: number;
    onComplete: () => void;
}

const FloatingClaimText: React.FC<FloatingClaimProps> = ({ amount, type, x, y, onComplete }) => {
    useEffect(() => {
        const timer = setTimeout(onComplete, 1400); // Animation duration match
        return () => clearTimeout(timer);
    }, [onComplete]);

    return (
        <div 
            className="fixed z-[999] pointer-events-none animate-float-reward-smooth flex items-center gap-1.5 whitespace-nowrap will-change-transform"
            style={{ 
                left: x, 
                top: y,
                /* We use translate(-50%, -50%) to center the spawn point on the hex */
            }}
        >
            {type !== 'box' && (
                <span className="text-white font-black italic text-2xl drop-shadow-[0_4px_8px_rgba(0,0,0,1)] tracking-tighter">
                    +{amount}
                </span>
            )}
            <div className="w-8 h-8 drop-shadow-[0_4px_10px_rgba(0,0,0,0.8)]">
                <RewardIconGraphic type={type} size="sm" />
