    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const CheckmarkIcon = ({ className = "", delay = 0, colorClass = "text-white" }: { className?: string, delay?: number, colorClass?: string }) => (
    <svg 
        className={`w-full h-full animate-pop ${colorClass} ${className}`} 
        fill="none" 
        viewBox="0 0 24 24" 
        stroke="currentColor" 
        strokeWidth={1.5}
        style={{ animationDelay: `${delay}ms` }}
    >
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

/**
 * GLOBAL FLOATING FEEDBACK ELEMENT
 * Rendered via Portal to avoid clipping and ensure smooth screen-space motion.
 */
interface FloatingClaimProps {
    amount: string | number;
    type: ProgressionRewardType;
    x: number;
    y: number;
    onComplete: () => void;
}

const FloatingClaimText: React.FC<FloatingClaimProps> = ({ amount, type, x, y, onComplete }) => {
    useEffect(() => {
        const timer = setTimeout(onComplete, 1800); // Extended duration for long smooth glide
        return () => clearTimeout(timer);
    }, [onComplete]);

    const themeColor = getFlareColor(type);

    return (
        <div 
            className="fixed z-[999] pointer-events-none animate-float-reward-smooth flex items-center gap-2 whitespace-nowrap will-change-transform"
