                left: x, 
                top: y,
                color: themeColor,
                /* Using filter for additional pop */
                filter: `drop-shadow(0 0 8px ${themeColor}66) brightness(1.2)`
            }}
        >
            {type !== 'box' && (
                <span className="font-black italic text-4xl tracking-tighter drop-shadow-[0_4px_8px_rgba(0,0,0,0.9)]">
                    +{amount}
                </span>
            )}
            <div className="w-10 h-10 drop-shadow-[0_4px_12px_rgba(0,0,0,0.8)]">
                <RewardIconGraphic type={type} size="sm" />
