                    animation: success-flare 2.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }

                /**
                 * PURE UNIFORM SPEED ENGINE
                 * Uses fixed pixel values (px) instead of percentages (%) to ensure
                 * all rewards travel at the exact same velocity regardless of their content size.
                 */
                @keyframes reward-drift-pure {
                    0% { 
                        transform: translate3d(-50%, -50%, 0); 
