import React, { useState, useRef, useEffect, useCallback } from 'react';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { ProgressionRewardType } from '../../types';
import { getVariant, getScale, getPulseColor, getSpinnerColor, getCheckmarkColor, getFlareColor } from './progressionUtils';
import { GameText } from '../ui/GameText';
import { Portal } from '../ui/Portal';

interface ProgressionHexButtonProps {
    type: ProgressionRewardType;
    unclaimedCount: number;
    rewardAmount?: string | number;
    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const CheckmarkIcon = ({ className = "", delay = 0, colorClass = "text-white" }: { className?: string, delay?: number, colorClass?: string }) => (
    <svg 
        className={`w-full h-full animate-pop ${colorClass} ${className}`} 
        fill="none" 
        viewBox="0 0 24 24" 
        stroke="currentColor" 
        strokeWidth={1.5}
        style={{ animationDelay: `${delay}ms` }}
    >
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

/**
 * GLOBAL FLOATING FEEDBACK ELEMENT
 * Optimized for uniform velocity and a clean "dissolve" fade-out.
 */
interface FloatingClaimProps {
    amount: string | number;
    type: ProgressionRewardType;
    x: number;
    y: number;
    onComplete: () => void;
}

const FloatingClaimText: React.FC<FloatingClaimProps> = ({ amount, type, x, y, onComplete }) => {
    useEffect(() => {
        const timer = setTimeout(onComplete, 1800); 
        return () => clearTimeout(timer);
    }, [onComplete]);

    const themeColor = getFlareColor(type);
    const isBox = type === 'box';

    return (
        <div 
            className="fixed z-[999] pointer-events-none flex items-center gap-1.5 whitespace-nowrap will-change-transform reward-float-container"
            style={{ 
                left: x, 
                top: y,
                color: themeColor,
                filter: `drop-shadow(0 0 6px ${themeColor}44)`
            }}
        >
            {!isBox && (
                <span className="font-black italic text-sm tracking-tighter drop-shadow-[0_2px_4px_rgba(0,0,0,1)]">
                    +{amount}
                </span>
            )}
            <div className={`${isBox ? 'w-10 h-10' : 'w-5 h-5'} drop-shadow-[0_2px_6px_rgba(0,0,0,0.8)]`}>
                <RewardIconGraphic type={type} size="sm" />
            </div>
        </div>
    );
};

export const ProgressionHexButton: React.FC<ProgressionHexButtonProps> = ({
    type,
    unclaimedCount,
    rewardAmount,
    isClaiming,
    isClaimingAll,
    isSuccess,
    onClaim,
    onClaimAll
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [showTapPulse, setShowTapPulse] = useState(false);
    const [capturedCount, setCapturedCount] = useState(1);

    const [activeFloaters, setActiveFloaters] = useState<{id: number, amount: string|number, x: number, y: number}[]>([]);

    const hasTriggeredHold = useRef(false);
    const timerRef = useRef<number | null>(null);
    const canClaim = unclaimedCount > 0;
    const variant = getVariant(type);
    const pulseBorderColor = getPulseColor(type);
    const spinnerBorderColor = getSpinnerColor(type);
    const checkmarkColor = getCheckmarkColor(type);
    const flareColor = getFlareColor(type);

    const triggerFloatingFeedback = useCallback((bulkCount: number = 1) => {
        if (!containerRef.current) return;

        const rect = containerRef.current.getBoundingClientRect();
        const spawnX = rect.left + rect.width / 2;
        const spawnY = rect.top + rect.height / 2;

        const amount = typeof rewardAmount === 'number' ? rewardAmount * bulkCount : (rewardAmount || '');
        const id = Date.now() + Math.random();
        setActiveFloaters(prev => [...prev, { id, amount, x: spawnX, y: spawnY }]);
    }, [rewardAmount]);

    const startHold = useCallback((e: React.PointerEvent) => {
        if (!canClaim || isClaiming || isClaimingAll || isSuccess) return;

        hasTriggeredHold.current = false;

        if (unclaimedCount <= 1) return;

        setIsHolding(true);
        const startTime = Date.now();
        timerRef.current = window.setInterval(() => {
            const p = Math.min(((Date.now() - startTime) / 800) * 100, 100);
            setProgress(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                hasTriggeredHold.current = true;
                setCapturedCount(unclaimedCount);
                triggerFloatingFeedback(unclaimedCount);
                onClaimAll();
                setIsHolding(false);
                setProgress(0);
            }
        }, 16);
    }, [canClaim, unclaimedCount, isClaiming, isClaimingAll, isSuccess, onClaimAll, triggerFloatingFeedback]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }

        if (!hasTriggeredHold.current && !isClaiming && !isClaimingAll && !isSuccess && canClaim) {
            setShowTapPulse(true);
            setTimeout(() => setShowTapPulse(false), 600);
            setCapturedCount(1);
            triggerFloatingFeedback(1);
            onClaim();
        }

        setIsHolding(false);
        setProgress(0);
    }, [isClaiming, isClaimingAll, isSuccess, canClaim, onClaim, triggerFloatingFeedback]);

    const cancelHold = useCallback(() => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        setProgress(0);
    }, []);

    useEffect(() => {
        return () => { if (timerRef.current) clearInterval(timerRef.current); };
    }, []);

    const pulseClass = canClaim && !isSuccess && !isClaiming && !isClaimingAll && !isHolding ? 'animate-hex-glow' : '';
    const successClass = isSuccess ? 'animate-success-flare' : '';
    const bulkChargeClass = isHolding ? 'brightness-125' : '';

    const renderSuccessIcons = () => {
        if (capturedCount <= 1) {
            return <div className="w-8 h-8"><CheckmarkIcon colorClass={checkmarkColor} /></div>;
        }
        if (capturedCount === 2) {
            return (
                <div className="relative w-10 h-10">
                    <div className="absolute top-1 left-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                    <div className="absolute bottom-1 right-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                </div>
            );
        }
        return (
            <div className="relative w-10 h-10">
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                <div className="absolute bottom-0.5 left-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                <div className="absolute bottom-0.5 right-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={300} /></div>
            </div>
        );
    };

    return (
        <div 
            ref={containerRef}
            className={`relative group cursor-pointer select-none touch-none transition-all duration-300 ${!canClaim && !isSuccess ? 'opacity-40 grayscale pointer-events-none' : ''} ${bulkChargeClass}`}
            onPointerDown={startHold}
            onPointerUp={handlePointerUp}
            onPointerLeave={cancelHold}
            onContextMenu={(e) => e.preventDefault()}
            style={{ 
                '--flare-color': flareColor,
                '--glow-color': flareColor 
            } as React.CSSProperties}
        >
            <Portal>
                {activeFloaters.map(f => (
                    <FloatingClaimText 
                        key={f.id} 
                        amount={f.amount} 
                        type={type} 
                        x={f.x}
                        y={f.y}
                        onComplete={() => setActiveFloaters(prev => prev.filter(item => item.id !== f.id))} 
                    />
                ))}
            </Portal>

            {showTapPulse && (
                <div className="absolute inset-0 z-50 pointer-events-none flex items-center justify-center">
                    <div className={`w-full h-full border-4 ${pulseBorderColor} rounded-full animate-ping opacity-100`} />
                </div>
            )}

            {isHolding && (
                <div className="absolute inset-[-0.2rem] z-50 pointer-events-none flex items-center justify-center">
                    <svg 
                        className="w-full h-full -rotate-90" 
                        style={{ filter: `drop-shadow(0 0 6px var(--flare-color))` }}
                        viewBox="0 0 100 100"
                    >
                        <circle
                            cx="50" cy="50" r="45"
                            fill="none"
                            stroke={flareColor}
                            strokeWidth="6"
                            strokeDasharray={`${progress * 2.82} 282`}
                            strokeLinecap="round"
                            className="opacity-90"
                        />
                    </svg>
                    <div className="absolute inset-0 rounded-full animate-pulse opacity-20" style={{ backgroundColor: flareColor }} />
                </div>
            )}

            <HexBadge 
                variant={variant} 
                size="lg" 
                glow={canClaim || isSuccess}
                className={`${pulseClass} ${successClass} transition-all duration-500`}
            >
                <div className="flex flex-col items-center justify-center w-full h-full relative">
                    {isSuccess ? (
                        renderSuccessIcons()
                    ) : isClaiming || isClaimingAll ? (
                        <div className={`w-6 h-6 border-4 border-white/20 ${spinnerBorderColor} rounded-full animate-spin shadow-[0_0_10px_rgba(255,255,255,0.2)]`} />
                    ) : (
                        <div className="relative flex items-center justify-center w-full h-full overflow-visible">
                            <div className={`${getScale(type)} ${type !== 'box' ? '-translate-y-[0.5rem]' : ''}`}>
                                <RewardIconGraphic type={type as any} size="sm" />
                            </div>

                            {rewardAmount && type !== 'box' && (
                                <div className="absolute left-1/2 -translate-x-1/2 bottom-[0.3rem] z-50 flex justify-center pointer-events-none overflow-visible">
                                    <span className={`text-white font-black italic drop-shadow-[0_2px_4px_rgba(0,0,0,1)] leading-none uppercase tracking-tighter tabular-nums whitespace-nowrap ${type === 'tokens' ? 'text-[0.7rem]' : 'text-[0.8rem]'}`}>
                                        {rewardAmount}
                                    </span>
                                </div>
                            )}

                            {unclaimedCount > 0 && (
                                <div className="absolute -bottom-3 -right-3 bg-red-600 border-2 border-white h-[1.3rem] min-w-[1.3rem] px-1 flex items-center justify-center rounded-full shadow-[0_2px_8px_rgba(0,0,0,0.6)] z-50 animate-pop overflow-hidden">
                                    <div className="w-full h-[75%]">
                                        <GameText 
                                            text={unclaimedCount.toString()} 
                                            baseFontSize={0.65} 
                                            italic={false}
                                            className="text-white font-black drop-shadow-md" 
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </HexBadge>

            <style>{`
                @keyframes hex-glow {
                    0% { filter: brightness(1) drop-shadow(0 0 2px var(--glow-color)); }
                    50% { 
                        filter: brightness(1.1) 
                                drop-shadow(0 0 4px var(--glow-color)) 
                                drop-shadow(0 0 8px var(--glow-color)); 
                    }
                    100% { filter: brightness(1) drop-shadow(0 0 2px var(--glow-color)); }
                }
                .animate-hex-glow {
                    animation: hex-glow 3s infinite ease-in-out;
                }

                @keyframes success-flare {
                    0% { filter: brightness(1) drop-shadow(0 0 0px var(--flare-color)); }
                    40% { filter: brightness(3.5) drop-shadow(0 0 45px var(--flare-color)); }
                    70% { filter: brightness(3) drop-shadow(0 0 40px var(--flare-color)); }
                    100% { filter: brightness(1) drop-shadow(0 0 5px rgba(255,255,255,0.1)); }
                }
                .animate-success-flare {
                    animation: success-flare 2.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }

                /**
                 * REFINED UNIFORM DISSOLVE ENGINE
                 * Uses a single continuous translate with a long opacity dissolve.
                 */
                @keyframes reward-drift-pure {
                    0% { 
                        transform: translate3d(-50%, -50%, 0); 
                        opacity: 0; 
                    }
                    15% { 
                        opacity: 1; 
                    }
                    100% { 
                        /* Fixed distance for uniform velocity */
                        transform: translate3d(-50%, -320px, 0); 
                        opacity: 0; 
                    }
                }
                .reward-float-container {
                    animation: reward-drift-pure 1.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionTrack } from '../../types';
import { getColors } from './progressionUtils';
import { GameText } from '../ui/GameText';
import { ProgressionHexButton } from './ProgressionHexButton';

interface ProgressionTrackRowProps {
    track: ProgressionTrack;
    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    isGlobalTicking: boolean;
    isLapping?: boolean;
    isNewlyGained?: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const ProgressionTrackRowComponent: React.FC<ProgressionTrackRowProps> = ({
    track,
    isClaiming,
    isClaimingAll,
    isSuccess,
    isGlobalTicking,
    isLapping = false,
    isNewlyGained = false,
    onClaim,
    onClaimAll
}) => {
    const styles = getColors(track.type);
    const percent = (track.currentXP / track.targetXP) * 100;

    /**
     * RESET LOGIC
     * We disable all transitions when the percent is at 0 to ensure the bar 
     * snaps to the start instantly without a sliding "rubber band" effect.
     */
    const isAtStart = percent === 0;
    const transitionClass = isAtStart 
        ? 'transition-none' 
        : 'transition-[width] duration-[200ms] ease-out';

    return (
        <div 
            className="flex flex-col h-11 px-4 will-change-transform overflow-visible justify-center"
            style={{ contain: 'layout' }} 
        >
            {/* BOTTOM ROW: CONNECTED BAR AND HEX */}
            <div className="flex items-center overflow-visible">
                {/* TRACK CONTAINER: Flat right edge, no gap */}
                <div className={`
                    flex-1 h-[1.7rem] ${styles.bgTrack} border-2 border-white/20 border-r-0 rounded-l-full overflow-hidden shadow-inner relative
                    ${isLapping ? 'ring-1 ring-white shadow-[0_0_10px_rgba(255,255,255,0.4)]' : ''}
                `}>
                    <div 
                        className={`h-full bg-gradient-to-r ${styles.color} ${transitionClass}`} 
                        style={{ width: `${isLapping ? 100 : percent}%` }} 
                    />

                    <div className="absolute inset-0 flex items-center justify-end pr-4 py-0 pointer-events-none">
                        <span className="text-[0.8rem] text-white font-black italic tracking-wider drop-shadow-md tabular-nums">
                            {isLapping ? track.targetXP : track.currentXP} / {track.targetXP} CL
                        </span>
                    </div>
                </div>

                {/* ACTION BUTTON: Negative margin pulls the hex vertical edge flush against the bar */}
                <div className={`shrink-0 z-20 transition-transform duration-300 ml-[-0.18rem]`}>
                    <ProgressionHexButton 
                        type={track.type}
                        unclaimedCount={track.unclaimedCount}
                        rewardAmount={track.nextRewardAmount}
                        isClaiming={isClaiming}
                        isClaimingAll={isClaimingAll}
                        isSuccess={isSuccess}
                        isGlobalTicking={isGlobalTicking}
                        isNewlyGained={isNewlyGained}
                        onClaim={onClaim}
                        onClaimAll={onClaimAll}
                    />
                </div>
            </div>
        </div>
    );
};

export const ProgressionTrackRow = React.memo(ProgressionTrackRowComponent);

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 70;
const LAP_MECHANICAL_PAUSE_MS = 100;
const VICTORY_CLIMAX_DURATION_MS = 4500; 

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    // Animation State
    const [isTicking, setIsTicking] = useState(pendingLevelIncrement > 0);
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [visualGain, setVisualGain] = useState<number>(pendingLevelIncrement);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [claimingAllIndices, setClaimingAllIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());

    const handleManualClose = useCallback(() => {
        clearLevelUpSignal();
        onClose();
    }, [clearLevelUpSignal, onClose]);

    // Numerical Chasing Logic
    useEffect(() => {
        if (isTicking && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;
            const nextGain = Math.max(0, visualGain - 1);

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) newLaps.add(i);
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => { const n = new Set(prev); newLaps.forEach(idx => n.add(idx)); return n; });
                    setNewlyGainedIndices(prev => { const n = new Set(prev); newLaps.forEach(idx => n.add(idx)); return n; });

                    audio.play('sfx_ui_click', 1.4); 

                    setTimeout(() => setLappingIndices(prev => { const n = new Set(prev); newLaps.forEach(idx => n.delete(idx)); return n; }), 100);
                    setTimeout(() => setNewlyGainedIndices(prev => { const n = new Set(prev); n.forEach(idx => n.delete(idx)); return n; }), 400);
                }

                setVisualLevel(nextLevel);
                setVisualGain(nextGain);
                audio.play('sfx_ui_hover', 0.3);
            }, currentStepDelay);
            return () => clearTimeout(timer);
        } else if (isTicking && visualLevel >= user.level) {
            setIsTicking(false);
            setIsCompletionFlare(true);
            audio.play('sfx_victory', 0.6);
            clearLevelUpSignal();
            setTimeout(() => setIsCompletionFlare(false), VICTORY_CLIMAX_DURATION_MS);
        }
    }, [isTicking, visualLevel, visualGain, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type, label: config.label,
                currentXP, targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount, nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || isTicking) return;
        setClaimingIndices(prev => { const n = new Set(prev); n.add(idx); return n; });

        const success = await performSynchronizedAction(() => api.claimProgressionReward(user.id, type), { visualDelay: 300 });

        setClaimingIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });

        if (success) {
            setSuccessIndices(prev => { const n = new Set(prev); n.add(idx); return n; });
            setTimeout(() => {
                setSuccessIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });
            }, 800);
        }
    }, [claimingIndices, claimingAllIndices, user.id, performSynchronizedAction, isTicking]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || isTicking) return;
        setClaimingAllIndices(prev => { const n = new Set(prev); n.add(idx); return n; });

        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user.id, type), { visualDelay: 500 });

        setClaimingAllIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });

        if (success) {
            setSuccessIndices(prev => { const n = new Set(prev); n.add(idx); return n; });
            setTimeout(() => {
                setSuccessIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });
            }, 1000);
        }
    }, [claimingIndices, claimingAllIndices, user.id, performSynchronizedAction, isTicking]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    const isShifted = isTicking;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                {/* Background */}
                <div className="absolute inset-0 z-0 bg-[radial-gradient(circle_at_50%_-20%,_#1e1b4b_0%,_#020617_60%)]" />
                <div className="absolute inset-0 animated-bg opacity-30 z-0" />

                {/* --- HEADER --- */}
                <div className="shrink-0 pt-0.5 pb-1.5 flex items-center px-1 bg-gradient-to-b from-slate-700 via-slate-900 to-black border-b border-slate-600 z-40 relative shadow-lg overflow-visible">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">COLLECTION LEVEL</h1>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs" 
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                            onClick={() => setActiveTab('REWARDS')} 
                            icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" /></svg>} 
                        />
                        <SlantedButton 
                            variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                            size="xs" 
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                            onClick={() => setActiveTab('ACTIVITY')} 
                            icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} 
                        />
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0 pt-1">
                            {/* --- HERO AREA (Tightened Spacing) --- */}
                            <div className="shrink-0 pb-2 flex flex-col items-center relative overflow-visible">
                                <div className="relative w-full flex justify-center items-center h-12 overflow-visible">
                                    <div className={`flex items-center gap-1.5 transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${isShifted ? '-translate-x-6' : 'translate-x-0'}`}>
                                        <div className="flex flex-col items-end text-right gap-0.5 opacity-90">
                                            <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white leading-none">COLLECTION</span>
                                            <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white font-black leading-none">LEVEL</span>
                                        </div>
                                        <div className="relative flex items-center overflow-visible">
                                            <div className={`text-[2.2rem] font-black italic tracking-tighter text-white drop-shadow-md leading-none transition-all ${isTicking ? 'animate-intensity-pulse' : ''} ${isCompletionFlare ? 'animate-completion-flare' : ''}`}>{visualLevel.toLocaleString()}</div>
                                            <div className={`absolute left-full ml-2 text-[1.8rem] font-black italic tracking-tighter text-emerald-400 drop-shadow-[0_0_15px_rgba(52,211,153,0.5)] whitespace-nowrap leading-none transition-opacity duration-300 ${visualGain > 0 ? 'opacity-100' : 'opacity-0 translate-x-4 pointer-events-none'}`}>+{visualGain}</div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* --- DIVIDING LINE --- */}
                            <div className="px-6 mb-2">
                                <div className="h-px w-full bg-white/20" />
                            </div>

                            {/* TRACK LIST (Flattened, generous spacing, zero-scroll layout) */}
                            <div className="flex-1 flex flex-col justify-around px-2 pb-4 overflow-hidden">
                                {visualTracks.map((track, idx) => (
                                    <div key={idx} className="w-full">
                                        <ProgressionTrackRow 
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isClaimingAll={claimingAllIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isGlobalTicking={isTicking}
                                            isLapping={lappingIndices.has(idx)}
                                            isNewlyGained={newlyGainedIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                        />
                                    </div>
                                ))}
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                             <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                {/* BOTTOM ANCHOR (Reduced Height) */}
                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3 bg-gradient-to-t from-black via-black/80 to-transparent">
                    <SlantedButton variant="danger" size="md" onClick={handleManualClose} className="shadow-2xl !w-[40vw] max-w-[10rem] !h-8">CLOSE</SlantedButton>
                </div>
            </div>
            <style>{`
                @keyframes intensity-pulse { 0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.2)); } 50% { filter: brightness(2.2) drop-shadow(0 0 35px rgba(255,255,255,0.9)); } }
                .animate-intensity-pulse { animation: intensity-pulse 2s ease-in-out infinite; will-change: filter; }
                @keyframes completion-flare { 0% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); } 35% { transform: scale(1.3); filter: brightness(14); text-shadow: 0 0 40px rgba(99,102,241,1), 0 0 100px rgba(255,255,255,1); } 100% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 25px rgba(99,102,241,0.7); } }
                .animate-completion-flare { animation: completion-flare 4.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; z-index: 100; }
            `}</style>
        </Portal>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { ProgressionRewardType } from '../../types';
import { getVariant, getScale, getPulseColor, getSpinnerColor, getCheckmarkColor, getFlareColor } from './progressionUtils';
import { GameText } from '../ui/GameText';
import { Portal } from '../ui/Portal';

interface ProgressionHexButtonProps {
    type: ProgressionRewardType;
    unclaimedCount: number;
    rewardAmount?: string | number;
    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    isGlobalTicking: boolean;
    isNewlyGained?: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const CheckmarkIcon = ({ className = "", delay = 0, colorClass = "text-white" }: { className?: string, delay?: number, colorClass?: string }) => (
    <svg 
        className={`w-full h-full animate-pop ${colorClass} ${className}`} 
        fill="none" 
        viewBox="0 0 24 24" 
        stroke="currentColor" 
        strokeWidth={1.5}
        style={{ animationDelay: `${delay}ms` }}
    >
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

/**
 * GLOBAL FLOATING FEEDBACK ELEMENT
 * Optimized for uniform velocity and a clean "dissolve" fade-out.
 */
interface FloatingClaimProps {
    amount: string | number;
    type: ProgressionRewardType;
    x: number;
    y: number;
    onComplete: () => void;
}

const FloatingClaimText: React.FC<FloatingClaimProps> = ({ amount, type, x, y, onComplete }) => {
    useEffect(() => {
        // Updated to 5.4s (3x original 1.8s)
        const timer = setTimeout(onComplete, 5400); 
        return () => clearTimeout(timer);
    }, [onComplete]);

    const themeColor = getFlareColor(type);
    const isBox = type === 'box';

    return (
        <div 
            className="fixed z-[999] pointer-events-none flex items-center gap-1.5 whitespace-nowrap will-change-transform reward-float-container"
            style={{ 
                left: x, 
                top: y,
                color: themeColor,
                filter: `drop-shadow(0 0 6px ${themeColor}44)`
            }}
        >
            {!isBox && (
                <span className="font-black italic text-sm tracking-tighter drop-shadow-[0_2px_4px_rgba(0,0,0,1)]">
                    +{amount}
                </span>
            )}
            <div className={`${isBox ? 'w-10 h-10' : 'w-5 h-5'} drop-shadow-[0_2px_6px_rgba(0,0,0,0.8)]`}>
                <RewardIconGraphic type={type} size="sm" />
            </div>
        </div>
    );
};

export const ProgressionHexButton: React.FC<ProgressionHexButtonProps> = ({
    type,
    unclaimedCount,
    rewardAmount,
    isClaiming,
    isClaimingAll,
    isSuccess,
    isGlobalTicking,
    isNewlyGained = false,
    onClaim,
    onClaimAll
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [showTapPulse, setShowTapPulse] = useState(false);
    const [capturedCount, setCapturedCount] = useState(1);

    const [activeFloaters, setActiveFloaters] = useState<{id: number, amount: string|number, x: number, y: number}[]>([]);

    const hasTriggeredHold = useRef(false);
    const timerRef = useRef<number | null>(null);
    const canClaim = unclaimedCount > 0;
    const variant = getVariant(type);
    const pulseBorderColor = getPulseColor(type);
    const spinnerBorderColor = getSpinnerColor(type);
    const checkmarkColor = getCheckmarkColor(type);
    const flareColor = getFlareColor(type);

    const triggerFloatingFeedback = useCallback((bulkCount: number = 1) => {
        if (!containerRef.current) return;

        const rect = containerRef.current.getBoundingClientRect();
        const spawnX = rect.left + rect.width / 2;
        const spawnY = rect.top + rect.height / 2;

        const amount = typeof rewardAmount === 'number' ? rewardAmount * bulkCount : (rewardAmount || '');
        const id = Date.now() + Math.random();
        setActiveFloaters(prev => [...prev, { id, amount, x: spawnX, y: spawnY }]);
    }, [rewardAmount]);

    const startHold = useCallback((e: React.PointerEvent) => {
        if (!canClaim || isClaiming || isClaimingAll || isSuccess) return;

        hasTriggeredHold.current = false;

        if (unclaimedCount <= 1) return;

        setIsHolding(true);
        const startTime = Date.now();
        timerRef.current = window.setInterval(() => {
            const p = Math.min(((Date.now() - startTime) / 800) * 100, 100);
            setProgress(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                hasTriggeredHold.current = true;
                setCapturedCount(unclaimedCount);
                triggerFloatingFeedback(unclaimedCount);
                onClaimAll();
                setIsHolding(false);
                setProgress(0);
            }
        }, 16);
    }, [canClaim, unclaimedCount, isClaiming, isClaimingAll, isSuccess, onClaimAll, triggerFloatingFeedback]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }

        if (!hasTriggeredHold.current && !isClaiming && !isClaimingAll && !isSuccess && canClaim) {
            setShowTapPulse(true);
            setTimeout(() => setShowTapPulse(false), 600);
            setCapturedCount(1);
            triggerFloatingFeedback(1);
            onClaim();
        }

        setIsHolding(false);
        setProgress(0);
    }, [isClaiming, isClaimingAll, isSuccess, canClaim, onClaim, triggerFloatingFeedback]);

    const cancelHold = useCallback(() => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        setProgress(0);
    }, []);

    useEffect(() => {
        return () => { if (timerRef.current) clearInterval(timerRef.current); };
    }, []);

    // Idle glow logic suppressed when global ticking is active
    const pulseClass = canClaim && !isSuccess && !isClaiming && !isClaimingAll && !isHolding && !isGlobalTicking ? 'animate-hex-glow' : '';
    const successClass = isSuccess ? 'animate-success-flare' : '';
    const gainClass = isNewlyGained ? 'animate-gain-flash' : '';
    const bulkChargeClass = isHolding ? 'brightness-125' : '';

    const renderSuccessIcons = () => {
        if (capturedCount <= 1) {
            return <div className="w-8 h-8"><CheckmarkIcon colorClass={checkmarkColor} /></div>;
        }
        if (capturedCount === 2) {
            return (
                <div className="relative w-10 h-10">
                    <div className="absolute top-1 left-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                    <div className="absolute bottom-1 right-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                </div>
            );
        }
        return (
            <div className="relative w-10 h-10">
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                <div className="absolute bottom-0.5 left-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                <div className="absolute bottom-0.5 right-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={300} /></div>
            </div>
        );
    };

    return (
        <div 
            ref={containerRef}
            className={`relative group cursor-pointer select-none touch-none transition-all duration-300 ${!canClaim && !isSuccess ? 'opacity-40 grayscale pointer-events-none' : ''} ${bulkChargeClass}`}
            onPointerDown={startHold}
            onPointerUp={handlePointerUp}
            onPointerLeave={cancelHold}
            onContextMenu={(e) => e.preventDefault()}
            style={{ 
                '--flare-color': flareColor,
                '--glow-color': flareColor 
            } as React.CSSProperties}
        >
            <Portal>
                {activeFloaters.map(f => (
                    <FloatingClaimText 
                        key={f.id} 
                        amount={f.amount} 
                        type={type} 
                        x={f.x}
                        y={f.y}
                        onComplete={() => setActiveFloaters(prev => prev.filter(item => item.id !== f.id))} 
                    />
                ))}
            </Portal>

            {showTapPulse && (
                <div className="absolute inset-0 z-50 pointer-events-none flex items-center justify-center">
                    <div className={`w-full h-full border-4 ${pulseBorderColor} rounded-full animate-ping opacity-100`} />
                </div>
            )}

            {isHolding && (
                <div className="absolute inset-[-0.2rem] z-50 pointer-events-none flex items-center justify-center">
                    <svg 
                        className="w-full h-full -rotate-90" 
                        style={{ filter: `drop-shadow(0 0 6px var(--flare-color))` }}
                        viewBox="0 0 100 100"
                    >
                        <circle
                            cx="50" cy="50" r="45"
                            fill="none"
                            stroke={flareColor}
                            strokeWidth="6"
                            strokeDasharray={`${progress * 2.82} 282`}
                            strokeLinecap="round"
                            className="opacity-90"
                        />
                    </svg>
                    <div className="absolute inset-0 rounded-full animate-pulse opacity-20" style={{ backgroundColor: flareColor }} />
                </div>
            )}

            <HexBadge 
                variant={variant} 
                size="lg" 
                glow={(canClaim || isSuccess) && !isGlobalTicking}
                className={`${pulseClass} ${successClass} ${gainClass} transition-all duration-500`}
            >
                <div className="flex flex-col items-center justify-center w-full h-full relative">
                    {isSuccess ? (
                        renderSuccessIcons()
                    ) : isClaiming || isClaimingAll ? (
                        <div className={`w-6 h-6 border-4 border-white/20 ${spinnerBorderColor} rounded-full animate-spin shadow-[0_0_10px_rgba(255,255,255,0.2)]`} />
                    ) : (
                        <div className="relative flex items-center justify-center w-full h-full overflow-visible">
                            <div className={`${getScale(type)} ${type !== 'box' ? '-translate-y-[0.5rem]' : ''}`}>
                                <RewardIconGraphic type={type as any} size="sm" />
                            </div>

                            {rewardAmount && type !== 'box' && (
                                <div className="absolute left-1/2 -translate-x-1/2 bottom-[0.3rem] z-50 flex justify-center pointer-events-none overflow-visible">
                                    <span className={`text-white font-black italic drop-shadow-[0_2px_4px_rgba(0,0,0,1)] leading-none uppercase tracking-tighter tabular-nums whitespace-nowrap ${type === 'tokens' ? 'text-[0.7rem]' : 'text-[0.8rem]'}`}>
                                        {rewardAmount}
                                    </span>
                                </div>
                            )}

                            {unclaimedCount > 0 && (
                                <div className="absolute -bottom-3 -right-3 bg-red-600 border-2 border-white h-[1.3rem] min-w-[1.3rem] px-1 flex items-center justify-center rounded-full shadow-[0_2px_8px_rgba(0,0,0,0.6)] z-50 animate-pop overflow-hidden">
                                    <div className="w-full h-[75%]">
                                        <GameText 
                                            text={unclaimedCount.toString()} 
                                            baseFontSize={0.65} 
                                            italic={false}
                                            className="text-white font-black drop-shadow-md" 
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </HexBadge>

            <style>{`
                @keyframes hex-glow {
                    0% { filter: brightness(1) drop-shadow(0 0 2px var(--glow-color)); }
                    50% { 
                        filter: brightness(1.1) 
                                drop-shadow(0 0 4px var(--glow-color)) 
                                drop-shadow(0 0 8px var(--glow-color)); 
                    }
                    100% { filter: brightness(1) drop-shadow(0 0 2px var(--glow-color)); }
                }
                .animate-hex-glow {
                    animation: hex-glow 3s infinite ease-in-out;
                }

                @keyframes gain-flash {
                    0% { filter: brightness(1); transform: scale(1); }
                    20% { filter: brightness(2.5) drop-shadow(0 0 15px var(--flare-color)); transform: scale(1.15); }
                    100% { filter: brightness(1); transform: scale(1); }
                }
                .animate-gain-flash {
                    animation: gain-flash 0.5s ease-out;
                }

                @keyframes success-flare {
                    0% { filter: brightness(1) drop-shadow(0 0 0px var(--flare-color)); }
                    40% { filter: brightness(3.5) drop-shadow(0 0 45px var(--flare-color)); }
                    70% { filter: brightness(3) drop-shadow(0 0 40px var(--flare-color)); }
                    100% { filter: brightness(1) drop-shadow(0 0 5px rgba(255,255,255,0.1)); }
                }
                .animate-success-flare {
                    animation: success-flare 2.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }

                /**
                 * REFINED UNIFORM DISSOLVE ENGINE
                 * Uses a single continuous translate with a long opacity dissolve.
                 * Duration increased to 5.4s (3x original).
                 */
                @keyframes reward-drift-pure {
                    0% { 
                        transform: translate3d(-50%, -50%, 0); 
                        opacity: 0; 
                    }
                    15% { 
                        opacity: 1; 
                    }
                    100% { 
                        /* Fixed distance for uniform velocity */
                        transform: translate3d(-50%, -320px, 0); 
                        opacity: 0; 
                    }
                }
                .reward-float-container {
                    animation: reward-drift-pure 5.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 70;
const LAP_MECHANICAL_PAUSE_MS = 100;
const VICTORY_CLIMAX_DURATION_MS = 4500; 

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    // Animation State
    const [isTicking, setIsTicking] = useState(pendingLevelIncrement > 0);
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [visualGain, setVisualGain] = useState<number>(pendingLevelIncrement);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [claimingAllIndices, setClaimingAllIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());

    const handleManualClose = useCallback(() => {
        clearLevelUpSignal();
        onClose();
    }, [clearLevelUpSignal, onClose]);

    // Numerical Chasing Logic
    useEffect(() => {
        if (isTicking && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;
            const nextGain = Math.max(0, visualGain - 1);

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) newLaps.add(i);
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => { const n = new Set(prev); newLaps.forEach(idx => n.add(idx)); return n; });

                    audio.play('sfx_ui_click', 1.4); 

                    setTimeout(() => setLappingIndices(prev => { const n = new Set(prev); newLaps.forEach(idx => n.delete(idx)); return n; }), 100);
                }

                setVisualLevel(nextLevel);
                setVisualGain(nextGain);
                audio.play('sfx_ui_hover', 0.3);
            }, currentStepDelay);
            return () => clearTimeout(timer);
        } else if (isTicking && visualLevel >= user.level) {
            setIsTicking(false);
            setIsCompletionFlare(true);
            audio.play('sfx_victory', 0.6);
            clearLevelUpSignal();
            setTimeout(() => setIsCompletionFlare(false), VICTORY_CLIMAX_DURATION_MS);
        }
    }, [isTicking, visualLevel, visualGain, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type, label: config.label,
                currentXP, targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount, nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || isTicking) return;
        setClaimingIndices(prev => { const n = new Set(prev); n.add(idx); return n; });

        const success = await performSynchronizedAction(() => api.claimProgressionReward(user.id, type), { visualDelay: 300 });

        setClaimingIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });

        if (success) {
            setSuccessIndices(prev => { const n = new Set(prev); n.add(idx); return n; });
            setTimeout(() => {
                setSuccessIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });
            }, 800);
        }
    }, [claimingIndices, claimingAllIndices, user.id, performSynchronizedAction, isTicking]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || isTicking) return;
        setClaimingAllIndices(prev => { const n = new Set(prev); n.add(idx); return n; });

        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user.id, type), { visualDelay: 500 });

        setClaimingAllIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });

        if (success) {
            setSuccessIndices(prev => { const n = new Set(prev); n.add(idx); return n; });
            setTimeout(() => {
                setSuccessIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });
            }, 1000);
        }
    }, [claimingIndices, claimingAllIndices, user.id, performSynchronizedAction, isTicking]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    const isShifted = isTicking;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                {/* Background */}
                <div className="absolute inset-0 z-0 bg-[radial-gradient(circle_at_50%_-20%,_#1e1b4b_0%,_#020617_60%)]" />
                <div className="absolute inset-0 animated-bg opacity-30 z-0" />

                {/* --- HEADER --- */}
                <div className="shrink-0 pt-0.5 pb-1.5 flex items-center px-1 bg-gradient-to-b from-slate-700 via-slate-900 to-black border-b border-slate-600 z-40 relative shadow-lg overflow-visible">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">COLLECTION LEVEL</h1>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs" 
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                            onClick={() => setActiveTab('REWARDS')} 
                            icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" /></svg>} 
                        />
                        <SlantedButton 
                            variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                            size="xs" 
                            className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                            onClick={() => setActiveTab('ACTIVITY')} 
                            icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} 
                        />
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0 pt-1">
                            {/* --- HERO AREA (Tightened Spacing) --- */}
                            <div className="shrink-0 pb-2 flex flex-col items-center relative overflow-visible">
                                <div className="relative w-full flex justify-center items-center h-12 overflow-visible">
                                    <div className={`flex items-center gap-1.5 transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${isShifted ? '-translate-x-6' : 'translate-x-0'}`}>
                                        <div className="flex flex-col items-end text-right gap-0.5 opacity-90">
                                            <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white leading-none">COLLECTION</span>
                                            <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white font-black leading-none">LEVEL</span>
                                        </div>
                                        <div className="relative flex items-center overflow-visible">
                                            <div className={`text-[2.2rem] font-black italic tracking-tighter text-white drop-shadow-md leading-none transition-all ${isTicking ? 'animate-intensity-pulse' : ''} ${isCompletionFlare ? 'animate-completion-flare' : ''}`}>{visualLevel.toLocaleString()}</div>
                                            <div className={`absolute left-full ml-2 text-[1.8rem] font-black italic tracking-tighter text-emerald-400 drop-shadow-[0_0_15px_rgba(52,211,153,0.5)] whitespace-nowrap leading-none transition-opacity duration-300 ${visualGain > 0 ? 'opacity-100' : 'opacity-0 translate-x-4 pointer-events-none'}`}>+{visualGain}</div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* --- DIVIDING LINE --- */}
                            <div className="px-6 mb-2">
                                <div className="h-px w-full bg-white/20" />
                            </div>

                            {/* TRACK LIST (Flattened, generous spacing, zero-scroll layout) */}
                            <div className="flex-1 flex flex-col justify-around px-2 pb-4 overflow-hidden">
                                {visualTracks.map((track, idx) => (
                                    <div key={idx} className="w-full">
                                        <ProgressionTrackRow 
                                            track={track}
                                            isClaiming={claimingIndices.has(idx)}
                                            isClaimingAll={claimingAllIndices.has(idx)}
                                            isSuccess={successIndices.has(idx)}
                                            isGlobalTicking={isTicking}
                                            isLapping={lappingIndices.has(idx)}
                                            onClaim={() => handleClaim(track.type, idx)}
                                            onClaimAll={() => handleClaimAll(track.type, idx)}
                                        />
                                    </div>
                                ))}
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                             <ActivityLogSection logs={activityLog} />
                        </div>
                    )}
                </div>

                {/* BOTTOM ANCHOR (Reduced Height) */}
                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3 bg-gradient-to-t from-black via-black/80 to-transparent">
                    <SlantedButton variant="danger" size="md" onClick={handleManualClose} className="shadow-2xl !w-[40vw] max-w-[10rem] !h-8">CLOSE</SlantedButton>
                </div>
            </div>
            <style>{`
                @keyframes intensity-pulse { 0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.2)); } 50% { filter: brightness(2.2) drop-shadow(0 0 35px rgba(255,255,255,0.9)); } }
                .animate-intensity-pulse { animation: intensity-pulse 2s ease-in-out infinite; will-change: filter; }
                @keyframes completion-flare { 0% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); } 35% { transform: scale(1.3); filter: brightness(14); text-shadow: 0 0 40px rgba(99,102,241,1), 0 0 100px rgba(255,255,255,1); } 100% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 25px rgba(99,102,241,0.7); } }
                .animate-completion-flare { animation: completion-flare 4.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; z-index: 100; }
            `}</style>
        </Portal>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { ProgressionRewardType } from '../../types';
import { getVariant, getScale, getPulseColor, getSpinnerColor, getCheckmarkColor, getFlareColor } from './progressionUtils';
import { GameText } from '../ui/GameText';
import { Portal } from '../ui/Portal';

interface ProgressionHexButtonProps {
    type: ProgressionRewardType;
    unclaimedCount: number;
    rewardAmount?: string | number;
    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    isGlobalTicking: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

const CheckmarkIcon = ({ className = "", delay = 0, colorClass = "text-white" }: { className?: string, delay?: number, colorClass?: string }) => (
    <svg 
        className={`w-full h-full animate-pop ${colorClass} ${className}`} 
        fill="none" 
        viewBox="0 0 24 24" 
        stroke="currentColor" 
        strokeWidth={1.5}
        style={{ animationDelay: `${delay}ms` }}
    >
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

/**
 * GLOBAL FLOATING FEEDBACK ELEMENT
 */
interface FloatingClaimProps {
    amount: string | number;
    type: ProgressionRewardType;
    x: number;
    y: number;
    onComplete: () => void;
}

const FloatingClaimText: React.FC<FloatingClaimProps> = ({ amount, type, x, y, onComplete }) => {
    useEffect(() => {
        // Uniform 5.4s duration (3x 1.8s) for long dissolve
        const timer = setTimeout(onComplete, 5400); 
        return () => clearTimeout(timer);
    }, [onComplete]);

    const themeColor = getFlareColor(type);
    const isBox = type === 'box';

    return (
        <div 
            className="fixed z-[999] pointer-events-none flex items-center gap-1.5 whitespace-nowrap will-change-transform reward-float-container"
            style={{ 
                left: x, 
                top: y,
                color: themeColor,
                filter: `drop-shadow(0 0 6px ${themeColor}44)`
            }}
        >
            {!isBox && (
                <span className="font-black italic text-sm tracking-tighter drop-shadow-[0_2px_4px_rgba(0,0,0,1)]">
                    +{amount}
                </span>
            )}
            <div className={`${isBox ? 'w-10 h-10' : 'w-5 h-5'} drop-shadow-[0_2px_6px_rgba(0,0,0,0.8)]`}>
                <RewardIconGraphic type={type} size="sm" />
            </div>
        </div>
    );
};

export const ProgressionHexButton: React.FC<ProgressionHexButtonProps> = ({
    type,
    unclaimedCount,
    rewardAmount,
    isClaiming,
    isClaimingAll,
    isSuccess,
    isGlobalTicking,
    onClaim,
    onClaimAll
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [showTapPulse, setShowTapPulse] = useState(false);
    const [capturedCount, setCapturedCount] = useState(1);

    const [activeFloaters, setActiveFloaters] = useState<{id: number, amount: string|number, x: number, y: number}[]>([]);

    const hasTriggeredHold = useRef(false);
    const timerRef = useRef<number | null>(null);
    const canClaim = unclaimedCount > 0;
    const variant = getVariant(type);
    const pulseBorderColor = getPulseColor(type);
    const spinnerBorderColor = getSpinnerColor(type);
    const checkmarkColor = getCheckmarkColor(type);
    const flareColor = getFlareColor(type);

    const triggerFloatingFeedback = useCallback((bulkCount: number = 1) => {
        if (!containerRef.current) return;

        const rect = containerRef.current.getBoundingClientRect();
        const spawnX = rect.left + rect.width / 2;
        const spawnY = rect.top + rect.height / 2;

        const amount = typeof rewardAmount === 'number' ? rewardAmount * bulkCount : (rewardAmount || '');
        const id = Date.now() + Math.random();
        setActiveFloaters(prev => [...prev, { id, amount, x: spawnX, y: spawnY }]);
    }, [rewardAmount]);

    const startHold = useCallback((e: React.PointerEvent) => {
        if (!canClaim || isClaiming || isClaimingAll || isSuccess) return;

        hasTriggeredHold.current = false;

        if (unclaimedCount <= 1) return;

        setIsHolding(true);
        const startTime = Date.now();
        timerRef.current = window.setInterval(() => {
            const p = Math.min(((Date.now() - startTime) / 800) * 100, 100);
            setProgress(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                hasTriggeredHold.current = true;
                setCapturedCount(unclaimedCount);
                triggerFloatingFeedback(unclaimedCount);
                onClaimAll();
                setIsHolding(false);
                setProgress(0);
            }
        }, 16);
    }, [canClaim, unclaimedCount, isClaiming, isClaimingAll, isSuccess, onClaimAll, triggerFloatingFeedback]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }

        if (!hasTriggeredHold.current && !isClaiming && !isClaimingAll && !isSuccess && canClaim) {
            setShowTapPulse(true);
            setTimeout(() => setShowTapPulse(false), 600);
            setCapturedCount(1);
            triggerFloatingFeedback(1);
            onClaim();
        }

        setIsHolding(false);
        setProgress(0);
    }, [isClaiming, isClaimingAll, isSuccess, canClaim, onClaim, triggerFloatingFeedback]);

    const cancelHold = useCallback(() => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        setProgress(0);
    }, []);

    useEffect(() => {
        return () => { if (timerRef.current) clearInterval(timerRef.current); };
    }, []);

    // Idle glow logic suppressed when global ticking is active
    const pulseClass = canClaim && !isSuccess && !isClaiming && !isClaimingAll && !isHolding && !isGlobalTicking ? 'animate-hex-glow' : '';
    const successClass = isSuccess ? 'animate-success-flare' : '';
    const bulkChargeClass = isHolding ? 'brightness-125' : '';

    const renderSuccessIcons = () => {
        if (capturedCount <= 1) {
            return <div className="w-8 h-8"><CheckmarkIcon colorClass={checkmarkColor} /></div>;
        }
        if (capturedCount === 2) {
            return (
                <div className="relative w-10 h-10">
                    <div className="absolute top-1 left-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                    <div className="absolute bottom-1 right-1 w-6 h-6"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                </div>
            );
        }
        return (
            <div className="relative w-10 h-10">
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={0} /></div>
                <div className="absolute bottom-0.5 left-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={150} /></div>
                <div className="absolute bottom-0.5 right-0 w-5 h-5"><CheckmarkIcon colorClass={checkmarkColor} delay={300} /></div>
            </div>
        );
    };

    return (
        <div 
            ref={containerRef}
            className={`relative group cursor-pointer select-none touch-none transition-all duration-300 ${!canClaim && !isSuccess ? 'opacity-40 grayscale pointer-events-none' : ''} ${bulkChargeClass}`}
            onPointerDown={startHold}
            onPointerUp={handlePointerUp}
            onPointerLeave={cancelHold}
            onContextMenu={(e) => e.preventDefault()}
            style={{ 
                '--flare-color': flareColor,
                '--glow-color': flareColor 
            } as React.CSSProperties}
        >
            <Portal>
                {activeFloaters.map(f => (
                    <FloatingClaimText 
                        key={f.id} 
                        amount={f.amount} 
                        type={type} 
                        x={f.x}
                        y={f.y}
                        onComplete={() => setActiveFloaters(prev => prev.filter(item => item.id !== f.id))} 
                    />
                ))}
            </Portal>

            {showTapPulse && (
                <div className="absolute inset-0 z-50 pointer-events-none flex items-center justify-center">
                    <div className={`w-full h-full border-4 ${pulseBorderColor} rounded-full animate-ping opacity-100`} />
                </div>
            )}

            {isHolding && (
                <div className="absolute inset-[-0.2rem] z-50 pointer-events-none flex items-center justify-center">
                    <svg 
                        className="w-full h-full -rotate-90" 
                        style={{ filter: `drop-shadow(0 0 6px var(--flare-color))` }}
                        viewBox="0 0 100 100"
                    >
                        <circle
                            cx="50" cy="50" r="45"
                            fill="none"
                            stroke={flareColor}
                            strokeWidth="6"
                            strokeDasharray={`${progress * 2.82} 282`}
                            strokeLinecap="round"
                            className="opacity-90"
                        />
                    </svg>
                    <div className="absolute inset-0 rounded-full animate-pulse opacity-20" style={{ backgroundColor: flareColor }} />
                </div>
            )}

            <HexBadge 
                variant={variant} 
                size="lg" 
                glow={(canClaim || isSuccess) && !isGlobalTicking}
                className={`${pulseClass} ${successClass} transition-all duration-500`}
            >
                <div className="flex flex-col items-center justify-center w-full h-full relative overflow-visible">
                    {/* 
                        FIRE AND FORGET FLASH ENGINE
                        By using the unclaimedCount as a key, we force a remount of this div 
                        whenever a new claim is earned. The CSS animation 'gain-flash' 
                        then runs to completion purely via CSS timing.
                    */}
                    {unclaimedCount > 0 && (
                        <div key={`flash-${unclaimedCount}`} className="absolute inset-0 z-0 pointer-events-none animate-gain-flash" />
                    )}

                    {isSuccess ? (
                        renderSuccessIcons()
                    ) : isClaiming || isClaimingAll ? (
                        <div className={`w-6 h-6 border-4 border-white/20 ${spinnerBorderColor} rounded-full animate-spin shadow-[0_0_10px_rgba(255,255,255,0.2)]`} />
                    ) : (
                        <div className="relative flex items-center justify-center w-full h-full overflow-visible">
                            <div className={`${getScale(type)} ${type !== 'box' ? '-translate-y-[0.5rem]' : ''}`}>
                                <RewardIconGraphic type={type as any} size="sm" />
                            </div>

                            {rewardAmount && type !== 'box' && (
                                <div className="absolute left-1/2 -translate-x-1/2 bottom-[0.3rem] z-50 flex justify-center pointer-events-none overflow-visible">
                                    <span className={`text-white font-black italic drop-shadow-[0_2px_4px_rgba(0,0,0,1)] leading-none uppercase tracking-tighter tabular-nums whitespace-nowrap ${type === 'tokens' ? 'text-[0.7rem]' : 'text-[0.8rem]'}`}>
                                        {rewardAmount}
                                    </span>
                                </div>
                            )}

                            {unclaimedCount > 0 && (
                                <div className="absolute -bottom-3 -right-3 bg-red-600 border-2 border-white h-[1.3rem] min-w-[1.3rem] px-1 flex items-center justify-center rounded-full shadow-[0_2px_8px_rgba(0,0,0,0.6)] z-50 animate-pop overflow-hidden">
                                    <div className="w-full h-[75%]">
                                        <GameText 
                                            text={unclaimedCount.toString()} 
                                            baseFontSize={0.65} 
                                            italic={false}
                                            className="text-white font-black drop-shadow-md" 
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </HexBadge>

            <style>{`
                @keyframes hex-glow {
                    0% { filter: brightness(1) drop-shadow(0 0 2px var(--glow-color)); }
                    50% { 
                        filter: brightness(1.1) 
                                drop-shadow(0 0 4px var(--glow-color)) 
                                drop-shadow(0 0 8px var(--glow-color)); 
                    }
                    100% { filter: brightness(1) drop-shadow(0 0 2px var(--glow-color)); }
                }
                .animate-hex-glow {
                    animation: hex-glow 3s infinite ease-in-out;
                }

                @keyframes gain-flash {
                    0% { 
                        opacity: 0;
                        transform: scale(0.8);
                        background: radial-gradient(circle, var(--flare-color) 0%, transparent 70%);
                        filter: brightness(1); 
                    }
                    20% { 
                        opacity: 1;
                        transform: scale(1.4);
                        filter: brightness(3) drop-shadow(0 0 20px var(--flare-color)); 
                    }
                    100% { 
                        opacity: 0;
                        transform: scale(1.1);
                        filter: brightness(1); 
                    }
                }
                .animate-gain-flash {
                    animation: gain-flash 0.8s ease-out forwards;
                }

                @keyframes success-flare {
                    0% { filter: brightness(1) drop-shadow(0 0 0px var(--flare-color)); }
                    40% { filter: brightness(3.5) drop-shadow(0 0 45px var(--flare-color)); }
                    70% { filter: brightness(3) drop-shadow(0 0 40px var(--flare-color)); }
                    100% { filter: brightness(1) drop-shadow(0 0 5px rgba(255,255,255,0.1)); }
                }
                .animate-success-flare {
                    animation: success-flare 2.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }

                /**
                 * REFINED UNIFORM DISSOLVE ENGINE
                 * Duration: 5.4s
                 */
                @keyframes reward-drift-pure {
                    0% { 
                        transform: translate3d(-50%, -50%, 0); 
                        opacity: 0; 
                    }
                    10% { 
                        opacity: 1; 
                    }
                    100% { 
                        /* Fixed distance for uniform velocity */
                        transform: translate3d(-50%, -320px, 0); 
                        opacity: 0; 
                    }
                }
                .reward-float-container {
                    animation: reward-drift-pure 5.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </div>
    );
};

