import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 70;
const LAP_MECHANICAL_PAUSE_MS = 100;
const VICTORY_CLIMAX_DURATION_MS = 4500; 

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');

    // Animation State
    const [isTicking, setIsTicking] = useState(pendingLevelIncrement > 0);
    const [visualLevel, setVisualLevel] = useState<number>(user.level - pendingLevelIncrement);
    const [visualGain, setVisualGain] = useState<number>(pendingLevelIncrement);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [claimingAllIndices, setClaimingAllIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());

    const handleManualClose = useCallback(() => {
        clearLevelUpSignal();
        onClose();
    }, [clearLevelUpSignal, onClose]);

    // Numerical Chasing Logic
    useEffect(() => {
        if (isTicking && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;
            const nextGain = Math.max(0, visualGain - 1);

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) newLaps.add(i);
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => { const n = new Set(prev); newLaps.forEach(idx => n.add(idx)); return n; });

                    audio.play('sfx_ui_click', 1.4); 

                    setTimeout(() => setLappingIndices(prev => { const n = new Set(prev); newLaps.forEach(idx => n.delete(idx)); return n; }), 100);
                }

                setVisualLevel(nextLevel);
                setVisualGain(nextGain);
                audio.play('sfx_ui_hover', 0.3);
            }, currentStepDelay);
            return () => clearTimeout(timer);
        } else if (isTicking && visualLevel >= user.level) {
            setIsTicking(false);
            setIsCompletionFlare(true);
            audio.play('sfx_victory', 0.6);
            clearLevelUpSignal();
            setTimeout(() => setIsCompletionFlare(false), VICTORY_CLIMAX_DURATION_MS);
        }
    }, [isTicking, visualLevel, visualGain, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type, label: config.label,
                currentXP, targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount, nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || isTicking) return;
        setClaimingIndices(prev => { const n = new Set(prev); n.add(idx); return n; });

        const success = await performSynchronizedAction(() => api.claimProgressionReward(user.id, type), { visualDelay: 300 });

        setClaimingIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });

        if (success) {
            setSuccessIndices(prev => { const n = new Set(prev); n.add(idx); return n; });
            setTimeout(() => {
                setSuccessIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });
            }, 800);
        }
    }, [claimingIndices, claimingAllIndices, user.id, performSynchronizedAction, isTicking]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || isTicking) return;
        setClaimingAllIndices(prev => { const n = new Set(prev); n.add(idx); return n; });

        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user.id, type), { visualDelay: 500 });

        setClaimingAllIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });

        if (success) {
            setSuccessIndices(prev => { const n = new Set(prev); n.add(idx); return n; });
            setTimeout(() => {
                setSuccessIndices(prev => { const n = new Set(prev); n.delete(idx); return n; });
            }, 1000);
        }
    }, [claimingIndices, claimingAllIndices, user.id, performSynchronizedAction, isTicking]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    const isShifted = isTicking;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-start bg-slate-950 overflow-hidden">

                {/* DYNAMIC BACKGROUND ENGINE (Synced with AppShell) */}
                <div className="absolute inset-0 z-0 animated-bg" />
                <div className="absolute inset-0 z-0 bg-black/40 pointer-events-none" />

                {/* THE CONTENT SHELL (Enforce physical device width limits) */}
                <div className="w-full h-full max-w-[23rem] flex flex-col relative z-10 overflow-hidden shadow-2xl">

                    {/* --- HEADER --- */}
                    <div className="shrink-0 pt-0.5 pb-1.5 flex items-center px-1 bg-gradient-to-b from-slate-700 via-slate-900 to-black border-b border-slate-600 z-40 relative shadow-lg overflow-visible">
                        <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                            <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">COLLECTION LEVEL</h1>
                        </div>
                        <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                            <SlantedButton 
                                variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                                size="xs" 
                                className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                                onClick={() => setActiveTab('REWARDS')} 
                                icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" /></svg>} 
                            />
                            <SlantedButton 
                                variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                                size="xs" 
                                className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                                onClick={() => setActiveTab('ACTIVITY')} 
                                icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} 
                            />
                        </div>
                    </div>

                    <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                        {activeTab === 'REWARDS' ? (
                            <div className="flex-1 flex flex-col min-h-0 pt-1">
                                {/* --- HERO AREA --- */}
                                <div className="shrink-0 pb-2 flex flex-col items-center relative overflow-visible">
                                    <div className="relative w-full flex justify-center items-center h-12 overflow-visible">
                                        <div className={`flex items-center gap-1.5 transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${isShifted ? '-translate-x-6' : 'translate-x-0'}`}>
                                            <div className="flex flex-col items-end text-right gap-0.5 opacity-90">
                                                <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white leading-none">COLLECTION</span>
                                                <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white font-black leading-none">LEVEL</span>
                                            </div>
                                            <div className="relative flex items-center overflow-visible">
                                                <div className={`text-[2.2rem] font-black italic tracking-tighter text-white drop-shadow-md leading-none transition-all ${isTicking ? 'animate-intensity-pulse' : ''} ${isCompletionFlare ? 'animate-completion-flare' : ''}`}>{visualLevel.toLocaleString()}</div>
                                                <div className={`absolute left-full ml-2 text-[1.8rem] font-black italic tracking-tighter text-emerald-400 drop-shadow-[0_0_15px_rgba(52,211,153,0.5)] whitespace-nowrap leading-none transition-opacity duration-300 ${visualGain > 0 ? 'opacity-100' : 'opacity-0 translate-x-4 pointer-events-none'}`}>+{visualGain}</div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* --- DIVIDING LINE --- */}
                                <div className="px-6 mb-2">
                                    <div className="h-px w-full bg-white/20" />
                                </div>

                                {/* TRACK LIST */}
                                <div className="flex-1 flex flex-col justify-around px-2 pb-4 overflow-hidden">
                                    {visualTracks.map((track, idx) => (
                                        <div key={idx} className="w-full">
                                            <ProgressionTrackRow 
                                                track={track}
                                                isClaiming={claimingIndices.has(idx)}
                                                isClaimingAll={claimingAllIndices.has(idx)}
                                                isSuccess={successIndices.has(idx)}
                                                isGlobalTicking={isTicking}
                                                isLapping={lappingIndices.has(idx)}
                                                onClaim={() => handleClaim(track.type, idx)}
                                                onClaimAll={() => handleClaimAll(track.type, idx)}
                                            />
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ) : (
                            <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                                 <ActivityLogSection logs={activityLog} />
                            </div>
                        )}
                    </div>

                    {/* BOTTOM ANCHOR */}
                    <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3 bg-gradient-to-t from-black via-black/80 to-transparent">
                        <SlantedButton variant="danger" size="md" onClick={handleManualClose} className="shadow-2xl !w-[40vw] max-w-[10rem] !h-8">CLOSE</SlantedButton>
                    </div>
                </div>
            </div>
            <style>{`
                @keyframes intensity-pulse { 0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.2)); } 50% { filter: brightness(2.2) drop-shadow(0 0 35px rgba(255,255,255,0.9)); } }
                .animate-intensity-pulse { animation: intensity-pulse 2s ease-in-out infinite; will-change: filter; }
                @keyframes completion-flare { 0% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); } 35% { transform: scale(1.3); filter: brightness(14); text-shadow: 0 0 40px rgba(99,102,241,1), 0 0 100px rgba(255,255,255,1); } 100% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 25px rgba(99,102,241,0.7); } }
                .animate-completion-flare { animation: completion-flare 4.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; z-index: 100; }
            `}</style>
        </Portal>
    );
};

import { GoogleGenAI } from "@google/genai";
import { GameState, CardInstance } from '../types';
import { PendingMove } from './planning';

/**
 * GEMINI STRATEGIC AI
 * Swaps the basic heuristic for a LLM-based reasoning agent.
 * It analyzes the board state as a JSON object and returns the optimal moves.
 */
export const generateAiMoves = async (gameState: GameState): Promise<PendingMove[]> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // 1. Simplify state for the model to minimize token usage and focus on strategy
        const simplifiedState = {
            turn: gameState.turn,
            energy: gameState.players.p2.energy,
            hand: gameState.players.p2.hand.map(c => ({
                id: c.instanceId,
                name: c.def.name,
                cost: c.totalCost,
                power: c.totalPower,
                ability: c.def.baseText
            })),
            lanes: gameState.lanes.map((l, i) => ({
                index: i,
                location: l.location.def.name,
                locationEffect: l.location.def.description,
                myPower: l.p2Slots.reduce((acc, c) => acc + (c?.totalPower || 0), 0),
                oppPower: l.p1Slots.reduce((acc, c) => acc + (c?.totalPower || 0), 0),
                mySlotsRemaining: l.p2Slots.filter(s => s === null).length
            }))
        };

        const prompt = `
            You are a world-class player in "Galactic Snap", a 3-lane card battler.
            Current Game State: ${JSON.stringify(simplifiedState)}

            Rules:
            1. You win by winning 2 out of 3 lanes.
            2. You can play multiple cards if you have enough energy.
            3. Each lane has 4 slots.

            Based on your hand and the board, return a JSON array of moves.
            Each move must be: {"cardInstanceId": string, "laneIdx": number}.
            Only return moves you can afford with your current energy (${simplifiedState.energy}).
            Return ONLY the JSON array.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json"
            }
        });

        const moves = JSON.parse(response.text || "[]");

        // Final safety validation: Filter moves that exceed energy or slot limits
        let remainingEnergy = simplifiedState.energy;
        const finalMoves: PendingMove[] = [];
        const laneCounts = simplifiedState.lanes.map(l => l.mySlotsRemaining);

        for (const move of moves) {
            const card = gameState.players.p2.hand.find(c => c.instanceId === move.cardInstanceId);
            if (card && card.totalCost <= remainingEnergy && laneCounts[move.laneIdx] > 0) {
                finalMoves.push(move);
                remainingEnergy -= card.totalCost;
                laneCounts[move.laneIdx]--;
            }
        }

        return finalMoves;

    } catch (error) {
        console.error("Gemini AI failed, falling back to heuristic:", error);
        return fallbackHeuristic(gameState);
    }
};

/**
 * HEURISTIC FALLBACK (Standard Logic)
 * Ensures the game continues if the API is unreachable.
 */
const fallbackHeuristic = (gameState: GameState): PendingMove[] => {
    const moves: PendingMove[] = [];
    let currentEnergy = gameState.players.p2.energy;
    const hand = [...gameState.players.p2.hand].sort((a, b) => b.totalPower - a.totalPower);

    for (const card of hand) {
        if (card.totalCost <= currentEnergy) {
            const bestLaneIdx = Math.floor(Math.random() * 3);
            if (gameState.lanes[bestLaneIdx].p2Slots.filter(s => s === null).length > 0) {
                moves.push({ cardInstanceId: card.instanceId, laneIdx: bestLaneIdx });
                currentEnergy -= card.totalCost;
            }
        }
    }
    return moves;
};

