import { useState, useEffect, useRef } from 'react';
import { audio } from '../services/audio';
import { REWARD_SEQUENCE } from '../services/api/mockData';

const TICK_RATE = 70;
const LAP_PAUSE = 100;

interface LevelChaserResult {
    visualLevel: number;
    visualGain: number;
    isTicking: boolean;
    lappingIndices: Set<number>;
    isFlare: boolean;
}

/**
 * HEADLESS LEVEL CHASER HOOK
 * Orchestrates the "Numerical Chase" animation sequence.
 */
export const useLevelChaser = (targetLevel: number, initialGain: number, onComplete: () => void): LevelChaserResult => {
    const [isTicking, setIsTicking] = useState(initialGain > 0);
    const [visualLevel, setVisualLevel] = useState(targetLevel - initialGain);
    const [visualGain, setVisualGain] = useState(initialGain);
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [isFlare, setIsFlare] = useState(false);

    const isFirstRun = useRef(true);

    useEffect(() => {
        if (!isTicking) return;

        if (visualLevel >= targetLevel) {
            setIsTicking(false);
            setIsFlare(true);
            audio.play('sfx_victory', 0.6);
            onComplete();
            setTimeout(() => setIsFlare(false), 4500);
            return;
        }

        const nextLevel = visualLevel + 1;
        const newLaps = new Set<number>();
        REWARD_SEQUENCE.forEach((conf, i) => {
            if ((nextLevel + conf.offset) % conf.capacity === 0) newLaps.add(i);
        });

        const delay = TICK_RATE + (newLaps.size > 0 ? LAP_PAUSE : 0);

        const timer = setTimeout(() => {
            if (newLaps.size > 0) {
                setLappingIndices(newLaps);
                audio.play('sfx_ui_click', 1.4);
                setTimeout(() => setLappingIndices(new Set()), 100);
            }
            setVisualLevel(nextLevel);
            setVisualGain(prev => Math.max(0, prev - 1));
            audio.play('sfx_ui_hover', 0.3);
        }, delay);

        return () => clearTimeout(timer);
    }, [isTicking, visualLevel, targetLevel, onComplete]);

    return { visualLevel, visualGain, isTicking, lappingIndices, isFlare };
};

