    const [rewardStates, setRewardStates] = useState<Record<string, 'idle' | 'claiming' | 'claiming-all' | 'success'>>({});

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimed = Math.max(0, finalUnclaimed - (totalEarnedFinal - totalEarnedVisual));

            return {
                type: config.type, label: config.label,
                currentXP, targetXP: config.capacity,
                unclaimedCount: visualUnclaimed, nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleClaimAction = useCallback(async (type: ProgressionRewardType, isBulk: boolean) => {
        if (rewardStates[type] && rewardStates[type] !== 'idle') return;
        if (isTicking) return;

        setRewardStates(prev => ({ ...prev, [type]: isBulk ? 'claiming-all' : 'claiming' }));

        const action = isBulk 
            ? () => api.claimAllProgressionRewards(user.id, type)
            : () => api.claimProgressionReward(user.id, type);

        const success = await performSynchronizedAction(action, { visualDelay: isBulk ? 400 : 250 });

        if (success) {
            setRewardStates(prev => ({ ...prev, [type]: 'success' }));
            setTimeout(() => setRewardStates(prev => ({ ...prev, [type]: 'idle' })), isBulk ? 1200 : 1000);
        } else {
            setRewardStates(prev => ({ ...prev, [type]: 'idle' }));
        }
    }, [rewardStates, user.id, performSynchronizedAction, isTicking]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-start bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 z-0 animated-bg" />
                <div className="absolute inset-0 z-0 bg-black/40 pointer-events-none" />

                <div className="w-full h-full max-w-[23rem] flex flex-col relative z-10 overflow-hidden shadow-2xl">
                    <div className="shrink-0 pt-0.5 pb-1.5 flex items-center px-1 bg-gradient-to-b from-slate-700 via-slate-900 to-black border-b border-slate-600 z-40 relative shadow-lg">
                        <div className="flex-none flex justify-start items-center gap-1.5 min-w-0">
                            <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 leading-none pr-4">Collection Level</h1>
                        </div>
                        <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                            <SlantedButton 
                                variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                                size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                                onClick={() => setActiveTab('REWARDS')} 
                                icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" /></svg>} 
                            />
                            <SlantedButton 
                                variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} 
                                size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" 
                                onClick={() => setActiveTab('ACTIVITY')} 
                                icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} 
                            />
                        </div>
                    </div>

                    <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                        {activeTab === 'REWARDS' ? (
                            <div className="flex-1 flex flex-col min-h-0 pt-1">
                                <LevelHero level={visualLevel} gain={visualGain} isTicking={isTicking} isFlare={isFlare} />
                                <div className="px-6 mb-2"><div className="h-px w-full bg-white/20" /></div>
                                <div className="flex-1 flex flex-col justify-around px-2 pb-4 overflow-hidden">
                                    {visualTracks.map((track, idx) => (
                                        <ProgressionTrackRow 
                                            key={track.type}
                                            track={track}
                                            rewardState={rewardStates[track.type] || 'idle'}
                                            isGlobalTicking={isTicking}
                                            isLapping={lappingIndices.has(idx)}
                                            onClaim={() => handleClaimAction(track.type, false)}
                                            onClaimAll={() => handleClaimAction(track.type, true)}
                                        />
                                    ))}
                                </div>
                            </div>
                        ) : (
                            <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                                 <ActivityLogSection logs={activityLog} />
                            </div>
                        )}
                    </div>

                    <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3 bg-gradient-to-t from-black via-black/80 to-transparent">
                        <SlantedButton variant="danger" size="md" onClick={onClose} className="shadow-2xl !w-[40vw] max-w-[10rem] !h-8">Close</SlantedButton>
                    </div>
                </div>
            </div>
            <style>{`
                @keyframes intensity-pulse { 0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.2)); } 50% { filter: brightness(2.2) drop-shadow(0 0 35px rgba(255,255,255,0.9)); } }
                .animate-intensity-pulse { animation: intensity-pulse 2s ease-in-out infinite; will-change: filter; }
                @keyframes completion-flare { 0% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); } 35% { transform: scale(1.3); filter: brightness(14); text-shadow: 0 0 40px rgba(99,102,241,1), 0 0 100px rgba(255,255,255,1); } 100% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 25px rgba(99,102,241,0.7); } }
                .animate-completion-flare { animation: completion-flare 4.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; z-index: 100; }

                /* CRITICAL: Reward Floating Keyframes */
                @keyframes reward-drift-upward { 
                    0% { transform: translate3d(-50%, -50%, 0) scale(0.5); opacity: 0; } 
                    15% { transform: translate3d(-50%, -100%, 0) scale(1.2); opacity: 1; } 
                    100% { transform: translate3d(-50%, -400px, 0) scale(1); opacity: 0; } 
                }
                .reward-float-animation { animation: reward-drift-upward 4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
            `}</style>
        </Portal>
    );
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { HexBadge } from '../ui/HexBadge';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { ProgressionRewardType } from '../../types';
import { getVariant, getScale, getPulseColor, getSpinnerColor, getCheckmarkColor, getFlareColor } from './progressionUtils';
import { GameText } from '../ui/GameText';
import { Portal } from '../ui/Portal';

interface ProgressionHexButtonProps {
    type: ProgressionRewardType;
    unclaimedCount: number;
    rewardAmount?: string | number;
    isClaiming: boolean;
    isClaimingAll: boolean;
    isSuccess: boolean;
    isGlobalTicking: boolean;
    onClaim: () => void;
    onClaimAll: () => void;
}

/**
 * REFACTOR: Floating Feedback Component
 * Isolated from parent re-renders via memoization and Portal rendering.
 */
const FloatingClaimFeedback: React.FC<{ 
    id: number;
    amount: string | number; 
    type: ProgressionRewardType; 
    x: number; 
    y: number; 
    onComplete: (id: number) => void 
}> = ({ id, amount, type, x, y, onComplete }) => {
    useEffect(() => {
        const timer = setTimeout(() => onComplete(id), 4200); 
        return () => clearTimeout(timer);
    }, [id, onComplete]);

    const themeColor = getFlareColor(type);
    const isBox = type === 'box';

    return (
        <div 
            className="fixed z-[9999] pointer-events-none flex flex-col items-center justify-center reward-float-animation"
            style={{ 
                left: x, 
                top: y, 
                color: themeColor, 
                filter: `drop-shadow(0 0 8px ${themeColor}66)` 
            }}
        >
            <div className={`${isBox ? 'w-12 h-12' : 'w-6 h-6'} drop-shadow-[0_4px_10px_rgba(0,0,0,0.8)] mb-1`}>
                <RewardIconGraphic type={type} size="sm" />
            </div>
            {!isBox && (
                <span className="font-black italic text-lg tracking-tighter drop-shadow-[0_2px_4px_rgba(0,0,0,1)] text-white">
                    +{amount}
                </span>
            )}
        </div>
    );
};

export const ProgressionHexButton: React.FC<ProgressionHexButtonProps> = ({
    type, unclaimedCount, rewardAmount, isClaiming, isClaimingAll, isSuccess, onClaim, onClaimAll
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const timerRef = useRef<number | null>(null);
    const hasTriggeredHold = useRef(false);

    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [showTapPulse, setShowTapPulse] = useState(false);
    const [lastCapturedCount, setLastCapturedCount] = useState(1);
    const [activeFloaters, setActiveFloaters] = useState<{ id: number; amount: string | number; x: number; y: number }[]>([]);

    const canClaim = unclaimedCount > 0;
    const colors = useMemo(() => ({
        variant: getVariant(type),
        pulse: getPulseColor(type),
        spinner: getSpinnerColor(type),
        checkmark: getCheckmarkColor(type),
        flare: getFlareColor(type)
    }), [type]);

    const removeFloater = useCallback((id: number) => {
        setActiveFloaters(prev => prev.filter(f => f.id !== id));
    }, []);

    const spawnFloater = useCallback((count: number) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        const x = rect.left + rect.width / 2;
        const y = rect.top + rect.height / 2;

        const isBox = type === 'box';

        // Staggered Spawning logic
        const amountPer = typeof rewardAmount === 'number' ? rewardAmount : 1;
        const totalAmount = typeof rewardAmount === 'number' ? rewardAmount * count : (rewardAmount || 'REWARD');

        if (isBox && count > 1) {
            for (let i = 0; i < count; i++) {
                setTimeout(() => {
                    setActiveFloaters(p => [...p, { id: Date.now() + Math.random(), amount: 1, x, y }]);
                }, i * 150);
            }
        } else {
            setActiveFloaters(p => [...p, { id: Date.now() + Math.random(), amount: totalAmount, x, y }]);
        }
    }, [rewardAmount, type]);

    // Trigger floater exactly when success signal is received
    useEffect(() => {
        if (isSuccess) {
            spawnFloater(lastCapturedCount);
        }
    }, [isSuccess, spawnFloater, lastCapturedCount]);

    const startHold = (e: React.PointerEvent) => {
        if (!canClaim || isClaiming || isClaimingAll || isSuccess) return;
        hasTriggeredHold.current = false;
        if (unclaimedCount <= 1) return;

        setIsHolding(true);
        const start = Date.now();
        timerRef.current = window.setInterval(() => {
            const p = Math.min(((Date.now() - start) / 800) * 100, 100);
            setProgress(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                hasTriggeredHold.current = true;
                setLastCapturedCount(unclaimedCount);
                onClaimAll();
                setIsHolding(false);
                setProgress(0);
            }
        }, 16);
    };

    const handlePointerUp = () => {
        if (timerRef.current) clearInterval(timerRef.current);
        if (!hasTriggeredHold.current && !isClaiming && !isClaimingAll && !isSuccess && canClaim) {
            setShowTapPulse(true);
            setTimeout(() => setShowTapPulse(false), 600);
            setLastCapturedCount(1);
            onClaim();
        }
        setIsHolding(false);
        setProgress(0);
    };

    const renderCheckmarks = () => {
        const count = Math.min(lastCapturedCount, 3);
        const positions = ['w-8 h-8', 'relative w-10 h-10', 'relative w-10 h-10'];
        if (count === 1) return <div className={positions[0]}><CheckmarkIcon colorClass={colors.checkmark} /></div>;
        if (count === 2) return (
            <div className={positions[1]}>
                <div className="absolute top-1 left-1 w-6 h-6"><CheckmarkIcon colorClass={colors.checkmark} delay={0} /></div>
                <div className="absolute bottom-1 right-1 w-6 h-6"><CheckmarkIcon colorClass={colors.checkmark} delay={150} /></div>
            </div>
        );
        return (
            <div className={positions[2]}>
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-5 h-5"><CheckmarkIcon colorClass={colors.checkmark} delay={0} /></div>
                <div className="absolute bottom-0.5 left-0 w-5 h-5"><CheckmarkIcon colorClass={colors.checkmark} delay={150} /></div>
                <div className="absolute bottom-0.5 right-0 w-5 h-5"><CheckmarkIcon colorClass={colors.checkmark} delay={300} /></div>
            </div>
        );
    };

    return (
        <div 
            ref={containerRef}
            className={`relative group cursor-pointer select-none touch-none transition-all duration-300 ${!canClaim && !isSuccess ? 'opacity-40 grayscale pointer-events-none' : ''} ${isHolding ? 'brightness-125' : ''}`}
            onPointerDown={startHold} onPointerUp={handlePointerUp} onPointerLeave={() => { if(timerRef.current) clearInterval(timerRef.current); setIsHolding(false); setProgress(0); }}
            style={{ '--flare-color': colors.flare, '--glow-color': colors.flare } as React.CSSProperties}
        >
            {/* RENDER FLOATERS INTO TOP-LEVEL PORTAL */}
            <Portal>
                {activeFloaters.map(f => (
                    <FloatingClaimFeedback key={f.id} {...f} type={type} onComplete={removeFloater} />
                ))}
            </Portal>

            {showTapPulse && <div className="absolute inset-0 z-50 pointer-events-none flex items-center justify-center"><div className={`w-full h-full border-4 ${colors.pulse} rounded-full animate-ping opacity-100`} /></div>}

            {isHolding && (
                <div className="absolute inset-[-0.2rem] z-50 pointer-events-none flex items-center justify-center">
                    <svg className="w-full h-full -rotate-90" style={{ filter: `drop-shadow(0 0 6px var(--flare-color))` }} viewBox="0 0 100 100">
                        <circle cx="50" cy="50" r="45" fill="none" stroke={colors.flare} strokeWidth="6" strokeDasharray={`${progress * 2.82} 282`} strokeLinecap="round" className="opacity-90" />
                    </svg>
                </div>
            )}

            <HexBadge 
                variant={colors.variant} size="lg" glow={canClaim || isSuccess}
                className={`${canClaim && !isSuccess && !isClaiming && !isClaimingAll && !isHolding ? 'animate-hex-glow' : ''} ${isSuccess ? 'animate-success-flare' : ''} transition-all duration-500`}
            >
                <div className="flex flex-col items-center justify-center w-full h-full relative overflow-visible">
                    {isSuccess ? renderCheckmarks() : (isClaiming || isClaimingAll) ? (
                        <div className={`w-6 h-6 border-4 border-white/20 ${colors.spinner} rounded-full animate-spin`} />
                    ) : (
                        <div className="relative flex items-center justify-center w-full h-full">
                            <div className={`${getScale(type)} ${type !== 'box' ? '-translate-y-[0.5rem]' : ''}`}><RewardIconGraphic type={type as any} size="sm" /></div>
                            {rewardAmount && type !== 'box' && (
                                <div className="absolute left-1/2 -translate-x-1/2 bottom-[0.3rem] z-50 flex justify-center overflow-visible">
                                    <span className="text-white font-black italic drop-shadow-[0_2px_4px_rgba(0,0,0,1)] leading-none uppercase tracking-tighter text-[0.8rem] whitespace-nowrap">{rewardAmount}</span>
                                </div>
                            )}
                            {unclaimedCount > 0 && (
                                <div className="absolute -bottom-3 -right-3 bg-red-600 border-2 border-white h-[1.3rem] min-w-[1.3rem] px-1 flex items-center justify-center rounded-full shadow-[0_2px_8px_rgba(0,0,0,0.6)] z-50 animate-badge-gain overflow-hidden">
                                    <div className="w-full h-[75%]"><GameText text={unclaimedCount.toString()} baseFontSize={0.65} italic={false} className="text-white font-black drop-shadow-md" /></div>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </HexBadge>

            <style>{`
                @keyframes hex-glow { 0%, 100% { filter: brightness(1) drop-shadow(0 0 2px var(--glow-color)); } 50% { filter: brightness(1.1) drop-shadow(0 0 4px var(--glow-color)) drop-shadow(0 0 8px var(--glow-color)); } }
                .animate-hex-glow { animation: hex-glow 3s infinite ease-in-out; }
                @keyframes badge-gain { 0%, 100% { transform: scale(1); } 30% { transform: scale(1.2); filter: brightness(1.3) drop-shadow(0 0 8px #ef4444); } }
                .animate-badge-gain { animation: badge-gain 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
                @keyframes success-flare { 0% { filter: brightness(1) drop-shadow(0 0 0px var(--flare-color)); } 40% { filter: brightness(3.5) drop-shadow(0 0 45px var(--flare-color)); } 100% { filter: brightness(1) drop-shadow(0 0 5px rgba(255,255,255,0.1)); } }
                .animate-success-flare { animation: success-flare 2.2s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
            `}</style>
        </div>
    );
};

const CheckmarkIcon = ({ className = "", delay = 0, colorClass = "text-white" }: { className?: string, delay?: number, colorClass?: string }) => (
    <svg className={`w-full h-full animate-pop ${colorClass} ${className}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5} style={{ animationDelay: `${delay}ms` }}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

import React, { useState, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { REWARD_SEQUENCE } from '../../services/api/mockData';
import { useLevelChaser } from '../../hooks/useLevelChaser';

// Modular Components
import { ProgressionTrackRow } from './ProgressionTrackRow';
import { ActivityLogSection } from './ActivityLogSection';

interface ProgressionScreenProps {
    onClose: () => void;
}

const LevelHero: React.FC<{ 
    level: number; 
    gain: number; 
    isTicking: boolean; 
    isFlare: boolean; 
}> = React.memo(({ level, gain, isTicking, isFlare }) => (
    <div className="shrink-0 pb-2 flex flex-col items-center relative overflow-visible">
        <div className="relative w-full flex justify-center items-center h-12 overflow-visible">
            <div className={`flex items-center gap-1.5 transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${isTicking ? '-translate-x-6' : 'translate-x-0'}`}>
                <div className="flex flex-col items-end text-right gap-0.5 opacity-90">
                    <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white leading-none uppercase">Collection</span>
                    <span className="text-[0.55rem] font-bold tracking-[0.25em] text-white font-black leading-none uppercase">Level</span>
                </div>
                <div className="relative flex items-center overflow-visible">
                    <div className={`text-[2.2rem] font-black italic tracking-tighter text-white drop-shadow-md leading-none transition-all ${isTicking ? 'animate-intensity-pulse' : ''} ${isFlare ? 'animate-completion-flare' : ''}`}>
                        {level.toLocaleString()}
                    </div>
                    <div className={`absolute left-full ml-2 text-[1.8rem] font-black italic tracking-tighter text-emerald-400 drop-shadow-[0_0_15px_rgba(52,211,153,0.5)] whitespace-nowrap leading-none transition-all duration-300 ${gain > 0 ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-4 pointer-events-none'}`}>
                        +{gain}
                    </div>
                </div>
            </div>
        </div>
    </div>
));

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const { visualLevel, visualGain, isTicking, lappingIndices, isFlare } = useLevelChaser(
        user.level, 
        pendingLevelIncrement, 
        clearLevelUpSignal
    );

    const [activeTab, setActiveTab] = useState<'REWARDS' | 'ACTIVITY'>('REWARDS');
    const [rewardStates, setRewardStates] = useState<Record<string, 'idle' | 'claiming' | 'claiming-all' | 'success'>>({});

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimed = Math.max(0, finalUnclaimed - (totalEarnedFinal - totalEarnedVisual));

            return {
                type: config.type, label: config.label,
                currentXP, targetXP: config.capacity,
                unclaimedCount: visualUnclaimed, nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleClaimAction = useCallback(async (type: ProgressionRewardType, isBulk: boolean) => {
        if (rewardStates[type] && rewardStates[type] !== 'idle') return;
        if (isTicking) return;

        setRewardStates(prev => ({ ...prev, [type]: isBulk ? 'claiming-all' : 'claiming' }));

        const action = isBulk 
            ? () => api.claimAllProgressionRewards(user.id, type)
            : () => api.claimProgressionReward(user.id, type);

        const success = await performSynchronizedAction(action, { visualDelay: isBulk ? 400 : 250 });

        if (success) {
            setRewardStates(prev => ({ ...prev, [type]: 'success' }));
            setTimeout(() => setRewardStates(prev => ({ ...prev, [type]: 'idle' })), isBulk ? 1200 : 1000);
        } else {
            setRewardStates(prev => ({ ...prev, [type]: 'idle' }));
        }
    }, [rewardStates, user.id, performSynchronizedAction, isTicking]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-start bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 z-0 animated-bg" />
                <div className="absolute inset-0 z-0 bg-black/40 pointer-events-none" />

                <div className="w-full h-full max-w-[23rem] flex flex-col relative z-10 overflow-hidden shadow-2xl">
                    <div className="shrink-0 pt-0.5 pb-1.5 flex items-center px-1 bg-gradient-to-b from-slate-700 via-slate-900 to-black border-b border-slate-600 z-40 relative shadow-lg">
