type FilterType = 'all' | ProgressionRewardType;

export const ActivityLogSection: React.FC<{ logs: ActivityLogEntry[] }> = ({ logs }) => {
    const [activeFilter, setActiveFilter] = useState<FilterType>('all');

    const filteredLogs = useMemo(() => {
        if (activeFilter === 'all') return logs;
        return logs.filter(log => log.type === activeFilter);
    }, [logs, activeFilter]);

    const filters: { id: FilterType; icon: React.ReactNode; variant: any }[] = [
        { 
            id: 'all', 
            icon: <span className="text-[0.8rem] font-black italic mt-0.5">ALL</span>, 
            variant: 'primary' 
        },
        { 
            id: 'booster', 
            icon: <div className="flex items-center justify-center scale-110 h-full w-full"><BoosterIcon size="sm" /></div>, 
            variant: 'success' 
        },
        { 
            id: 'credits', 
            icon: <div className="flex items-center justify-center scale-90 h-full w-full"><CreditIcon size="sm" /></div>, 
            variant: 'blue' 
        },
        { 
            id: 'gold', 
            icon: <div className="flex items-center justify-center scale-[1.05] h-full w-full"><GoldIcon size="sm" /></div>, 
            variant: 'warning' 
        },
        { 
            id: 'tokens', 
            icon: <div className="flex items-center justify-center scale-90 h-full w-full"><TokenIcon size="sm" /></div>, 
            variant: 'danger' 
        },
        { 
            id: 'box', 
            icon: <div className="flex items-center justify-center scale-110 h-full w-full"><OmegaBoxIcon size="sm" /></div>, 
            variant: 'primary' 
        },
    ];

    return (
        <div className="flex flex-col h-full overflow-hidden">
            <div className="shrink-0 pt-4">
                <div className="flex flex-col gap-4 mb-4 px-4">
                    <div className="flex items-center gap-3">
                        <h3 className="text-[0.6rem] font-black text-white uppercase tracking-[0.4em] whitespace-nowrap">Activity Archive</h3>
                        <div className="flex-1 h-px bg-white/5" />
                    </div>
                </div>

                <div className="flex items-center gap-1.5 mb-4 overflow-x-auto pb-1 scrollbar-hide px-4">
                    {filters.map((f) => (
                        <SlantedButton
                            key={f.id}
                            variant={activeFilter === f.id ? f.variant : 'black'}
                            size="xs"
                            className={`!w-[13vw] max-w-[3rem] shrink-0 !transition-none`}
                            onClick={() => setActiveFilter(f.id)}
                        >
                            {f.icon}
                        </SlantedButton>
                    ))}
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 pb-24 custom-scrollbar scrolling-touch">
                <div className="mb-4 text-center">
                    <span className="text-[0.5rem] font-black text-white/20 uppercase tracking-[0.3em] italic">Only the last 200 entries shown</span>
                </div>

                <div className="space-y-2">
                    {filteredLogs.length > 0 ? (
                        filteredLogs.map((item) => (
                            <ActivityLogItem key={item.id} item={item} />
                        ))
                    ) : (
                        <div className="h-32 flex flex-col items-center justify-center border-2 border-dashed border-white/5 rounded-xl bg-white/5">
                            <div className="opacity-10 mb-2">
                                 {filters.find(f => f.id === activeFilter)?.icon}
                            </div>
                            <span className="text-[0.55rem] font-black text-white/20 uppercase tracking-[0.4em]">No {activeFilter} entries</span>
                        </div>
                    )}
                </div>
                <div className="h-10 w-full" />
            </div>
        </div>
    );
};

