                                            track={track}
                                            isClaiming={rewardStates[idx] === 'claiming'}
                                            isClaimingAll={rewardStates[idx] === 'claiming-all'}
                                            isSuccess={rewardStates[idx] === 'success'}
                                            isGlobalTicking={isTicking}
                                            isLapping={lappingIndices.has(idx)}
