import React from 'react';
import { useUser } from '../../contexts/UserContext';
// Added useUI import to access inspector state
import { useUI } from '../../contexts/UIContext';
import { CardInstance, CardDefinition, CardRarity } from '../../types';
import { Card } from '../Card';
import { LocationCard } from '../LocationCard';
import { StatHistory } from './inspector/StatHistory';
import { KeywordText } from '../ui/KeywordText';
import { HexButton } from '../ui/HexButton';

export const InspectorOverlay: React.FC = () => {
    const { 
        user,
        upgradeCard,
    } = useUser();

    // Fixed: Migration of inspector state from useUser to useUI
    const {
        inspectingCard, 
        inspectingLocation, 
        inspectingCurrency,
        closeInspector 
    } = useUI();

    if (!inspectingCard && !inspectingLocation && !inspectingCurrency) return null;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    const getDef = (): CardDefinition | null => {
        if (!inspectingCard) return null;
        const data = (inspectingCard as any).data || inspectingCard;
        return isInstance(data) ? data.def : data as CardDefinition;
    };

    const def = getDef();

    const currentRarity = def ? (user.cardRarities[def.id] || def.rarity) : "Common";
    const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
    const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
    const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
    const upgradeCost = nextRarity ? costMap[nextRarity] : null;

    const inspectingCardData = (inspectingCard as any)?.data;

    return (
        <div 
            className="fixed inset-0 z-[500] bg-black/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-pop overflow-y-auto"
            onClick={closeInspector}
        >
            {/* CARD INSPECTOR */}
            {inspectingCard && def && (
                <div 
                    className="flex flex-col items-center w-full max-w-[13rem]"
                    onClick={(e) => e.stopPropagation()} 
                > 
                    <div className="relative z-40 mb-5 shadow-[0_0_3rem_rgba(0,0,0,0.8)]">
                        {isInstance(inspectingCardData) && (
                            <>
                                <StatHistory modifiers={inspectingCardData.costModifiers} type="cost" side="left" />
                                <StatHistory modifiers={inspectingCardData.powerModifiers} type="power" side="right" />
                            </>
                        )}
                        <Card card={{ ...def, rarity: currentRarity }} size="lg" />
                    </div>

                    <div className="w-full text-center mb-4 px-1">
                         <KeywordText className="text-[0.7rem]" text={isInstance(inspectingCardData) ? inspectingCardData.currentText : def.baseText} />
                    </div>

                    {!isInstance(inspectingCardData) && nextRarity && (
                        <div className="w-full mb-4">
                            <HexButton 
                                variant="success" 
                                fullWidth 
                                size="sm"
                                onClick={() => upgradeCard(def.id)}
                                disabled={user.credits < (upgradeCost || 0)}
                            >
                                <div className="flex items-center justify-center gap-2">
                                    <div className="flex flex-col items-start leading-none">
                                        <span className="text-[0.45rem] opacity-70">UPGRADE TO</span>
                                        <span className="text-[0.6rem]">{nextRarity.toUpperCase()}</span>
                                    </div>
                                    <div className="h-4 w-px bg-white/20"></div>
                                    <span className="text-xs">{upgradeCost} CREDITS</span>
                                </div>
                            </HexButton>
                        </div>
                    )}

                    {def.flavorText && (
                        <div className="w-full bg-slate-900/60 border border-slate-800 rounded-lg p-2 min-h-[2.5rem] flex flex-col items-center justify-center relative group overflow-hidden">
                            <p className="text-[0.55rem] text-indigo-200/70 italic leading-tight font-mono text-center px-1">
                                "{def.flavorText}"
                            </p>
                        </div>
                    )}
                </div>
            )}

            {/* LOCATION INSPECTOR */}
            {inspectingLocation && (
                <div 
                    className="relative z-40 animate-pop drop-shadow-2xl max-w-[20rem]"
                    onClick={(e) => e.stopPropagation()}
                >
                    <LocationCard location={inspectingLocation} size="lg" />
                </div>
            )}

            {/* CURRENCY INSPECTOR */}
            {inspectingCurrency && (
                <div 
                    className="flex flex-col items-center animate-pop"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className={`w-24 h-24 rounded-full flex items-center justify-center border-4 shadow-[0_0_2rem_rgba(0,0,0,0.5)] mb-6 ${inspectingCurrency.type === 'gold' ? 'bg-amber-500/10 border-amber-500/40' : 'bg-blue-500/10 border-blue-500/40'}`}>
                        {inspectingCurrency.type === 'gold' ? (
                            <div className="w-12 h-8 bg-amber-400 rounded-sm shadow-xl border border-white/30"></div>
                        ) : (
                            <div className="w-12 h-12 rounded-full bg-blue-400 shadow-xl border border-white/30"></div>
                        )}
                    </div>
                    <div className="text-center">
                        <h2 className="text-3xl font-black text-white italic tracking-tighter mb-1 uppercase">
                            {inspectingCurrency.amount.toLocaleString()} {inspectingCurrency.type}
                        </h2>
                        <p className="text-slate-500 font-bold text-[0.6rem] uppercase tracking-widest">
                            Available Balance
                        </p>
                    </div>
                </div>
            )}

            <div className="fixed bottom-8 text-slate-500/50 font-black text-[0.5rem] uppercase tracking-[0.4em] animate-pulse">
                Tap anywhere to close
            </div>
        </div>
    );
};

import React, { useCallback } from 'react';
import { useGameLogic } from './useGameLogic';
import { useDragAndDrop } from './useDragAndDrop';
import { useEventSystem } from './useEventSystem';
import { CardDefinition, CardInstance, LocationDefinition } from '../types';
import { useUser } from '../contexts/UserContext';
// Added useUI import for inspector actions
import { useUI } from '../contexts/UIContext';

export const useGameController = (onExit?: () => void) => {
    const logic = useGameLogic();
    // Fixed: Get inspector methods from useUI instead of useUser
    const { inspect, closeInspector } = useUI();
    const eventSystem = useEventSystem(logic.events);

    const dnd = useDragAndDrop({
        gameState: logic.gameState,
        pendingMoves: logic.pendingMoves,
        isResolving: logic.isResolving,
        setPendingMoves: logic.setPendingMoves,
        setInspectingCard: logic.setInspectingCard,
        setInspectingLocation: logic.setInspectingLocation,
        setSelectedCardIdx: logic.setSelectedCardIdx,
        setShowUndoMenu: logic.setShowUndoMenu,
        onDrop: (success) => {
            if (success) eventSystem.playSnap();
        }
    });

    const handleCardClick = useCallback((idx: number, isDragging: boolean) => {
        if (isDragging) return; // Allow inspection during resolution for better feel

        const card = logic.gameState.players.p1.hand[idx];
        if (card) {
            eventSystem.playClick();
            // Trigger logic selection (handles energy/playability checks)
            // Note: handleCardClick in logic might still block selection if resolving
            logic.handleCardClick(idx, isDragging);
            // Always show inspection on explicit click regardless of phase
            inspect(card);
        }
    }, [eventSystem, logic, inspect]);

    const wrappedCloseInspector = useCallback(() => {
        eventSystem.playClick();
        closeInspector();
        logic.setInspectingCard(null);
        logic.setInspectingLocation(null);
    }, [eventSystem, closeInspector, logic]);

    const wrappedInspectCard = useCallback((c: CardInstance | CardDefinition) => {
        eventSystem.playClick();
        inspect(c);
        logic.setInspectingCard(c);
    }, [eventSystem, inspect, logic]);

    const wrappedInspectLocation = useCallback((l: LocationDefinition) => {
        eventSystem.playClick();
        inspect(l);
        logic.setInspectingLocation(l);
    }, [eventSystem, inspect, logic]);

    const handleUndoAll = useCallback(() => {
        eventSystem.playClick();
        logic.handleUndoAll();
    }, [eventSystem, logic]);

    const handleEndTurn = useCallback(() => {
        eventSystem.playClick();
        logic.handleEndTurn();
    }, [eventSystem, logic]);

    const handleResign = useCallback(() => {
        eventSystem.playClick();
        logic.handleResign();
    }, [eventSystem, logic]);

    const restartGame = useCallback(() => {
        eventSystem.playClick();
        logic.restartGame();
    }, [eventSystem, logic]);

    const toggleResults = useCallback((val: boolean) => {
        eventSystem.playClick();
        logic.setIsResultsHidden(val);
    }, [eventSystem, logic]);

    const handleLocationClick = useCallback((laneIdx: number) => {
        if (logic.selectedCardIdx !== null) eventSystem.playSnap();
        logic.handleLocationClick(laneIdx);
    }, [eventSystem, logic]);

    return {
        ...logic,
        dragState: dnd.dragState,
        activeVfx: eventSystem.activeVfx,
        actions: {
            handleCardClick,
            handleUndoAll,
            handleEndTurn,
            handleResign,
            restartGame,
            handleExit: () => { eventSystem.playClick(); onExit?.(); },
            toggleResults,
            closeInspector: wrappedCloseInspector,
            inspectCard: wrappedInspectCard,
            inspectLocation: wrappedInspectLocation,
            handleLocationClick,
            handleCardPointerDownHand: (e: React.PointerEvent, card: CardInstance, index: number) => 
                dnd.handleCardPointerDown(e, card, { type: 'hand', index }),
            handleCardPointerDownLane: (e: React.PointerEvent, card: CardInstance, laneIdx: number) => 
                dnd.handleCardPointerDown(e, card, { type: 'lane', laneIdx })
        }
    };
};

import { GameState, CardInstance, PlayerID, Lane, StatModifier } from '../types';

export const findCardInState = (state: GameState, instanceId: string): { card: CardInstance, location: 'hand' | 'deck' | 'board' | 'discard' | 'destroyed' | 'banished', owner: PlayerID, laneIdx?: number, slotIdx?: number } | null => {
    if (!state || !state.players) return null;

    // Search Hands
    if (state.players.p1?.hand) {
        const p1HandCard = (state.players.p1.hand || []).find(c => c && c.instanceId === instanceId);
        if (p1HandCard) return { card: p1HandCard, location: 'hand', owner: 'p1' };
    }
    if (state.players.p2?.hand) {
        const p2HandCard = (state.players.p2.hand || []).find(c => c && c.instanceId === instanceId);
        if (p2HandCard) return { card: p2HandCard, location: 'hand', owner: 'p2' };
    }

    // Search Board
    if (state.lanes) {
        for (let l = 0; l < state.lanes.length; l++) {
            const lane = state.lanes[l];
            if (!lane) continue;

            // Fixed: Explicitly typed slots to avoid 'never' inference
            const p1Slots = (lane.p1Slots as (CardInstance | null)[]);
            const p1SlotIdx = p1Slots.findIndex(s => s?.instanceId === instanceId);
            if (p1SlotIdx !== -1) return { card: lane.p1Slots[p1SlotIdx]!, location: 'board', owner: 'p1', laneIdx: l, slotIdx: p1SlotIdx };

            const p2Slots = (lane.p2Slots as (CardInstance | null)[]);
            const p2SlotIdx = p2Slots.findIndex(s => s?.instanceId === instanceId);
            if (p2SlotIdx !== -1) return { card: lane.p2Slots[p2SlotIdx]!, location: 'board', owner: 'p2', laneIdx: l, slotIdx: p2SlotIdx };
        }
    }

    // Search Piles
    if (state.players.p1?.discardPile) {
        const p1Discard = (state.players.p1.discardPile || []).find(c => c && c.instanceId === instanceId);
        if (p1Discard) return { card: p1Discard, location: 'discard', owner: 'p1' };
    }
    if (state.players.p2?.discardPile) {
        const p2Discard = (state.players.p2.discardPile || []).find(c => c && c.instanceId === instanceId);
        if (p2Discard) return { card: p2Discard, location: 'discard', owner: 'p2' };
    }

    // Search Decks
    if (state.players.p1?.deck) {
        const p1DeckCard = (state.players.p1.deck || []).find(c => c && c.instanceId === instanceId);
        if (p1DeckCard) return { card: p1DeckCard, location: 'deck', owner: 'p1' };
    }
    if (state.players.p2?.deck) {
        const p2DeckCard = (state.players.p2.deck || []).find(c => c && c.instanceId === instanceId);
        if (p2DeckCard) return { card: p2DeckCard, location: 'deck', owner: 'p2' };
    }

    // Search Destroyed
    if (state.players.p1?.destroyedPile) {
        const p1Destroyed = (state.players.p1.destroyedPile || []).find(c => c && c.instanceId === instanceId);
        if (p1Destroyed) return { card: p1Destroyed, location: 'destroyed', owner: 'p1' };
    }
    if (state.players.p2?.destroyedPile) {
        const p2Destroyed = (state.players.p2.destroyedPile || []).find(c => c && c.instanceId === instanceId);
        if (p2Destroyed) return { card: p2Destroyed, location: 'destroyed', owner: 'p2' };
    }

     // Search Banished
    if (state.players.p1?.banishedPile) {
        const p1Banished = (state.players.p1.banishedPile || []).find(c => c && c.instanceId === instanceId);
        if (p1Banished) return { card: p1Banished, location: 'banished', owner: 'p1' };
    }
    if (state.players.p2?.banishedPile) {
        const p2Banished = (state.players.p2.banishedPile || []).find(c => c && c.instanceId === instanceId);
        if (p2Banished) return { card: p2Banished, location: 'banished', owner: 'p2' };
    }

    return null;
}

export const calculateLanePower = (lane: Lane, player: PlayerID, gameState: GameState): number => {
  if (!lane) return 0;
  // Fixed: Cast to array of nullable instances to avoid inference issues in loop
  const slots = (player === 'p1' ? lane.p1Slots : lane.p2Slots) as (CardInstance | null)[];
  let power = 0;
  slots.forEach(card => {
      if (card && card.faceUp) {
          power += card.totalPower;
      }
  });
  return power;
};

/**
 * Calculates the visual stats of a card if it were to be played in the given lane.
 */
const projectCardStats = (originalCard: CardInstance, lane: Lane): CardInstance => {
    const card = {
        ...originalCard,
        powerModifiers: [...(originalCard.powerModifiers || [])],
        costModifiers: [...(originalCard.costModifiers || [])]
    };

    card.powerModifiers = card.powerModifiers.filter(m => m.type !== 'CONTINUOUS');
    const currentP = card.powerModifiers.reduce((sum, m) => sum + m.value, 0);
    card.totalPower = currentP;

    if (lane.location?.def?.effect === 'PowerPlantEffect') {
        const mod: StatModifier = { source: lane.location.def.name, value: 1, type: 'CONTINUOUS' };
        card.powerModifiers.push(mod);
        card.totalPower += 1;
    }

    return card;
};

export const getProjectedLaneState = (
    gameState: GameState,
    laneIndex: number,
    pendingCards: { card: CardInstance, handIndex?: number }[]
): (CardInstance | null)[] => {
    if (!gameState || !gameState.lanes) return [null, null, null, null];
    const lane = gameState.lanes[laneIndex];
    if (!lane) return [null, null, null, null];

    const slots = [...(lane.p1Slots || [])];
    const realCount = slots.filter(s => s !== null).length;

    pendingCards.forEach((move, i) => {
        const targetIndex = realCount + i;
        if (targetIndex < 4) {
            const projectedCard = projectCardStats(move.card, lane);
            slots[targetIndex] = projectedCard;
        }
    });

    return slots as (CardInstance | null)[];
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { StoreResourceItem } from '../store/StoreResourceItem';
import { StoreSection } from '../store/StoreSection';
import { DailyOfferCard } from '../store/DailyOfferCard';
import { StoreOfferDetailOverlay } from '../store/StoreOfferDetailOverlay';
import { StoreOffer, OfferItem } from '../../types';
import { useUser } from '../../contexts/UserContext';
// Added useUI to access storeScrollTarget
import { useUI } from '../../contexts/UIContext';

export const StoreScreen: React.FC = () => {
    const { storeData, isStoreLoading, syncStore } = useUser();
    // Fixed: Migration of scroll target state from useUser to useUI
    const { storeScrollTarget, setStoreScrollTarget } = useUI();
    const [selectedOffer, setSelectedOffer] = useState<StoreOffer | null>(null);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const handleJumpToSection = useCallback((id: string) => {
        const el = document.getElementById(id);
        const container = scrollContainerRef.current;
        if (el && container) {
            const targetTop = el.offsetTop - 8;
            container.scrollTo({ 
                top: targetTop, 
                behavior: 'smooth' 
            });
        }
    }, []);

    useEffect(() => {
        if (storeScrollTarget) {
            const t = setTimeout(() => {
                handleJumpToSection(storeScrollTarget);
                setStoreScrollTarget(null);
            }, 150);
            return () => clearTimeout(t);
        }
    }, [storeScrollTarget, setStoreScrollTarget, handleJumpToSection]);

    const offers = storeData?.offers || [];

    const getCurrencyAmount = (offer: StoreOffer) => {
        const item = offer.contents.find(c => c.type === 'currency');
        if (item && 'amount' in item) return item.amount;
        return 0;
    };

    /**
     * Filter functions - We trust the SERVER'S order, so we just filter by type.
     */
    const featuredOffers = offers.filter(o => o.category === 'featured');

    const creditOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'credits')
    );

    const goldOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'gold')
    );

    const tokenOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'tokens')
    );

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative">
            <StandardHeader 
                title="Store" 
                showCurrency={true}
                onCreditClick={() => handleJumpToSection('store-credits')}
                onGoldClick={() => handleJumpToSection('store-gold')}
                onTokenClick={() => handleJumpToSection('store-tokens')}
            />

            <div 
                ref={scrollContainerRef}
                className="flex-1 overflow-y-auto p-4 pb-32 space-y-10 relative"
            >
                {/* 1. FEATURED SECTION */}
                {featuredOffers.length > 0 && (
                    <StoreSection id="store-featured" title="Featured" colorClass="text-indigo-400">
                        <div className="space-y-4">
                            {featuredOffers.map(offer => (
                                <DailyOfferCard 
                                    key={offer.id}
                                    title={offer.title}
                                    description={offer.description}
                                    price={offer.price}
                                    discount={offer.discountLabel}
                                    backgroundImage={offer.imageUrl}
                                    onClick={() => setSelectedOffer(offer)}
                                />
                            ))}
                        </div>
                    </StoreSection>
                )}

                {/* 2. CREDITS SECTION */}
                <StoreSection id="store-credits" title="Credits" colorClass="text-blue-400">
                    <div className="grid grid-cols-3 gap-2">
                        {creditOffers.map(offer => (
                            <StoreResourceItem 
                                key={offer.id}
