        if (success) {
            setStatus('success');
            audio.play('sfx_victory', 0.5);

            setTimeout(() => {
                setStatus('idle');
                setHoldProgress(0);
            }, 2500);
        } else {
            setStatus('idle');
        }
    };

    return (
        <div className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10rem] relative group overflow-hidden shadow-[0_4px_15_rgba(0,0,0,0.8)] ${status === 'success' ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}>
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/40 animate-pulse z-40 pointer-events-none" />
            )}

            {/* Hold progress background */}
            {holdProgress > 0 && status === 'idle' && (
                <div 
                    className="absolute inset-y-0 left-0 bg-amber-300 shadow-[0_0_2rem_rgba(251,191,36,1),0_0_4rem_rgba(251,191,36,0.5)] z-0 pointer-events-none"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {badge && status === 'idle' && (
                <div className="absolute -top-1 -right-1 z-30 bg-red-600 border border-red-400 text-white text-[0.45rem] font-black px-1.5 py-0.5 rounded shadow-[0_0_10px_rgba(220,38,38,0.8)] uppercase tracking-tight skew-x-[-10deg]">
                    {badge}
                </div>
