                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { UnifiedCardView } from './card/UnifiedCardView';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
  borderOverride?: string; 
  // Added variant prop to fix layout errors in sub-components
  variant?: 'default' | 'thumbnail' | 'board';
}

/**
 * Card Component
 * A high-performance wrapper that delegates all rendering to the UnifiedCardView engine.
 */
const CardComponent: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  hidden, 
  onPointerDown,
  isDragging,
  borderOverride
}) => {
  return (
    <UnifiedCardView
        card={card}
        size={size}
        hidden={hidden}
        isDragging={isDragging}
        onPointerDown={onPointerDown}
        onClick={onClick}
        borderOverride={borderOverride}
    />
  );
};

export const Card = React.memo(CardComponent, (prev, next) => {
    if (prev.size !== next.size || prev.isDragging !== next.isDragging || prev.hidden !== next.hidden || prev.borderOverride !== next.borderOverride) return false;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    if (isInstance(prev.card) && isInstance(next.card)) {
        return prev.card.instanceId === next.card.instanceId && 
               prev.card.totalPower === next.card.totalPower && 
               prev.card.totalCost === next.card.totalCost &&
               prev.card.faceUp === next.card.faceUp;
    }

    const getDefinitionId = (card: CardInstance | CardDefinition) => 
        isInstance(card) ? card.definitionId : card.id;

    return getDefinitionId(prev.card) === getDefinitionId(next.card);
});

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';
// Added useUI import for inspector actions
import { useUI } from '../contexts/UIContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  scrollRef: React.RefObject<HTMLElement>;
}

const DRAG_THRESHOLD = 8;
const SCROLL_THRESHOLD = 4;
const PICKUP_DELAY = 120; // Fast response for premium feel
const FRICTION = 0.96; // Slightly less friction for longer glides
const MIN_VELOCITY = 0.2;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef }: UseCollectionDragProps) => {
    // Fixed: Get user from useUser and inspect from useUI
    const { user } = useUser();
    const { inspect } = useUI();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    // Internal refs for high-frequency updates
    const gestureRef = useRef({
        isScrolling: false,
        isDragging: false,
        startPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        samples: [] as { dy: number, dt: number }[] // For velocity smoothing
    });

    const inertiaFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runInertia = useCallback(() => {
        if (!scrollRef.current) return;

        const g = gestureRef.current;
        const el = scrollRef.current;

        el.scrollTop -= g.velocity;
        g.velocity *= FRICTION;

        // Boundary check for "bounce" or hard stop
        if (el.scrollTop <= 0 || el.scrollTop >= el.scrollHeight - el.clientHeight) {
            g.velocity = 0;
        }

        if (Math.abs(g.velocity) > MIN_VELOCITY) {
            inertiaFrameRef.current = requestAnimationFrame(runInertia);
        } else {
            g.velocity = 0;
            inertiaFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopInertia = useCallback(() => {
        if (inertiaFrameRef.current !== null) {
            cancelAnimationFrame(inertiaFrameRef.current);
            inertiaFrameRef.current = null;
        }
        gestureRef.current.velocity = 0;
        gestureRef.current.samples = [];
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;

        stopInertia();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { target.setPointerCapture(e.pointerId); } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        gestureRef.current = {
            isScrolling: false,
            isDragging: false,
            startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (origin === 'vault' && card) {
            gestureRef.current.isDragging = true;
            setDragState(prev => prev ? { ...prev, active: true } : null);
        } else if (origin === 'archive' && card) {
            pickupTimerRef.current = window.setTimeout(() => {
                if (!gestureRef.current.isScrolling) {
                    gestureRef.current.isDragging = true;
                    setDragState(prev => prev ? { ...prev, active: true } : null);
                }
            }, PICKUP_DELAY);
        }

    }, [scrollRef, stopInertia]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const g = gestureRef.current;
            const now = performance.now();
            const dt = now - g.lastTime;
            const deltaX = e.clientX - g.startPos.x;
            const deltaY = e.clientY - g.startPos.y;

            if (dt > 0) {
                const dy = e.clientY - g.lastY;
                // Add sample for moving average
                g.samples.push({ dy, dt });
                if (g.samples.length > 3) g.samples.shift();

                // Calculate smoothed velocity
                const totalDy = g.samples.reduce((sum, s) => sum + s.dy, 0);
                const totalDt = g.samples.reduce((sum, s) => sum + s.dt, 0);
                g.velocity = totalDy / (totalDt / 16.67);

                g.lastY = e.clientY;
                g.lastTime = now;
            }

            // GESTURE DETECTION
            if (!g.isScrolling && !g.isDragging) {
                const absX = Math.abs(deltaX);
                const absY = Math.abs(deltaY);

                // If moving finger down (deltaY > 0), it's always a scroll
                if (deltaY > SCROLL_THRESHOLD) {
                    g.isScrolling = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                } 
                // If moving finger up (deltaY < 0), we check intent
                else if (deltaY < -SCROLL_THRESHOLD) {
                    const isFastSwipe = Math.abs(g.velocity) > 10;
                    if (g.hasCard && !isFastSwipe) {
                        // Slow upward move with card = potential drag
                        if (absY > DRAG_THRESHOLD) {
                            g.isDragging = true;
                            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                            setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                        }
                    } else {
                        // Fast upward move or no card = scroll
                        g.isScrolling = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    }
                }
                // Horizontal move
                else if (absX > DRAG_THRESHOLD) {
                    if (g.hasCard) {
                        g.isDragging = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                        setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                    }
                }
            }

            if (g.isScrolling && scrollRef.current) {
                scrollRef.current.scrollTop = g.startScrollTop - deltaY;
                return;
            }

            if (g.isDragging) {
                if (e.cancelable) e.preventDefault();
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const { isDragging, isScrolling, startPos, hasCard, velocity } = gestureRef.current;

            if (isScrolling && Math.abs(velocity) > MIN_VELOCITY) {
                inertiaFrameRef.current = requestAnimationFrame(runInertia);
            }

            if (isDragging && hasCard) {
                const els = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !user.collection.includes(dragState.card.id))) {
                    // Logic to ensure cards are only dropped where valid
                    onRemove(dragState.card.id);
                }
            } else if (!isScrolling && !isDragging && hasCard) {
                const dist = Math.hypot(e.clientX - startPos.x, e.clientY - startPos.y);
                if (dist < DRAG_THRESHOLD) inspect(dragState.card);
            }

            setDragState(null);
            gestureRef.current.isScrolling = false;
            gestureRef.current.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, runInertia, user]);

    return { dragState, handlePointerDown };
};

import React, { useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInMins = Math.floor(diffInMs / (1000 * 60));
    if (diffInMins < 1) return 'just now';
    if (diffInMins < 60) return `${diffInMins} ${diffInMins === 1 ? 'minute' : 'minutes'} ago`;
    const diffInHours = Math.floor(diffInMs / (1000 * 60 * 60));
    if (diffInHours < 24) return `${diffInHours} ${diffInHours === 1 ? 'hour' : 'hours'} ago`;
    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 110;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            rotationRef.current = (activeDeckId - 1) * angleStep;
            updateDom(rotationRef.current);
        }
    }, [activeDeckId, angleStep]);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;
        let currentCenterI = -1;
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;
            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;
            const absAngle = Math.abs(normalizedAngle);
            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);
                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.05, opacity).toString();
                item.style.visibility = 'visible';
                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) { prevItem.classList.remove('is-visually-center'); prevItem.style.zIndex = '10'; }
            if (nextItem) { nextItem.classList.add('is-visually-center'); nextItem.style.zIndex = '50'; }
            lastCenteredIndexRef.current = currentCenterI;
        }
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;
            if (!isDraggingRef.current && elapsed > 1000) canPlayAudioRef.current = false;
            if (canPlayAudioRef.current && elapsed > 12) {
                audio.play('sfx_ui_click', 0.45);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.95;
        rotationRef.current += velocityRef.current;
        if (Math.abs(velocityRef.current) < 0.35) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.45;
            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) onSelectDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.2 + instantVelocity * 0.8;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    return (
        <div 
            className="w-full h-64 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div ref={drumRef} className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform">
                {deckIds.map((id, i) => {
                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                    const isInitialCenter = activeDeckId === id;
                    const isValid = (user.decks[id]?.length || 0) === 12;
                    const statsText = `conquest: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} (${stats?.conquestWinRate || 0}%) - ladder ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0} (${stats?.ladderWinRate || 0}%)`;

                    return (
                        // Fixed: Ref callback wrapped in braces to return void
                        <div key={id} ref={el => { itemsRef.current[i] = el; }} className={`absolute inset-0 backface-hidden transition-opacity duration-300 transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`} style={{ transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`, opacity: isInitialCenter ? 1 : 0.5, zIndex: isInitialCenter ? 50 : 10 }}>
                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText text={deckName} baseFontSize={1.4} maxLines={1} className="text-white" />
                                    </div>
                                    <div className="w-full h-5 flex items-center justify-center opacity-80">
                                        <GameText text={statsText} baseFontSize={0.75} maxLines={1} className="text-white font-bold" />
                                    </div>
                                    <div className="w-full h-3 mt-0.5 opacity-50">
                                        <GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="text-white lowercase italic" />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>
            <div className="absolute left-0 right-0 h-24 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />
            <style>{`.transform-style-3d { transform-style: preserve-3d; } .backface-hidden { backface-visibility: hidden; } .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; } .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; } .is-visually-center { filter: grayscale(0) !important; } div:not(.is-visually-center) { filter: grayscale(0.3); }`}</style>
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
