import { ActivityLogSection } from '../progression/ActivityLogSection';

// ANIMATION CONSTANTS
const BASE_TICK_MS = 80;
const LAP_MECHANICAL_PAUSE_MS = 100;
const LAP_OVER_RIDE_DURATION_MS = 75;
const BUTTON_FLASH_DURATION_MS = 500;
const CENTERING_DURATION_MS = 500; 
const VICTORY_CLIMAX_DURATION_MS = 4500; 

interface ProgressionScreenProps {
    onClose: () => void;
}

type ProgressionTab = 'REWARDS' | 'ACTIVITY';
type HeaderStage = 'INITIAL' | 'SLIDING' | 'TICKING' | 'FINAL';

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    const [activeTab, setActiveTab] = useState<ProgressionTab>('REWARDS');
    const [headerStage, setHeaderStage] = useState<HeaderStage>(pendingLevelIncrement > 0 ? 'INITIAL' : 'FINAL');

    const initialStats = useMemo(() => ({
        startLevel: user.level - pendingLevelIncrement,
        totalGain: pendingLevelIncrement
    }), []);

    const [visualLevel, setVisualLevel] = useState<number>(initialStats.startLevel);
    const [visualGain, setVisualGain] = useState<number>(initialStats.totalGain);
    const [isCompletionFlare, setIsCompletionFlare] = useState(false);

    const [claimingIndices, setClaimingIndices] = useState<Set<number>>(new Set());
    const [claimingAllIndices, setClaimingAllIndices] = useState<Set<number>>(new Set());
    const [successIndices, setSuccessIndices] = useState<Set<number>>(new Set());
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [newlyGainedIndices, setNewlyGainedIndices] = useState<Set<number>>(new Set());

    const isChasingRef = useRef(false);

    const handleManualClose = useCallback(() => {
        clearLevelUpSignal();
        onClose();
    }, [clearLevelUpSignal, onClose]);

    useEffect(() => {
        if (headerStage === 'INITIAL') {
            const timer = setTimeout(() => setHeaderStage('SLIDING'), 1000);
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    useEffect(() => {
        if (headerStage === 'SLIDING') {
            const timer = setTimeout(() => {
                setHeaderStage('TICKING');
                isChasingRef.current = true;
            }, 500); 
            return () => clearTimeout(timer);
        }
    }, [headerStage]);

    useEffect(() => {
        if (headerStage === 'TICKING' && isChasingRef.current && visualLevel < user.level) {
            const nextLevel = visualLevel + 1;
            const nextGain = Math.max(0, visualGain - 1);

            const newLaps = new Set<number>();
            REWARD_SEQUENCE.forEach((conf, i) => {
                if ((nextLevel + conf.offset) % conf.capacity === 0) newLaps.add(i);
            });

            const currentStepDelay = BASE_TICK_MS + (newLaps.size > 0 ? LAP_MECHANICAL_PAUSE_MS : 0);

            const timer = setTimeout(() => {
                if (newLaps.size > 0) {
                    setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });
                    setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.add(idx));
                        return next;
                    });

                    if (newLaps.has(4)) audio.play('sfx_teleport_short', 0.8);
                    else if (newLaps.has(3)) audio.play('sfx_equip_tech', 1.2);
                    else audio.play('sfx_ui_click', 1.6); 

                    setTimeout(() => setLappingIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), LAP_OVER_RIDE_DURATION_MS);
                    setTimeout(() => setNewlyGainedIndices(prev => {
                        const next = new Set(prev);
                        newLaps.forEach(idx => next.delete(idx));
                        return next;
                    }), BUTTON_FLASH_DURATION_MS);
                }

                setVisualLevel(nextLevel);
                setVisualGain(nextGain);
                audio.play('sfx_ui_hover', 0.4);
            }, currentStepDelay);
            return () => clearTimeout(timer);
        } 
        else if (headerStage === 'TICKING' && visualLevel >= user.level) {
            isChasingRef.current = false;
            const settleTimer = setTimeout(() => {
                setHeaderStage('FINAL'); 
                setTimeout(() => {
                    setIsCompletionFlare(true);
                    audio.play('sfx_victory', 0.6);
                    clearLevelUpSignal();
                    setTimeout(() => setIsCompletionFlare(false), VICTORY_CLIMAX_DURATION_MS);
                }, CENTERING_DURATION_MS);
            }, 400); 
            return () => clearTimeout(settleTimer);
        }
    }, [headerStage, visualLevel, visualGain, user.level, clearLevelUpSignal]);

    const visualTracks: ProgressionTrack[] = useMemo(() => {
        if (!progressionData) return [];
        return REWARD_SEQUENCE.map((config, i) => {
            const totalPointsVisual = visualLevel + config.offset;
            const currentXP = totalPointsVisual % config.capacity;
            const totalEarnedFinal = Math.floor((user.level + config.offset) / config.capacity);
            const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
            const deltaNotYetEarned = totalEarnedFinal - totalEarnedVisual;
            const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
            const visualUnclaimedCount = Math.max(0, finalUnclaimed - deltaNotYetEarned);
            return {
                type: config.type,
                label: config.label,
                currentXP,
                targetXP: config.capacity,
                unclaimedCount: visualUnclaimedCount,
                nextRewardAmount: config.amount,
            };
        });
    }, [visualLevel, progressionData, user.level]);

    const handleClaim = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || successIndices.has(idx) || headerStage === 'TICKING') return;
        setClaimingIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        // Fixed: API expects userId string, not user object
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user.id, type), { visualDelay: 400 });
        setClaimingIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 1500);
        }
    }, [claimingIndices, claimingAllIndices, successIndices, user.id, performSynchronizedAction, headerStage]);

    const handleClaimAll = useCallback(async (type: ProgressionRewardType, idx: number) => {
        if (claimingIndices.has(idx) || claimingAllIndices.has(idx) || successIndices.has(idx) || headerStage === 'TICKING') return;
        setClaimingAllIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
        // Fixed: API expects userId string, not user object
        const success = await performSynchronizedAction(() => api.claimAllProgressionRewards(user.id, type), { visualDelay: 600 });
        setClaimingAllIndices(prev => { const next = new Set(prev); next.delete(idx); return next; });
        if (success) {
            setSuccessIndices(prev => { const next = new Set(prev); next.add(idx); return next; });
            setTimeout(() => setSuccessIndices(prev => { const next = new Set(prev); next.delete(idx); return next; }), 2000);
        }
    }, [claimingIndices, claimingAllIndices, successIndices, user.id, performSynchronizedAction, headerStage]);

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    const isShifted = headerStage === 'SLIDING' || headerStage === 'TICKING';
    const showGain = headerStage === 'TICKING' || (headerStage === 'SLIDING' && visualGain > 0);

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden">
                <div className="absolute inset-0 animated-bg z-0" />
                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-0.5 pb-1.5 flex items-center px-1 z-40 shadow-lg overflow-visible">
                    <div className="flex-none flex justify-start items-center gap-1.5 min-w-0 overflow-visible">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase drop-shadow-[0_2px_5px_rgba(0,0,0,0.8)] whitespace-nowrap italic ml-2 font-sans leading-none pr-4">COLLECTION LEVEL</h1>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-1.5 pr-1">
                        <SlantedButton variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('REWARDS')} icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 18C15.3137 18 18 15.3137 18 12V4H6V12C6 15.3137 8.68629 18 12 18ZM12 18V21M12 21H8M12 21H16M18 6H20C21.1046 6 22 6.89543 22 8V10C22 11.1046 21.1046 12 20 12H18M6 6H4C2.89543 6 2 6.89543 2 8V10C2 11.1046 2.89543 12 4 12H6" /></svg>} />
                        <SlantedButton variant={activeTab === 'ACTIVITY' ? 'primary' : 'secondary'} size="xs" className="!w-[10vw] max-w-[2.4rem] !h-[1.5rem]" onClick={() => setActiveTab('ACTIVITY')} icon={<svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
                    </div>
                </div>

                <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                    {activeTab === 'REWARDS' ? (
                        <div className="flex-1 flex flex-col min-h-0">
                            <div className="shrink-0 pt-1 pb-0 flex flex-col items-center relative z-10 overflow-visible">
                                <div className="relative w-full flex justify-center items-center h-9 overflow-visible">
                                    <div className={`flex items-center gap-1.5 transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${isShifted ? '-translate-x-6' : 'translate-x-0'}`}>
                                        <div className="flex flex-col items-end text-right gap-0.5 opacity-90">
                                            <span className="text-[0.55rem] font-bold tracking-widest text-white leading-none">COLLECTION</span>
                                            <span className="text-[0.55rem] font-bold tracking-widest text-white leading-none">LEVEL</span>
                                        </div>
                                        <div className="relative flex items-center overflow-visible">
                                            <div className={`text-[1.8rem] font-black italic tracking-tighter text-white drop-shadow-md leading-none transition-all ${headerStage === 'TICKING' ? 'animate-intensity-pulse' : ''} ${isCompletionFlare ? 'animate-completion-flare' : ''}`}>{visualLevel.toLocaleString()}</div>
                                            <div className={`absolute left-full ml-2 text-[1.4rem] font-black italic tracking-tighter text-emerald-400 drop-shadow-[0_0_10px_rgba(52,211,153,0.4)] whitespace-nowrap leading-none transition-opacity duration-300 ${showGain && visualGain > 0 ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-4 pointer-events-none'}`}>+{visualGain}</div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className="flex-1 flex flex-col px-2 pt-1 pb-2 justify-between relative z-10 overflow-hidden">
                                <div className="space-y-2 mb-4 px-2"><div className="h-px w-full bg-white/60 shadow-[0_0_5px_rgba(255,255,255,0.4)]" /><div className="h-4 w-full"><GameText text="Progression Details" baseFontSize={0.6} className="text-white font-black uppercase tracking-[0.4em]" /></div></div>
                                <div className="flex-1 flex flex-col justify-around gap-2">
                                    {visualTracks.length > 0 ? visualTracks.map((track, idx) => (
                                        // Fixed: Added missing isGlobalTicking prop
                                        <ProgressionTrackRow key={`${track.type}-${idx}`} track={track} isClaiming={claimingIndices.has(idx)} isClaimingAll={claimingAllIndices.has(idx)} isSuccess={successIndices.has(idx)} isLapping={lappingIndices.has(idx)} isNewlyGained={newlyGainedIndices.has(idx)} isGlobalTicking={headerStage === 'TICKING'} onClaim={() => handleClaim(track.type, idx)} onClaimAll={() => handleClaimAll(track.type, idx)} />
                                    )) : <div className="flex-1 flex items-center justify-center opacity-20"><span className="text-[0.6rem] font-black uppercase tracking-[0.3em]">No Track Data</span></div>}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col bg-transparent overflow-hidden"><ActivityLogSection logs={activityLog} /></div>
                    )}
                </div>
                <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3"><SlantedButton variant="danger" size="md" onClick={handleManualClose} className="shadow-2xl !w-[32vw] max-w-[8.5rem] !h-8">CLOSE</SlantedButton></div>
            </div>
            <style>{`
                @keyframes intensity-pulse { 0%, 100% { filter: brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.2)); } 50% { filter: brightness(2.2) drop-shadow(0 0 35px rgba(255,255,255,0.9)); } }
                .animate-intensity-pulse { animation: intensity-pulse 2s ease-in-out infinite; will-change: filter; }
                @keyframes completion-flare { 0% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 0px rgba(255,255,255,0); } 35% { transform: scale(1.3); filter: brightness(14); text-shadow: 0 0 40px rgba(99,102,241,1), 0 0 100px rgba(255,255,255,1); } 100% { transform: scale(1); filter: brightness(1); text-shadow: 0 0 25px rgba(99,102,241,0.7); } }
                .animate-completion-flare { animation: completion-flare 4.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; z-index: 100; }
            `}</style>
        </Portal>
    );
};

import { ProgressionRewardType, ProgressionTrack, ProgressionData } from '../../types';
import { REWARD_SEQUENCE } from '../../services/api/mockData';

// Ensure this matches the HexBadge type definition
type BadgeVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

export const getScale = (type: string) => {
    if (type === 'tokens') return 'scale-[0.85]';   
    if (type === 'gold') return 'scale-[1.1]';     
    if (type === 'credits') return 'scale-[1.1]';  
    if (type === 'booster') return 'scale-[1.3]';    
    if (type === 'box') return 'scale-[1.3]';        
    return 'scale-[1.3]';
};

// Fixed: Explicit return type to avoid 'string' mismatch in HexBadge
export const getVariant = (type: ProgressionRewardType): BadgeVariant => {
    switch(type) {
        case 'booster': return 'success';
        case 'credits': return 'blue';
        case 'gold': return 'warning';
        case 'tokens': return 'danger';
        case 'box': return 'primary';
        default: return 'secondary';
    }
};

export const getPulseColor = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return 'border-emerald-400';
        case 'credits': return 'border-blue-400';
        case 'gold': return 'border-amber-400';
        case 'tokens': return 'border-red-400';
        case 'box': return 'border-indigo-400';
        default: return 'border-white';
    }
};

export const getCheckmarkColor = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return 'text-emerald-400';
        case 'credits': return 'text-blue-400';
        case 'gold': return 'text-yellow-400'; 
        case 'tokens': return 'text-red-400';
        case 'box': return 'text-indigo-400';
        default: return 'text-white';
    }
};

export const getFlareColor = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return '#34d399'; // Emerald
        case 'credits': return '#60a5fa'; // Blue
        case 'gold': return '#fbbf24';    // Amber/Gold
        case 'tokens': return '#f87171';   // Red
        case 'box': return '#818cf8';      // Indigo
        default: return '#ffffff';
    }
};

export const getSpinnerColor = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return 'border-t-emerald-400';
        case 'credits': return 'border-t-blue-400';
        case 'gold': return 'border-t-amber-400';
        case 'tokens': return 'border-t-red-400';
        case 'box': return 'border-t-indigo-400';
        default: return 'border-t-white';
    }
};

export const getColors = (type: ProgressionRewardType) => {
    switch(type) {
        case 'booster': return { color: 'from-emerald-600 to-emerald-400', bgTrack: 'bg-[#064e3b]', borderColor: 'border-emerald-400/50' };
        case 'credits': return { color: 'from-blue-600 to-blue-400', bgTrack: 'bg-[#1e3a8a]', borderColor: 'border-blue-400/50' };
        case 'gold': return { color: 'from-amber-600 to-amber-400', bgTrack: 'bg-[#78350f]', borderColor: 'border-amber-400/50' };
        case 'tokens': return { color: 'from-red-600 to-red-400', bgTrack: 'bg-[#450a0a]', borderColor: 'border-red-400/50' };
        case 'box': return { color: 'from-indigo-600 to-indigo-400', bgTrack: 'bg-[#1e1b4b]', borderColor: 'border-indigo-400/50' };
        default: return { color: 'from-slate-600 to-white', bgTrack: 'bg-[#334155]', borderColor: 'border-white/50' };
    }
};

/**
 * Calculates visual progression tracks based on the current animated level.
 * Ensures rewards "appear" exactly as the level ticks past their threshold.
 */
export const projectVisualTracks = (
    visualLevel: number, 
    actualLevel: number, 
    progressionData: ProgressionData | null
): ProgressionTrack[] => {
    if (!progressionData) return [];

    return REWARD_SEQUENCE.map((config, i) => {
        const totalPointsVisual = visualLevel + config.offset;
        const currentXP = totalPointsVisual % config.capacity;

        // Unclaimed logic projection
        const totalEarnedFinal = Math.floor((actualLevel + config.offset) / config.capacity);
        const totalEarnedVisual = Math.floor(totalPointsVisual / config.capacity);
        const finalUnclaimed = progressionData.tracks[i]?.unclaimedCount || 0;
        const visualUnclaimed = Math.max(0, finalUnclaimed - (totalEarnedFinal - totalEarnedVisual));

        return {
            type: config.type,
            label: config.label,
            currentXP,
            targetXP: config.capacity,
            unclaimedCount: visualUnclaimed,
            nextRewardAmount: config.amount,
        };
    });
};

