import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { useLevelChaser } from '../../hooks/useLevelChaser';
import { useProgressionTracks } from '../../hooks/useProgressionTracks';
import { useProgressionClaims } from '../../hooks/useProgressionClaims';

// Modular Components
import { ProgressionLoading } from '../progression/ProgressionLoading';
import { ProgressionHeader } from '../progression/ProgressionHeader';
import { RewardView } from '../progression/RewardView';
import { ActivityLogSection } from '../progression/ActivityLogSection';

interface ProgressionScreenProps {
    onClose: () => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    // 1. Manage the animated numerical sequence
    const { visualLevel, visualGain, isTicking, isShifted, lappingIndices, isFlare } = useLevelChaser(
        user.level, 
        pendingLevelIncrement, 
        clearLevelUpSignal
    );

    // 2. Project the state of reward tracks based on visual level
    const visualTracks = useProgressionTracks(
        visualLevel, 
        user.level, 
        progressionData
    );

    // 3. Manage claiming interactions
    const { rewardStates, handleClaimAction } = useProgressionClaims(isTicking);

    const [activeTab, setActiveTab] = useState<'REWARDS' | 'ACTIVITY'>('REWARDS');

    const handleManualClose = useCallback(() => {
        clearLevelUpSignal();
        onClose();
    }, [clearLevelUpSignal, onClose]);

    if (!progressionData && isProgressionLoading) {
        return <ProgressionLoading />;
    }

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-start bg-slate-950 overflow-hidden">
                {/* Visual Background Layers */}
                <div className="absolute inset-0 z-0 animated-bg" />
                <div className="absolute inset-0 z-0 bg-black/40 pointer-events-none" />

                <div className="w-full h-full max-w-[23rem] flex flex-col relative z-10 overflow-hidden shadow-2xl">
                    <ProgressionHeader 
                        activeTab={activeTab} 
                        onTabChange={setActiveTab} 
                    />

                    <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                        {activeTab === 'REWARDS' ? (
                            <RewardView 
                                visualLevel={visualLevel}
                                visualGain={visualGain}
                                isTicking={isTicking}
                                isShifted={isShifted}
                                isFlare={isFlare}
                                visualTracks={visualTracks}
                                lappingIndices={lappingIndices}
                                rewardStates={rewardStates as any}
                                onClaim={handleClaimAction}
                            />
                        ) : (
                            <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                                 <ActivityLogSection logs={activityLog} />
                            </div>
                        )}
                    </div>

                    <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3 bg-gradient-to-t from-black via-black/80 to-transparent">
                        <SlantedButton 
                            variant="danger" 
                            size="md" 
                            onClick={handleManualClose} 
                            className="shadow-2xl !w-[40vw] max-w-[10rem] !h-8"
                        >
                            Close
                        </SlantedButton>
                    </div>
                </div>
            </div>
        </Portal>
    );
};

import { useState, useEffect, useRef } from 'react';
import { audio } from '../services/audio';
import { REWARD_SEQUENCE } from '../services/api/mockData';

const TICK_RATE = 70;
const LAP_PAUSE = 100;
const CLIMAX_DURATION = 4500;
const INITIAL_STABILIZATION_DELAY = 1500;
const SHIFT_DURATION = 600; 
const SETTLE_DELAY = 500; // Hold on final number for 0.5s

export const useLevelChaser = (targetLevel: number, increment: number, onComplete: () => void) => {
    const [isTicking, setIsTicking] = useState(increment > 0);
    const [isWaitingToStart, setIsWaitingToStart] = useState(increment > 0);
    const [isShifted, setIsShifted] = useState(false);
    const [visualLevel, setVisualLevel] = useState(targetLevel - increment);
    const [visualGain, setVisualGain] = useState(increment);
    const [lappingIndices, setLappingIndices] = useState<Set<number>>(new Set());
    const [isFlare, setIsFlare] = useState(false);

    // 1. Orchestrated Sequence: Wait -> Shift -> Start Ticking
    useEffect(() => {
        if (increment > 0) {
            let active = true;
            const sequence = async () => {
                // Stage 1: Absolute Center Stabilization
                await new Promise(resolve => setTimeout(resolve, INITIAL_STABILIZATION_DELAY));
                if (!active) return;

                // Stage 2: Slide to left to make room for Gain
                setIsShifted(true);

                // Stage 3: Wait for animation, then begin numerical chase
                await new Promise(resolve => setTimeout(resolve, SHIFT_DURATION));
                if (!active) return;
                setIsWaitingToStart(false);
            };
            sequence();
            return () => { active = false; };
        } else {
            setIsWaitingToStart(false);
        }
    }, [increment]);

    // 2. The Ticking Loop
    useEffect(() => {
        if (isWaitingToStart) return;

        if (!isTicking || visualLevel >= targetLevel) {
            if (isTicking) {
                // We reached the end! 
                setIsTicking(false);

                const finishSequence = async () => {
                    // Hold on the final number (0 gain)
                    await new Promise(resolve => setTimeout(resolve, SETTLE_DELAY));

                    setIsShifted(false); // Slide back to perfect center
                    setIsFlare(true);
                    audio.play('sfx_victory', 0.6);
                    onComplete();
                    setTimeout(() => setIsFlare(false), CLIMAX_DURATION);
                };

                finishSequence();
            }
            return;
        }

        const nextLevel = visualLevel + 1;
        const newLaps = new Set<number>();

        REWARD_SEQUENCE.forEach((conf, i) => {
            if ((nextLevel + conf.offset) % conf.capacity === 0) {
                newLaps.add(i);
            }
        });

        const timer = setTimeout(() => {
            if (newLaps.size > 0) {
                setLappingIndices(newLaps);
                audio.play('sfx_ui_click', 1.4);
                setTimeout(() => setLappingIndices(new Set()), 100);
            }

            setVisualLevel(nextLevel);
            setVisualGain(prev => Math.max(0, prev - 1));
            audio.play('sfx_ui_hover', 0.3);
        }, TICK_RATE + (newLaps.size > 0 ? LAP_PAUSE : 0));

        return () => clearTimeout(timer);
    }, [isTicking, isWaitingToStart, visualLevel, targetLevel, onComplete]);

    return {
        visualLevel,
        visualGain,
        isTicking: isTicking && !isWaitingToStart,
        isShifted,
        lappingIndices,
        isFlare
    };
};

import React from 'react';

interface LevelHeroProps {
    level: number;
    gain: number;
    isTicking: boolean;
    isShifted: boolean;
    isFlare: boolean;
}

export const LevelHero: React.FC<LevelHeroProps> = React.memo(({ level, gain, isTicking, isShifted, isFlare }) => (
    <div className="shrink-0 pb-2 flex flex-col items-center relative overflow-visible w-full">
        <div className="relative w-full flex justify-center items-center h-14 overflow-visible">
            <div 
                className={`flex items-center gap-2 transition-transform duration-700 ease-[cubic-bezier(0.22,1,0.36,1)] ${isShifted ? '-translate-x-6' : 'translate-x-0'}`}
                style={{ willChange: 'transform' }}
            >
                {/* LABEL GROUP */}
                <div className="flex flex-col items-end text-right gap-0 opacity-80 shrink-0">
                    <span className="text-[0.45rem] font-bold tracking-[0.3em] text-white leading-none uppercase">Collection</span>
                    <span className="text-[0.5rem] font-black tracking-[0.3em] text-white leading-none uppercase">Level</span>
                </div>

                {/* NUMBER GROUP */}
                <div className="relative flex items-center overflow-visible shrink-0">
                    {/* Size reduced from 2.4rem to 1.6rem (~33% reduction) */}
                    <div className={`text-[1.6rem] font-black italic tracking-tighter text-white drop-shadow-[0_2px_8px_rgba(0,0,0,0.5)] leading-none transition-all ${isTicking ? 'animate-intensity-pulse' : ''} ${isFlare ? 'animate-completion-flare' : ''}`}>
                        {level.toLocaleString()}
                    </div>

                    {/* 
                        THE GAIN INDICATOR 
                        Strictly gated by isShifted to prevent immediate visibility on screen load.
                        Size reduced from 1.8rem to 1.2rem (~33% reduction).
                    */}
                    {isShifted && gain >= 0 && (
                        <div className="absolute left-full ml-3 flex items-center animate-gain-reveal">
                            <span className="text-[1.2rem] font-black italic tracking-tighter text-emerald-400 drop-shadow-[0_0_15px_rgba(52,211,153,0.6)] leading-none">
                                +{gain}
                            </span>
                        </div>
                    )}
                </div>
            </div>
        </div>
        <style>{`
            @keyframes gain-reveal {
                from { opacity: 0; transform: translateX(1rem); }
                to { opacity: 1; transform: translateX(0); }
            }
            .animate-gain-reveal {
                animation: gain-reveal 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
            }
        `}</style>
    </div>
));

