import React, { useState, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { Portal } from '../ui/Portal';
import { SlantedButton } from '../ui/SlantedButton';
import { useLevelChaser } from '../../hooks/useLevelChaser';
import { useProgressionTracks } from '../../hooks/useProgressionTracks';
import { useProgressionClaims } from '../../hooks/useProgressionClaims';

// Modular Components
import { ProgressionLoading } from '../progression/ProgressionLoading';
import { ProgressionHeader } from '../progression/ProgressionHeader';
import { RewardView } from '../progression/RewardView';
import { ActivityLogSection } from '../progression/ActivityLogSection';

interface ProgressionScreenProps {
    onClose: () => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading } = useUser();
    const { pendingLevelIncrement, clearLevelUpSignal } = useUI();

    // 1. Manage the animated numerical sequence
    // This hook emits the ticking values every 70ms
    const { visualLevel, visualGain, isTicking, isShifted, lappingIndices, isFlare } = useLevelChaser(
        user.level, 
        pendingLevelIncrement, 
        clearLevelUpSignal
    );

    // 2. Project the state of reward tracks based on visual level
    // Memoized internally to only update when visualLevel hits a "lap" point
    const visualTracks = useProgressionTracks(
        visualLevel, 
        user.level, 
        progressionData
    );

    // 3. Manage claiming interactions
    const { rewardStates, handleClaimAction } = useProgressionClaims(isTicking);

    const [activeTab, setActiveTab] = useState<'REWARDS' | 'ACTIVITY'>('REWARDS');

    const handleManualClose = useCallback(() => {
        clearLevelUpSignal();
        onClose();
    }, [clearLevelUpSignal, onClose]);

    if (!progressionData && isProgressionLoading) {
        return <ProgressionLoading />;
    }

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-start bg-slate-950 overflow-hidden">
                {/* Visual Background Layers */}
                <div className="absolute inset-0 z-0 animated-bg" />
                <div className="absolute inset-0 z-0 bg-black/40 pointer-events-none" />

                <div className="w-full h-full max-w-[23rem] flex flex-col relative z-10 overflow-hidden shadow-2xl">
                    <ProgressionHeader 
                        activeTab={activeTab} 
                        onTabChange={setActiveTab} 
                    />

                    <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                        {activeTab === 'REWARDS' ? (
                            <RewardView 
                                visualLevel={visualLevel}
                                visualGain={visualGain}
                                isTicking={isTicking}
                                isShifted={isShifted}
                                isFlare={isFlare}
                                visualTracks={visualTracks}
                                lappingIndices={lappingIndices}
                                rewardStates={rewardStates as any}
                                onClaim={handleClaimAction}
                            />
                        ) : (
                            <div className="flex-1 flex flex-col bg-transparent overflow-hidden">
                                 <ActivityLogSection logs={activityLog} />
                            </div>
                        )}
                    </div>

                    {/* Fixed Footer Close Action */}
                    <div className="shrink-0 h-14 flex items-center justify-center z-50 mb-3 bg-gradient-to-t from-black via-black/80 to-transparent">
                        <SlantedButton 
                            variant="danger" 
                            size="md" 
                            onClick={handleManualClose} 
                            className="shadow-2xl !w-[40vw] max-w-[10rem] !h-8"
                        >
                            Close
                        </SlantedButton>
                    </div>
                </div>
            </div>
        </Portal>
    );
};

import { SfxKey } from './utils/assets';

export { SfxKey };

// --- UI Types ---
export type ScreenKey = 'MENU' | 'GAME' | 'DECK' | 'SEASON' | 'STORE' | 'PROFILE' | 'INBOX' | 'RANK' | 'PROGRESSION' | 'HISTORY';

export type CollectionTab = 'CARDS' | 'COMICS' | 'INVENTORY';

export type Zone = 
  | "DECK" 
  | "HAND" 
  | "BOARD" 
  | "DISCARDED" 
  | "DESTROYED" 
  | "BANISHED";

export type PlayerID = "p1" | "p2";

// --- Meta Game Types ---
export interface SeasonProgressData {
    level: number;
    xp: number;
}

export interface UserProfile {
    id: string;
    username: string;
    level: number; 
    seasonProgress: Record<string, SeasonProgressData>; 
    rank: number; 
    credits: number;
    gold: number;
    tokens: number; 
    activeDeckId: number;
    avatarId: string;
    purchasedOfferIds: string[]; 
    lastClaimedDates: Record<string, string>;
    collection: string[]; 
    decks: Record<number, string[]>; 
    deckNames: Record<number, string>;
    deckStats: Record<number, {
        conquestWinRate: number;
        ladderWinRate: number;
        conquestWins: number;
        conquestTotal: number;
        ladderWins: number;
        ladderLosses: number;
        lastModified: string; 
    }>;
    cardRarities: Record<string, CardRarity>; 
}

export type CardRarity = "Common" | "Rare" | "Epic" | "Legendary";

// --- Progression Types ---
export type ProgressionRewardType = 'booster' | 'credits' | 'gold' | 'box' | 'card' | 'tokens';

export interface ProgressionTrack {
    type: ProgressionRewardType;
    label: string;
    currentXP: number;
    targetXP: number;
    unclaimedCount: number;
    nextRewardAmount: number | string;
    nextRewardCardDef?: CardDefinition;
}

export interface ProgressionData {
    collectionLevel: number;
    tracks: ProgressionTrack[];
}

export interface ActivityLogEntry {
    id: string;
    title: string;
    type: ProgressionRewardType | 'purchase' | 'system';
    date: string;
    time: string;
    amount?: string | number;
    delta?: number; // Numerical change for ledger tracking
    isSpend?: boolean; // True if currency was lost
    currencyType?: 'gold' | 'credits' | 'tokens';
    cardDef?: CardDefinition;
}

// --- Season Types ---
export type SeasonRewardType = 'gold' | 'credits' | 'card' | 'booster' | 'tokens';

export interface SeasonPassReward {
    level: number;
    type: SeasonRewardType;
    amount: string | number;
    isClaimed: boolean;
    isActive: boolean;
    isLocked: boolean;
    cardDef?: CardDefinition;
}

export interface SeasonPassData {
    id: string;
    themeName: string;
    startDate: string;
    endDate: string;
    endsInSeconds: number;
    premiumActive: boolean;
    heroCardId: string;
    heroVariantName?: string;
    rewards: SeasonPassReward[];
}

// --- Store Types ---
export type OfferItem = 
  | { type: 'card'; definitionId: string }
  | { type: 'currency'; currencyType: 'gold' | 'credits' | 'tokens'; amount: number };

export interface StoreOffer {
    id: string;
    title: string;
    description: string;
    price: string; 
    priceAmount?: number; 
    priceType: 'real' | 'gold' | 'credits' | 'free' | 'tokens';
    imageUrl: string;
    discountLabel?: string;
    category?: 'featured' | 'monthly' | 'daily';
    isOneTime: boolean;
    purchaseLimit?: number; 
    contents: OfferItem[];
    expiryDate?: string; 
    cooldownSeconds?: number; 
    availableAt?: string; 
}

export interface StoreData {
    offers: StoreOffer[];
    lastUpdated: number;
    refreshHintSeconds: number;
}

export type StoreErrorCode = 
    | 'ERR_OFFER_NOT_FOUND' 
    | 'ERR_INSUFFICIENT_FUNDS' 
    | 'ERR_STALE_OFFER' 
    | 'ERR_DUPLICATE_TRANSACTION' 
    | 'ERR_BALANCE_DESYNC'
    | 'ERR_COOLDOWN_ACTIVE';

export interface PurchaseResponse {
    success: boolean;
    errorCode?: StoreErrorCode;
    transactionId: string;
    updatedProfile?: UserProfile; 
}

export type VfxKey = 
    | 'vfx_explosion_small' 
    | 'vfx_warp_trail' 
    | 'vfx_dust_motes' 
    | 'vfx_electric_arcs' 
    | 'vfx_nebula_fog';

export interface CardDefinition {
  id: string;
  name: string;
  rarity: CardRarity;
  baseCost: number;
  basePower: number;
  tags: string[]; 
  baseText: string;
  effect: string; 
  imageUrl: string;
  flavorText?: string;

  sfxOnPlay?: SfxKey;   
  sfxOnReveal?: SfxKey; 
  vfxOnReveal?: VfxKey; 
}

export interface StatModifier {
  source: string; 
  value: number;
  type: "BASE" | "PERMANENT" | "CONTINUOUS";
}

export interface CardInstance {
  instanceId: string;
  definitionId: string;
  owner: PlayerID;

  zone: Zone;
  laneIndex: number | null;
  slotIndex: number | null;
