    claimedCounts: [0, 0, 0, 0, 0],
    activityLog: [
        { id: 'log_0', title: "Daily Token Gift", type: 'tokens', date: "15 MAY", time: "10:30", delta: 50, isSpend: false, currencyType: 'tokens' },
        { id: 'log_1', title: "Titan Variant", type: 'card', date: "14 MAY", time: "22:15", cardDef: CARDS[5], isSpend: true, currencyType: 'gold', delta: 1200 },
        { id: 'log_2', title: "Omega Box", type: 'box', date: "12 MAY", time: "14:20", isSpend: false },
        { id: 'log_3', title: "Credit Patch", type: 'credits', date: "11 MAY", time: "09:45", delta: 500, isSpend: false, currencyType: 'credits' },
