}

const formatTimeAMPM = (timeStr: string) => {
    if (!timeStr) return '';
    try {
        const [hours, minutes] = timeStr.split(':').map(Number);
        const ampm = hours >= 12 ? 'PM' : 'AM';
        const h = hours % 12 || 12;
        return `${h}:${minutes.toString().padStart(2, '0')} ${ampm}`;
    } catch (e) {
        return timeStr;
    }
};

export const ActivityLogItem: React.FC<ActivityLogItemProps> = React.memo(({ item }) => {
    const isSpend = item.isSpend ?? false;

    // Filter out spends for "Gains Only" archive experience
    if (isSpend) return null;

    // Standardized localized icon scaling for activity log rows
    let iconClass = 'scale-[1.2]'; 
    if (item.type === 'card') iconClass = 'scale-[0.55]'; 

    // Construct the primary Gain Header
    let gainHeader = '';
    if (item.type === 'card') {
        gainHeader = item.cardDef?.name || 'New Variant';
    } else if (item.type === 'box') {
        gainHeader = 'Omega Box';
    } else {
        const label = item.type.charAt(0).toUpperCase() + item.type.slice(1);
        gainHeader = `+${item.delta?.toLocaleString()} ${label}`;
    }

    return (
        <div className={`flex items-center justify-between py-2.5 px-3 bg-black/30 border border-white/5 rounded-lg shadow-sm cursor-default transition-colors hover:bg-white/5`}>
            <div className="flex items-center gap-3 overflow-hidden">
                <div className="w-10 h-10 flex items-center justify-center overflow-visible shrink-0">
                    <div className={iconClass}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>
                <div className="overflow-hidden">
                    {/* Gain Header: Italicized per requirement */}
                    <div className="font-black text-[0.85rem] tracking-tight text-white uppercase italic leading-tight truncate">
                        {gainHeader}
                    </div>
                    {/* Source Line: Non-italic for better clarity */}
                    <div className="text-[0.55rem] font-bold uppercase tracking-[0.1em] mt-0.5 text-indigo-400 opacity-80 truncate">
                        {item.title}
                    </div>
                </div>
            </div>

            <div className="text-right flex flex-col items-end shrink-0 pl-2">
                 {/* Date and Time: Regular non-italic font weight */}
                 <div className="text-[0.65rem] font-bold text-white uppercase tracking-tighter leading-none mb-1">
                    {item.date}
                 </div>
                 <div className="text-[0.5rem] font-bold text-white/30 uppercase tracking-[0.2em] tabular-nums leading-none">
