// Atomic transaction lock to prevent concurrent modifications to the mock DB
let transactionTail: Promise<any> = Promise.resolve();

const COOLDOWN_DURATION_MS = 60000; // 1 minute as requested
const LOG_LIMIT = 500;

const formatDate = (now: Date) => {
