                        >
                            <span className="text-[0.45rem] font-black tracking-tighter">{f.label}</span>
                        </SlantedButton>
                    ))}
                </div>

                {/* RIGHT GROUP: ALL [SWORDS] [LADDER] */}
                <div className="flex gap-1">
                    {modeFilters.map((f) => (
