import React, { useState, useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { BattleLogItem } from '../history/BattleLogItem';
import { ModalFooter } from '../ui/ModalFooter';
import { SlantedButton } from '../ui/SlantedButton';

interface HistoryScreenProps {
    onExit: () => void;
}

type ResultFilter = 'ALL' | 'VICTORY' | 'DEFEAT' | 'DRAW';
type ModeFilter = 'ALL' | 'CONQUEST' | 'LADDER';

export const HistoryScreen: React.FC<HistoryScreenProps> = ({ onExit }) => {
    const [resFilter, setResFilter] = useState<ResultFilter>('ALL');
    const [modeFilter, setModeFilter] = useState<ModeFilter>('ALL');

    const logs = useMemo(() => [
        { res: 'VICTORY', opp: 'Xenon_GS', mode: 'CONQUEST', score: '2-1-0', date: '24 MAY 25', time: '14:20' },
        { res: 'DEFEAT', opp: 'Bot_Alpha', mode: 'LADDER', cubes: -4, date: '23 MAY 25', time: '18:45' },
        { res: 'VICTORY', opp: 'PlayerOne', mode: 'LADDER', cubes: 2, date: '23 MAY 25', time: '10:12' },
        { res: 'DRAW', opp: 'Guest_99', mode: 'CONQUEST', score: '1-1-2', date: '22 MAY 25', time: '22:30' },
        { res: 'VICTORY', opp: 'Starlord', mode: 'CONQUEST', score: '2-0-0', date: '21 MAY 25', time: '16:05' },
        { res: 'DEFEAT', opp: 'ThanosWasRight', mode: 'LADDER', cubes: -8, date: '20 MAY 25', time: '09:15' },
        { res: 'VICTORY', opp: 'NovaCommander', mode: 'LADDER', cubes: 4, date: '19 MAY 25', time: '13:40' },
        { res: 'DEFEAT', opp: 'Zabu_Fan', mode: 'CONQUEST', score: '0-2-1', date: '18 MAY 25', time: '21:55' },
    ], []);

    const filteredLogs = logs.filter(log => {
        const matchesRes = resFilter === 'ALL' || log.res === resFilter;
        const matchesMode = modeFilter === 'ALL' || log.mode === modeFilter;
        return matchesRes && matchesMode;
    });

    const resultFilters: { label: string; value: ResultFilter }[] = [
        { label: 'ALL', value: 'ALL' },
        { label: 'WIN', value: 'VICTORY' },
        { label: 'LOSS', value: 'DEFEAT' }, // Changed from LOS to LOSS
        { label: 'TIE', value: 'DRAW' },
    ];

    const modeFilters: { label: string; value: ModeFilter; icon?: React.ReactNode }[] = [
        { label: 'ALL', value: 'ALL' },
        { 
            label: 'CONQUEST', 
            value: 'CONQUEST',
            icon: (
                <svg className="w-3.5 h-3.5 drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M14 10l7-7m-7 7l-4 4-4-4 7-7z" />
                    <path strokeLinecap="round" strokeLinejoin="round" d="M10 14l-7 7m7-7l4-4 4 4-7 7z" />
                </svg>
            )
        },
        { 
            label: 'LADDER', 
            value: 'LADDER',
            icon: (
                <svg className="w-3.5 h-3.5 drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M8 3v18M16 3v18M8 7h8M8 12h8M8 17h8" />
                </svg>
            )
        },
    ];

    // Increased min-width from 1.8rem to 2.4rem to fit "LOSS" at larger font size
    const tightButtonClass = "[&_div.z-20]:!px-0 min-w-[2.4rem] !px-0 shadow-none border-white/10";

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden">
            <StandardHeader title="BATTLE HISTORY" />

            {/* FILTER ROW - Wide spacing between groups, tight spacing within groups */}
            <div className="flex items-center justify-between px-2 py-2 bg-slate-950/95 border-b border-white/5 backdrop-blur-md z-10 shadow-lg">

                {/* LEFT GROUP: ALL WIN LOSS TIE */}
                <div className="flex gap-1">
                    {resultFilters.map((f) => (
                        <SlantedButton 
                            key={f.value}
                            variant={resFilter === f.value ? 'primary' : 'black'}
                            size="xs"
                            onClick={() => setResFilter(f.value)}
                            className={`!h-6 ${tightButtonClass}`}
                        >
                            {/* Increased font size from 0.45rem to 0.6rem */}
                            <span className="text-[0.6rem] font-black tracking-tighter">{f.label}</span>
                        </SlantedButton>
                    ))}
                </div>

                {/* RIGHT GROUP: ALL [SWORDS] [LADDER] */}
                <div className="flex gap-1">
                    {modeFilters.map((f) => (
                        <SlantedButton 
                            key={f.value}
                            variant={modeFilter === f.value ? 'blue' : 'black'}
                            size="xs"
                            onClick={() => setModeFilter(f.value)}
                            className={`!h-6 ${tightButtonClass} ${f.icon ? 'min-w-[1.5rem]' : ''}`}
                        >
                            {f.icon ? (
                                <div className="flex items-center justify-center w-full h-full scale-[0.85]">
                                    {f.icon}
                                </div>
                            ) : (
                                <span className="text-[0.6rem] font-black tracking-tighter">{f.label}</span>
                            )}
                        </SlantedButton>
                    ))}
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-2.5 pb-24">
                <div className="px-1 mb-2">
                    <h2 className="text-[0.55rem] font-black text-indigo-400/50 uppercase tracking-[0.4em] italic">
                        ONLY THE LAST 200 GAMES SHOWN
                    </h2>
                </div>

                {filteredLogs.length > 0 ? (
                    filteredLogs.map((game, i) => (
                        <BattleLogItem 
                            key={i}
                            result={game.res as any}
                            opponent={game.opp}
                            mode={game.mode as any}
                            date={game.date}
                            time={game.time}
                            score={game.score}
                            cubes={game.cubes}
                        />
                    ))
                ) : (
                    <div className="text-center py-20 opacity-30">
                        <p className="text-[0.6rem] font-black text-slate-500 uppercase tracking-widest italic">No matching records found</p>
                    </div>
                )}

                <div className="text-center py-10">
                    <div className="inline-block h-1 w-12 bg-white/5 rounded-full mb-4"></div>
                    <p className="text-[0.55rem] text-slate-700 font-bold uppercase tracking-[0.4em]">End of Archive</p>
                </div>
            </div>

            <ModalFooter onClose={onExit} />
        </div>
    );
};

