interface HistoryScreenProps {
    onExit: () => void;
}

type ResultFilter = 'ALL' | 'VICTORY' | 'DEFEAT' | 'DRAW';
type ModeFilter = 'ALL' | 'CONQUEST' | 'LADDER';

export const HistoryScreen: React.FC<HistoryScreenProps> = ({ onExit }) => {
    const [resFilter, setResFilter] = useState<ResultFilter>('ALL');
    const [modeFilter, setModeFilter] = useState<ModeFilter>('ALL');

    const logs = useMemo(() => [
        { res: 'VICTORY', opp: 'Xenon_GS', mode: 'CONQUEST', score: '2-1-0', date: '24 MAY 25', time: '14:20' },
        { res: 'DEFEAT', opp: 'Bot_Alpha', mode: 'LADDER', cubes: -4, date: '23 MAY 25', time: '18:45' },
        { res: 'VICTORY', opp: 'PlayerOne', mode: 'LADDER', cubes: 2, date: '23 MAY 25', time: '10:12' },
        { res: 'DRAW', opp: 'Guest_99', mode: 'CONQUEST', score: '1-1-2', date: '22 MAY 25', time: '22:30' },
        { res: 'VICTORY', opp: 'Starlord', mode: 'CONQUEST', score: '2-0-0', date: '21 MAY 25', time: '16:05' },
        { res: 'DEFEAT', opp: 'ThanosWasRight', mode: 'LADDER', cubes: -8, date: '20 MAY 25', time: '09:15' },
        { res: 'VICTORY', opp: 'NovaCommander', mode: 'LADDER', cubes: 4, date: '19 MAY 25', time: '13:40' },
        { res: 'DEFEAT', opp: 'Zabu_Fan', mode: 'CONQUEST', score: '0-2-1', date: '18 MAY 25', time: '21:55' },
    ], []);

    const filteredLogs = logs.filter(log => {
        const matchesRes = resFilter === 'ALL' || log.res === resFilter;
        const matchesMode = modeFilter === 'ALL' || log.mode === modeFilter;
        return matchesRes && matchesMode;
    });

    const resultFilters: { label: string; value: ResultFilter }[] = [
        { label: 'ALL', value: 'ALL' },
        { label: 'WIN', value: 'VICTORY' },
        { label: 'LOSS', value: 'DEFEAT' },
        { label: 'TIE', value: 'DRAW' },
    ];

    const modeFilters: { label: string; value: ModeFilter; icon?: React.ReactNode }[] = [
        { label: 'ALL', value: 'ALL' },
        { 
            label: 'CONQUEST', 
            value: 'CONQUEST',
            icon: (
                <svg className="w-3.5 h-3.5 drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M14 10l7-7m-7 7l-4 4-4-4 7-7z" />
                    <path strokeLinecap="round" strokeLinejoin="round" d="M10 14l-7 7m7-7l4-4 4 4-7 7z" />
                </svg>
            )
        },
        { 
            label: 'LADDER', 
            value: 'LADDER',
            icon: (
                <svg className="w-3.5 h-3.5 drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M8 3v18M16 3v18M8 7h8M8 12h8M8 17h8" />
                </svg>
            )
        },
    ];

    // Reduced min-width from 2.4rem to 1.8rem to make buttons tighter
    const tightButtonClass = "[&_div.z-20]:!px-0 min-w-[1.8rem] !px-0 shadow-none border-white/10";

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden">
            <StandardHeader title="BATTLE HISTORY" />

            {/* 
                FILTER ROW: 
                Restored horizontal padding to px-4 for a more balanced layout.
            */}
            <div className="flex items-center justify-between px-4 py-2 bg-slate-950/95 border-b border-white/5 backdrop-blur-md z-10 shadow-lg">

                {/* LEFT GROUP: ALL WIN LOSS TIE */}
                <div className="flex gap-0.5">
                    {resultFilters.map((f) => (
                        <SlantedButton 
                            key={f.value}
                            variant={resFilter === f.value ? 'primary' : 'black'}
                            size="xs"
                            onClick={() => setResFilter(f.value)}
                            className={`!h-6 ${tightButtonClass}`}
                        >
                            <span className="text-[0.6rem] font-black tracking-tighter">{f.label}</span>
                        </SlantedButton>
                    ))}
                </div>

                {/* RIGHT GROUP: ALL [SWORDS] [LADDER] */}
                <div className="flex gap-0.5">
                    {modeFilters.map((f) => (
                        <SlantedButton 
                            key={f.value}
                            variant={modeFilter === f.value ? 'blue' : 'black'}
                            size="xs"
                            onClick={() => setModeFilter(f.value)}
                            className={`!h-6 ${tightButtonClass} ${f.icon ? 'min-w-[1.4rem]' : ''}`}
                        >
                            {f.icon ? (
                                <div className="flex items-center justify-center w-full h-full scale-[0.85]">
                                    {f.icon}
                                </div>
                            ) : (
                                <span className="text-[0.6rem] font-black tracking-tighter">{f.label}</span>
                            )}
                        </SlantedButton>
                    ))}
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-2.5 pb-24">
                <div className="px-1 mb-2">
                    <h2 className="text-[0.55rem] font-black text-indigo-400/50 uppercase tracking-[0.4em] italic">
                        ONLY THE LAST 200 GAMES SHOWN
                    </h2>
                </div>

                {filteredLogs.length > 0 ? (
                    filteredLogs.map((game, i) => (
                        <BattleLogItem 
                            key={i}
                            result={game.res as any}
                            opponent={game.opp}
                            mode={game.mode as any}
                            date={game.date}
                            time={game.time}
                            score={game.score}
                            cubes={game.cubes}
                        />
                    ))
                ) : (
                    <div className="text-center py-20 opacity-30">
                        <p className="text-[0.6rem] font-black text-slate-500 uppercase tracking-widest italic">No matching records found</p>
                    </div>
                )}

                <div className="text-center py-10">
                    <div className="inline-block h-1 w-12 bg-white/5 rounded-full mb-4"></div>
                    <p className="text-[0.55rem] text-slate-700 font-bold uppercase tracking-[0.4em]">End of Archive</p>
                </div>
            </div>

            <ModalFooter onClose={onExit} />
        </div>
    );
};

import React from 'react';
import { GameText } from '../ui/GameText';

interface BattleLogItemProps {
    result: 'VICTORY' | 'DEFEAT' | 'DRAW';
    opponent: string;
    mode: 'CONQUEST' | 'LADDER';
    date?: string;
    time?: string;
    score?: string; // e.g. "2-1-0" for Conquest
    cubes?: number; // e.g. +4 or -2 for Ladder
}

/**
 * Formats a 24h time string (HH:mm) into a 12h AM/PM format.
 */
const formatTimeAMPM = (timeStr: string) => {
    if (!timeStr) return '';
    try {
        const [hours, minutes] = timeStr.split(':').map(Number);
        const ampm = hours >= 12 ? 'PM' : 'AM';
        const h = hours % 12 || 12;
        return `${h}:${minutes.toString().padStart(2, '0')} ${ampm}`;
    } catch (e) {
        return timeStr;
    }
};

export const BattleLogItem: React.FC<BattleLogItemProps> = ({ 
    result, 
    opponent, 
    mode, 
    date = "24 MAY 25",
    time = "14:20",
    score, 
    cubes 
}) => {
    const isWin = result === 'VICTORY';
    const isLoss = result === 'DEFEAT';

    const shortResult = isWin ? 'WIN' : (isLoss ? 'LOSS' : 'TIE');
    const resultColor = isWin ? 'text-emerald-400' : (isLoss ? 'text-red-400' : 'text-slate-100');
    const isConquest = mode === 'CONQUEST';

    const cubeVal = cubes || 0;
    const cubeColor = cubeVal > 0 ? 'text-emerald-400' : (cubeVal < 0 ? 'text-red-400' : 'text-slate-500');
    const cubePrefix = cubeVal > 0 ? '+' : '';

    return (
        <div className="relative group cursor-pointer active:scale-[0.98] transition-all p-[1px] rounded-xl bg-gradient-to-r from-cyan-400/30 via-indigo-500/50 to-fuchsia-500/30 hover:from-cyan-400/60 hover:via-indigo-500 hover:to-fuchsia-500/60 shadow-2xl h-[3.2rem] overflow-hidden">
            {/* 
                INNER CONTAINER REFINEMENTS:
                1. Increased padding from px-1.5 to px-4 for a less "tight" feel.
                2. Changed bg-slate-950/95 (black) to bg-indigo-950/80 for a "colored" feel.
            */}
            <div className="flex items-center justify-between py-0 px-4 bg-indigo-950/80 backdrop-blur-sm rounded-[calc(0.75rem-1px)] h-full w-full gap-2">

                {/* LEFT SIDE: Identity & Outcome */}
                <div className="flex flex-col justify-center h-full min-w-0 flex-1">
                    <div className="flex items-center gap-1 h-5 overflow-hidden w-full">
                        <div className="shrink-0 flex items-center h-full">
                            <GameText 
                                text={shortResult} 
                                baseFontSize={0.7} 
                                className={`font-black italic tracking-tighter ${resultColor} !justify-start drop-shadow-md`}
                            />
                        </div>

                        <span className="text-[0.55rem] font-black text-indigo-400 uppercase tracking-tighter italic mx-0.5 shrink-0">VS</span>

                        {/* 
                            PLAYER NAME CONTAINER: 
                            Added pr-2 to ensure the italic slant (like in 'T') doesn't clip on the right edge.
                        */}
                        <div className="flex-1 min-w-0 h-full pr-2">
                            <GameText 
                                text={opponent} 
                                baseFontSize={1.05} 
                                maxScale={1.5}
                                className="text-white font-black uppercase italic !justify-start drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                            />
                        </div>
                    </div>

                    <div className="flex items-center gap-2 mt-[0.02rem] opacity-80">
                         <span className="text-[0.45rem] font-black text-indigo-100 uppercase tracking-widest font-sans">
                            {date}
                         </span>
                         <div className="w-0.5 h-0.5 rounded-full bg-indigo-300" />
                         <span className="text-[0.45rem] font-black text-indigo-100 uppercase tracking-widest font-sans tabular-nums">
                            {formatTimeAMPM(time)}
                         </span>
                    </div>
                </div>

                {/* RIGHT SIDE: Mode & Stats */}
                <div className="flex flex-col items-end justify-center shrink-0 h-[85%]">
                    <div className="text-[0.45rem] font-black text-indigo-200 uppercase tracking-[0.2em] leading-none mb-0.5 drop-shadow-sm">
                        {mode}
                    </div>

                    {isConquest ? (
                        <span className="text-[1.1rem] font-black text-white italic tracking-[0.1em] tabular-nums leading-tight drop-shadow-sm">
                            {score || '0-0-0'}
                        </span>
                    ) : (
                        <div className="flex items-center gap-0.5 leading-none">
                            <span className={`text-[1.3rem] font-black italic tabular-nums drop-shadow-sm ${cubeColor}`}>
                                {cubePrefix}{cubeVal}
                            </span>
                            <span className="text-[0.45rem] font-black text-slate-200 uppercase tracking-tighter mt-1 drop-shadow-md">CUBES</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

