    icon: React.ReactNode;
    active: boolean;
    onClick: () => void;
}

const NavItemComponent: React.FC<NavItemProps> = ({ label, icon, onClick, active }) => {
    /**
     * UI REFINEMENT: 
     * Inactive buttons now use transparency and a crisp subtle border to 
     * feel like "Glass" modules integrated into the footer.
