                    <path strokeLinecap="round" strokeLinejoin="round" d="M14 10l7-7m-7 7l-4 4-4-4 7-7z" />
                    <path strokeLinecap="round" strokeLinejoin="round" d="M10 14l-7 7m7-7l4-4 4 4-7 7z" />
                </svg>
