        },
        { 
            label: 'LADDER', 
            value: 'LADDER',
            icon: (
                <svg className="w-3.5 h-3.5 drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M8 3v18M16 3v18M8 7h8M8 12h8M8 17h8" />
                </svg>
            )
        },
    ];

    const tightButtonClass = "[&_div.z-20]:!px-0 min-w-[1.8rem] !px-0 shadow-none border-white/10";

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden">
            <StandardHeader title="BATTLE HISTORY" />

            {/* 
                FILTER ROW: 
                Now transparent to match ActivityLogSection. 
                Added pt-4 to give breathing room from the header rail.
            */}
            <div className="flex items-center justify-between px-5 pt-4 pb-2 z-10">

                {/* LEFT GROUP: ALL WIN LOSS TIE */}
                <div className="flex gap-0.5">
                    {resultFilters.map((f) => (
                        <SlantedButton 
                            key={f.value}
                            variant={resFilter === f.value ? 'primary' : 'black'}
                            size="xs"
                            onClick={() => setResFilter(f.value)}
                            className={`!h-6 ${tightButtonClass}`}
                        >
