                {filteredLogs.length > 0 ? (
                    filteredLogs.map((game, i) => (
                        <BattleLogItem 
                            key={i}
                            result={game.res as any}
                            opponent={game.opp}
                            mode={game.mode as any}
                            date={game.date}
                            time={game.time}
                            score={game.score}
                            cubes={game.cubes}
                        />
                    ))
                ) : (
                    <div className="text-center py-20 opacity-30">
                        <p className="text-[0.6rem] font-black text-slate-500 uppercase tracking-widest italic">No matching records found</p>
                    </div>
                )}

                <div className="text-center py-10">
                    <div className="inline-block h-1 w-12 bg-white/5 rounded-full mb-4"></div>
                    <p className="text-[0.55rem] text-slate-700 font-bold uppercase tracking-[0.4em]">End of Archive</p>
                </div>
            </div>

            <ModalFooter onClose={onExit} />
        </div>
    );
};

import React from 'react';
import { GameText } from '../ui/GameText';

interface BattleLogItemProps {
    result: 'VICTORY' | 'DEFEAT' | 'DRAW';
    opponent: string;
    mode: 'CONQUEST' | 'LADDER';
    date?: string;
    time?: string;
    score?: string; // e.g. "2-1-0" for Conquest
    cubes?: number; // e.g. +4 or -2 for Ladder
}

/**
 * Formats a 24h time string (HH:mm) into a 12h AM/PM format.
 */
const formatTimeAMPM = (timeStr: string) => {
    if (!timeStr) return '';
    try {
        const [hours, minutes] = timeStr.split(':').map(Number);
        const ampm = hours >= 12 ? 'PM' : 'AM';
        const h = hours % 12 || 12;
        return `${h}:${minutes.toString().padStart(2, '0')} ${ampm}`;
    } catch (e) {
        return timeStr;
    }
};

export const BattleLogItem: React.FC<BattleLogItemProps> = ({ 
    result, 
    opponent, 
    mode, 
    date = "24 MAY 25",
    time = "14:20",
    score, 
    cubes 
}) => {
    const isWin = result === 'VICTORY';
    const isLoss = result === 'DEFEAT';

    const shortResult = isWin ? 'WIN' : (isLoss ? 'LOSS' : 'TIE');
    const resultColor = isWin ? 'text-emerald-400' : (isLoss ? 'text-red-400' : 'text-slate-100');
    const isConquest = mode === 'CONQUEST';

    const cubeVal = cubes || 0;
