import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue' | 'black' | 'glass' | 'ghost';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'xs' | 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onHoldComplete?: (e: React.PointerEvent) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onHoldComplete,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);
    const hasTriggeredHold = useRef(false);

    const variants = {
        primary: "from-indigo-500 to-indigo-800 border-indigo-400 shadow-[0_0.2rem_0_rgb(30,58,138)] bg-gradient-to-b",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)] bg-gradient-to-b",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)] bg-gradient-to-b",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)] bg-gradient-to-b",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)] bg-gradient-to-b",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)] bg-gradient-to-b",
        black: "from-slate-900 to-black border-slate-800 shadow-[0_0.2rem_0_rgb(0,0,0)] bg-gradient-to-b",
        glass: "bg-slate-900/90 border-white/30 shadow-[0_2px_10px_rgba(0,0,0,0.5)] hover:bg-indigo-950/95 hover:border-white/50 transition-all",
        ghost: "bg-white/[0.04] border-white/20 shadow-none hover:bg-white/[0.08] hover:border-white/30 transition-all",
    };

    const sizeConfigs = {
        xs: { height: "h-[1.65rem]", fontSize: 1.2, padding: "px-1" },
        sm: { height: "h-8", fontSize: 1.35, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-3" },
        lg: { height: "h-16", fontSize: 1.45, padding: "px-4" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        hasTriggeredHold.current = false;
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                hasTriggeredHold.current = true;
                onHoldComplete?.(e);
                setIsHolding(false);
                onHoldChange?.(false);
                setProgress(0);
                onProgressChange?.(0);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const widthClass = fullWidth ? 'w-full' : 'w-max min-w-[3rem]';

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                {...props}
            >
                <div className={`absolute inset-0 border rounded skew-x-[-10deg] group-hover:brightness-110 transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear" style={{ width: `${progress}%` }} />
                    )}
                </div>

                <div className={`relative z-20 skew-x-[-10deg] ${config.padding} flex items-center justify-center h-full pointer-events-none`}>
                    <div className={`w-full h-full flex items-center justify-center gap-1.5 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center">
                                {icon}
                            </div>
                        )}

                        {children && (typeof children === 'string' || typeof children === 'number') ? (
                            <div className="flex-1 h-full min-w-0">
                                <GameText 
                                    text={children.toString()} 
                                    baseFontSize={config.fontSize} 
                                    skewFactor={0.88}
                                    className="text-white drop-shadow-md font-black italic uppercase tracking-tighter"
                                />
                            </div>
                        ) : (
                            <div className="flex items-center justify-center h-full w-full">
                                {children}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

