      if (progress < 30) return t('LOAD_DOWNLOADING');
      if (progress < 60) return t('LOAD_CALIBRATING');
      if (progress < 90) return t('LOAD_SYNCING_TYPO');
      return t('LOAD_FINALIZING');
  }, [progress]);

  return (
    <div 
        /* 
