import { seasonService } from './api/seasonService';
import { progressionService } from './api/progressionService';

export const api = {
    getProfile: (userId: string) => profileService.getProfile(userId),
    updateActiveDeck: (userId: string, deckId: number) => profileService.updateActiveDeck(userId, deckId),
    addCollectionLevels: (userId: string, increment: number) => profileService.addCollectionLevels(userId, increment),

    async submitTurn(gameState: GameState, playerMoves: PendingMove[]): Promise<{ opponentMoves: PendingMove[] }> {
        await new Promise(resolve => setTimeout(resolve, 600));
        return { opponentMoves: generateAiMoves(gameState) };
    },

    // Locale-aware Inbox (Simulating future CMS integration)
    async getInbox(userId: string, locale: string = 'en') {
        await new Promise(resolve => setTimeout(resolve, 400));
        // Fallback to English if locale not authored
        return (MOCK_INBOX_DATA as any)[locale] || MOCK_INBOX_DATA.en;
    },

    getStoreOffers: (userId: string) => storeService.getOffers(userId),
    purchaseOffer: (userId: string, offerId: string, txnId: string) => storeService.purchaseOffer(userId, offerId, txnId),

    getSeasonPass: (userId: string) => seasonService.getSeasonPass(userId),
    debugNextSeason: () => seasonService.debugNextSeason(),

    getProgression: (userId: string) => progressionService.getProgression(userId),
    getActivityLog: () => progressionService.getActivityLog(),
    claimProgressionReward: (userId: string, type: ProgressionRewardType) => progressionService.claimReward(userId, type),
    claimAllProgressionRewards: (userId: string, type: ProgressionRewardType) => progressionService.claimAllRewards(userId, type),
};

import React, { useState, useEffect } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { InboxItem } from '../inbox/InboxItem';
import { NewsCard } from '../menu/NewsCard';
import { SlantedButton } from '../ui/SlantedButton';
import { t } from '../../services/localization';
import { api } from '../../services/api';
import { useUser } from '../../contexts/UserContext';

export const InboxScreen: React.FC = () => {
    const { user } = useUser();
    const [activeTab, setActiveTab] = useState<'REWARDS' | 'BROADCASTS'>('REWARDS');
    const [messages, setMessages] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchInbox = async () => {
            setIsLoading(true);
            try {
                // Future-proof: Passing user locale to API
                const data = await api.getInbox(user.id, 'en'); 
                setMessages(data);
            } catch (err) {
                console.error("Inbox Sync Failed", err);
            } finally {
                setIsLoading(false);
            }
        };
        fetchInbox();
    }, [user.id]);

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden">
            <StandardHeader 
                title={`\u00A0\u00A0${t('NAV_INBOX')}`} 
                rightContent={
                    <div className="flex gap-1 items-center mr-1">
                        <SlantedButton 
                            variant={activeTab === 'REWARDS' ? 'primary' : 'secondary'} 
                            size="xs"
                            onClick={() => setActiveTab('REWARDS')}
                            className="!w-[14vw] max-w-[3.5rem] !h-[1.5rem]"
                        >
                            MAIL
                        </SlantedButton>
                        <SlantedButton 
                            variant={activeTab === 'BROADCASTS' ? 'primary' : 'secondary'} 
                            size="xs"
                            onClick={() => setActiveTab('BROADCASTS')}
                            className="!w-[14vw] max-w-[3.5rem] !h-[1.5rem]"
                        >
                            NEWS
                        </SlantedButton>
                    </div>
                }
            />

            <div className="flex-1 overflow-y-auto p-4 space-y-3 pb-24">
                {isLoading ? (
                    <div className="flex items-center justify-center py-20 opacity-20">
                         <div className="w-6 h-6 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                    </div>
                ) : activeTab === 'REWARDS' ? (
                    <div className="space-y-3 animate-pop">
                        {messages.map((msg) => (
                            <InboxItem 
                                key={msg.id}
                                type={msg.type}
                                title={msg.title} // Content is already localized by server
                                message={msg.body} // Content is already localized by server
                                isRead={msg.isRead}
                                rewardLabel={msg.ctaLabel}
                                onClaim={() => console.log('Claimed', msg.id)}
                            />
                        ))}

                        {messages.length === 0 && (
                            <div className="text-center py-20 opacity-30">
                                <p className="text-[0.6rem] font-black text-slate-500 uppercase tracking-widest italic">No Transmissions Found</p>
                            </div>
                        )}
                    </div>
                ) : (
                    <div className="space-y-4 animate-pop">
                        <div className="px-1 mb-2">
                            <h2 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.4em]">Sector Announcements</h2>
                        </div>
                        <NewsCard type="Patch Notes" title="Update 1.4.0: Spatial UI" subtitle="We've completely overhauled the navigation system for a faster, more immersive experience." imageColor="bg-indigo-700/50" />
                        <NewsCard type="Community" title="Top Decks of the Week" subtitle="See what the pros are using to climb the galactic ladder." imageColor="bg-slate-800/50" />
                        <NewsCard type="Event" title="Double Credit Weekend" subtitle="Earn double rewards for every Conquest match completed this Saturday and Sunday." imageColor="bg-amber-700/50" />
                    </div>
                )}
            </div>
        </div>
    );
};

import React from 'react';
import { SlantedButton } from '../ui/SlantedButton';

interface InboxItemProps {
    type: 'REWARD' | 'SYSTEM';
    title: string;
    message: string;
    isRead: boolean;
    rewardLabel?: string;
    onClaim?: () => void;
}

/**
 * INBOX ITEM
 * Renders server-authored content directly. 
 * This component is "dumb" regarding localization, as the server 
 * is the source of truth for long-form messaging.
 */
const InboxItemComponent: React.FC<InboxItemProps> = ({ type, title, message, isRead, rewardLabel, onClaim }) => {
    return (
        <div className={`p-4 border rounded-xl relative transition-all duration-300 ${type === 'REWARD' ? 'bg-indigo-950/40 border-indigo-500/30' : 'bg-slate-900/60 border-white/5 opacity-80'}`}>

            {/* Unread Indicator */}
            {!isRead && <div className="absolute top-4 right-4 w-2 h-2 bg-red-500 rounded-full shadow-[0_0_10px_rgba(239,68,68,0.8)] animate-pulse"></div>}

            {/* Tag */}
            <div className={`text-[0.55rem] font-black mb-1.5 uppercase tracking-[0.3em] ${type === 'REWARD' ? 'text-indigo-400' : 'text-slate-500'}`}>
                {type}
            </div>

            {/* Content */}
            <h3 className={`font-black italic tracking-tighter text-sm mb-1.5 uppercase leading-tight ${type === 'REWARD' ? 'text-white' : 'text-slate-300'}`}>
                {title}
            </h3>
            <p className={`text-[0.7rem] mb-4 leading-relaxed font-medium ${type === 'REWARD' ? 'text-indigo-100/70' : 'text-slate-500'}`}>
                {message}
            </p>

            {/* Action */}
            {type === 'REWARD' && rewardLabel && (
                <div className="w-full">
                    <SlantedButton variant="blue" fullWidth size="sm" onClick={onClaim}>
                        {rewardLabel}
                    </SlantedButton>
                </div>
            )}
        </div>
    );
};

