        ghost: "bg-white/[0.04] border-white/20 shadow-[0_0.15rem_0_rgba(255,255,255,0.05)] hover:bg-white/[0.08] hover:border-white/30 transition-all",
    };

    /**
     * RECALIBRATED SIZE CONFIGS
     * 'sm' reduced to h-7 for a sleeker profile in the store grid.
     */
    const sizeConfigs = {
        xs: { height: "h-[1.65rem]", fontSize: 0.8, padding: "px-1" },
        sm: { height: "h-7", fontSize: 0.95, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.1, padding: "px-3" },
        lg: { height: "h-16", fontSize: 1.4, padding: "px-4" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        hasTriggeredHold.current = false;
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100 && !hasTriggeredHold.current) {
                hasTriggeredHold.current = true;
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                if (onHoldComplete) {
                    onHoldComplete(e);
                } else if (onClick) {
                    const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                    onClick(sEvent);
                }

                setIsHolding(false);
                onHoldChange?.(false);
                setProgress(0);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    const handleButtonClick = (e: React.MouseEvent<HTMLButtonElement>) => {
        if (holdDuration > 0 && hasTriggeredHold.current) {
            return;
        }
        onClick?.(e);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const hasExplicitWidth = className.includes('w-') || className.includes('max-w-');
    const widthClass = fullWidth ? 'w-full' : (hasExplicitWidth ? '' : 'w-max');

    const containerJustify = (icon && children !== undefined) ? 'justify-start' : 'justify-center';
    const textJustify = 'justify-center';

    return (
        <div className={`relative group ${widthClass} ${config.height} min-w-0 ${props.disabled ? 'opacity-50 pointer-events-none' : ''} ${className}`}>
            <button 
                className={`w-full h-full relative z-10 outline-none`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={handleButtonClick}
                role="button"
                {...props}
            >
                {/* SLANTED BACKGROUND */}
                <div className={`absolute inset-0 border rounded skew-x-[-9deg] overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className={`absolute inset-y-0 left-0 bg-white/30 transition-all duration-75 ease-linear pointer-events-none`} style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* SLANTED CONTENT WRAPPER */}
                <div className={`relative z-20 h-full w-full pointer-events-none flex items-center ${containerJustify} skew-x-[-9deg] min-w-0 ${config.padding}`}>
                    <div className={`flex items-center ${containerJustify} gap-0 w-full h-full min-w-0 ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className={`shrink-0 flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] ${children !== undefined ? 'pr-0.5' : ''}`}>
                                {icon}
                            </div>
                        )}

                        {children !== undefined && (
                            <div className={`flex-1 h-full min-w-0 flex items-center ${textJustify}`}>
                                {typeof children === 'string' || typeof children === 'number' ? (
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        skewFactor={0.9} 
                                        maxScale={1.5}
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                    />
                                ) : (
                                    <div className={`flex items-center ${textJustify} drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] w-full h-full min-w-0`}>
                                        {children}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useEffect, useState, useMemo } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { useSynchronizedAction } from '../../hooks/useSynchronizedAction';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';
import { api } from '../../services/api';
import { t } from '../../services/localization';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    // Fix: Expanded costType to include 'tokens' and 'credits' to match possible price types and avoid invalid comparison errors
    costType: 'gold' | 'real' | 'free' | 'tokens' | 'credits';
    offerId?: string;
    availableAt?: string;
}

const SUCCESS_WINDOW = 800; 
const THEATRICAL_RESET_DELAY = 4000; 

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, storeData, performSynchronizedAction, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    // Fix: line 30 comparison was unintentional because 'tokens' wasn't in the union of costType. 
    // Expanding the interface and updating the logic resolves this.
    const isFree = costType === 'free';
    const hasFunds = isFree || costType === 'real' || 
                     (costType === 'gold' && user.gold >= (costAmount || 0)) || 
                     (costType === 'tokens' && user.tokens >= (costAmount || 0)) ||
                     (costType === 'credits' && user.credits >= (costAmount || 0));

    const effectiveAvailableAt = useMemo(() => {
        const userClaimedAt = offerId ? user.lastClaimedDates[offerId] : null;
        if (userClaimedAt) {
            const userTime = new Date(userClaimedAt).getTime();
            const manifestTime = availableAt ? new Date(availableAt).getTime() : 0;
            return userTime > manifestTime ? userClaimedAt : availableAt;
        }
        return availableAt;
    }, [availableAt, user.lastClaimedDates, offerId]);

    useEffect(() => {
        if (!effectiveAvailableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(effectiveAvailableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [effectiveAvailableAt]);

    const { status, holdProgress, isHolding, execute, bind } = useSynchronizedAction({
        holdDuration: isFree ? 0 : 800,
        resetDelay: THEATRICAL_RESET_DELAY,
        onAction: async () => {
            if (!hasFunds) {
                syncStore();
                return false;
            }
            if (!offerId) return false;

            return await performSynchronizedAction(
                () => api.purchaseOffer(user.id, offerId, `txn_${Math.random()}`),
                { visualDelay: SUCCESS_WINDOW }
            );
        }
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    const isPermanentlyClaimed = useMemo(() => {
        const offer = storeData?.offers.find(o => o.id === offerId);
        return offer?.isOneTime && user.purchasedOfferIds.includes(offerId || '');
    }, [user.purchasedOfferIds, offerId, storeData]);

    const showSuccess = isSuccess || isPermanentlyClaimed;

    const colors = type === 'gold' 
        ? { text: 'text-amber-500', bg: 'bg-amber-400/30' } 
        : (type === 'tokens' ? { text: 'text-red-500', bg: 'bg-red-400/30' } : { text: 'text-blue-400', bg: 'bg-blue-400/30' });

    return (
        <div 
            className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : (isLocked ? 'border-slate-800 grayscale-[0.3]' : 'border-slate-700')}`}
            {...(isFree || isLocked || isPermanentlyClaimed ? {} : bind)}
        >
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`} style={{ width: `${holdProgress}%` }} />
            )}

            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText text={amount.toLocaleString()} baseFontSize={1.1} className="text-white drop-shadow-md" />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>
                    {t(type === 'gold' ? 'STORE_GOLD' : (type === 'tokens' ? 'STORE_TOKENS' : 'STORE_CREDITS'))}
                </div>
            </div>

            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : (isLocked ? 'bg-slate-950 border-slate-800 opacity-40' : 'bg-slate-900 border-slate-700')}`}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-black">
                            {t('UI_HOLD_BUY')}
                         </span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-cyan">
                            {t('UI_SYNCING')}
                         </span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-emerald">
                            {t('UI_SYNCED')}
                         </span>
                    ) : isLocked ? (
                         <span className="text-[0.45rem] font-black text-slate-500 uppercase tracking-[0.3em] leading-none">Cooldown</span>
                    ) : null}
                </div>

                {isLocked && !showSuccess ? (
                    <div className="h-7 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        onClick={execute}
                        disabled={isProcessing || showSuccess || isLocked}
                    >
                        {isProcessing ? t('UI_SYNCING').toUpperCase() : (showSuccess ? t('UI_SYNCED').toUpperCase() : costLabel)}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import React, { useRef, useEffect } from 'react';
import { SeasonPassReward } from '../../types';
import { SeasonRewardButton } from '../ui/SeasonRewardButton';

interface SeasonRewardTrackProps {
    rewards: SeasonPassReward[];
    currentXPPercent: number;
    onInspect: (reward: any) => void;
    isActiveView: boolean;
}

export const SeasonRewardTrack: React.FC<SeasonRewardTrackProps> = ({ 
    rewards, 
    currentXPPercent, 
    onInspect,
    isActiveView
}) => {
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const activeLevelRef = useRef<HTMLDivElement>(null);

    // Self-contained scroll management
    useEffect(() => {
        if (isActiveView) {
            const timer = setTimeout(() => {
                if (activeLevelRef.current && scrollContainerRef.current) {
                    const container = scrollContainerRef.current;
                    const activeItem = activeLevelRef.current;
                    const targetScroll = activeItem.offsetTop - (container.offsetHeight / 2) + (activeItem.offsetHeight / 2);
                    container.scrollTo({ top: targetScroll, behavior: 'smooth' });
                }
            }, 600);
            return () => clearTimeout(timer);
        }
    }, [isActiveView]);

    return (
        <div 
            ref={scrollContainerRef}
            className="flex-1 overflow-y-auto pl-3 pr-2 py-4 space-y-3 scrollbar-hide pb-24"
        >
            {rewards.map((reward) => (
                <div 
                    key={reward.level} 
                    ref={reward.isActive ? activeLevelRef : null}
                    className="relative w-full overflow-visible"
                >
                    <SeasonRewardButton 
                        level={reward.level}
                        title={reward.type.toUpperCase()}
                        variant={reward.isActive ? 'primary' : 'blue'}
                        isClaimed={reward.isClaimed}
                        isActive={reward.isActive}
                        isLocked={reward.isLocked}
                        onClick={() => onInspect({
                            type: 'level_info',
                            level: reward.level,
                            rewardType: reward.type,
                            rewardAmount: reward.amount,
                            isClaimed: reward.isClaimed,
                            cardDef: reward.cardDef
                        })}
                    />
                </div>
            ))}
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

/** @deprecated Use SlantedButton instead */
export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 0.8, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.0, padding: "px-4" },
        lg: { height: "h-14", fontSize: 1.2, padding: "px-6" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const widthClass = fullWidth ? 'w-full' : 'w-max min-w-[3.5rem]';

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] group-hover:brightness-110 transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                <div className={`relative z-20 skew-x-[-10deg] ${config.padding} flex items-center justify-center h-full pointer-events-none`}>
                    <div className={`w-full h-full flex items-center justify-center gap-1.5 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center">
                                {icon}
                            </div>
                        )}

                        {typeof children === 'string' || typeof children === 'number' ? (
                            <div className="flex-1 h-full min-w-0">
                                <GameText 
                                    text={children.toString()} 
                                    baseFontSize={config.fontSize} 
                                    skewFactor={0.88}
                                    className="text-white drop-shadow-md font-black italic uppercase tracking-tighter"
                                />
                            </div>
                        ) : (
                            <div className="font-black text-white italic tracking-tight uppercase drop-shadow-md flex items-center gap-1 h-full w-full" style={{ fontSize: `${config.fontSize}rem` }}>
                                {children}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React from 'react';
import { HexBadge } from './HexBadge';
import { RewardItemVisual, SeasonRewardType } from './RewardItemVisual';
import { CardDefinition } from '../../types';

// Export type for convenience when using the button
export type { SeasonRewardType };

interface SeasonRewardButtonV2Props {
    level: number;
    progressPercent: number; // 0-100
    isClaimed: boolean;
    isActive: boolean;
    isLocked: boolean;
    rewardType: SeasonRewardType;
    rewardAmount?: string | number;
    rewardImageUrl?: string; // Optional: for mini card rendering
    cardDef?: CardDefinition; // Optional: full definition for level 50
    onClick: () => void;
    className?: string;
}

export const SeasonRewardButtonV2: React.FC<SeasonRewardButtonV2Props> = ({
    level,
    progressPercent,
    isClaimed,
    isActive,
    isLocked,
    rewardType,
    rewardAmount,
    rewardImageUrl,
    cardDef,
    onClick,
    className = ""
}) => {
    // Fill logic: Claimed rewards are 100% full, active is partial, locked is 0
    const barWidth = isClaimed ? 100 : (isActive ? progressPercent : 0);

    // Unified 'Claimed' filter for solid objects
    const claimedFilter = "grayscale-[0.7] brightness-[0.6]";

    return (
        <div 
            className={`
                h-10 w-full relative flex items-center cursor-pointer select-none overflow-visible 
                transition-all duration-300 ease-out
                ${isActive ? 'z-20 drop-shadow-[0_0_12px_rgba(165,180,252,0.6)] scale-[1.02]' : 'z-0'}
                ${className}
            `}
            onClick={onClick}
        >
            <div className="flex items-center w-full relative h-full">

                {/* 1. LEVEL BADGE (z-50) */}
                <div className="relative z-50 -mr-4 shrink-0">
                    <HexBadge 
                        variant="primary" 
                        size="sm" 
                        glow={isActive}
                        className={isClaimed ? claimedFilter : ''}
                    >
                        {level}
                    </HexBadge>
                </div>

                {/* 2. PROGRESS TRACK (z-10) */}
                <div className={`
                    flex-1 h-5 bg-indigo-950/60 border border-indigo-400/40 rounded-full overflow-hidden shadow-black/40 relative z-10 transition-all duration-300
                    ${isClaimed ? claimedFilter : ''}
                `}>

                    {/* XP BAR FILL */}
                    <div 
                        className={`h-full transition-all duration-700 bg-gradient-to-r from-indigo-700 via-indigo-400 to-purple-600`}
                        style={{ width: `${barWidth}%` }}
                    >
                        {isActive && <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />}
                    </div>

                    {/* Progress Percentage Overlay */}
                    <div className="absolute inset-0 flex items-center justify-end pr-4 pointer-events-none">
                        <span className="text-[0.5rem] font-black italic tabular-nums text-white/50 drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                            {isActive ? `${progressPercent}%` : (isClaimed ? '100%' : '')}
                        </span>
                    </div>
                </div>

                {/* 
                    3. REWARD VISUAL OVERLAY (z-30)
                */}
                <div className={`absolute inset-0 flex items-center justify-center z-30 pl-6 transition-all duration-300 ${isClaimed ? claimedFilter : ''}`}>
                    <RewardItemVisual 
                        type={rewardType} 
                        amount={rewardAmount} 
                        imageUrl={rewardImageUrl} 
                        level={level} 
                        cardDef={cardDef}
                    />
                </div>

                {/* 4. CLAIMED BANNER OVERLAY (z-40) */}
