                    </div>
                ) : filteredLogs.length > 0 ? (
                    filteredLogs.map((game, i) => (
                        <BattleLogItem 
                            key={i}
                            result={game.res as any}
                            opponent={game.opp}
                            mode={game.mode as any}
                            date={game.date}
                            time={game.time}
                            score={game.score}
                            cubes={game.cubes}
