import React from 'react';
import { ActivityLogEntry } from '../../types';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';

interface ActivityLogItemProps {
    item: ActivityLogEntry;
}

const formatTimeAMPM = (timeStr: string) => {
    if (!timeStr) return '';
    try {
        const [hours, minutes] = timeStr.split(':').map(Number);
        const ampm = hours >= 12 ? 'PM' : 'AM';
        const h = hours % 12 || 12;
        return `${h}:${minutes.toString().padStart(2, '0')} ${ampm}`;
    } catch (e) {
        return timeStr;
    }
};

export const ActivityLogItem: React.FC<ActivityLogItemProps> = React.memo(({ item }) => {
    const isSpend = item.isSpend ?? false;

    // GAINS ONLY RULE: Filter out spend entries from the UI
    if (isSpend) return null;

    // Icon scaling: Balanced for the 3.5rem height
    let iconScale = 'scale-[1.35]'; 
    if (item.type === 'card') iconScale = 'scale-[0.75]'; 

    // Construct the primary Gain Header (The "What")
    let gainHeader = '';
    if (item.type === 'card') {
        gainHeader = item.cardDef?.name || 'New Variant';
    } else if (item.type === 'box') {
        gainHeader = 'Omega Box';
    } else {
        const label = item.type.charAt(0).toUpperCase() + item.type.slice(1);
        const prefix = item.isBulk ? 'Bulk: ' : '';
        // Removed '+' prefix as gain is assumed
        gainHeader = `${prefix}${item.delta?.toLocaleString()} ${label}`;
    }

    return (
        /* 
           DENSE ROW: 
           Height: 3.5rem
           Padding: py-2 (0.5rem total)
           Left Padding: pl-2 (Reduced from pl-4 to fix the "too much space" look)
        */
        <div className="flex items-center w-full py-2 pl-2 pr-3 bg-black/40 border border-white/20 rounded-lg shadow-lg cursor-default transition-colors hover:bg-white/5 h-[3.5rem] overflow-hidden">

            {/* COLUMN 1: ICON (Fixed 15%, Center Aligned) 
                Reduced width from 18% to 15% to move it closer to the left edge.
            */}
            <div className="w-[15%] flex items-center justify-center shrink-0 overflow-visible">
                <div className={iconScale}>
                    <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                </div>
            </div>

            {/* COLUMN 2: TEXT CONTENT (Fixed 58%, Grouped and Centered) 
                Added pl-3 (increased from pl-1) to create a clear gap between the icon and label.
            */}
            <div className="w-[58%] flex flex-col justify-center h-full min-w-0 pr-2 pl-3">
                {/* TIGHT TOP CONTAINER: The "What" */}
                <div className="h-[1.1rem] w-full">
                    <GameText 
                        text={gainHeader} 
                        baseFontSize={1.0} 
                        italic={true}
                        className="text-white font-black italic tracking-tighter uppercase !justify-start"
                    />
                </div>

                {/* TIGHT BOTTOM CONTAINER: The "Source" */}
                <div className="h-[0.8rem] w-full opacity-60 mt-[0.05rem]">
                     <GameText 
                        text={item.title} 
                        baseFontSize={0.45} 
                        italic={false}
                        maxLines={2}
