/**
 * REDACTION ENGINE
 * Strips private server reconciliation data before it reaches the client.
 * Public spending data is hidden entirely (client doesn't see how much they spent).
 */
const sanitizeLog = (logs: ActivityLogEntry[]): ActivityLogEntry[] => {
    return logs.map(entry => {
        const { amountSpent, currencySpent, amountGained, itemGained, ...publicData } = entry;

        // PRIVACY RULE: If it's a spend entry, strip the delta so client doesn't see the cost in the log.
        if (entry.isSpend) {
            return { ...publicData, delta: undefined };
        }

        return publicData;
    });
};

const sanitizePurchaseResponse = (res: PurchaseResponse): PurchaseResponse => {
    if (res.activityLog) {
        return { ...res, activityLog: sanitizeLog(res.activityLog) };
    }
    return res;
};

