/**
 * Standard UUID Generator
 * Uses the native Web Crypto API to generate cryptographically strong 
 * 36-character RFC 4122 version 4 UUIDs.
 */
export const generateInstanceId = () => {
    try {
        return self.crypto.randomUUID();
    } catch (e) {
        // Fallback for non-secure contexts if necessary
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
            const r = (Math.random() * 16) | 0;
            const v = c === 'x' ? r : (r & 0x3) | 0x8;
            return v.toString(16);
        });
    }
};

