                {/* COLUMN 1: ICON */}
                <div className="w-[15%] flex items-center justify-center shrink-0 overflow-visible">
                    <div className={iconScale}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>

                {/* COLUMN 2: TEXT CONTENT */}
                <div className="w-[58%] flex flex-col justify-center h-full min-w-0 pr-2 pl-3">
                    <div className="h-[1.1rem] w-full">
                        <GameText 
                            text={gainHeader} 
                            baseFontSize={1.0} 
                            italic={true}
                            className="text-white font-black italic tracking-tighter uppercase !justify-start"
                        />
                    </div>
                    <div className="h-[0.8rem] w-full opacity-60 mt-[0.05rem]">
                         <GameText 
                            text={item.title} 
                            baseFontSize={0.45} 
                            italic={false}
                            maxLines={2}
                            className="text-indigo-300 font-bold uppercase tracking-[0.05em] !justify-start"
                        />
                    </div>
                </div>

                {/* COLUMN 3: DATE / TIME */}
                <div className="w-[27%] flex flex-col items-end justify-center shrink-0 h-full">
                     <div className="text-[0.6rem] font-bold text-white/90 uppercase tracking-tighter whitespace-nowrap leading-none mb-1 font-sans">
                        {item.date}
                     </div>
                     <div className="text-[0.4rem] font-black text-white/30 uppercase tracking-[0.1em] tabular-nums leading-none whitespace-nowrap">
                        {formatTimeAMPM(item.time)}
                     </div>
