            </div>

            {/* BACK FACE: TRANSACTION ID */}
            <div 
                className="absolute inset-0 backface-hidden rotate-y-180 flex flex-col justify-center px-4 bg-indigo-950 border border-indigo-400/40 rounded-lg shadow-2xl overflow-hidden"
                style={{ transform: 'rotateY(180deg)' }}
            >
                <div className="w-full flex items-center mb-0.5">
                    <span className="text-[0.5rem] font-black text-indigo-400 uppercase tracking-[0.25em]">Transaction ID</span>
                </div>
                <div className="w-full overflow-hidden flex items-center h-7">
