import React, { useState, useCallback, useEffect } from 'react';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { Portal } from '../ui/Portal';
import { DynamicBackground } from '../ui/DynamicBackground';
import { ModalFooter } from '../ui/ModalFooter';
import { ActivityLogSection } from './ActivityLogSection';
import { PremiumHeaderBase } from '../ui/PremiumHeaderBase';

export const ActivityLogOverlay: React.FC = () => {
    const { activityLog } = useUser();
    const { isActivityLogOpen, closeActivityLog } = useUI();
    const [flippedItemId, setFlippedItemId] = useState<string | null>(null);
    const [isExiting, setIsExiting] = useState(false);

    // Reset exit state when the modal is reopened via context
    useEffect(() => {
        if (isActivityLogOpen) {
            setIsExiting(false);
        }
    }, [isActivityLogOpen]);

    /**
     * ORCHESTRATED CLOSE
     * 1. Initiates reverse flip on any active row.
     * 2. Triggers CSS fade-out animation.
     * 3. Delays the hard unmount by 250ms as requested.
     */
    const handleClose = useCallback(() => {
        if (isExiting) return;

        // Start animations
        setIsExiting(true);
        setFlippedItemId(null);

        // Wait for animations to play out before clearing global state
        setTimeout(() => {
            closeActivityLog();
        }, 250); 
    }, [isExiting, closeActivityLog]);

    if (!isActivityLogOpen) return null;

    return (
        <Portal>
            <div 
                className={`fixed inset-0 z-[250] flex flex-col items-center justify-start bg-slate-950 overflow-hidden transition-opacity duration-300 ${isExiting ? 'opacity-0' : 'opacity-100'}`}
            >
                <DynamicBackground opacity={0.6} />

                <div className={`w-full h-full max-w-[23rem] flex flex-col relative z-10 overflow-hidden shadow-2xl border-x border-white/5 transition-transform duration-300 ${isExiting ? 'scale-95 brightness-50' : 'scale-100'}`}>

                    <PremiumHeaderBase className="pt-1 pb-2 px-1">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase italic font-sans leading-none">
                            {"\u00A0\u00A0"}Activity Log
                        </h1>
                    </PremiumHeaderBase>

                    <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                        <ActivityLogSection 
                            logs={activityLog} 
                            flippedItemId={flippedItemId}
                            onFlipItem={setFlippedItemId}
                        />
                    </div>

                    <ModalFooter onClose={handleClose} />
                </div>
            </div>
        </Portal>
    );
};

