import React, { useState, useCallback, useEffect, useRef } from 'react';
import { useUser } from '../../contexts/UserContext';
import { useUI } from '../../contexts/UIContext';
import { Portal } from '../ui/Portal';
import { DynamicBackground } from '../ui/DynamicBackground';
import { ModalFooter } from '../ui/ModalFooter';
import { ActivityLogSection } from './ActivityLogSection';
import { PremiumHeaderBase } from '../ui/PremiumHeaderBase';

export const ActivityLogOverlay: React.FC = () => {
    const { activityLog } = useUser();
    const { isActivityLogOpen, closeActivityLog } = useUI();

    // flippedItemId: The newly selected card (flips immediately)
    const [flippedItemId, setFlippedItemId] = useState<string | null>(null);
    // closingItemId: The previously selected card (stays open for 1s)
    const [closingItemId, setClosingItemId] = useState<string | null>(null);

    const [isExiting, setIsExiting] = useState(false);

    const closingTimeoutRef = useRef<number | null>(null);

    // Reset exit state when the modal is reopened via context
    useEffect(() => {
        if (isActivityLogOpen) {
            setIsExiting(false);
            setFlippedItemId(null);
            setClosingItemId(null);
        }
    }, [isActivityLogOpen]);

    // Cleanup timeouts on unmount
    useEffect(() => {
        return () => {
            if (closingTimeoutRef.current) {
                window.clearTimeout(closingTimeoutRef.current);
            }
        };
    }, []);

    /**
     * STAGGERED FLIP HANDLER
     * - nextId flips over IMMEDIATELY.
     * - currentId remains flipped for 1s.
     */
    const handleFlipItem = useCallback((nextId: string | null) => {
        const currentFlipped = flippedItemId;

        // Clear existing closing timers
        if (closingTimeoutRef.current) {
            window.clearTimeout(closingTimeoutRef.current);
            closingTimeoutRef.current = null;
        }

        // SCENARIO: Switching from Card A to Card B
        if (currentFlipped && nextId && currentFlipped !== nextId) {
            // 1. New card flips IMMEDIATELY
            setFlippedItemId(nextId);
            // 2. Old card becomes the 'closing' card (stays flipped)
            setClosingItemId(currentFlipped);

            // 3. Wait 1 second before un-flipping the old card
            closingTimeoutRef.current = window.setTimeout(() => {
                setClosingItemId(null);
                closingTimeoutRef.current = null;
            }, 1000);
        } 
        // SCENARIO: Toggling off or opening first time
        else {
            setFlippedItemId(nextId);
            setClosingItemId(null);
        }
    }, [flippedItemId]);

    /**
     * ORCHESTRATED CLOSE
     * 1. Hard reset flip states.
     * 2. Triggers CSS fade-out/scale-down animation.
     * 3. Delays the hard unmount by 1000ms (1 second).
     */
    const handleClose = useCallback(() => {
        if (isExiting) return;

        setIsExiting(true);
        // Force un-flip everything immediately on exit for clean transition
        setFlippedItemId(null); 
        setClosingItemId(null);

        setTimeout(() => {
            closeActivityLog();
        }, 1000); 
    }, [isExiting, closeActivityLog]);

    if (!isActivityLogOpen) return null;

    return (
        <Portal>
            <div 
                className={`fixed inset-0 z-[250] flex flex-col items-center justify-start bg-slate-950 overflow-hidden transition-all duration-700 ${isExiting ? 'opacity-0 scale-110 pointer-events-none' : 'opacity-100 scale-100'}`}
            >
                <DynamicBackground opacity={0.6} />

                <div className={`w-full h-full max-w-[23rem] flex flex-col relative z-10 overflow-hidden shadow-2xl border-x border-white/5 transition-transform duration-500 ${isExiting ? 'scale-90 brightness-50 blur-sm' : 'scale-100'}`}>

                    <PremiumHeaderBase className="pt-1 pb-2 px-1">
                        <h1 className="text-[1.2rem] font-black text-white tracking-tighter uppercase italic font-sans leading-none">
                            {"\u00A0\u00A0"}Activity Log
                        </h1>
                    </PremiumHeaderBase>

                    <div className="flex-1 flex flex-col min-h-0 relative z-10 overflow-hidden">
                        <ActivityLogSection 
                            logs={activityLog} 
                            flippedItemId={flippedItemId}
                            closingItemId={closingItemId}
                            onFlipItem={handleFlipItem}
                        />
                    </div>

                    <ModalFooter onClose={handleClose} />
                </div>
            </div>
        </Portal>
    );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { ActivityLogEntry, ProgressionRewardType } from '../../types';
import { SlantedButton } from '../ui/SlantedButton';
import { BoosterIcon, CreditIcon, GoldIcon, TokenIcon, OmegaBoxIcon, CardIcon } from '../ui/CurrencyIcons';
import { ActivityLogItem } from './ActivityLogItem';
import { t } from '../../services/localization';

type FilterType = 'all' | ProgressionRewardType;

interface ActivityLogSectionProps {
    logs: ActivityLogEntry[];
    flippedItemId: string | null;
    closingItemId?: string | null;
    onFlipItem: (id: string | null) => void;
}

export const ActivityLogSection: React.FC<ActivityLogSectionProps> = ({ 
    logs, 
    flippedItemId,
    closingItemId,
    onFlipItem 
}) => {
    const [activeFilter, setActiveFilter] = useState<FilterType>('all');
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    // AUTO-RESET: Unflip if filter changes
    useEffect(() => {
        onFlipItem(null);
    }, [activeFilter, onFlipItem]);

    // AUTO-RESET: Unflip if user scrolls
    const handleScroll = () => {
        if (flippedItemId) onFlipItem(null);
    };

    // BACKGROUND RESET: Unflip if user clicks empty area
    const handleBackgroundClick = (e: React.MouseEvent) => {
        if (e.target === e.currentTarget && (flippedItemId || closingItemId)) {
            onFlipItem(null);
        }
    };

    const filteredLogs = useMemo(() => {
        if (activeFilter === 'all') return logs;
        return logs.filter(log => log.type === activeFilter);
    }, [logs, activeFilter]);

    const filters: { id: FilterType; icon: React.ReactNode; variant: any }[] = [
        { 
            id: 'all', 
            icon: <div className="flex items-center justify-center h-full w-full"><span className="text-[0.7rem] font-black italic leading-none">{t('HIST_ALL').toUpperCase()}</span></div>, 
            variant: 'primary' 
        },
        { 
            id: 'card', 
            icon: <div className="flex items-center justify-center scale-75 h-full w-full"><CardIcon size="sm" /></div>, 
            variant: 'primary' 
        },
        { 
            id: 'booster', 
            icon: <div className="flex items-center justify-center scale-90 h-full w-full"><BoosterIcon size="sm" /></div>, 
            variant: 'success' 
        },
        { 
            id: 'credits', 
            icon: <div className="flex items-center justify-center scale-75 h-full w-full"><CreditIcon size="sm" /></div>, 
            variant: 'blue' 
        },
        { 
            id: 'gold', 
            icon: <div className="flex items-center justify-center scale-[0.85] h-full w-full"><GoldIcon size="sm" /></div>, 
            variant: 'warning' 
        },
        { 
            id: 'tokens', 
            icon: <div className="flex items-center justify-center scale-75 h-full w-full"><TokenIcon size="sm" /></div>, 
            variant: 'danger' 
        },
        { 
            id: 'box', 
            icon: <div className="flex items-center justify-center scale-90 h-full w-full"><OmegaBoxIcon size="sm" /></div>, 
            variant: 'primary' 
        },
    ];

    return (
        <div className="flex flex-col h-full overflow-hidden">
            <div className="shrink-0 pt-6">
                <div className="flex items-center gap-1 px-4 justify-center pb-3">
                    {filters.map((f) => (
                        <SlantedButton
                            key={f.id}
                            variant={activeFilter === f.id ? f.variant : 'ghost'}
                            size="xs"
                            className={`!w-[12vw] max-w-[2.8rem] shrink-0 !transition-none !h-[1.5rem]`}
                            onClick={() => setActiveFilter(f.id)}
                        >
                            {f.icon}
                        </SlantedButton>
                    ))}
                </div>

                <div className="mt-1 px-6 pb-3 text-center whitespace-nowrap overflow-hidden">
                    <span className="text-[0.5rem] font-black text-white uppercase tracking-[0.3em] italic leading-none inline-block">
                        {"\u00A0\u00A0"}{t('UI_SHOWING_LAST_LOGS')}{"\u00A0\u00A0"}
                    </span>
                </div>
            </div>

            <div 
                ref={scrollContainerRef}
                onScroll={handleScroll}
                onClick={handleBackgroundClick}
                className="flex-1 overflow-y-auto px-2 pb-24 custom-scrollbar scrolling-touch"
            >
                <div className="space-y-2 perspective-[1000px] pointer-events-none">
                    {filteredLogs.length > 0 ? (
                        filteredLogs.map((item) => (
                            <div key={item.id} className="pointer-events-auto">
                                <ActivityLogItem 
                                    item={item} 
                                    isFlipped={flippedItemId === item.id || closingItemId === item.id}
                                    onFlip={() => onFlipItem(flippedItemId === item.id ? null : item.id)}
                                />
                            </div>
                        ))
                    ) : (
                        <div className="h-32 flex flex-col items-center justify-center border-2 border-dashed border-white/5 rounded-xl bg-white/5">
                            <div className="opacity-10 mb-2">
                                 {filters.find(f => f.id === activeFilter)?.icon}
                            </div>
                            <span className="text-[0.55rem] font-black text-white/20 uppercase tracking-[0.4em]">{t('UI_LOG_EMPTY')}</span>
                        </div>
                    )}
                </div>
                <div className="h-10 w-full" />
            </div>
        </div>
    );
};

import React from 'react';
import { ActivityLogEntry } from '../../types';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';

interface ActivityLogItemProps {
    item: ActivityLogEntry;
    isFlipped?: boolean;
    onFlip?: () => void;
}

const formatTimeAMPM = (timeStr: string) => {
    if (!timeStr) return '';
    try {
        const [hours, minutes] = timeStr.split(':').map(Number);
        const ampm = hours >= 12 ? 'PM' : 'AM';
        const h = hours % 12 || 12;
        return `${h}:${minutes.toString().padStart(2, '0')} ${ampm}`;
    } catch (e) {
        return timeStr;
    }
};

export const ActivityLogItem: React.FC<ActivityLogItemProps> = React.memo(({ item, isFlipped, onFlip }) => {
    const isSpend = item.isSpend ?? false;

    // GAINS ONLY RULE: Filter out spend entries from the UI
    if (isSpend) return null;

    // Icon scaling: Balanced for the 3.5rem height
    let iconScale = 'scale-[1.35]'; 
    if (item.type === 'card') iconScale = 'scale-[0.75]'; 

    // Construct the primary Gain Header (The "What")
    let gainHeader = '';
    if (item.type === 'card') {
        gainHeader = item.cardDef?.name || 'New Variant';
    } else {
        const delta = item.delta || 1;
        const isBulk = item.isBulk ?? false;

        // RULE: We don't need '1' for single Omega Boxes. One is implied.
        if (item.type === 'box' && delta === 1 && !isBulk) {
            gainHeader = 'Omega Box';
        } else {
            const prefix = isBulk ? 'Bulk: ' : '';

            let label = '';
            if (item.type === 'booster') {
                // Boosters are always plural in this game
                label = 'Boosters';
            } else if (item.type === 'box') {
                label = delta > 1 ? 'Omega Boxes' : 'Omega Box';
            } else {
                // Credits, Gold, Tokens are collective/already plural
                label = item.type.charAt(0).toUpperCase() + item.type.slice(1);
            }

            // Removed '+' prefix as gain is assumed
            gainHeader = `${prefix}${delta.toLocaleString()} ${label}`;
        }
    }

    return (
        <div 
            className="w-full h-[3.5rem] relative preserve-3d transition-transform duration-300 cursor-pointer select-none"
            style={{ 
                transform: isFlipped ? 'rotateY(180deg)' : 'rotateY(0deg)',
                transformStyle: 'preserve-3d'
            }}
            onClick={onFlip}
        >
            {/* FRONT FACE: REWARD INFO */}
            <div className="absolute inset-0 backface-hidden flex items-center w-full py-2 pl-2 pr-3 bg-black/40 border border-white/20 rounded-lg shadow-lg hover:bg-white/5 transition-colors overflow-hidden">
                {/* COLUMN 1: ICON */}
                <div className="w-[15%] flex items-center justify-center shrink-0 overflow-visible">
                    <div className={iconScale}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>

                {/* COLUMN 2: TEXT CONTENT */}
                <div className="w-[58%] flex flex-col justify-center h-full min-w-0 pr-2 pl-3">
                    <div className="h-[1.1rem] w-full">
                        <GameText 
                            text={gainHeader} 
                            baseFontSize={0.95} 
                            italic={true}
                            className="text-white font-black italic tracking-tighter uppercase !justify-start"
                        />
                    </div>
                    <div className="h-[0.8rem] w-full opacity-60 mt-[0.1rem]">
                         <GameText 
                            text={item.title} 
                            baseFontSize={0.55} 
                            italic={false}
                            maxLines={1}
                            className="text-indigo-300 font-bold uppercase tracking-[0.05em] !justify-start"
                        />
                    </div>
                </div>

                {/* COLUMN 3: DATE / TIME */}
                <div className="w-[27%] flex flex-col items-end justify-center shrink-0 h-full">
                     <div className="text-[0.6rem] font-bold text-white/90 uppercase tracking-tighter whitespace-nowrap leading-none mb-1 font-sans">
                        {item.date}
                     </div>
                     <div className="text-[0.4rem] font-black text-white/30 uppercase tracking-[0.1em] tabular-nums leading-none whitespace-nowrap">
                        {formatTimeAMPM(item.time)}
                     </div>
                </div>
            </div>

            {/* BACK FACE: TRANSACTION ID */}
            <div 
                className="absolute inset-0 backface-hidden rotate-y-180 flex flex-col justify-center px-2 bg-indigo-950 border border-indigo-400/40 rounded-lg shadow-2xl overflow-hidden"
                style={{ transform: 'rotateY(180deg)' }}
            >
                <div className="w-full flex items-center mb-0.5">
                    <span className="text-[0.45rem] font-black text-indigo-400 uppercase tracking-[0.25em]">Transaction ID</span>
                </div>
                <div className="w-full h-6 flex items-center">
                    <GameText 
                        text={item.id} 
                        baseFontSize={0.7} 
                        letterSpacing="0.05em"
                        italic={false}
                        className="text-white font-bold select-all !justify-start"
