                    <span className="text-[0.45rem] font-black text-indigo-400 uppercase tracking-[0.25em] mb-1">Transaction ID</span>
                    <div className="h-6 flex items-center">
                        <GameText text={item.id} baseFontSize={0.65} italic={false} className="text-white font-bold select-all !justify-start" />
                    </div>
                    <div className="absolute inset-x-0 bottom-0 h-[1px] bg-indigo-500/20 shadow-[0_0_10px_rgba(99,102,241,0.5)]" />
                </div>
            </div>

            <style>{`.backface-hidden { backface-visibility: hidden; -webkit-backface-visibility: hidden; }`}</style>
        </div>
    );
});

import { ActivityLogEntry } from '../../types';

/**
 * SIMULATED NETWORK LATENCY
 * Standardizes fake API delays to make UI testing consistent.
 */
export const simulateNetwork = async (minMs = 200, maxMs = 600) => {
    const delay = Math.floor(Math.random() * (maxMs - minMs + 1) + minMs);
    await new Promise(resolve => setTimeout(resolve, delay));
};

/**
 * REDACTION ENGINE
 * Strips private server reconciliation data before it reaches the client.
 * Public spending data is hidden entirely (client doesn't see how much they spent in the log).
 */
export const sanitizeLog = (logs: ActivityLogEntry[]): ActivityLogEntry[] => {
    return logs.map(entry => {
        const { amountSpent, currencySpent, amountGained, itemGained, ...publicData } = entry;

        // PRIVACY RULE: If it's a spend entry, strip the delta so client doesn't see the cost in the log.
        if (entry.isSpend) {
            return { ...publicData, delta: undefined };
        }

        return publicData;
    });
};

