/**
 * SIMULATED NETWORK LATENCY
 */
export const simulateNetwork = async (minMs = 200, maxMs = 600) => {
    const delay = Math.floor(Math.random() * (maxMs - minMs + 1) + minMs);
    await new Promise(resolve => setTimeout(resolve, delay));
};

/**
 * SERVER-SIDE INPUT VALIDATION (Authoritative Guard)
 * Simulates AJV/Zod logic. Checks for malformed IDs or suspicious payloads
 * before the database logic is ever reached.
 */
export const validateRequest = (userId: string, payload?: any) => {
    if (!userId || userId.length < 2) {
        throw new ApiError('ERR_UNAUTHORIZED', 'Invalid or missing secure session token.');
    }

    // Simulate checking for "impossible" client data
    if (payload && payload.amount && payload.amount < 0) {
        throw new ApiError('ERR_ILLEGAL_OPERATION', 'Negative resource delta detected. Nice try.');
    }

    return true;
};

/**
 * WHITELIST SANITIZATION
 * Ensures sensitive server-only fields (like internal DB IDs or payment notes)
 * are physically removed before sending data back to the client.
 */
export const sanitizeLog = (logs: ServerActivityLogEntry[]): ActivityLogEntry[] => {
    return logs.map(entry => {
        const publicEntry: ActivityLogEntry = {
            id: entry.id,
            title: entry.title,
            type: entry.type,
            date: entry.date,
            time: entry.time,
            amount: entry.amount,
            isSpend: entry.isSpend,
            isBulk: entry.isBulk,
            currencyType: entry.currencyType,
            cardDef: entry.cardDef
        };

        if (!entry.isSpend) {
            publicEntry.delta = entry.delta;
        }

        return publicEntry;
    });
};

/**
 * ELITE API WRAPPER
 * Standardizes all API calls to return ApiResponse<T>.
 */
export const safeExecute = async <T>(
    action: () => Promise<T>,
    validator?: (data: T) => boolean
): Promise<ApiResponse<T>> => {
    try {
        const data = await action();

        // RUNTIME OUTPUT VALIDATION
        if (validator && !validator(data)) {
            throw new ApiError('ERR_MALFORMED_DATA', 'Server response failed data integrity check.');
        }

        return {
            success: true,
            data,
            error: null,
            timestamp: Date.now()
        };
    } catch (err: any) {
        console.error("[AUTHORITATIVE API ERROR]", err);

        const errorPayload: ApiErrorPayload = {
            code: err.code || 'ERR_SYSTEM_FAILURE',
            message: err.message || 'The Galactic Grid rejected your request.'
        };

        return {
            success: false,
            data: null,
            error: errorPayload,
            timestamp: Date.now()
        };
    }
};

export class ApiError extends Error {
    constructor(public code: string, message: string) {
        super(message);
        this.name = 'ApiError';
    }
}

import { UserProfile, StoreData, PurchaseResponse, StoreOffer, ActivityLogEntry } from '../../types';
import { MOCK_STORE_OFFERS } from './mockData';
import { ITEM_SOURCES } from '../../config/sources';
import { simulateNetwork, validateRequest, ApiError } from './apiUtils';
import { getPersistedProfile, persistUserProfile, progressionStore } from './mockDb';
import { generateInstanceId } from '../../utils/id';

// Atomic transaction lock to prevent race-condition exploits
let transactionTail: Promise<any> = Promise.resolve();

const COOLDOWN_DURATION_MS = 60000;
const LOG_LIMIT = 500;

const formatDate = (now: Date) => {
    const day = now.getDate();
    const month = now.toLocaleString('default', { month: 'short' }).toUpperCase();
    const year = now.getFullYear().toString().slice(-2);
    return `${day} ${month} ${year}`;
};

/**
 * AUTHORITATIVE STORE SERVICE
 * Logic here happens strictly "behind the curtain".
 */
export const storeService = {
    async getOffers(userId: string): Promise<StoreData> {
        validateRequest(userId);
        await simulateNetwork(300, 500); 
        const user = getPersistedProfile();

        const offersWithCooldowns = MOCK_STORE_OFFERS.map(offer => {
            const lastClaimed = user?.lastClaimedDates[offer.id];
            if (lastClaimed) {
                const availableAt = new Date(lastClaimed).getTime();
                const now = Date.now();
                if (availableAt > now) {
                    return { ...offer, availableAt: new Date(availableAt).toISOString() };
                }
            }
            return { ...offer };
        }).filter(offer => {
            if (offer.isOneTime && user?.purchasedOfferIds.includes(offer.id)) return false;
            return true;
        });

        return { offers: [...offersWithCooldowns], lastUpdated: Date.now(), refreshHintSeconds: 60 };
    },

    /**
     * AUTHORITATIVE PURCHASE
     * Note that price and amounts are NOT passed from the client.
     * We ONLY accept the offerId and verify everything internally.
     */
    async purchaseOffer(userId: string, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        const result = await (transactionTail = transactionTail.then(async () => {
            validateRequest(userId);
            await simulateNetwork(800, 1200);

            const user = getPersistedProfile();
            if (!user || user.id !== userId) {
                throw new ApiError('ERR_UNAUTHORIZED', 'Account ownership mismatch.');
            }

            // SERVER SOURCE OF TRUTH: Fetch the official price and contents
            const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
            if (!offer) {
                throw new ApiError('ERR_OFFER_NOT_FOUND', 'Target resource is no longer available.');
            }

            // AUTHORITATIVE COOLDOWN CHECK
            if (offer.priceType === 'free') {
                const nextAvailableAt = user.lastClaimedDates[offerId];
                if (nextAvailableAt && new Date(nextAvailableAt).getTime() > Date.now()) {
                    throw new ApiError('ERR_COOLDOWN_ACTIVE', 'Neural link charging. Please wait.');
                }
            }

            // AUTHORITATIVE BALANCE CHECK
            if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) {
                throw new ApiError('ERR_INSUFFICIENT_FUNDS', 'Insufficient Gold in local sector.');
            }
            if (offer.priceType === 'tokens' && user.tokens < (offer.priceAmount || 0)) {
                throw new ApiError('ERR_INSUFFICIENT_FUNDS', 'Insufficient Tokens in local sector.');
            }

            const updatedProfile: UserProfile = { ...user };
            const now = new Date();
            const dateStr = formatDate(now);
            const timeStr = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;

            const logSource = offer.priceType === 'free' ? ITEM_SOURCES.FREE_STORE_REWARD : ITEM_SOURCES.STORE_PURCHASE;

            // Apply price based on SERVER CONFIG
            if (offer.priceType === 'gold' || offer.priceType === 'tokens' || offer.priceType === 'credits') {
                const curType = offer.priceType as 'gold' | 'tokens' | 'credits';
                updatedProfile[curType] -= (offer.priceAmount || 0);

                const spendLog: ActivityLogEntry = {
                    id: generateInstanceId(),
                    title: logSource,
                    type: 'purchase',
                    date: dateStr,
                    time: timeStr,
                    delta: offer.priceAmount,
                    isSpend: true,
                    currencyType: curType,
                    amountSpent: offer.priceAmount,
                    currencySpent: curType
                };
                progressionStore.activityLog = [spendLog, ...progressionStore.activityLog].slice(0, LOG_LIMIT);
            }

            if (offer.priceType === 'free') {
                updatedProfile.lastClaimedDates = {
                    ...updatedProfile.lastClaimedDates,
                    [offerId]: new Date(Date.now() + COOLDOWN_DURATION_MS).toISOString()
                };
            }

            // Grant rewards based on SERVER CONFIG
            offer.contents.forEach(item => {
                if (item.type === 'currency') {
                    if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                    if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
                    if (item.currencyType === 'tokens') updatedProfile.tokens += item.amount;

                    const gainLog: ActivityLogEntry = {
                        id: generateInstanceId(),
                        title: logSource,
                        type: item.currencyType as any,
                        date: dateStr,
                        time: timeStr,
                        delta: item.amount,
                        isSpend: false,
                        currencyType: item.currencyType,
                        amountGained: item.amount,
                        itemGained: item.currencyType
                    };
                    progressionStore.activityLog = [gainLog, ...progressionStore.activityLog].slice(0, LOG_LIMIT);
                } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                    updatedProfile.collection = [...updatedProfile.collection, item.definitionId];

                    const cardLog: ActivityLogEntry = {
                        id: generateInstanceId(),
                        title: logSource,
                        type: 'card',
                        date: dateStr,
                        time: timeStr,
                        isSpend: false,
                        cardDef: item as any,
                        amountGained: 1,
                        itemGained: item.definitionId
                    };
                    progressionStore.activityLog = [cardLog, ...progressionStore.activityLog].slice(0, LOG_LIMIT);
                }
            });

            if (offer.isOneTime) {
                updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
            }

            persistUserProfile(updatedProfile);

            return { 
                success: true, 
                transactionId, 
                updatedProfile,
                activityLog: [...progressionStore.activityLog] 
            };
        }));

        return result;
    }
};

import { UserProfile, ProgressionData, ActivityLogEntry, ProgressionRewardType } from '../../types';
import { REWARD_SEQUENCE } from './mockData';
import { ITEM_SOURCES } from '../../config/sources';
import { progressionStore, getPersistedProfile, persistUserProfile } from './mockDb';
import { getProgressionDataInternal } from './progressionLogic';
import { generateInstanceId } from '../../utils/id';
import { simulateNetwork, validateRequest, ApiError } from './apiUtils';

// Atomic lock for progression updates
let progressionTail: Promise<any> = Promise.resolve();

const LOG_LIMIT = 500;

const formatDate = (now: Date) => {
    const day = now.getDate();
    const month = now.toLocaleString('default', { month: 'short' }).toUpperCase();
    const year = now.getFullYear().toString().slice(-2);
    return `${day} ${month} ${year}`;
};

/**
 * AUTHORITATIVE PROGRESSION SERVICE
 */
export const progressionService = {
    async getProgression(userId: string): Promise<ProgressionData> {
        validateRequest(userId);
        await simulateNetwork(200, 400);
        const user = getPersistedProfile();
        return getProgressionDataInternal(user);
    },

    async getActivityLog(): Promise<ActivityLogEntry[]> {
        await simulateNetwork(100, 200);
        return progressionStore.activityLog;
    },

    /**
     * AUTHORITATIVE CLAIM
     * The client just sends the "type". The server calculates if it's 
     * actually earned and how much it's worth.
     */
    async claimReward(userId: string, type: ProgressionRewardType) {
        return progressionTail = progressionTail.then(async () => {
            validateRequest(userId);
            await simulateNetwork(400, 600);

            const user = getPersistedProfile();
            if (!user || user.id !== userId) throw new ApiError('ERR_UNAUTHORIZED', 'Access denied.');

            // SERVER RE-CALCULATES REAL STATE
            const currentData = getProgressionDataInternal(user);
            const trackIdx = currentData.tracks.findIndex(t => t.type === type && t.unclaimedCount > 0);

            if (trackIdx === -1) {
                throw new ApiError('ERR_ILLEGAL_CLAIM', 'Reward not yet available in your neural sector.');
            }

            // GET REAL AMOUNT FROM SERVER CONFIG
            const rewardConfig = REWARD_SEQUENCE[trackIdx];
            const updatedProfile = { ...user };

            const newClaimed = [...progressionStore.claimedCounts];
            newClaimed[trackIdx]++;
            progressionStore.claimedCounts = newClaimed;

            const amountToGrant = Number(rewardConfig.amount);

            if (type === 'credits') updatedProfile.credits += amountToGrant;
            else if (type === 'gold') updatedProfile.gold += amountToGrant;
            else if (type === 'tokens') updatedProfile.tokens += amountToGrant;

            const now = new Date();
            const dateStr = formatDate(now);
            const timeStr = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;

            const newLog: ActivityLogEntry = {
                id: generateInstanceId(),
                title: ITEM_SOURCES.COLLECTION_LEVEL_REWARD,
                type,
                date: dateStr,
                time: timeStr,
                delta: amountToGrant,
                isSpend: false,
                amountGained: amountToGrant,
                itemGained: type
            };

            progressionStore.activityLog = [newLog, ...progressionStore.activityLog].slice(0, LOG_LIMIT);
            persistUserProfile(updatedProfile);

            return { 
                success: true, 
                updatedProfile, 
                progressionData: getProgressionDataInternal(updatedProfile),
                activityLog: [...progressionStore.activityLog]
            };
        });
    },

    async claimAllRewards(userId: string, type: ProgressionRewardType) {
        return progressionTail = progressionTail.then(async () => {
            validateRequest(userId);
            await simulateNetwork(600, 900);

            const user = getPersistedProfile();
            if (!user || user.id !== userId) throw new ApiError('ERR_UNAUTHORIZED', 'Access denied.');

            const currentData = getProgressionDataInternal(user);
            const trackIdx = currentData.tracks.findIndex(t => t.type === type);

            if (trackIdx === -1 || currentData.tracks[trackIdx].unclaimedCount <= 0) {
                throw new ApiError('ERR_ILLEGAL_CLAIM', 'Nothing to claim in this sector.');
            }

            const count = currentData.tracks[trackIdx].unclaimedCount;
            const rewardConfig = REWARD_SEQUENCE[trackIdx];
            const updatedProfile = { ...user };

            const newClaimed = [...progressionStore.claimedCounts];
            newClaimed[trackIdx] += count;
            progressionStore.claimedCounts = newClaimed;

            const totalAmount = (rewardConfig.amount as number) * count;
            if (type === 'credits') updatedProfile.credits += totalAmount;
            else if (type === 'gold') updatedProfile.gold += totalAmount;
            else if (type === 'tokens') updatedProfile.tokens += totalAmount;

            const now = new Date();
            const dateStr = formatDate(now);
            const timeStr = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;

            const newLog: ActivityLogEntry = {
                id: generateInstanceId(),
                title: ITEM_SOURCES.COLLECTION_LEVEL_REWARD,
                type,
                date: dateStr,
                time: timeStr,
                delta: totalAmount,
                isSpend: false,
                isBulk: true,
                amountGained: totalAmount,
                itemGained: type
            };

            progressionStore.activityLog = [newLog, ...progressionStore.activityLog].slice(0, LOG_LIMIT);
            persistUserProfile(updatedProfile);

            return { 
                success: true, 
                updatedProfile, 
                progressionData: getProgressionDataInternal(updatedProfile),
                activityLog: [...progressionStore.activityLog]
            };
        });
    }
};

import { ActivityLogEntry, ServerActivityLogEntry, ApiResponse, ApiErrorPayload } from '../../types';

/**
 * SIMULATED NETWORK LATENCY
 */
export const simulateNetwork = async (minMs = 200, maxMs = 600) => {
    const delay = Math.floor(Math.random() * (maxMs - minMs + 1) + minMs);
    await new Promise(resolve => setTimeout(resolve, delay));
};

/**
 * SESSION VALIDATION (Authoritative)
 * In a production app, this would verify a JWT or Session Cookie.
 * Here, it prevents cross-user access and malformed IDs.
 */
export const verifySession = (userId: string) => {
    if (!userId || userId.length < 2) {
        throw new ApiError('ERR_UNAUTHORIZED', 'Secure session link severed. Please re-authenticate.');
    }
    // Simulate server-side user lookup
    return userId; 
};

/**
 * WHITELIST SANITIZATION
 */
export const sanitizeLog = (logs: ServerActivityLogEntry[]): ActivityLogEntry[] => {
    return logs.map(entry => {
        const publicEntry: ActivityLogEntry = {
            id: entry.id,
            title: entry.title,
            type: entry.type,
            date: entry.date,
            time: entry.time,
            amount: entry.amount,
            isSpend: entry.isSpend,
            isBulk: entry.isBulk,
            currencyType: entry.currencyType,
            cardDef: entry.cardDef
        };

        if (!entry.isSpend) {
            publicEntry.delta = entry.delta;
        }

        return publicEntry;
    });
};

/**
 * HARDENED API WRAPPER
 * Standardizes all API calls to return ApiResponse<T>.
 * Acts as the global error catch-all and request logger.
 */
export const safeExecute = async <T>(
    action: () => Promise<T>,
    validator?: (data: T) => boolean
): Promise<ApiResponse<T>> => {
    try {
        const data = await action();

        // RUNTIME INTEGRITY CHECK
        if (validator && !validator(data)) {
            throw new ApiError('ERR_DATA_INTEGRITY', 'Server-side data integrity check failed.');
        }

        return {
            success: true,
            data,
            error: null,
            timestamp: Date.now()
        };
    } catch (err: any) {
        // Log to "Server" console (simulated)
        console.error(`[SECURITY LOG] Request Failed. Code: ${err.code || 'UNKNOWN'}. Msg: ${err.message}`);

        const errorPayload: ApiErrorPayload = {
            code: err.code || 'ERR_SYSTEM_FAILURE',
            message: err.message || 'A transmission error occurred in the Galactic Grid.'
        };

        return {
            success: false,
            data: null,
            error: errorPayload,
            timestamp: Date.now()
        };
    }
};

