import { GameState, CardInstance } from '../types';
import { findCardInState } from './selectors';

export type PendingMove = { cardInstanceId: string, laneIdx: number };

/**
 * Calculates the remaining energy for P1 based on current game state and pending moves.
 */
export const calculateRemainingEnergy = (gameState: GameState | null, pendingMoves: PendingMove[]): number => {
    if (!gameState || !gameState.players) return 0;

    const usedEnergy = pendingMoves.reduce((sum, m) => {
        const lookup = findCardInState(gameState, m.cardInstanceId);
        return sum + (lookup ? lookup.card.totalCost : 0);
    }, 0);
    return Math.max(0, gameState.players.p1.energy - usedEnergy);
};

/**
 * Determines if a card interaction (drag start) is valid.
 */
export const canInteractWithCard = (
    gameState: GameState | null, 
    pendingMoves: PendingMove[], 
    card: CardInstance, 
    origin: { type: 'hand' | 'lane', laneIdx?: number }
): boolean => {
    if (!gameState) return false;

    // 1. Phase Check
    if (gameState.phase !== 'planning') return false;

    // 2. LIFO Check (Must be the top of the stack if on board)
    if (origin.type === 'lane') {
        const lastMove = pendingMoves[pendingMoves.length - 1];
        if (!lastMove || lastMove.cardInstanceId !== card.instanceId) return false;
    }

    // 3. Energy Check (If playing from hand)
    if (origin.type === 'hand') {
        const currentEnergy = calculateRemainingEnergy(gameState, pendingMoves);
        if (card.totalCost > currentEnergy) return false;
    }

    return true;
};

/**
 * Determines if a card can be dropped into a specific lane.
 * Authoritative check for both Drag-and-Drop and Tap-to-Play.
 */
export const canPlayCardToLane = (
    gameState: GameState | null,
    pendingMoves: PendingMove[],
    cardInstanceId: string,
    targetLaneIdx: number,
    origin: { type: 'hand' | 'lane', laneIdx?: number }
): boolean => {
    if (!gameState) return false;

    // 1. Energy Check (Only if moving from hand)
    if (origin.type === 'hand') {
        const lookup = findCardInState(gameState, cardInstanceId);
        if (!lookup) return false;

        const remainingEnergy = calculateRemainingEnergy(gameState, pendingMoves);
        // Strict energy check
        if (lookup.card.totalCost > remainingEnergy) return false;
    }

    // 2. Validation: Cannot move a pending card directly from one lane to another (simplification for UI)
    if (origin.type === 'lane' && origin.laneIdx !== targetLaneIdx) return false;

    // 3. Capacity Check
    const lane = gameState.lanes[targetLaneIdx];
    const usedSlots = lane.p1Slots.filter(s => s !== null).length;
    const pendingHere = pendingMoves.filter(m => m.laneIdx === targetLaneIdx).length;

    let effectivePendingHere = pendingHere;
    if (origin.type === 'lane' && origin.laneIdx === targetLaneIdx) {
        effectivePendingHere -= 1; // Don't delete the card we are currently holding
    }

    // Max 4 slots per lane
    if (usedSlots + effectivePendingHere >= 4) return false;

    return true;
};

import { useState } from 'react';
import { PendingMove, calculateRemainingEnergy, canPlayCardToLane, canInteractWithCard } from '../services/planning';
import { GameState, CardDefinition, CardInstance, LocationDefinition } from '../types';

export const useInputHandler = (gameState: GameState | null) => {
    const [pendingMoves, setPendingMoves] = useState<PendingMove[]>([]);
    const [selectedCardIdx, setSelectedCardIdx] = useState<number | null>(null);
    const [showUndoMenu, setShowUndoMenu] = useState(false);
    const [isResultsHidden, setIsResultsHidden] = useState(false);
    const [inspectingCard, setInspectingCard] = useState<CardDefinition | CardInstance | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);

    const resetInput = () => {
        setPendingMoves([]);
        setSelectedCardIdx(null);
        setInspectingCard(null);
        setInspectingLocation(null);
        setShowUndoMenu(false);
        setIsResultsHidden(false);
    };

    const handleCardClick = (idx: number, isDragging: boolean) => {
        if (isDragging || !gameState || !gameState.players) return;

        const card = gameState.players.p1.hand[idx];
        if (!card) return;

        // Toggle logic: If clicking the same card, deselect
        if (selectedCardIdx === idx) {
            setSelectedCardIdx(null);
            return;
        }

        // Only allow selection if affordable with *remaining* energy
        if (canInteractWithCard(gameState, pendingMoves, card, { type: 'hand' })) {
            setSelectedCardIdx(idx);
        } else {
            setSelectedCardIdx(null);
        }

        // Show inspector
        setInspectingCard(card);
    };

    const handleLaneClick = (laneIdx: number) => {
        if (selectedCardIdx === null || !gameState || !gameState.players) return false;

        const card = gameState.players.p1.hand[selectedCardIdx];
        if (!card) return false;

        // Authoritative play check
        if (canPlayCardToLane(gameState, pendingMoves, card.instanceId, laneIdx, { type: 'hand' })) {
            setPendingMoves(prev => [...prev, { cardInstanceId: card.instanceId, laneIdx }]);
            // Deselect after play to allow selecting next card
            setSelectedCardIdx(null); 
            setInspectingCard(null); 
            return true;
        }

        return false;
    };

    const handleUndoAll = () => {
        setPendingMoves([]);
        setShowUndoMenu(false);
        setSelectedCardIdx(null);
    };

    const currentEnergy = gameState ? calculateRemainingEnergy(gameState, pendingMoves) : 0;

    return {
        pendingMoves,
        setPendingMoves,
        selectedCardIdx,
        setSelectedCardIdx,
        showUndoMenu,
        setShowUndoMenu,
        isResultsHidden,
        setIsResultsHidden,
        inspectingCard,
        setInspectingCard,
        inspectingLocation,
        setInspectingLocation,
        currentEnergy,
        handleCardClick,
        handleLaneClick,
        handleUndoAll,
        resetInput
    };
};

import React, { useCallback } from 'react';
import { useGameLogic } from './useGameLogic';
import { useDragAndDrop } from './useDragAndDrop';
import { useEventSystem } from './useEventSystem';
import { CardDefinition, CardInstance, LocationDefinition } from '../types';
import { useUser } from '../contexts/UserContext';
// Added useUI import for inspector actions
import { useUI } from '../contexts/UIContext';

export const useGameController = (onExit?: () => void) => {
    const logic = useGameLogic();
    // Fixed: Get inspector methods from useUI instead of useUser
    const { inspect, closeInspector } = useUI();
    const eventSystem = useEventSystem(logic.events);

    const dnd = useDragAndDrop({
        gameState: logic.gameState!,
        pendingMoves: logic.pendingMoves,
        isResolving: logic.isResolving,
        setPendingMoves: logic.setPendingMoves,
        setInspectingCard: logic.setInspectingCard,
        setInspectingLocation: logic.setInspectingLocation,
        setSelectedCardIdx: logic.setSelectedCardIdx,
        setShowUndoMenu: logic.setShowUndoMenu,
        onDrop: (success) => {
            if (success) eventSystem.playSnap();
        }
    });

    const handleCardClick = useCallback((idx: number, isDragging: boolean) => {
        if (isDragging || !logic.gameState || !logic.gameState.players) return;

        const card = logic.gameState.players.p1.hand[idx];
        if (card) {
            eventSystem.playClick();
            // Trigger logic selection (handles energy/playability checks)
            // Note: handleCardClick in logic might still block selection if resolving
            logic.handleCardClick(idx, isDragging);
            // Always show inspection on explicit click regardless of phase
            inspect(card);
        }
    }, [eventSystem, logic, inspect]);

    const wrappedCloseInspector = useCallback(() => {
        eventSystem.playClick();
        closeInspector();
        logic.setInspectingCard(null);
        logic.setInspectingLocation(null);
    }, [eventSystem, closeInspector, logic]);

    const wrappedInspectCard = useCallback((c: CardInstance | CardDefinition) => {
        eventSystem.playClick();
        inspect(c);
        logic.setInspectingCard(c);
    }, [eventSystem, inspect, logic]);

    const wrappedInspectLocation = useCallback((l: LocationDefinition) => {
        eventSystem.playClick();
        inspect(l);
        logic.setInspectingLocation(l);
    }, [eventSystem, inspect, logic]);

    const handleUndoAll = useCallback(() => {
        eventSystem.playClick();
        logic.handleUndoAll();
    }, [eventSystem, logic]);

    const handleEndTurn = useCallback(() => {
        eventSystem.playClick();
        logic.handleEndTurn();
    }, [eventSystem, logic]);

    const handleResign = useCallback(() => {
        eventSystem.playClick();
        logic.handleResign();
    }, [eventSystem, logic]);

    const restartGame = useCallback(() => {
        eventSystem.playClick();
        logic.restartGame();
    }, [eventSystem, logic]);

    const toggleResults = useCallback((val: boolean) => {
        eventSystem.playClick();
        logic.setIsResultsHidden(val);
    }, [eventSystem, logic]);

    const handleLocationClick = useCallback((laneIdx: number) => {
        if (logic.selectedCardIdx !== null) eventSystem.playSnap();
        logic.handleLocationClick(laneIdx);
    }, [eventSystem, logic]);

    return {
        ...logic,
        dragState: dnd.dragState,
        activeVfx: eventSystem.activeVfx,
        actions: {
            handleCardClick,
            handleUndoAll,
            handleEndTurn,
            handleResign,
            restartGame,
            handleExit: () => { eventSystem.playClick(); onExit?.(); },
            toggleResults,
            closeInspector: wrappedCloseInspector,
            inspectCard: wrappedInspectCard,
            inspectLocation: wrappedInspectLocation,
            handleLocationClick,
            handleCardPointerDownHand: (e: React.PointerEvent, card: CardInstance, index: number) => 
                dnd.handleCardPointerDown(e, card, { type: 'hand', index }),
            handleCardPointerDownLane: (e: React.PointerEvent, card: CardInstance, laneIdx: number) => 
                dnd.handleCardPointerDown(e, card, { type: 'lane', laneIdx })
        }
    };
};

