import { simulateNetwork, verifySession, ApiError, lockedMutation } from './apiUtils';
import { getPersistedProfile, persistUserProfile, progressionStore } from './mockDb';
import { generateInstanceId } from '../../utils/id';

const INITIAL_PROFILE: Omit<UserProfile, 'id'> = {
    username: 'Commander',
    level: 0, 
    seasonProgress: { '2025_01': { level: 1, xp: 0 } },
    rank: 10, 
    credits: 500, gold: 0, tokens: 0,
    activeDeckId: 1,
    avatarId: 'avatar_01',
    purchasedOfferIds: [],
    lastClaimedDates: {},
    collection: [...CARDS.map(c => c.id).slice(0, 10)], 
    decks: {
        1: [...CARDS.map(c => c.id).slice(0, 10)], 
        2: [], 3: [], 4: [], 5: [], 6: [], 7: [], 8: [], 9: [], 10: []
    },
    deckNames: {
        1: 'ASSAULT', 2: 'DECK 2', 3: 'DECK 3', 4: 'DECK 4', 5: 'DECK 5',
        6: 'DECK 6', 7: 'DECK 7', 8: 'DECK 8', 9: 'DECK 9', 10: 'DECK 10'
    },
    deckStats: {
        1: { conquestWinRate: 0, ladderWinRate: 0, conquestWins: 0, conquestTotal: 0, ladderWins: 0, ladderLosses: 0, lastModified: new Date().toISOString() },
    },
    cardRarities: {},
};

const RARITY_PATH: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
const UPGRADE_COSTS: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };

export const profileService = {
    async getProfile(userId: string): Promise<UserProfile> {
        verifySession(userId);
        await simulateNetwork(400, 700);
        const persisted = getPersistedProfile();
        if (persisted && persisted.id === userId) return persisted;

        const newProfile = { ...INITIAL_PROFILE, id: userId } as UserProfile;
        persistUserProfile(newProfile);
        return newProfile;
    },

    async updateActiveDeck(userId: string, deckId: number): Promise<UserProfile> {
        return lockedMutation(async () => {
            verifySession(userId);
            await simulateNetwork(100, 200);
            const user = getPersistedProfile();
            if (!user || user.id !== userId) throw new ApiError('ERR_UNAUTHORIZED', 'Session desync.');

            const updated = { ...user, activeDeckId: deckId };
            persistUserProfile(updated);
            return updated;
        });
    },

    /**
     * AUTHORITATIVE CARD UPGRADE
     */
    async upgradeCard(userId: string, cardId: string): Promise<any> {
        return lockedMutation(async () => {
            verifySession(userId);
            await simulateNetwork(600, 900);

            const user = getPersistedProfile();
            if (!user || user.id !== userId) throw new ApiError('ERR_UNAUTHORIZED', 'Account lock failed.');

            const currentRarity = user.cardRarities[cardId] || "Common";
            const nextIdx = RARITY_PATH.indexOf(currentRarity) + 1;

            if (nextIdx >= RARITY_PATH.length) {
                throw new ApiError('ERR_MAX_LEVEL', 'Card has reached maximum evolution.');
            }

            const nextRarity = RARITY_PATH[nextIdx];
            const cost = UPGRADE_COSTS[nextRarity];

            if (user.credits < cost) {
                throw new ApiError('ERR_INSUFFICIENT_FUNDS', 'Insufficient Credits for neural upgrade.');
            }

            const updatedProfile = { ...user };
            updatedProfile.credits -= cost;
            updatedProfile.level += 1; 
            updatedProfile.cardRarities = { ...user.cardRarities, [cardId]: nextRarity };

            const now = new Date();
            const logEntry: ActivityLogEntry = {
                id: generateInstanceId(),
                title: `Upgrade: ${cardId}`,
                type: 'credits',
                date: `${now.getDate()} ${now.toLocaleString('en', {month:'short'}).toUpperCase()} ${now.getFullYear().toString().slice(-2)}`,
                time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
                delta: cost,
                isSpend: true,
                currencyType: 'credits'
            };
            progressionStore.activityLog = [logEntry, ...progressionStore.activityLog].slice(0, 500);

            persistUserProfile(updatedProfile);

            return {
                success: true,
                updatedProfile,
                activityLog: [...progressionStore.activityLog]
            };
        });
    },

    async addCollectionLevels(userId: string, increment: number): Promise<UserProfile> {
        return lockedMutation(async () => {
            verifySession(userId);
            await simulateNetwork(300, 600);
            const user = getPersistedProfile();
            if (!user || user.id !== userId) throw new ApiError('ERR_UNAUTHORIZED', 'Access denied.');

            const updated = { ...user, level: user.level + increment };
            persistUserProfile(updated);
            return updated;
        });
    }
};

import { UserProfile, ProgressionData, ActivityLogEntry, ProgressionRewardType } from '../../types';
import { REWARD_SEQUENCE } from './mockData';
import { ITEM_SOURCES } from '../../config/sources';
import { progressionStore, getPersistedProfile, persistUserProfile } from './mockDb';
import { getProgressionDataInternal } from './progressionLogic';
import { generateInstanceId } from '../../utils/id';
import { simulateNetwork, verifySession, ApiError, lockedMutation } from './apiUtils';

const LOG_LIMIT = 500;

const formatDate = (now: Date) => {
    const day = now.getDate();
    const month = now.toLocaleString('default', { month: 'short' }).toUpperCase();
    const year = now.getFullYear().toString().slice(-2);
    return `${day} ${month} ${year}`;
};

export const progressionService = {
    async getProgression(userId: string): Promise<ProgressionData> {
        verifySession(userId);
        await simulateNetwork(200, 400);
        const user = getPersistedProfile();
        return getProgressionDataInternal(user);
    },

    async getActivityLog(): Promise<ActivityLogEntry[]> {
        await simulateNetwork(100, 200);
        return progressionStore.activityLog;
    },

    /**
     * AUTHORITATIVE CLAIM
     */
    async claimReward(userId: string, type: ProgressionRewardType) {
        return lockedMutation(async () => {
            verifySession(userId);
            await simulateNetwork(400, 600);

            const user = getPersistedProfile();
            if (!user || user.id !== userId) throw new ApiError('ERR_UNAUTHORIZED', 'Neural sync failed.');

            const currentData = getProgressionDataInternal(user);
            const trackIdx = currentData.tracks.findIndex(t => t.type === type);

            if (trackIdx === -1 || currentData.tracks[trackIdx].unclaimedCount <= 0) {
                throw new ApiError('ERR_ILLEGAL_CLAIM', 'Target reward not available or already claimed.');
            }

            const rewardConfig = REWARD_SEQUENCE[trackIdx];
            const updatedProfile = { ...user };

            const newClaimed = [...progressionStore.claimedCounts];
            newClaimed[trackIdx]++;
            progressionStore.claimedCounts = newClaimed;

            const amountToGrant = Number(rewardConfig.amount);

            if (type === 'credits') updatedProfile.credits += amountToGrant;
            else if (type === 'gold') updatedProfile.gold += amountToGrant;
            else if (type === 'tokens') updatedProfile.tokens += amountToGrant;

            const now = new Date();
            const dateStr = formatDate(now);
            const timeStr = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;

            const newLog: ActivityLogEntry = {
                id: generateInstanceId(),
                title: ITEM_SOURCES.COLLECTION_LEVEL_REWARD,
                type,
                date: dateStr,
                time: timeStr,
                delta: amountToGrant,
                isSpend: false,
                amountGained: amountToGrant,
                itemGained: type
            };

            progressionStore.activityLog = [newLog, ...progressionStore.activityLog].slice(0, LOG_LIMIT);
            persistUserProfile(updatedProfile);

            return { 
                success: true, 
                updatedProfile, 
                progressionData: getProgressionDataInternal(updatedProfile),
                activityLog: [...progressionStore.activityLog]
            };
        });
    },

    async claimAllRewards(userId: string, type: ProgressionRewardType) {
        return lockedMutation(async () => {
            verifySession(userId);
            await simulateNetwork(600, 900);

            const user = getPersistedProfile();
            if (!user || user.id !== userId) throw new ApiError('ERR_UNAUTHORIZED', 'Access denied.');

            const currentData = getProgressionDataInternal(user);
            const trackIdx = currentData.tracks.findIndex(t => t.type === type);

            if (trackIdx === -1 || currentData.tracks[trackIdx].unclaimedCount <= 0) {
                throw new ApiError('ERR_ILLEGAL_CLAIM', 'Nothing to claim in this sector.');
            }

            const count = currentData.tracks[trackIdx].unclaimedCount;
            const rewardConfig = REWARD_SEQUENCE[trackIdx];
            const updatedProfile = { ...user };

            const newClaimed = [...progressionStore.claimedCounts];
            newClaimed[trackIdx] += count;
            progressionStore.claimedCounts = newClaimed;

            const totalAmount = (rewardConfig.amount as number) * count;
            if (type === 'credits') updatedProfile.credits += totalAmount;
            else if (type === 'gold') updatedProfile.gold += totalAmount;
            else if (type === 'tokens') updatedProfile.tokens += totalAmount;

            const now = new Date();
            const dateStr = formatDate(now);
            const timeStr = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;

            const newLog: ActivityLogEntry = {
                id: generateInstanceId(),
                title: ITEM_SOURCES.COLLECTION_LEVEL_REWARD,
                type,
                date: dateStr,
                time: timeStr,
                delta: totalAmount,
                isSpend: false,
                isBulk: true,
                amountGained: totalAmount,
                itemGained: type
            };

            progressionStore.activityLog = [newLog, ...progressionStore.activityLog].slice(0, LOG_LIMIT);
            persistUserProfile(updatedProfile);

            return { 
                success: true, 
                updatedProfile, 
                progressionData: getProgressionDataInternal(updatedProfile),
                activityLog: [...progressionStore.activityLog]
            };
        });
    }
};

