export interface ScreenTheme {
    acc1: string;
    acc2: string;
    acc3: string;
    bloom: string;
}

export interface ScreenConfig {
    x: number; // Viewport Multiplier
    y: number; // Viewport Multiplier
    component: React.FC<any>;
    isPersistent?: boolean; 
    theme: ScreenTheme;
}

const THEMES = {
    COOL: { acc1: '#22d3ee', acc2: '#6366f1', acc3: '#d946ef', bloom: 'rgba(99, 102, 241, 0.2)' },
    WARM: { acc1: '#d946ef', acc2: '#f59e0b', acc3: '#ef4444', bloom: 'rgba(245, 158, 11, 0.2)' },
    VOID: { acc1: '#64748b', acc2: '#1e1b4b', acc3: '#312e81', bloom: 'rgba(30, 41, 59, 0.2)' },
    TECH: { acc1: '#4ade80', acc2: '#0891b2', acc3: '#4f46e5', bloom: 'rgba(74, 222, 128, 0.1)' }
};

/**
 * THE SPATIAL GRID CONFIGURATION
 */
export const WORLDS: Record<ScreenKey, ScreenConfig> = {
    SEASON:  { x: -2, y: 0, component: SeasonScreen, isPersistent: true, theme: THEMES.WARM },
    INBOX:   { x: -1, y: 0, component: InboxScreen, isPersistent: true, theme: THEMES.COOL },
    MENU:    { x: 0,  y: 0, component: MainMenuScreen, isPersistent: true, theme: THEMES.COOL },
    DECK:    { x: 1,  y: 0, component: DeckScreen, isPersistent: true, theme: THEMES.COOL },
    STORE:   { x: 2,  y: 0, component: StoreScreen, isPersistent: true, theme: THEMES.WARM },

    // Vertical Layers
    GAME:    { x: 0,  y: -1, component: GameScreen, isPersistent: false, theme: THEMES.VOID },
    PROFILE: { x: 0,  y: 1,  component: ProfileScreen, isPersistent: true, theme: THEMES.TECH },
    HISTORY: { x: 1,  y: 1,  component: HistoryScreen, isPersistent: true, theme: THEMES.TECH },
    RANK:    { x: -1, y: 1,  component: LadderRankingScreen, isPersistent: true, theme: THEMES.TECH },
    SETTINGS: { x: -1, y: -1, component: SettingsScreen, isPersistent: true, theme: THEMES.VOID },

    PROGRESSION: { x: 99, y: 99, component: () => null, isPersistent: false, theme: THEMES.COOL }, 
};

import { useState, useEffect } from 'react';
import { ScreenKey } from '../types';
import { WORLDS } from '../config/spatialMap';
import { audio } from '../services/audio';

export const useSpatialNavigation = () => {
    const [activeScreen, setActiveScreen] = useState<ScreenKey>('MENU');
    const [prevScreen, setPrevScreen] = useState<ScreenKey | null>(null);
    const [isTransitioning, setIsTransitioning] = useState(false);

    // Apply Theme Variables to :root
    useEffect(() => {
        const theme = WORLDS[activeScreen].theme;
        const root = document.documentElement;
        root.style.setProperty('--theme-acc-1', theme.acc1);
        root.style.setProperty('--theme-acc-2', theme.acc2);
        root.style.setProperty('--theme-acc-3', theme.acc3);
        root.style.setProperty('--theme-bloom', theme.bloom);
    }, [activeScreen]);

    const navigateTo = (target: ScreenKey) => {
        if (target === activeScreen || isTransitioning) return;

        audio.playUiHover();

        setPrevScreen(activeScreen);
        setActiveScreen(target);
        setIsTransitioning(true);

        // Match the App.tsx duration-500
        setTimeout(() => {
            setIsTransitioning(false);
            setPrevScreen(null); 
        }, 500); 
    };

    const resetToMenu = () => {
        setActiveScreen('MENU');
        setPrevScreen(null);
        setIsTransitioning(false);
    };

    const activeConfig = WORLDS[activeScreen];
    const cameraX = activeConfig.x * -100;
    const cameraY = activeConfig.y * -100;

    const containerStyle = { 
        transform: `translate3d(${cameraX}%, ${cameraY}%, 0)` 
    };

    return {
        activeScreen,
        prevScreen,
        isTransitioning,
        containerStyle,
        navigateTo,
        resetToMenu,
        WORLDS
    };
};

